/* 民法錯題複習卷題池（模擬卷 75 題＋歷屆 519 題）。由 tools/mockrec/pool.py 產生，不要手改。 */
window.BXPOOL={"S":"civ","papers":{"civls1":["民法來勝(一)","民法_來勝模擬試題一.html"],"civ1":["民法模擬試題一","民法_模擬試題一.html"],"civ2":["民法模擬試題二","民法_模擬試題二.html"]},"q":[{"id":"civls1-1","p":"civls1","src":"民法來勝(一) 第1題","sec":"A 行為能力","stem":"甲為17歲之未成年人，未得法定代理人允許，向乙購買價值新臺幣5萬元之筆記型電腦。該交易並非依甲之年齡及身分、日常生活所必需，甲亦未以詐術使乙信其有行為能力。依民法規定，下列敘述何者正確？","opts":["該買賣契約自始無效","該買賣契約當然有效","該買賣契約須經甲之法定代理人承認，始生效力","甲得不待法定代理人表示，隨時自行撤銷該契約"],"ok":[2],"ex":["❌ 限制行為能力人未得允許所訂契約是「效力未定」，不是無效（無效是無行為能力人，§75）。","❌ 非純獲法律上利益、非日常生活所必需，依§77 須得允許；也沒有§83 詐術，所以不會當然有效。","✅ §79：限制行為能力人未得法定代理人之允許，所訂立之契約，須經法定代理人之承認，始生效力。","❌ 民法沒有讓限制行為能力人自行「撤銷」的規定；能撤回的是不知情的相對人（§82）。"],"tr":"效力未定 ≠ 無效 ≠ 得撤銷。17 歲＝限制行為能力（§12、§13Ⅱ）。"},{"id":"civls1-2","p":"civls1","src":"民法來勝(一) 第2題","sec":"A 意思表示（第三人詐欺）","stem":"甲因第三人丙之詐欺，與乙訂立買賣契約；乙對丙之詐欺並不知情，且依當時情形亦無從知悉。依民法規定，下列敘述何者正確？","opts":["甲只要證明受詐欺，即得一律撤銷對乙之意思表示","甲不得以丙之詐欺為由，撤銷對乙之意思表示","該買賣契約自始當然無效","甲須先向丙請求損害賠償，始得撤銷對乙之意思表示"],"ok":[1],"ex":["❌ §92Ⅰ但書：詐欺由第三人所為者，以相對人明知或可得而知為限始得撤銷；本題乙不知且無從知悉，甲不得撤銷，「一律可撤銷」錯。","✅ §92Ⅰ但書：詐欺係由第三人所為者，以相對人明知其事實或可得而知者為限，始得撤銷之。乙不知也無從知悉→甲不得撤銷。","❌ 被詐欺的效果是「得撤銷」，不是當然無效。","❌ 撤銷不以先向詐欺人求償為前提；甲可另依§184 向丙請求賠償。"],"tr":"第三人詐欺→看相對人「明知或可得而知」；第三人脅迫則無此限制。"},{"id":"civls1-3","p":"civls1","src":"民法來勝(一) 第3題","sec":"B 給付遲延","stem":"甲向乙借款，約定應於9月1日清償。9月1日屆至後，甲仍未清償，且無不可歸責於甲之事由。乙尚未另行催告。依民法規定，甲自何時起負遲延責任？","opts":["自9月1日期限屆滿時起","自乙以存證信函催告時起","自乙起訴且判決確定時起","自甲表示拒絕清償時起"],"ok":[0],"ex":["✅ §229Ⅰ：給付有確定期限者，債務人自期限屆滿時起，負遲延責任。不必催告。","❌ 催告是「無確定期限」才需要（§229Ⅱ）。","❌ 起訴送達訴狀才與催告同效，且一樣只用在無確定期限；不必等判決確定。","❌ 遲延責任不以債務人表示拒絕為要件。"],"tr":"有確定期限→期限屆滿起；無確定期限→催告時起（起訴送達訴狀＝催告）。"},{"id":"civls1-4","p":"civls1","src":"民法來勝(一) 第4題","sec":"B 違約金","stem":"甲、乙約定甲如遲延履約，應支付違約金新臺幣500萬元。嗣甲遲延情節輕微，約定之違約金顯然過高。依民法規定，下列敘述何者正確？","opts":["法院僅得宣告違約金約定全部無效，不得調整數額","法院不得介入，因契約自由優先於一切考量","僅債權人得決定是否降低違約金","法院得將約定之違約金減至相當之數額"],"ok":[3],"ex":["❌ §252：違約金額過高者，法院得「減至相當之數額」；效果是酌減，不是宣告無效。","❌ §252 明文授權法院介入，契約自由有界限。","❌ §252 授權「法院」減至相當之數額，不是由債權人單方決定。","✅ §252：約定之違約金額過高者，法院得減至相當之數額。"],"tr":"過高→法院「酌減」，不是無效。"},{"id":"civls1-5","p":"civls1","src":"民法來勝(一) 第5題","sec":"B 債權讓與","stem":"甲將其對乙之金錢債權讓與丙，但甲、丙均尚未通知乙。依民法規定，下列敘述何者正確？","opts":["債權讓與因未經乙同意而無效","債權讓與在甲、丙間得成立，但未通知乙前，對乙不生效力","只有甲得通知乙，丙所為通知不生效力","債權讓與須經公證始生效力"],"ok":[1],"ex":["❌ 債權讓與不需債務人同意（§294）。","✅ §297Ⅰ：債權之讓與，非經讓與人或受讓人通知債務人，對於債務人不生效力。甲丙間仍成立。","❌ 讓與人「或受讓人」都可通知；受讓人提示讓與字據亦同（§297Ⅱ）。","❌ 民法未要求公證。"],"tr":"通知是「對債務人生效」要件，不是讓與成立要件；甲、丙任一方通知都可以。"},{"id":"civls1-6","p":"civls1","src":"民法來勝(一) 第6題","sec":"B 多數債務人（連帶）","stem":"甲、乙二人共同向丙借款，契約僅記載甲、乙各負擔一半債務，法律亦無特別規定。依民法規定，下列敘述何者正確？","opts":["只要債務人有二人以上，即一律成立連帶債務","丙得任意向甲請求全部債務，因多數債務人即推定連帶","甲、乙不因共同借款即當然成立連帶債務","甲、乙是否連帶，完全取決於丙之單方意思"],"ok":[2],"ex":["❌ §272：連帶債務須債務人明示各負全部給付之責任，或法律有規定，不因債務人有二人以上就當然成立。","❌ 民法沒有「推定連帶」；本題甚至約定各負一半。","✅ §272：須明示對債權人各負全部給付之責任，或法律有規定，始為連帶債務。本題兩者皆無。","❌ §272Ⅰ：須數債務人「明示對於債權人各負全部給付之責任」，或依同條Ⅱ有法律規定；不是債權人單方決定。"],"tr":"連帶債務＝「明示」或「法律規定」二選一；沒有推定。"},{"id":"civls1-7","p":"civls1","src":"民法來勝(一) 第7題","sec":"C 買賣・物之瑕疵擔保","stem":"關於買賣契約中出賣人之物之瑕疵擔保責任，下列敘述何者正確？","opts":["出賣人原則上應擔保標的物於危險移轉時，無滅失或減少價值、通常效用或契約預定效用之瑕疵","標的物只要有任何極輕微缺點，無論是否重要，均必然構成法律上之瑕疵","出賣人僅擔保標的物交付時之外觀，不擔保其通常效用","出賣人所保證之品質，不屬瑕疵擔保範圍"],"ok":[0],"ex":["✅ §354Ⅰ本文：危險移轉（§373，原則為交付時）時無滅失或減少價值、通常效用或契約預定效用之瑕疵。","❌ §354Ⅰ但書：減少之程度無關重要者，不得視為瑕疵。","❌ 通常效用正是擔保範圍。","❌ §354Ⅱ：出賣人並應擔保其物於危險移轉時，具有其所保證之品質。"],"tr":"基準時點＝危險移轉時；無關重要不算瑕疵；保證品質另列第2項。"},{"id":"civls1-8","p":"civls1","src":"民法來勝(一) 第8題","sec":"C 互易","stem":"甲、乙約定，甲將其名畫所有權移轉於乙，乙則將其古董手錶所有權移轉於甲。依民法規定，該契約之性質及適用規範為何？","opts":["屬贈與契約，準用委任規定","屬租賃契約，準用使用借貸規定","屬合夥契約，不準用其他有名契約規定","屬互易契約，準用關於買賣之規定"],"ok":[3],"ex":["❌ 雙方都有對價，不是無償。","❌ 移轉所有權，不是使用收益。","❌ 不是共同經營事業。","✅ §398：當事人雙方約定互相移轉金錢以外之財產權者，準用關於買賣之規定。"],"tr":"物換物＝互易，準用買賣。"},{"id":"civls1-9","p":"civls1","src":"民法來勝(一) 第9題","sec":"C 贈與（任意撤銷）","stem":"甲以經公證之契約表示贈與乙一部汽車，惟尚未移轉汽車所有權。甲僅以贈與物權利尚未移轉為由，主張依民法第408條第1項撤銷贈與。下列敘述何者正確？","opts":["甲得任意撤銷，因所有未履行之贈與均可撤銷","甲不得僅以權利尚未移轉為由，依該項規定撤銷經公證之贈與","贈與契約須交付標的物始成立，因此本案根本無契約","經公證之贈與在任何情況下均絕對不得撤銷"],"ok":[1],"ex":["❌ §408Ⅱ排除經公證之贈與。","✅ §408Ⅱ：前項規定，於經公證之贈與，或為履行道德上義務而為贈與者，不適用之。","❌ 贈與是諾成契約（§406），不以交付為成立要件。","❌ 太絕對：仍可能依§412（附負擔）、§416、§417 等法定事由撤銷。"],"tr":"公證只擋住§408 任意撤銷，擋不住§416、§417 法定撤銷——「絕對」選項多半錯。"},{"id":"civls1-10","p":"civls1","src":"民法來勝(一) 第10題","sec":"C 租賃（買賣不破租賃）","stem":"甲將房屋出租予乙3年，租賃契約未經公證，但甲已交付房屋，乙亦占有使用中。其後甲將房屋所有權讓與丙。依民法規定，下列敘述何者正確？","opts":["房屋所有權一經移轉，租賃契約當然消滅","乙僅得向甲請求損害賠償，不得對丙主張租賃關係","該租賃契約原則上對丙仍繼續存在","任何不動產租賃契約均須公證，始得對受讓人繼續存在"],"ok":[2],"ex":["❌ §425Ⅰ買賣不破租賃。","❌ 乙得對丙主張租約繼續存在。","✅ §425Ⅰ：租賃物交付後、承租人占有中讓與所有權，租約對受讓人仍繼續存在；3年未逾5年，不受同條Ⅱ限制。","❌ §425Ⅱ只排除「未經公證且逾5年或未定期限」者；3年定期不必公證。"],"tr":"要件＝交付＋占有中；例外＝未公證且（逾5年或不定期）。"},{"id":"civls1-11","p":"civls1","src":"民法來勝(一) 第11題","sec":"C 消費借貸","stem":"依民法關於消費借貸之規定，下列敘述何者正確？","opts":["貸與人移轉金錢或其他代替物之所有權，借用人應返還種類、品質、數量相同之物","借用人僅取得占有，不取得借用物所有權","借用人必須返還原來交付之同一物","消費借貸之標的僅限於不動產"],"ok":[0],"ex":["✅ §474Ⅰ：移轉金錢或其他代替物之所有權於他方，而約定他方以種類、品質、數量相同之物返還。","❌ 那是使用借貸（§464）；消費借貸移轉所有權。","❌ 返還同種類物即可，不必原物。","❌ 標的是金錢或代替物，通常是動產。"],"tr":"消費借貸＝移轉所有權＋還同種類；使用借貸＝只交付使用＋還原物。"},{"id":"civls1-12","p":"civls1","src":"民法來勝(一) 第12題","sec":"C 僱傭（終止）","stem":"甲、乙間之僱傭未定期限，且不能依勞務之性質或目的定其期限；本題並無其他特別法規定。依民法規定，下列敘述何者正確？","opts":["僅受僱人得終止契約，僱用人不得終止","雙方均須提出不可歸責於己之事由，始得終止","契約一經成立，須經雙方合意始得終止","各當事人原則上得隨時終止，但有利於受僱人之習慣者，從其習慣"],"ok":[3],"ex":["❌ §488Ⅱ：未定期限且不能依勞務性質或目的定其期限之僱傭，「各當事人」得隨時終止，僱用人也可以，不限受僱人。","❌ §488Ⅱ 規定各當事人得「隨時」終止，不以提出不可歸責於己之事由為要件。","❌ §488Ⅱ：一方以意思表示即可隨時終止，不必雙方合意。","✅ §488Ⅱ：僱傭未定期限，亦不能依勞務之性質或目的定其期限者，各當事人得隨時終止契約。但有利於受僱人之習慣者，從其習慣。"],"tr":"本題排除勞基法（題目寫無特別法）；與§450Ⅱ租賃「有利於承租人之習慣」同一句型。"},{"id":"civls1-13","p":"civls1","src":"民法來勝(一) 第13題","sec":"C 委任（終止）","stem":"甲委任乙處理事務。嗣甲於明顯不利於乙之時期終止委任，且無非可歸責於甲而不得不終止之事由。依民法規定，下列敘述何者正確？","opts":["委任契約成立後，雙方均不得片面終止","甲雖得隨時終止，但應就不利時期終止所生損害負賠償責任","甲之終止一律無效，委任關係仍繼續存在","只有受任人乙得隨時終止，委任人甲不得終止"],"ok":[1],"ex":["❌ §549Ⅰ任何一方得隨時終止。","✅ §549Ⅱ：於不利於他方之時期終止契約者，應負損害賠償責任；但非可歸責而不得不終止者除外。本題無但書情形。","❌ 終止仍有效，只是要賠償。","❌ 雙方都可終止。"],"tr":"終止「有效」＋「賠償」兩件事分開看。"},{"id":"civls1-14","p":"civls1","src":"民法來勝(一) 第14題","sec":"C 居間（報酬）","stem":"甲委託乙居間尋找房屋買受人。嗣甲與丙因乙之媒介而成立買賣契約，但該契約附停止條件，條件尚未成就。依民法規定，下列敘述何者正確？","opts":["乙只要曾提供資訊，無論契約是否因其報告或媒介成立，均得請求報酬","乙須等到房屋完成所有權移轉登記後，始可能請求任何費用","乙於停止條件成就前，尚不得請求居間報酬","附停止條件之契約不得作為居間標的，因此居間契約無效"],"ok":[2],"ex":["❌ §568Ⅰ以契約因其報告或媒介而成立為限。","❌ 報酬以契約因其媒介而「成立」為準（§568Ⅰ），附停止條件者再等條件成就（§568Ⅱ），不以移轉登記為準；費用另依§569 須有約定。","✅ §568Ⅱ：契約附有停止條件者，於該條件成就前，居間人不得請求報酬。","❌ 民法沒有禁止以附停止條件之契約為居間標的；§568Ⅱ 正是針對「契約附有停止條件」時的居間報酬時點所設，可見此種居間有效，只是報酬要等條件成就。"],"tr":"居間報酬＝契約成立；附停止條件→條件成就後。與 112-二、113-二 申論同一條。"},{"id":"civls1-15","p":"civls1","src":"民法來勝(一) 第15題","sec":"C 合夥（出資）","stem":"關於民法上合夥契約之出資，下列敘述何者正確？","opts":["合夥人之出資只能是金錢","合夥須有5人以上始得成立","勞務得作為出資，但信用絕對不得作為出資","出資得為金錢、其他財產權、勞務、信用或其他利益"],"ok":[3],"ex":["❌ §667Ⅱ：出資得為金錢或其他財產權，或以勞務、信用或其他利益代之，不限金錢。","❌ §667Ⅰ二人以上即可。","❌ §667Ⅱ明列信用。","✅ §667Ⅱ：出資得為金錢或其他財產權，或以勞務、信用或其他利益代之。"],"tr":"合夥＝二人以上；出資五種都可。"},{"id":"civls1-16","p":"civls1","src":"民法來勝(一) 第16題","sec":"D 不動產物權變動","stem":"甲、乙以口頭約定，由甲將其土地所有權移轉予乙，惟尚未辦理登記。依民法關於依法律行為所為不動產物權變動之規定，下列敘述何者正確？","opts":["土地所有權移轉應以書面為之，且非經登記不生物權變動效力","只要雙方口頭合意，土地所有權即移轉","只要乙支付全部價金，即使未登記也取得土地所有權","不動產登記僅是對抗第三人要件，不是生效要件"],"ok":[0],"ex":["✅ §758Ⅰ非經登記不生效力；§758Ⅱ前項行為應以書面為之。","❌ 欠書面與登記。","❌ 付款不等於登記。","❌ 我國採登記生效主義，不是對抗主義。"],"tr":"物權行為書面＋登記；債權契約（買賣）口頭仍可成立——別混淆。"},{"id":"civls1-17","p":"civls1","src":"民法來勝(一) 第17題","sec":"D 共有物管理","stem":"甲、乙、丙、丁共有一物，應有部分依序為70%、10%、10%、10%，彼此間就共有物管理未另有約定。依民法規定，下列敘述何者正確？","opts":["共有物之任何管理決定均須全體共有人一致同意","甲一人之應有部分已逾三分之二，作成管理決定時得不計算同意人數","共有物之簡易修繕也須經共有人過半數同意","共有人不得以契約另行約定共有物之管理方式"],"ok":[1],"ex":["❌ §820Ⅰ為多數決。","✅ §820Ⅰ但書：應有部分合計逾三分之二者，其人數不予計算。甲 70% 已逾 2/3。","❌ §820Ⅴ：簡易修繕及其他保存行為得單獨為之。","❌ §820Ⅰ「除契約另有約定外」，可以約定。"],"tr":"管理＝雙過半或應有部分逾 2/3；保存＝單獨；處分＝全體（§819Ⅱ）。"},{"id":"civls1-18","p":"civls1","src":"民法來勝(一) 第18題","sec":"D 地上權","stem":"關於普通地上權之讓與及設定抵押權，下列敘述何者正確？","opts":["地上權人絕對不得將地上權讓與他人","地上權人絕對不得以地上權設定抵押權","限制地上權讓與之約定，即使未登記，也一律得對抗第三人","地上權與其建築物或其他工作物，不得分離而為讓與或設定其他權利"],"ok":[3],"ex":["❌ §838Ⅰ原則得讓與。","❌ §838Ⅰ得設定抵押權；§882 地上權得為抵押權標的。","❌ §838Ⅱ：前項約定，非經登記，不得對抗第三人。","✅ §838Ⅲ：地上權與其建築物或其他工作物，不得分離而為讓與或設定其他權利。"],"tr":"「絕對」通常錯；限制約定要登記才能對抗。"},{"id":"civls1-19","p":"civls1","src":"民法來勝(一) 第19題","sec":"D 不動產役權","stem":"下列何者最符合民法上不動產役權之定義？","opts":["以占有他人動產作為債權擔保之權利","以他人不動產供自己不動產通行、汲水、採光或其他特定便宜之用的權利","支付價金後取得他人動產所有權之權利","在他人土地上建築房屋並永久取得土地所有權之權利"],"ok":[1],"ex":["❌ 動產質權（§884）。","✅ §851：以他人不動產供自己不動產通行、汲水、採光、眺望、電信或其他以特定便宜之用為目的之權。","❌ 買賣。","❌ 地上權不取得土地所有權。"],"tr":"需役／供役都是「不動產」（不限土地）。"},{"id":"civls1-20","p":"civls1","src":"民法來勝(一) 第20題","sec":"D 農育權","stem":"關於農育權之期限，下列敘述何者正確？","opts":["農育權期限一律不得逾5年","農育權期限一律不得逾10年","農育權期限原則上不得逾20年，但以造林、保育為目的或法令另有規定者，不在此限","農育權必須永久存續，不得約定期限"],"ok":[2],"ex":["❌ §850-1Ⅱ：農育權期限上限是二十年，不是 5 年；且以造林、保育為目的或法令另有規定者不受此限，「一律」錯。","❌ §850-1Ⅱ：農育權期限上限是二十年，不是 10 年；且以造林、保育為目的或法令另有規定者不受此限，「一律」錯。","✅ §850-1Ⅱ：農育權之期限，不得逾二十年；逾二十年者，縮短為二十年。但以造林、保育為目的或法令另有規定者，不在此限。","❌ §850-1Ⅱ 明定農育權有期限上限（原則二十年，逾者縮短為二十年），並非須永久存續、不得約定期限。"],"tr":"20 年上限：租賃§449Ⅰ（租用基地建築房屋除外）、農育權§850-1Ⅱ（造林、保育除外）；典權則是 30 年（§912）。"},{"id":"civls1-21","p":"civls1","src":"民法來勝(一) 第21題","sec":"D 抵押權（從屬性）","stem":"甲對乙有借款債權，並就乙之土地享有抵押權。依民法規定，下列敘述何者正確？","opts":["甲不得將抵押權與其擔保之債權分離讓與，也不得以該抵押權擔保其他債權","甲得保留債權而單獨將抵押權讓與丙","甲得以該抵押權轉供完全無關之其他債權作擔保","抵押權一經設定，即與被擔保債權完全獨立"],"ok":[0],"ex":["✅ §870：抵押權不得由債權分離而為讓與，或為其他債權之擔保。","❌ 違反§870。","❌ 違反§870。","❌ 抵押權具從屬性。"],"tr":"從屬性：成立、移轉、消滅都跟著債權。"},{"id":"civls1-22","p":"civls1","src":"民法來勝(一) 第22題","sec":"D 典權","stem":"下列何者最符合民法上典權之定義？","opts":["債權人占有債務人之動產，於債務未清償時得拒絕返還之權利","承租人支付租金後，取得租賃物所有權之權利","抵押權人不經實行程序，即當然取得抵押物所有權之權利","典權人支付典價，在他人不動產為使用、收益，於出典人不回贖時取得該不動產所有權之權利"],"ok":[3],"ex":["❌ 留置權（§928）。","❌ 租賃不取得所有權。","❌ 流抵約定須登記才能對抗第三人（§873-1），不是當然取得。","✅ §911：支付典價在他人之不動產為使用、收益，於他人不回贖時，取得該不動產所有權之權。"],"tr":"典權三要素：典價、使用收益、不回贖取得所有權。"},{"id":"civls1-23","p":"civls1","src":"民法來勝(一) 第23題","sec":"D 占有（權利推定）","stem":"關於占有之權利推定，下列敘述何者正確？","opts":["任何占有人均直接取得占有物所有權","占有人於占有物上行使之權利，原則上推定其適法有此權利，但法律設有例外","占有已登記之不動產而行使物權時，仍一律適用占有之權利推定","占有人行使所有權以外之權利時，對使其占有之人也一律適用該推定"],"ok":[1],"ex":["❌ 推定不是取得。","✅ §943Ⅰ推定適法有此權利；Ⅱ列兩種例外。","❌ §943Ⅱ①：占有已登記之不動產而行使物權→不適用（登記推定優先，§759-1Ⅰ）。","❌ §943Ⅱ②：行使所有權以外之權利者，對使其占有之人→不適用。"],"tr":"兩個例外：已登記不動產；對使其占有之人（如承租人對出租人）。"},{"id":"civls1-24","p":"civls1","src":"民法來勝(一) 第24題","sec":"E 剩餘財產分配（計算）","stem":"甲、乙夫妻適用法定財產制。法定財產制關係消滅時，甲扣除婚姻關係存續所負債務後之現存婚後財產為800萬元，其中200萬元為繼承所得；乙扣除債務後之現存婚後財產為200萬元。假設無其他應排除或調整之情形，乙得向甲請求多少剩餘財產差額？","opts":["100萬元","150萬元","200萬元","300萬元"],"ok":[2],"ex":["❌ 依 §1030-1Ⅰ：甲 800−200（繼承不列入）＝600 萬，乙 200 萬，差額 400 萬平均分配＝200 萬，不是 100 萬。","❌ 依 §1030-1Ⅰ：甲 600 萬（800 扣繼承 200）−乙 200 萬＝差額 400 萬，平均分配＝200 萬，不是 150 萬。","✅ §1030-1Ⅰ①繼承所得不列入：甲 800−200＝600 萬；乙 200 萬；差額 400 萬平均分配→乙得請求 200 萬。","❌ 300 萬是把甲的繼承所得 200 萬也算進去：（甲 800−乙 200）÷2＝300；繼承所得依 §1030-1Ⅰ① 不列入分配。"],"tr":"先扣繼承／無償取得與慰撫金，再相減÷2。"},{"id":"civls1-25","p":"civls1","src":"民法來勝(一) 第25題","sec":"E 法定應繼分","stem":"甲死亡，未立遺囑，遺有配偶乙及子女丙、丁，且無其他影響繼承之事由。依民法規定，乙、丙、丁之應繼分各為多少？","opts":["乙、丙、丁各三分之一","乙二分之一，丙、丁各四分之一","乙三分之二，丙、丁各六分之一","乙不參與繼承，由丙、丁各二分之一"],"ok":[0],"ex":["✅ §1144①：配偶與第一順序繼承人同為繼承時，應繼分與他繼承人平均→各 1/3。","❌ 1/2 是配偶與第二、三順序（父母、兄弟姊妹）。","❌ 2/3 是配偶與第四順序（祖父母）。","❌ 配偶為當然繼承人（§1138）。"],"tr":"配偶：一平均、二三 1/2、四 2/3、無人全部。"},{"id":"civ1-1","p":"civ1","src":"民法模擬試題一 第1題","sec":"A 行為能力","stem":"甲（17 歲）未得法定代理人允許，將自己所有之機車賣與乙，乙訂約時明知甲未成年且未得法定代理人允許。下列敘述何者正確？","opts":["該買賣契約當然無效","乙於承認前得撤回其意思表示","乙得定一個月以上之期限催告甲之法定代理人確答是否承認；逾期不為確答，視為拒絕承認","乙定相當期限催告後，法定代理人逾期未答，視為承認"],"ok":[2],"ex":["❌ 限制行為能力人未得允許所訂契約是「效力未定」（§79），不是當然無效。","❌ §82 但書：訂立契約時知其未得允許者不得撤回；乙明知，故不得撤回。","✅ §79 契約須經法定代理人承認始生效力；§80 相對人得定一個月以上期限催告，逾期不確答視為拒絕承認。","❌ §80Ⅱ 逾期不確答是「視為拒絕承認」。"],"tr":"效力未定＋催告（一個月以上、逾期＝拒絕）＋撤回權（善意相對人才有）。"},{"id":"civ1-2","p":"civ1","src":"民法模擬試題一 第2題","sec":"A 意思表示瑕疵","stem":"下列有關意思表示瑕疵之敘述，何者錯誤？","opts":["通謀虛偽意思表示無效，且得以其無效對抗善意第三人","被詐欺而為之意思表示，其撤銷不得以之對抗善意第三人","因錯誤而得撤銷之意思表示，其撤銷權自意思表示後經過一年而消滅","第三人所為詐欺，以相對人明知其事實或可得而知者為限，始得撤銷"],"ok":[0],"ex":["✅ 此敘述錯誤（本題答案）：§87Ⅰ 但書：不得以其無效對抗善意第三人，本選項與條文相反。","❌ 此敘述正確，不選：§92Ⅱ 規定如此，敘述正確。","❌ 此敘述正確，不選：§90 規定一年，敘述正確。","❌ 此敘述正確，不選：§92Ⅰ 但書，敘述正確。"],"tr":"§87 善意第三人受保護；§92 詐欺撤銷不得對抗善意第三人；§90 一年、§93 發見後一年／十年。"},{"id":"civ1-3","p":"civ1","src":"民法模擬試題一 第3題","sec":"A 消滅時效","stem":"甲出租房屋與乙，約定每月租金 2 萬元，乙積欠租金多年未付。下列敘述何者正確？","opts":["租金請求權之消滅時效為 15 年","甲以存證信函請求乙清償後，於七個月後才起訴，時效仍因該請求而中斷","乙於時效完成後承認該債務，仍得請求返還已給付之租金","乙得以時效完成為由拒絕給付；但乙於時效完成後仍為履行之給付者，不得以不知時效為理由請求返還"],"ok":[3],"ex":["❌ §126 租金等一年或不及一年之定期給付債權，各期給付請求權 5 年消滅，不是 15 年。","❌ §130：請求後六個月內不起訴，視為不中斷；七個月才起訴已逾期。","❌ §144Ⅱ：以契約承認該債務或提出擔保者亦同，不得返還。","✅ §144：時效完成後債務人得拒絕給付；已為履行不得以不知時效請求返還。"],"tr":"租金 5 年（§126）≠ 一般請求權 15 年（§125）；請求中斷後六個月內要起訴（§130）。"},{"id":"civ1-4","p":"civ1","src":"民法模擬試題一 第4題","sec":"A 無權代理","stem":"無代理權人以他人代理人名義所為之法律行為，下列敘述何者正確？","opts":["對本人當然無效","相對人於本人未承認前得撤回之，但為法律行為時明知其無代理權者不在此限","相對人定期催告本人確答，本人逾期未答視為承認","無代理權人對惡意相對人亦負損害賠償責任"],"ok":[1],"ex":["❌ §170Ⅰ：非經本人承認，對本人「不生效力」，屬效力未定，本人承認後即生效。","✅ §171 原文。","❌ §170Ⅱ：逾期未確答視為「拒絕」承認。","❌ §110：僅對「善意」之相對人負損害賠償責任。"],"tr":"無權代理：本人承認前相對人撤回權（善意）；催告逾期＝拒絕；§110 只對善意相對人負責。"},{"id":"civ1-5","p":"civ1","src":"民法模擬試題一 第5題","sec":"A 物與孳息","stem":"下列關於「物」與「孳息」之敘述：\n①不動產之出產物尚未分離者，為該不動產之部分\n②主物之處分及於從物\n③租金屬於天然孳息\n④有收取法定孳息權利之人，按其權利存續期間內之日數取得其孳息\n⑤從物須與主物同屬於一人\n何者組合正確？","opts":["①②③④","①②④⑤","②③④⑤","①③④⑤"],"ok":[1],"ex":["❌ ③ 錯：租金是「法定孳息」（§69Ⅱ），不是天然孳息。","✅ ①（§66Ⅱ）②（§68Ⅱ）④（§70Ⅱ）⑤（§68Ⅰ「同屬於一人」）均正確，③錯誤。","❌ 含③，且漏①。","❌ 含③，且漏②。"],"tr":"天然孳息＝果實、動物產物；法定孳息＝利息、租金；從物要與主物同屬一人。"},{"id":"civ1-6","p":"civ1","src":"民法模擬試題一 第6題","sec":"B 風險負擔","stem":"甲將房屋出賣予乙，乙已付清全部價金，房屋尚未交付亦未移轉登記，嗣因地震全毀（雙方均無可歸責事由）。下列敘述何者正確？","opts":["甲仍應移轉房屋所有權，並依 §226 賠償損害","買賣標的物之危險自訂約時起即由買受人承擔","乙不得請求返還價金，因價金已完成給付","甲免給付義務；乙免對待給付義務，已為對待給付者得依不當得利規定請求返還"],"ok":[3],"ex":["❌ §226 須「可歸責於債務人」，本題雙方皆無可歸責。","❌ §373：利益與危險自「交付時」起由買受人承擔；本題尚未交付。","❌ §266Ⅱ 已為給付者得依不當得利規定請求返還。","✅ §225Ⅰ 給付不能免給付義務；§266 雙方均無可歸責，他方免對待給付，已給付者依不當得利返還。"],"tr":"買賣危險移轉＝交付時；雙方皆無可歸責的給付不能＝雙方都免給付（§266）。"},{"id":"civ1-7","p":"civ1","src":"民法模擬試題一 第7題","sec":"B 連帶債務","stem":"甲、乙、丙對丁負連帶債務 300 萬元，內部約定平均分擔。丁對甲免除債務，但無消滅全部債務之意思。下列敘述何者正確？","opts":["乙、丙全部免責","乙、丙仍須各負 300 萬元之連帶責任","乙、丙就剩餘 200 萬元仍負連帶責任","丁對甲免除，對乙、丙完全不生效力（§279）"],"ok":[2],"ex":["❌ 免除若無消滅全部債務之意思，只免甲應分擔之部分。","❌ 甲應分擔之 100 萬已被免除，他債務人於該部分免責。","✅ §276Ⅰ：除該債務人應分擔部分（100 萬）外，他債務人仍不免責任。","❌ §276 為 §279 所稱「前五條規定」之例外，免除對他人有一定效力。"],"tr":"連帶債務：清償、抵銷、提存、混同＝絕對效力；免除、時效完成＝只扣掉該人應分擔額（§276）；其餘相對效力（§279）。"},{"id":"civ1-8","p":"civ1","src":"民法模擬試題一 第8題","sec":"B 債權讓與","stem":"甲將對乙之 100 萬元借款債權讓與丙。下列敘述何者正確？","opts":["乙受讓與通知時，對甲有清償期先於或同時屆至之債權者，得向丙主張抵銷","讓與非經通知乙，讓與契約無效","該債權之擔保及其他從屬之權利，不隨同移轉","當事人特約不得讓與，不得對抗任何第三人"],"ok":[0],"ex":["✅ §299Ⅱ 原文。","❌ §297Ⅰ：非經通知，是「對債務人不生效力」，不是契約無效。","❌ §295Ⅰ：從屬權利隨同移轉（與讓與人有不可分離之關係者除外）。","❌ §294Ⅱ：僅「不得對抗善意第三人」。"],"tr":"通知＝對債務人生效要件；債務人抗辯與抵銷可對抗受讓人；禁止讓與特約不得對抗善意第三人。"},{"id":"civ1-9","p":"civ1","src":"民法模擬試題一 第9題","sec":"B 定金","stem":"甲乙訂立房屋買賣契約，乙交付定金 50 萬元予甲。嗣因可歸責於甲之事由致契約不能履行，當事人無另有訂定。下列敘述何者正確？","opts":["乙不得請求返還定金","甲應加倍返還所受之定金","定金視為因不履行而生損害之賠償總額","契約因不可歸責雙方而不能履行時，甲得沒收定金"],"ok":[1],"ex":["❌ 那是可歸責於付定金當事人（乙）時的效果（§249②）。","✅ §249③：可歸責於受定金當事人者，該當事人應加倍返還其所受之定金。","❌ 那是違約金「視為」損害賠償總額之規定（§250Ⅱ）。","❌ §249④：不可歸責於雙方，定金應返還。"],"tr":"定金四款：履行（返還或充給付）／乙過失（不得請求返還）／甲過失（加倍返還）／雙方無過失（返還）。"},{"id":"civ1-10","p":"civ1","src":"民法模擬試題一 第10題","sec":"C 買賣瑕疵擔保","stem":"關於買賣標的物之瑕疵擔保，下列敘述何者正確？","opts":["買受人於契約成立時知其物有瑕疵者，出賣人仍負擔保責任","出賣人故意不告知瑕疵者，六個月期間仍適用","買受人因重大過失不知有瑕疵，出賣人縱故意不告知亦不負擔保責任","買受人之解除權或請求權，自物之交付時起經過五年而消滅"],"ok":[3],"ex":["❌ §355Ⅰ：買受人知悉者，出賣人不負擔保之責。","❌ §365Ⅱ：故意不告知瑕疵者，六個月期間不適用（五年仍適用）。","❌ §355Ⅱ 但書：故意不告知者仍須負責。","✅ §365Ⅰ 後段。"],"tr":"瑕疵擔保期間：通知後 6 個月／交付後 5 年；故意不告知＝6 個月不適用；知悉＝免責；重大過失＋未保證＝免責（但故意不告知例外）。"},{"id":"civ1-11","p":"civ1","src":"民法模擬試題一 第11題","sec":"C 買賣不破租賃","stem":"甲將房屋出租與乙，書面約定租期 3 年（未公證），房屋已交付乙居住。其後甲將房屋出賣並移轉登記予丙。下列敘述何者正確？","opts":["租賃契約對丙不存在，丙得請求乙返還房屋","該租賃契約對丙繼續存在，丙不得請求乙返還房屋","租賃契約須經公證，始得對抗受讓人丙","丙受讓後，租賃契約僅於出租人甲與乙間繼續存在"],"ok":[1],"ex":["❌ §425Ⅱ 排除的是「未公證且逾五年或未定期限」；3 年不在排除之列。","✅ §425Ⅰ；本題租期 3 年未逾 5 年，不受 §425Ⅱ 排除。","❌ 公證只與「期限逾五年或未定期限」的不動產租賃有關（§425Ⅱ）；本題租期 3 年且定有期限，不需公證即受 §425Ⅰ 保護。","❌ §425Ⅰ「對於受讓人仍繼續存在」，丙承受出租人地位。"],"tr":"買賣不破租賃三要件：已交付、承租人占有中、未被排除（未公證且逾5年或未定期）。"},{"id":"civ1-12","p":"civ1","src":"民法模擬試題一 第12題","sec":"C 居間","stem":"甲委託乙居間出售房屋，約定成交後給付報酬。下列敘述何者正確？","opts":["買賣契約附停止條件，條件成就前乙已得請求報酬","乙為居間所支出之費用，縱未約定亦得向甲請求償還","居間人違反其對於委託人之義務，而為利於委託人之相對人之行為，由相對人收受利益者，不得向委託人請求報酬及償還費用","約定報酬過高時，法院不得酌減"],"ok":[2],"ex":["❌ §568Ⅱ：條件成就前居間人不得請求報酬。","❌ §569Ⅰ：非經約定不得請求償還費用。","✅ §571 原文。","❌ §572：報酬過鉅失其公平者，法院得因給付義務人之請求酌減。"],"tr":"居間：成立要件（因其報告或媒介而成立）／附停止條件不得先請求／費用非經約定不得請／違反義務且對方給好處＝沒報酬／過高可酌減。"},{"id":"civ1-13","p":"civ1","src":"民法模擬試題一 第13題","sec":"D 動產善意取得","stem":"甲將其所有之名畫寄放於乙處，乙擅自將該畫以市價出賣並交付予善意且無重大過失之丙。下列敘述何者正確？","opts":["丙善意受讓動產占有，受法律保護，取得所有權","乙為無權處分，非經甲承認不生效力，丙不得取得所有權","若該畫為遺失物，甲得於喪失占有後十年內請求丙返還","甲須先償還丙支出之價金，始得請求回復（寄放物亦同）"],"ok":[0],"ex":["✅ §801、§948 動產善意受讓：受讓人善意受現實交付，縱讓與人無處分權，仍取得所有權。","❌ 乙確屬無權處分，依 §118Ⅰ 原則上須經甲承認始生效力；但動產另有善意取得特別規定（§801、§948Ⅰ）：丙善意且無重大過失受讓占有，縱乙無讓與權利，丙仍取得所有權，不必等甲承認。","❌ §949：盜贓、遺失物，原占有人自喪失占有時起「二年」內得請求回復。","❌ §950 償還價金限於「盜贓、遺失物」由公開交易場所或商人善意買得者；本題為寄放物，不適用。"],"tr":"動產＝交付善意取得（§801、§948）；盜贓遺失物例外（§949 二年、§950 償還價金）。"},{"id":"civ1-14","p":"civ1","src":"民法模擬試題一 第14題","sec":"D 不動產繼承登記","stem":"甲因繼承取得 A 地，尚未辦理繼承登記，即與乙訂立買賣契約欲將 A 地所有權移轉予乙。下列敘述何者正確？","opts":["甲須辦理繼承登記後始取得 A 地所有權","不動產物權變動採意思主義，買賣合意即生移轉效力","甲得免辦繼承登記，直接移轉登記予乙","甲於繼承開始時即取得 A 地所有權，但非經登記不得處分其物權"],"ok":[3],"ex":["❌ 繼承是非因法律行為取得，繼承開始時即取得，登記只影響「處分」。","❌ §758：依法律行為變動，非經登記不生效力。","❌ §759 要求先辦繼承登記再處分。","✅ §759：因繼承於登記前已取得不動產物權者，應經登記，始得處分其物權。"],"tr":"§758（法律行為→登記生效）vs §759（非因法律行為→先取得，但處分前要先登記）。"},{"id":"civ1-15","p":"civ1","src":"民法模擬試題一 第15題","sec":"D 共有物管理","stem":"甲、乙、丙共有 A 屋，應有部分甲 3/4、乙 1/8、丙 1/8，無特約。甲欲將 A 屋出租於丁，乙、丙均不同意。下列敘述何者正確？","opts":["出租為處分行為，須全體共有人同意","管理決定有故意或重大過失致共有人受損害，甲不負賠償責任","甲之應有部分逾 2/3，其人數不予計算，甲得依 §820Ⅰ 決定出租","乙、丙對甲之決定顯失公平者，仍無任何救濟"],"ok":[2],"ex":["❌ 出租屬「管理」行為，適用 §820Ⅰ；處分、變更、設定負擔才須全體同意（§819Ⅱ）。","❌ §820Ⅳ：對不同意之共有人連帶負賠償責任。","✅ §820Ⅰ 但書：應有部分合計逾三分之二者，其人數不予計算。","❌ §820Ⅱ：顯失公平者，不同意之共有人得聲請法院以裁定變更。"],"tr":"§820 修法後：人數過半＋應有部分過半；應有部分逾 2/3 人數不計；顯失公平可聲請法院；保存行為可單獨。"},{"id":"civ1-16","p":"civ1","src":"民法模擬試題一 第16題","sec":"D 共有物分割","stem":"共有人不能協議分割方法，訴請法院裁判分割共有物。下列敘述何者正確？","opts":["法院僅得判決變賣共有物，不得以原物分配","以原物為分配時，如共有人中有未受分配或不能按其應有部分受分配者，得以金錢補償之","變賣共有物時，共有人無優先承買權","分割後各共有人對他共有人因分割而得之物，不負擔保責任"],"ok":[1],"ex":["❌ §824Ⅱ 以原物分配為優先（但書另有規定）。","✅ §824Ⅲ 原文。","❌ §824Ⅶ：除買受人為共有人外，共有人有依相同條件優先承買之權。","❌ §825：按應有部分，負與出賣人同一之擔保責任。"],"tr":"分割：協議→裁判（原物→變賣）；金錢補償；變賣優先承買；分割後互負擔保。"},{"id":"civ1-17","p":"civ1","src":"民法模擬試題一 第17題","sec":"D 抵押權效力","stem":"下列有關普通抵押權之敘述：\n①抵押權所擔保者為原債權、利息、遲延利息、違約金及實行抵押權之費用，但契約另有約定者從其約定\n②抵押權之效力及於抵押物之從物與從權利\n③抵押人設定抵押權後讓與抵押物，抵押權不受影響\n④抵押權得由債權分離而單獨讓與\n何者組合正確？","opts":["①②③","①②④","②③④","①③④"],"ok":[0],"ex":["✅ ①（§861Ⅰ）②（§862Ⅰ）③（§867）均正確，④錯誤。","❌ ④ 錯：抵押權不得由債權分離而為讓與（§870）。","❌ 含④，且漏①。","❌ 含④，且漏②。"],"tr":"抵押權具從屬性：不得與債權分離（§870）；追及力：讓與抵押物不影響（§867）。"},{"id":"civ1-18","p":"civ1","src":"民法模擬試題一 第18題","sec":"D 抵押權消滅","stem":"甲對乙有 500 萬元借款債權，乙以 A 地設定抵押權擔保；該債權請求權時效已完成。甲在時效完成後 5 年內都未實行抵押權。下列敘述何者正確？","opts":["請求權時效完成，抵押權亦同時當然消滅","抵押權永遠不因時效而消滅","乙若在時效完成後清償一部，得以不知時效為由請求返還","甲之抵押權因 5 年間不實行而消滅"],"ok":[3],"ex":["❌ §145Ⅰ 抵押權擔保之請求權雖經時效消滅，仍得就抵押物取償；須再加 §880 的 5 年。","❌ §880 明定 5 年消滅。","❌ §144Ⅱ：不得請求返還。","✅ §880：擔保債權請求權已因時效而消滅，抵押權人於時效完成後 5 年間不實行抵押權者，抵押權消滅。"],"tr":"請求權時效完成後：抵押權還可實行（§145），但 5 年內不實行即消滅（§880）。"},{"id":"civ1-19","p":"civ1","src":"民法模擬試題一 第19題","sec":"D 地上權","stem":"甲在乙地上設定普通地上權，約定有地租。下列敘述何者正確？","opts":["地上權人積欠地租一年，土地所有人即得逕行終止","地上權人積欠地租達二年之總額，除另有習慣外，土地所有人得定相當期限催告支付，逾期不為支付，得終止地上權","地上權因建築物之滅失而當然消滅","地上權人得不經土地所有人同意，單獨將地上權與建築物分離讓與"],"ok":[1],"ex":["❌ §836 要件是「達二年之總額」且須先催告。","✅ §836Ⅰ 原文（地上權經設定抵押權者，並應同時將催告事實通知抵押權人）。","❌ §841：地上權不因建築物或其他工作物之滅失而消滅。","❌ §838Ⅲ：地上權與其建築物不得分離而為讓與或設定其他權利。"],"tr":"§836：積欠二年總額＋催告＋終止（向地上權人為意思表示）；§841 不因建物滅失消滅；§838Ⅲ 地上權與建物不得分離。"},{"id":"civ1-20","p":"civ1","src":"民法模擬試題一 第20題","sec":"E 剩餘財產分配","stem":"甲乙為夫妻，未約定財產制，嗣離婚。甲婚後財產現存 800 萬元（含繼承所得 200 萬元），無負債；乙婚後財產現存 100 萬元，無負債。依 §1030-1，乙得向甲請求分配之金額為何？","opts":["100 萬元","300 萬元","250 萬元","350 萬元"],"ok":[2],"ex":["❌ 100 萬是乙自己的婚後財產，不是分配金額。","❌ 300 萬＝600÷2，忘了扣乙自己的 100 萬（應先算差額）。","✅ 甲：800−200（繼承不列入）＝600；乙：100；差額 500，平均分配 250 萬。","❌ 350 萬＝(800−100)÷2，誤把繼承所得 200 萬也算入。"],"tr":"剩餘財產分配＝(雙方各自婚後財產扣除繼承／無償取得／慰撫金後)的「差額」÷ 2。"},{"id":"civ1-21","p":"civ1","src":"民法模擬試題一 第21題","sec":"E 法定繼承與代位","stem":"甲死亡，遺有配偶乙、長子丙（已先於甲死亡，遺有子丁）及次子戊，遺產 1,200 萬元。下列敘述何者正確？","opts":["乙、戊、丁各得 400 萬元","乙得 600 萬元，戊得 600 萬元","乙得 600 萬元（遺產二分之一），戊、丁各得 300 萬元","乙、戊各得 400 萬元，丁因代位僅得繼承遺產而無應繼分"],"ok":[0],"ex":["✅ 配偶與第一順序同為繼承，應繼分平均（§1144①）；丙之應繼分由丁代位（§1140）。三人平均各 400 萬。","❌ 忘了丙有直系血親卑親屬丁可代位繼承。","❌ 配偶與第一順序同為繼承是「平均」，二分之一是與第二、三順序同為繼承時（§1144②）。","❌ 代位繼承人取得被代位人之應繼分（§1140），丁得 400 萬。"],"tr":"§1144：配偶＋第一順序＝平均；＋第二、三順序＝1/2；＋第四順序＝2/3。代位繼承只限第一順序（§1140）。"},{"id":"civ1-22","p":"civ1","src":"民法模擬試題一 第22題","sec":"E 拋棄繼承","stem":"下列有關拋棄繼承之敘述，何者正確？","opts":["拋棄繼承自向法院表示時起發生效力","第一順序繼承人中有拋棄繼承者，其應繼分歸屬國庫","因他人拋棄繼承而應為繼承之人，應於知悉其得繼承之日起六個月內拋棄","拋棄繼承應於知悉其得繼承之時起三個月內，以書面向法院為之"],"ok":[3],"ex":["❌ §1175：溯及於繼承開始時發生效力。","❌ §1176Ⅰ：應繼分歸屬於其他同為繼承之人。","❌ §1176Ⅶ：三個月，不是六個月。","✅ §1174Ⅱ 原文。"],"tr":"拋棄＝三個月／書面／向法院／溯及繼承開始；次順位後手也是三個月。"},{"id":"civ1-23","p":"civ1","src":"民法模擬試題一 第23題","sec":"E 遺囑","stem":"下列有關遺囑之敘述，何者正確？","opts":["限制行為能力人為遺囑，一律須經法定代理人允許","未滿十六歲者，不得為遺囑","繼承人之配偶得為遺囑見證人","口授遺囑自遺囑人能依其他方式為遺囑之時起，經過六個月失其效力"],"ok":[1],"ex":["❌ §1186Ⅱ：限制行為能力人無須經法定代理人允許，得為遺囑（但未滿十六歲不得）。","✅ §1186Ⅱ 但書。","❌ §1198③：繼承人及其配偶或其直系血親不得為見證人。","❌ §1196：三個月。"],"tr":"遺囑能力：16 歲、不需法代允許；見證人排除：繼承人／受遺贈人及其配偶直系血親；口授失效 3 個月。"},{"id":"civ1-24","p":"civ1","src":"民法模擬試題一 第24題","sec":"E 特留分扣減","stem":"甲死亡，遺有配偶乙及子丙、丁，遺產 1,200 萬元；甲以遺囑將全部遺產遺贈予戊。丙得向戊主張扣減之金額為何？","opts":["400 萬元","100 萬元","200 萬元","0 元，遺囑自由處分不受限制"],"ok":[2],"ex":["❌ 400 萬是應繼分，不是特留分。","❌ 把特留分算成應繼分的 1/4 了；子女特留分是 1/2。","✅ 乙丙丁平均應繼分各 400 萬；子女特留分為應繼分 1/2（§1223①）＝200 萬；全被遺贈，不足 200 萬，得按不足數扣減（§1225）。","❌ §1187：遺囑人須於「不違反特留分規定」之範圍內自由處分。"],"tr":"步驟：先算應繼分→乘特留分比例→比較遺贈後實得→不足數向受遺贈人扣減（§1225）。"},{"id":"civ1-25","p":"civ1","src":"民法模擬試題一 第25題","sec":"E 夫妻財產制","stem":"下列有關法定財產制之敘述，何者錯誤？","opts":["不能證明為婚前或婚後財產者，推定為夫妻共有","夫或妻婚前財產於婚姻關係存續中所生之孳息，視為婚後財產","夫或妻各自管理、使用、收益及處分其財產","夫妻之一方以自己財產清償他方之債務時，雖於婚姻關係存續中，亦得請求償還"],"ok":[0],"ex":["✅ 此敘述錯誤（本題答案）：§1017Ⅰ：不能證明為婚前或婚後財產者，推定為「婚後財產」；不能證明為夫或妻所有者，才推定夫妻共有。","❌ 此敘述正確，不選：§1017Ⅱ 原文，敘述正確。","❌ 此敘述正確，不選：§1018，敘述正確。","❌ 此敘述正確，不選：§1023Ⅱ，敘述正確。"],"tr":"§1017 兩個推定：婚前/婚後不明→婚後財產；夫/妻所有不明→共有。"},{"id":"civ2-1","p":"civ2","src":"民法模擬試題二 第1題","sec":"A 行為能力","stem":"關於行為能力，下列敘述何者正確？","opts":["受監護宣告之人，僅有限制行為能力","未滿七歲之未成年人，無行為能力；滿七歲以上之未成年人，有限制行為能力","受輔助宣告之人處分不動產，無須經輔助人同意","限制行為能力人用詐術使人信其為有行為能力人者，其法律行為效力未定"],"ok":[1],"ex":["❌ §15：受監護宣告之人，無行為能力。","✅ §13 原文（成年已改為滿十八歲，§12）。","❌ §15-2Ⅰ⑤：不動產之處分、設定負擔、買賣、租賃或借貸，應經輔助人同意。","❌ §83：其法律行為為「有效」。"],"tr":"未成年（7歲分界）／監護＝無行為能力／輔助＝特定重要行為須同意／詐術＝有效。"},{"id":"civ2-2","p":"civ2","src":"民法模擬試題二 第2題","sec":"A 暴利行為","stem":"甲趁乙急需用錢，以市價三成買受乙之房屋，並辦妥移轉登記。下列敘述何者正確？","opts":["該買賣當然無效","乙得於法律行為後二年內聲請撤銷","乙得逕以意思表示撤銷，毋須經法院","乙得於法律行為後一年內，聲請法院撤銷其法律行為或減輕其給付"],"ok":[3],"ex":["❌ §74 的效果是「法院得撤銷或減輕」，不是當然無效。","❌ §74Ⅱ：一年，不是二年。","❌ §74 須「聲請法院」，與 §92 詐欺脅迫（以意思表示撤銷）不同。","✅ §74Ⅰ、Ⅱ：乘人急迫、輕率或無經驗，顯失公平者，法院得因利害關係人之聲請撤銷或減輕給付；聲請應於法律行為後一年內為之。"],"tr":"暴利行為＝聲請法院＋一年；詐欺脅迫＝意思表示撤銷＋發見後一年／十年。"},{"id":"civ2-3","p":"civ2","src":"民法模擬試題二 第3題","sec":"A 要約與承諾","stem":"下列有關要約與承諾之敘述，何者錯誤？","opts":["價目表之寄送，視為要約","貨物標定賣價陳列者，視為要約","對話為要約者，非立時承諾，即失其拘束力","將要約擴張、限制或為其他變更而承諾者，視為拒絕原要約而為新要約"],"ok":[0],"ex":["✅ 此敘述錯誤（本題答案）：§154Ⅱ 但書：價目表之寄送，「不視為」要約。","❌ 此敘述正確，不選：§154Ⅱ 本文，敘述正確。","❌ 此敘述正確，不選：§156，敘述正確。","❌ 此敘述正確，不選：§160Ⅱ，敘述正確。"],"tr":"標價陳列＝要約；價目表寄送＝要約引誘；變更承諾＝新要約。"},{"id":"civ2-4","p":"civ2","src":"民法模擬試題二 第4題","sec":"A 條件","stem":"下列有關附條件法律行為之敘述，何者正確？","opts":["附停止條件之法律行為，於成立時即生效力","因條件成就而受不利益之當事人，以不正當行為阻其條件之成就者，視為條件不成就","附解除條件之法律行為，於條件成就時，失其效力","條件成否未定前，當事人損害相對人因條件成就所應得之利益，無須負賠償責任"],"ok":[2],"ex":["❌ §99Ⅰ：附停止條件者，於條件成就時發生效力。","❌ §101Ⅰ：視為條件「已成就」。","✅ §99Ⅱ 原文。","❌ §100：負賠償損害之責任。"],"tr":"停止＝成就才生效；解除＝成就即失效；惡意阻止成就＝視為成就；惡意促成成就＝視為不成就。"},{"id":"civ2-5","p":"civ2","src":"民法模擬試題二 第5題","sec":"A 短期時效","stem":"下列請求權，何者因二年間不行使而消滅？","opts":["房屋租金之各期給付請求權","律師之報酬及其墊款請求權","借款本金返還請求權","定期給付之利息各期請求權"],"ok":[1],"ex":["❌ §126：租金各期給付請求權 5 年。","✅ §127⑤。","❌ 一般請求權，§125：15 年。","❌ §126：5 年。"],"tr":"二年短期時效（§127）八款：旅店飲食／運送／動產租賃營業／醫藥／律師會計公證之報酬墊款／律師會計公證所收物件之交還／技師承攬／商人製造供貨。租金利息＝5 年。"},{"id":"civ2-6","p":"civ2","src":"民法模擬試題二 第6題","sec":"B 契約解除","stem":"甲乙訂立房屋買賣契約，乙遲延給付第二期價金。下列敘述何者正確？","opts":["甲得定相當期限催告乙履行，乙於期限內仍不履行時，甲得解除契約","甲得不經催告，逕行解除契約","契約解除後，受領之價金返還時無須加計利息","行使解除權後，不得再請求損害賠償"],"ok":[0],"ex":["✅ §254 原文。","❌ 除 §255 定期行為或 §256 給付不能外，遲延給付須先催告。","❌ §259②：受領之給付為金錢者，應附加自受領時起之利息償還。","❌ §260：解除權之行使，不妨礙損害賠償之請求。"],"tr":"遲延→催告→解除；解除後互負回復原狀（金錢加利息）；損害賠償仍可請求。"},{"id":"civ2-7","p":"civ2","src":"民法模擬試題二 第7題","sec":"B 債權人撤銷權","stem":"下列有關債權人撤銷權之敘述，何者正確？","opts":["債務人所為之有償行為，只要債務人明知有害債權，債權人即得撤銷，不問受益人是否知情","撤銷權自債權人知有撤銷原因時起三年間不行使而消滅","債務人所為之無償行為，須受益人明知有害債權，債權人始得撤銷","債權人行使撤銷權，自債權人知有撤銷原因時起一年間不行使，或自行為時起經過十年而消滅"],"ok":[3],"ex":["❌ §244Ⅱ：須受益人於受益時亦知其情事。","❌ §245：一年。","❌ §244Ⅰ：無償行為，有害及債權者即得撤銷，不問受益人知情與否。","✅ §245 原文。"],"tr":"無償＝有害即可撤銷；有償＝債務人明知＋受益人亦知；撤銷權 1 年／10 年。"},{"id":"civ2-8","p":"civ2","src":"民法模擬試題二 第8題","sec":"B 侵權行為與與有過失","stem":"下列有關損害賠償之敘述，何者正確？","opts":["僱用人對受僱人因執行職務之侵權行為，一律不得免責","侵權行為損害賠償請求權，自知有損害及賠償義務人時起五年間不行使而消滅","損害之發生或擴大，被害人與有過失者，法院得減輕賠償金額，或免除之","故意以背於善良風俗之方法加損害於他人，須有法律明文始負賠償責任"],"ok":[2],"ex":["❌ §188Ⅰ 但書：選任及監督已盡相當注意者，僱用人不負賠償責任。","❌ §197Ⅰ：二年（自行為時起逾十年亦同）。","✅ §217Ⅰ 原文。","❌ §184Ⅰ 後段：本身即為賠償事由。"],"tr":"侵權基本：§184 要件／§188 僱用人（可免責）／§197 二年十年／§217 與有過失。民法申論近年幾乎不考，選擇題掌握基本即可。"},{"id":"civ2-9","p":"civ2","src":"民法模擬試題二 第9題","sec":"B 利息","stem":"下列有關利息之敘述，何者正確？","opts":["未約定利率，亦無法律可據者，週年利率為 10%","約定週年利率 18%，其超過週年 16% 之部分，約定無效","約定週年利率 15% 者，債務人於一年後不得提前清償原本","債務人提前清償之權利，得以契約除去或限制"],"ok":[1],"ex":["❌ §203：週年利率 5%。","✅ §205 原文。","❌ §204Ⅰ：約定利率逾 12%，經一年後債務人得隨時清償原本（須一個月前預告）。","❌ §204Ⅱ：不得以契約除去或限制。"],"tr":"5%（法定）／12%（一年後可提前清償）／16%（超過部分無效）。"},{"id":"civ2-10","p":"civ2","src":"民法模擬試題二 第10題","sec":"C 贈與","stem":"甲以公證書將其房屋贈與乙，尚未移轉登記。下列敘述何者正確？","opts":["經公證之贈與，甲不得依 §408Ⅰ 於權利移轉前任意撤銷","甲仍得依 §408Ⅰ 任意撤銷，因為尚未移轉登記","贈與物有瑕疵者，贈與人一律負擔保責任","受贈人對贈與人有扶養義務而不履行，贈與人之撤銷權自知有撤銷原因時起二年不行使而消滅"],"ok":[0],"ex":["✅ §408Ⅱ：經公證之贈與或履行道德上義務之贈與，不適用任意撤銷。","❌ 經公證者，§408Ⅱ 排除任意撤銷。","❌ §411：原則不負擔保責任，僅故意不告知或保證無瑕疵者負賠償義務。","❌ §416Ⅱ：一年。"],"tr":"任意撤銷（§408）：權利移轉前，但公證／道德義務除外；法定撤銷（§416）：一年；繼承人撤銷（§417）：六個月。"},{"id":"civ2-11","p":"civ2","src":"民法模擬試題二 第11題","sec":"C 承攬","stem":"乙承攬甲之房屋裝修工程，工作尚未完成。下列有關終止契約之敘述，何者正確？","opts":["甲須經乙同意，始得終止契約","甲得隨時終止契約，且無須賠償乙任何損害","甲僅於乙遲延完工時，始得終止契約","甲得隨時終止契約，但應賠償乙因契約終止而生之損害"],"ok":[3],"ex":["❌ §511：定作人得「隨時」終止。","❌ §511 但書：應賠償承攬人因契約終止而生之損害。","❌ §511 不以承攬人遲延為要件。","✅ §511 原文。"],"tr":"承攬＝定作人隨時可終止但賠償；委任＝任何一方隨時可終止，不利時機賠償（§549）。"},{"id":"civ2-12","p":"civ2","src":"民法模擬試題二 第12題","sec":"C 委任報酬","stem":"甲委任乙（有報酬）出售 A 屋，乙處理部分事務後，甲無故終止委任。下列敘述何者正確？","opts":["乙須待事務全部處理完畢，始得請求報酬","僅受任人得隨時終止委任契約，委任人不得","乙得就已處理之部分，請求報酬","甲於不利於乙之時期終止契約，無須賠償"],"ok":[2],"ex":["❌ §548Ⅱ 例外允許就已處理部分請求。","❌ §549Ⅰ：當事人任何一方得隨時終止。","✅ §548Ⅱ：委任關係因非可歸責於受任人之事由，於事務處理未完畢前已終止者，受任人得就已處理之部分請求報酬。","❌ §549Ⅱ：應負損害賠償責任（因非可歸責之事由者除外）。"],"tr":"委任報酬：關係終止＋明確報告顛末後才得請求（§548Ⅰ）；中途終止（非可歸責受任人）→ 已處理部分報酬（Ⅱ）。"},{"id":"civ2-13","p":"civ2","src":"民法模擬試題二 第13題","sec":"D 物上請求權","stem":"乙無權占有甲所有且已登記之 A 地。下列敘述何者正確？","opts":["甲之返還請求權，因 15 年間不行使而消滅","甲得請求乙返還 A 地；所有權以外之物權，準用之","甲須證明乙有故意或過失，始得請求返還","§767 僅適用於所有權，他物權人不得準用"],"ok":[1],"ex":["❌ 釋字第 107 號：已登記不動產所有人之回復請求權，無 §125 消滅時效之適用。","✅ §767Ⅰ、Ⅱ。","❌ §767 不問占有人有無故意過失。","❌ §767Ⅱ：於所有權以外之物權，準用之。"],"tr":"§767 物上請求權三種（返還／除去／防止），不以過失為要件；已登記不動產所有權的物上請求權不適用 15 年時效（釋字107）。"},{"id":"civ2-14","p":"civ2","src":"民法模擬試題二 第14題","sec":"D 時效取得","stem":"下列有關占有取得時效之敘述，何者正確？","opts":["以所有之意思，二十年間和平、公然、繼續占有他人未登記之不動產者，得請求登記為所有人","動產須占有二十年，始能取得所有權","善意無過失占有他人未登記之不動產，須十五年，始得請求登記為所有人","地上權不得因時效而取得"],"ok":[0],"ex":["✅ §769 原文。","❌ §768：動產 10 年；§768-1：善意無過失 5 年。","❌ §770：十年。","❌ §772：前五條規定於所有權以外財產權之取得準用之，於已登記之不動產亦同。"],"tr":"動產 10／5；不動產 20／10；其他財產權準用（109-二 時效取得地上權）。"},{"id":"civ2-15","p":"civ2","src":"民法模擬試題二 第15題","sec":"D 袋地通行","stem":"甲將其所有之 A 地分割為 A1、A2，將 A2 讓與乙，致 A2 與公路無適宜之聯絡。下列敘述何者正確？","opts":["乙得通行任何周圍地，並應支付償金","乙須先取得不動產役權登記，始得通行","乙應擇對周圍地損害最少之處所通行，並支付償金","乙僅得通行讓與人甲或他分割人之所有地，且無須支付償金"],"ok":[3],"ex":["❌ 那是 §787 一般袋地規則；因分割或讓與所生之袋地，通行範圍限於讓與人、受讓人或他分割人之所有地。","❌ 通行權依法律規定而生（§787~§789），不以登記為前提。","❌ 那是 §787Ⅱ 一般袋地規則；§789Ⅱ 無須支付償金。","✅ §789Ⅰ、Ⅱ。"],"tr":"§787（一般袋地：周圍地、損害最少、付償金）vs §789（分割讓與：限於相關人之地、無須付償金）。"},{"id":"civ2-16","p":"civ2","src":"民法模擬試題二 第16題","sec":"D 區分所有","stem":"關於區分所有建築物，下列敘述何者正確？","opts":["專有部分得單獨讓與，而保留其共有部分及基地之應有部分","規約對區分所有人之繼受人一律不生拘束力","區分所有人就共有部分及基地之應有部分，依專有部分面積與專有部分總面積之比例定之，但另有約定者從其約定","規約內容顯失公平者，不同意之區分所有人得於規約成立後六個月內請求法院撤銷"],"ok":[2],"ex":["❌ §799Ⅴ：專有部分與其所屬之共有部分及其基地之權利，不得分離而為移轉或設定負擔。","❌ §799-1Ⅳ：區分所有人間依規約所生之權利義務，繼受人應受拘束。","✅ §799Ⅳ 原文。","❌ §799-1Ⅲ：三個月。"],"tr":"區分所有：專有／共有／基地三者不得分離；規約繼受人受拘束；顯失公平三個月內撤銷。"},{"id":"civ2-17","p":"civ2","src":"民法模擬試題二 第17題","sec":"D 不動產役權","stem":"下列有關不動產役權之敘述，何者正確？","opts":["不動產役權得由需役不動產分離而單獨讓與","需役不動產經分割者，不動產役權為各部分之利益仍為存續；但其行使依性質祇關於需役不動產之一部分者，僅就該部分仍為存續","供役不動產經分割者，不動產役權即歸消滅","不動產役權僅得以通行為目的"],"ok":[1],"ex":["❌ §853：不得由需役不動產分離而為讓與，或為其他權利之標的物。","✅ §856 原文。","❌ §857：就其各部分仍為存續（但性質只關於一部分者僅對該部分存續）。","❌ §851：通行、汲水、採光、眺望、電信或其他以特定便宜之用為目的。"],"tr":"不動產役權（舊地役權）：從屬於需役不動產；分割後仍存續。"},{"id":"civ2-18","p":"civ2","src":"民法模擬試題二 第18題","sec":"D 最高限額抵押權","stem":"下列有關最高限額抵押權之敘述，何者正確？","opts":["確定期日之約定，自抵押權設定時起不得逾三十年；逾三十年者，縮短為三十年","所擔保之債權，不以由一定法律關係所生或基於票據所生者為限","未約定確定期日者，自請求之日起經三十日為其確定期日","所擔保之債權，於原債權確定前讓與他人者，最高限額抵押權隨同移轉"],"ok":[0],"ex":["✅ §881-4Ⅱ 原文。","❌ §881-1Ⅱ：以由一定法律關係所生之債權或基於票據所生之權利為限。","❌ §881-5Ⅱ：十五日。","❌ §881-6Ⅰ：不隨同移轉。"],"tr":"最高限額：一定法律關係／確定期日 30 年／請求確定 15 日／確定前讓與不隨同。"},{"id":"civ2-19","p":"civ2","src":"民法模擬試題二 第19題","sec":"D 強制執行與法定地上權","stem":"甲有 A 地及其上 B 屋（均未設定抵押權），乙聲請強制執行拍賣 A 地，由丙拍定，B 屋仍屬甲所有。下列敘述何者正確？","opts":["丙得請求甲拆屋還地","須設定抵押權時土地與建物同屬一人，始有法定地上權","該地上權不因建築物之滅失而消滅","視為已有地上權之設定，其地租、期間及範圍由當事人協議；不能協議者，得請求法院以判決定之"],"ok":[3],"ex":["❌ §838-1Ⅰ 視為已有地上權設定，丙不得請求拆屋還地。","❌ 那是 §876 抵押權情形；強制執行拍賣適用 §838-1，不以設定抵押權為前提。","❌ §838-1Ⅱ：此地上權因建築物之滅失而消滅（與一般地上權 §841 不同）。","✅ §838-1Ⅰ 原文。"],"tr":"法定地上權兩條：§876（抵押權拍賣，設定時同屬一人）／§838-1（強制執行拍賣，土地建物同屬一人）。後者建物滅失即消滅。"},{"id":"civ2-20","p":"civ2","src":"民法模擬試題二 第20題","sec":"E 結婚","stem":"下列有關結婚之敘述，何者錯誤？","opts":["男女未滿十八歲者，不得結婚","結婚應以書面為之，有二人以上證人之簽名，並應由雙方當事人向戶政機關為結婚之登記","違反重婚禁止之結婚，得由當事人請求法院撤銷","因被詐欺而結婚者，得於發見詐欺終止後六個月內向法院請求撤銷"],"ok":[2],"ex":["❌ 此敘述正確，不選：§980 原文。","❌ 此敘述正確，不選：§982 原文。","✅ 此敘述錯誤（本題答案）：§988③：重婚的結婚為「無效」（但書情形除外），不是得撤銷。","❌ 此敘述正確，不選：§997 原文。"],"tr":"結婚無效（§988：方式、近親、重婚）vs 得撤銷（未達法定年齡、詐欺脅迫、不能人道等）。"},{"id":"civ2-21","p":"civ2","src":"民法模擬試題二 第21題","sec":"E 裁判離婚","stem":"甲知悉其配偶乙與丙合意性交之事實後，事前未同意、事後亦未宥恕，但拖延七個月才訴請離婚（該情事發生距今約一年）。下列敘述何者正確？","opts":["甲得請求離婚，不受期間限制","甲不得請求離婚，因知悉後已逾六個月","甲不得請求離婚，因自情事發生後已逾一年","甲不得請求離婚，因知悉後已逾三個月"],"ok":[1],"ex":["❌ §1053 就 §1052Ⅰ①② 設有除斥期間。","✅ §1053：有請求權之一方，知悉後已逾六個月，或自其情事發生後已逾二年，不得請求離婚。","❌ §1053 的「情事發生後」期間是二年，不是一年。","❌ §1053 知悉後期間為六個月。"],"tr":"§1053：事前同意／事後宥恕／知悉後 6 個月／發生後 2 年——四擇一即不得請求離婚（限重婚、合意性交兩款）。"},{"id":"civ2-22","p":"civ2","src":"民法模擬試題二 第22題","sec":"E 非婚生子女","stem":"下列有關非婚生子女之敘述，何者正確？","opts":["非婚生子女經生父撫育者，視為認領","非婚生子女與其生母之關係，須經生母認領始視為婚生子女","生父認領非婚生子女後，無論如何均不得撤銷","認領之訴於生父死亡後即不得提起"],"ok":[0],"ex":["✅ §1065Ⅰ 後段。","❌ §1065Ⅱ：與生母之關係視為婚生子女，無須認領。","❌ §1070 但書：有事實足認其非生父者，不在此限。","❌ §1067Ⅱ：生父死亡後，得向生父之繼承人為之。"],"tr":"認領：生父認領／撫育視為認領；生母無須認領；撤銷限於非生父。"},{"id":"civ2-23","p":"civ2","src":"民法模擬試題二 第23題","sec":"E 收養","stem":"下列有關收養之敘述，何者正確？","opts":["收養者之年齡，只須長於被收養者十六歲以上","除夫妻共同收養外，一人得同時為二人之養子女","收養應以口頭為之即可，無須向法院聲請認可","養子女與本生父母及其親屬間之權利義務，於收養關係存續中停止之"],"ok":[3],"ex":["❌ §1073Ⅰ：原則須長於被收養者二十歲以上；夫妻共同收養時一方二十歲、他方十六歲；§1073Ⅱ 繼親收養長十六歲。","❌ §1075：除夫妻共同收養外，一人不得同時為二人之養子女。","❌ §1079Ⅰ：應以書面為之，並向法院聲請認可。","✅ §1077Ⅱ：停止（但夫妻之一方收養他方之子女者，他方與其子女之權利義務不受影響）。"],"tr":"收養：書面＋法院認可；年齡差 20（例外 16）；養子女本生關係停止；不得同時為二人養子女。"},{"id":"civ2-24","p":"civ2","src":"民法模擬試題二 第24題","sec":"E 隱匿遺產","stem":"繼承人丙隱匿遺產，情節重大。下列敘述何者正確？","opts":["丙當然喪失繼承權","丙之應繼分歸屬國庫","丙不得主張 §1148Ⅱ 所定之利益，即不得主張以因繼承所得遺產為限負清償責任","丙仍得主張以所得遺產為限負清償責任，隱匿遺產不影響"],"ok":[2],"ex":["❌ §1145 喪失繼承權的事由不含隱匿遺產；隱匿遺產只是喪失限定責任的利益（§1163）。","❌ 隱匿遺產不在 §1145 喪失繼承權五款之內，丙仍是繼承人、應繼分仍歸丙，效果只是依 §1163① 不得主張限定責任。遺產歸屬國庫只發生在無人承認繼承、清償債權並交付遺贈物後尚有賸餘時（§1185），與本題無關。","✅ §1163①：隱匿遺產情節重大者，不得主張 §1148Ⅱ 之利益。","❌ §1163 明文剝奪該利益。"],"tr":"喪失繼承權（§1145 五款，如殺害、偽造遺囑）≠ 喪失限定責任利益（§1163：隱匿、虛偽記載、詐害債權人處分）。"},{"id":"civ2-25","p":"civ2","src":"民法模擬試題二 第25題","sec":"E 遺產分割","stem":"下列有關遺產分割之敘述，何者正確？","opts":["遺囑禁止遺產分割之效力，以二十年為限","遺囑禁止遺產之分割者，其禁止之效力以十年為限","胎兒為繼承人時，其他繼承人得逕行分割遺產，毋須保留其應繼分","繼承人於繼承開始前因結婚受被繼承人贈與，縱被繼承人於贈與時有反對意思表示，仍須歸扣"],"ok":[1],"ex":["❌ §1165Ⅱ：十年。","✅ §1165Ⅱ 原文。","❌ §1166Ⅰ：非保留其應繼分，他繼承人不得分割遺產。","❌ §1173Ⅰ 但書：被繼承人有反對意思表示者，不在此限。"],"tr":"遺產分割：隨時請求（§1164）／遺囑禁止 10 年／胎兒保留應繼分／歸扣（結婚分居營業）。"},{"id":"h:114-1","p":"h","src":"114年第1題","sec":"A1","stem":"依我國民法有關死亡宣告之規定，下述何者錯誤？","opts":["失蹤人遺留之與他人共有不動產之共有人，得聲請對失蹤人為死亡宣告","失蹤人已年滿 80 歲，其失蹤期間應滿 3 年後，始得被聲請死亡宣告","失蹤人受死亡宣告後，生存歸來時，得聲請地檢署撤銷死亡宣告","受死亡宣告之失蹤人實際上仍生存時，其權利能力不因死亡宣告而喪失"],"ok":[2],"ex":["共有不動產之其他共有人，因失蹤人之財產狀況與其有法律上利益關係，屬利害關係人，得聲請死亡宣告，正確。","失蹤人年滿80歲，依§8Ⅱ，失蹤期間屆滿三年，即得聲請死亡宣告（縮短期間），正確。","撤銷死亡宣告須向「法院」聲請撤銷（家事事件），並非向「地檢署」聲請，兩者管轄機關不同，敘述錯誤，為應選答案。","死亡宣告係「推定」死亡，若實際仍生存，其權利能力不因此宣告而喪失，正確。"],"tr":""},{"id":"h:114-2","p":"h","src":"114年第2題","sec":"A1","stem":"我國民法修正時，增訂有關監護宣告及輔助宣告制度之規定。依現行民法相關之規定，下列何者錯誤？","opts":["受監護宣告之成年人，無行為能力","成年人因精神障礙或其他心智缺陷，致其辨識其意思表示效果之能力顯有不足者，得因聲請，對其為監護之宣告","受監護宣告之成年人，仍保有完全之權利能力","受輔助宣告之成年人逕自締結汽車之買賣契約，該契約不因欠缺輔助人之事前同意而無效"],"ok":[1],"ex":["§15 受監護宣告之人無行為能力。","「辨識效果能力顯有不足」是輔助宣告之要件（§15-1）；監護宣告為不能辨識（§14）。","§6 權利能力始於出生終於死亡，監護宣告不影響權利能力。","受輔助宣告之人欠缺輔助人同意之行為為效力未定（§15-2Ⅱ 準用§78至§83），並非無效。"],"tr":""},{"id":"h:114-3","p":"h","src":"114年第3題","sec":"A2","stem":"下列敘述，何者與民法法人之規定並不相容？","opts":["民法關於公益社團法人之設立，係採取許可主義","法人解散後，在清算程序中，在清算之必要範圍內，仍具有法人格","法人之權利能力，受到性質上之限制，因此無法享有民法賦予自然人所有之人格權利","財團法人之設立，捐助人亦得以遺囑捐助之方式為之，且以此種方式設立之財團法人，無須訂立捐助章程"],"ok":[2],"ex":["公益社團法人採許可主義，須經主管機關許可（§46），正確。","§40Ⅱ：法人至清算終結止，在清算之必要範圍內，視為存續，故解散後清算中仍有法人格，正確。","法人之權利能力確受「性質」限制（§26但書，專屬自然人之權利除外），但法人「並非無法享有任何人格權」：如名譽權（商譽）、名稱權等，法人均得享有，故「無法享有民法賦予自然人所有之人格權利」過於絕對，與民法規定不相容，為應選答案。","§60Ⅰ但書：設立財團應訂立捐助章程，但以遺囑捐助者不在此限，故以遺囑捐助設立財團法人，無須另訂捐助章程（無遺囑執行人時，法院得依§60Ⅲ指定遺囑執行人），選項與民法規定相容，正確。"],"tr":""},{"id":"h:114-4","p":"h","src":"114年第4題","sec":"A2","stem":"甲當選 A 法人董事，準備大顯身手，下列敘述何者錯誤？","opts":["就 A 法人一切事務，甲可代表 A 法人","A 法人可僅設甲一位董事","A 法人若對甲董事之代表權加以限制，其限制得對抗任何第三人","若 A 法人僅有甲與丙兩位董事，則該法人事務之執行，若兩人意見相左，則恐陷入表決的僵局"],"ok":[2],"ex":["§27Ⅱ：董事就法人一切事務，對外代表法人，正確。","§27Ⅰ：法人應設董事；僅董事有數人時才適用過半數決，法律並無最低名額限制，法人可僅設一位董事，正確。","§27Ⅲ：對於董事代表權所加之限制，「不得對抗善意第三人」；選項說「得對抗任何第三人」，與條文相反，為應選答案。","§27Ⅰ：董事有數人者，法人事務之執行除章程另有規定外，取決於全體董事過半數之同意；僅兩人意見相左（1：1）達不到過半數，確實可能陷入僵局，正確。"],"tr":""},{"id":"h:114-5","p":"h","src":"114年第5題","sec":"A1","stem":"有關自然人從事有效法律行為之情形，依現行民法規定，應以具備完全之行為能力為其要件。對此，下列相關之選項何者正確？","opts":["年滿 16 歲之人，取得完全行為能力","15 歲之人得逕行有效撤銷被他人詐欺而締結日常生活所需之買賣契約","14 歲之未成年人得有效書立遺囑","某成年人被法院為輔助之宣告，若未得輔助人事前同意，即締結消費借貸契約，其得於法院撤銷該輔助宣告後，承認該消費借貸契約，使之逕行生效"],"ok":[3],"ex":["滿18歲才取得完全行為能力，滿16歲仍為限制行為能力人。","撤銷為單獨行為，限制行為能力人單獨為之須經法定代理人允許（§78），不得逕行撤銷。","§1186Ⅱ 未滿16歲不得為遺囑。","輔助宣告撤銷後，本人可承認效力未定之行為（§15-2Ⅱ 準用§81Ⅰ），使之確定有效。"],"tr":""},{"id":"h:114-6","p":"h","src":"114年第6題","sec":"A3","stem":"民法規定權利客體中動產、不動產之定義、種類及變動之法定方式；依該規定之內容，下列何者屬於正確之敘述？","opts":["甲在所有 A 地種植芭樂樹，樹上之芭樂成熟時，即已成為獨立之動產","甲為慶祝關聖帝君生日臨時搭建完成之表演舞台，屬於甲獨立取得之定著物所有權","甲移轉買賣標的物之 A 地予乙，甲、乙完成 A 地所有權讓與合意並交付 A 地後，乙即成為 A地之新所有權人","甲在 A 地池塘養殖金魚，池中金魚所生金魚苗，由甲取得該金魚苗之獨立動產物權"],"ok":[3],"ex":["芭樂成熟但尚未採收，仍為土地之一部分（§66Ⅱ），尚非獨立動產。","臨時搭建之舞台非繼續附著，不屬定著物，不能取得定著物所有權。","不動產所有權移轉須書面並登記（§758），僅合意與交付尚未取得所有權。","金魚苗為金魚之天然孳息（§69Ⅰ），與原物分離後為獨立動產，由甲取得（§70Ⅰ）。"],"tr":""},{"id":"h:114-7","p":"h","src":"114年第7題","sec":"A5","stem":"不同之權利主體以法律行為方式，形成了彼此間之法律關係。嗣後，當事人一方發現自己已為之意思表示發生錯誤，乃依民法第 88 條規定行使撤銷權。下列相關之敘述，何者錯誤？","opts":["該錯誤之意思表示若因表意人之過失所致時，表意人不得撤銷其所為之意思表示","該錯誤必須在交易上被認為具有重要性","錯誤之表意人必須在意思表示後，於 2 年內行使撤銷權，反之於除斥期間經過後，該法律關係即應繼續有效存續","錯誤之表意人撤銷其意思表示後，對於相對人應承擔信賴該法律行為有效而生之損害賠償責任"],"ok":[2],"ex":["§88Ⅰ但書，表意人之錯誤若由其過失所致，不得撤銷，正確。","依通說，錯誤須具重要性（交易上認為重要）始得撤銷；條文明定「交易上認為重要」者為§88Ⅱ（當事人資格或物之性質之錯誤），正確。","§90：§88、§89的撤銷權，「自意思表示後，經過一年而消滅」（除斥期間為意思表示後1年，非2年）；選項的「2年」錯誤，故為應選答案。（後半句「除斥期間經過後，法律關係繼續有效」方向正確。）","§91：依§88、§89撤銷意思表示時，表意人對於信其意思表示為有效而受損害之相對人或第三人，應負賠償責任（但受害人明知或可得而知撤銷原因者除外），正確。"],"tr":""},{"id":"h:114-8","p":"h","src":"114年第8題","sec":"B5","stem":"關於無因管理之制度，下列何者非屬我國民法相關規範之內容？","opts":["無因管理人誤將客觀上屬於自己事務當作他人之事務，而為事務之管理者，不成立民法之無因管理","無因管理人違反本人明示或可得推知之意思，代本人繳納贈與稅捐，得依民法第 176 條之規定，請求本人返還","管理人為免除本人生命之急迫危險，因重大過失造成本人財產上之損害，亦無須負損害賠償的責任","管理人明知為他人事務，卻違反本人明示或可得推知之意思或僅為自己利益，而為他人事務之管理者，本人主張管理事務之利益時，對管理人負第 176 條第 1 項之義務，以其所得利益為限"],"ok":[2],"ex":["管理他人事務須有為他人管理之意思（§172），客觀上屬自己的事務並非『他人事務』，不成立無因管理。","代繳贈與稅屬為本人盡公益上義務，§174 II 不適用違反本人意思之規定，管理人依§176 II 仍得依§176 I 請求返還。","§175：為免除本人生命、身體或財產上急迫危險而管理者，僅就惡意或重大過失負賠償責任，重大過失仍須負責。","§177Ⅰ：管理事務不合於§176時，本人仍得享有利益，其義務以所得利益為限；明知為他人事務而為自己利益管理者準用之。"],"tr":""},{"id":"h:114-9","p":"h","src":"114年第9題","sec":"A6","stem":"甲授與乙代理權，並委任乙與丙商談甲買受丙所有房屋及辦理移轉所有權之事宜。下列敘述何者錯誤？","opts":["本件代理權的授與和委任契約二者均須書面","若丙自始至終不知道乙為甲的代理人，且債權契約和物權契約當事人簽乙的名字，則本件法律效果無法歸屬於甲","若甲知道丙欺騙乙，把房屋的優點講得天花亂墜，但甲仍要乙代理他買下房屋，則甲事後不得主張受詐欺撤銷意思表示","甲跟乙說好，最多出價 1 億元，1 億元的事情沒寫在書面，乙和丙講價的結果，被丙說服用行情價 1 億 1 千萬簽訂契約。該買賣契約在 1 億元價金的範圍內有效"],"ok":[3],"ex":["買賣不動產之物權移轉，依§758Ⅱ應以書面為之；該法律行為依法應以文字為之者，其委任處理權之授與及代理權之授與，也都應以文字為之（§531），正確。","§103Ⅰ：代理人於代理權限內「以本人名義」所為之意思表示，直接對本人發生效力（顯名主義）；乙以自己名義簽約，並未顯名，效果不歸屬甲，正確。","§105本文：代理人意思表示因被詐欺等致效力受影響者，其事實之有無就代理人決之；但代理權以法律行為授與、且代理人依本人所指示之意思而為者，其事實之有無就本人決之（§105但書）。本題甲指示乙買下該屋，且甲自己明知丙在誇大（並未受騙），故不得以受詐欺為由撤銷，選項正確。","乙逾越甲授權的1億元上限，以1億1千萬簽約，屬無權代理（超越代理權限），依§170Ⅰ，非經本人承認，對本人不生效力；該契約並非當然「在1億元範圍內有效」，而是整體效力未定，須由甲承認或拒絕，故本選項錯誤，為應選答案。"],"tr":""},{"id":"h:114-10","p":"h","src":"114年第10題","sec":"B6","stem":"下述情形，何者不符合我國民法侵權行為之規定？","opts":["加害人因過失致直接被害人死亡，因直接被害人已喪失權利能力，無須對直接被害人負非財產上之損害賠償","承攬人於執行承攬事務不法侵害他人之權利，除定作人於定作或指示有過失者，原則上定作人無須負損害賠償責任","限制行為能力人不法侵害他人權利，且於行為時無識別能力，其法定代理人對被害人亦無須負擔賠償責任","受僱人執行職務，因過失不法侵害他人之權利，如僱用人對於受僱人已盡選任、監督相當之注意義務，僱用人不負賠償責任"],"ok":[2],"ex":["被害人本人死亡後已無權利能力，無從向其賠償非財產損害；§194 的慰撫金是賠給特定親屬。","§189：承攬人執行承攬事項不法侵害他人，定作人原則上不負賠償責任，但定作或指示有過失者不在此限。","§187 I：限制行為能力人行為時無識別能力者，由其法定代理人負損害賠償責任，並非免責。","§188 I 但書：僱用人證明選任受僱人及監督其職務之執行已盡相當注意者，不負賠償責任。"],"tr":""},{"id":"h:114-11","p":"h","src":"114年第11題","sec":"B1","stem":"甲賣給乙一隻狗狗，名喚 S，乙光看甲提供的 S 犬照片就喜歡的不得了，馬上承諾以 10 萬元的價金訂立契約。下列何者錯誤？","opts":["若 S 實則在甲、乙訂立契約前已死亡，則甲、乙契約無效","若 S 身上有跳蚤，並傳染給乙的貓咪 B 和乙家的環境，則甲應負加害給付責任","若 S 其實是甲母的狗，僅因甲母出國，暫時寄放於甲處，則乙即使已經把 S 抱回家照顧，乙絕不可能取得 S 的所有權","若乙向甲主張交付 S，甲得主張同時履行抗辯"],"ok":[2],"ex":["買賣標的訂約前已滅失屬原始給付不能，契約無效（§246 I 前段）。","S 之跳蚤傳染乙之貓與環境，屬瑕疵給付造成固有利益損害，為加害給付，依§227 II 負賠償責任。","動產他人之物，若乙善意受讓並受占有交付，得依§801、§948 善意取得；「絕不可能」取得之敘述過於絕對，錯誤。","買賣為雙務契約，乙請求交付 S，甲得依§264 主張同時履行抗辯（乙未付價金）。"],"tr":""},{"id":"h:114-12","p":"h","src":"114年第12題","sec":"C2","stem":"甲將房屋租給乙。下列何者正確？","opts":["租期若超過 1 年，且未寫書面契約，則租賃契約無效","若未特別約定，則乙有權將其中的房間分租給丙","若未特別約定，則乙有權將承租人的地位債權讓與給丙","若雙方約定租期 3 年，3 年過後乙默默繳房租，甲默默收房租，則雙方均不得主張租賃契約默示更新"],"ok":[1],"ex":["§422：不動產租賃期限逾1年而未以字據訂立者，視為不定期租賃，並非無效。","§443 I 但書：租賃物為房屋者，除有反對約定外，承租人得將其一部分轉租。","承租人地位屬契約承擔，須經出租人同意；單純債權讓與只能讓與租賃債權，不能讓與承租人整體地位。","§451：租期屆滿後承租人仍使用收益，出租人不即表示反對者，視為以不定期限繼續契約，故得主張默示更新。"],"tr":""},{"id":"h:114-13","p":"h","src":"114年第13題","sec":"B2","stem":"對於權利主體間之贈與契約，依我國民法規定，下列何者為正確之論述？","opts":["在經公證之贈與契約，贈與人因可歸責之事由致給付遲延，受贈人得依民法第 231 條之規定請求贈與人對於遲延給付造成之損害，負賠償責任","依現行民法之規定，以不動產為標的之贈與契約，屬於具要物性之法律行為","贈與人所贈與之標的物本身具有瑕疵，贈與人應負無過失之擔保責任","贈與人所贈與之標的物具有瑕疵，造成受贈人之損害，僅於贈與人故意不告知其瑕疵或保證其無瑕疵時，始得請求賠償"],"ok":[3],"ex":["§409Ⅱ：贈與人給付遲延時，受贈人不得請求遲延利息或其他不履行之損害賠償，故不得依§231 請求（公證不影響此規則）；§410 僅規定贈與人就故意或重大過失負給付不能之責任。","贈與為諾成契約（§406），不動產贈與不以交付為成立要件，非要物行為。","§411：贈與物有瑕疵，贈與人原則不負擔保責任。","§411 但書：贈與人故意不告知其瑕疵或保證其無瑕疵者，對受贈人因瑕疵所生損害負賠償義務。"],"tr":""},{"id":"h:114-14","p":"h","src":"114年第14題","sec":"C4","stem":"甲、乙兩人合夥開了一家小麵館 M，生意興隆。下列何者錯誤？","opts":["如甲在麵館以外之場所猥褻 K，乙無須對 K 負連帶損害賠償責任","麵體供應商 J 多次索取買賣價金均無果，J 得以 M 為被告請求履行債務","甲、乙兩人想把 M 收起來，尚須經清算程序","M 麵館的餐具是甲提供的、攤車是乙提供的，當麵館持續在營業時，餐具的所有權仍是甲的、攤車的所有權仍是乙的"],"ok":[3],"ex":["合夥為非法人團體，合夥人在合夥事務之外的個人侵權行為，不屬合夥事務，乙不須連帶負責。","合夥為非法人團體，設有代表人或管理人者有當事人能力（民事訴訟法§40 III），J 得以合夥為被告。","合夥解散後須經清算程序（§694 以下）。","§668：合夥人出資及合夥財產為全體合夥人公同共有，餐具與攤車作為出資後已屬公同共有，非各自所有。"],"tr":""},{"id":"h:114-15","p":"h","src":"114年第15題","sec":"D4","stem":"依現行民法物權編有關不動產所有權相鄰關係規定之內容，下列之選項，何者正確？","opts":["土地所有人建築房屋故意逾越地界者，法院得斟酌公共利益後，能允許鄰地所有人請求移去或變更","共有土地因分割，致其中一共有人所取得分得土地與公路無適宜之聯絡，無法為通常之使用，應支付償金，取得通行他分割人所有地之權利","果實自落於鄰地，推定由鄰地所有人取得所有權","鄰地所有人因營造或修繕建築物之必要，得使用土地所有人之土地及其上建物內部閒置之空間。但受有損害時，則得拒絕鄰地所有人之使用"],"ok":[0],"ex":["§796-1 I 但書：故意越界者，法院不得免為移去，故鄰地所有人之移去或變更請求應被允許。","§789 I、II：土地分割致不通公路者，通行分割人之土地，通行權人無須支付償金。","§798：果實自落鄰地者「視為」屬於鄰地所有人，非推定。","§792：營造修繕建築物有使用土地之必要者，應許使用，受損害者僅得請求償金，不得拒絕。"],"tr":""},{"id":"h:114-16","p":"h","src":"114年第16題","sec":"D2","stem":"甲、乙兩人共有 A 地，應有部分甲為 1/3、乙為 2/3。下列何者錯誤？","opts":["若甲、乙協議 20 年內不得分割，則在該期限內，不論發生任何事由，甲、乙均不得請求分割","甲得在未經乙的同意下，將其應有部分贈與及移轉給丁","若甲商請乙分割 A 地未果，甲可聲請法院分割 A 地，此時法院須優先考慮原物分配","A 地由丙無權占有使用，乙得在未經甲的同意下請求丙返還 A 地"],"ok":[0],"ex":["§823 III：約定不分割期間有重大事由時，共有人仍得隨時請求分割；同條II：不分割約定一般不得逾5年；共有不動產訂有管理約定者不得逾30年。","§819 I：共有人得自由處分其應有部分，贈與並移轉予丁無須他共有人同意。","§824 II：法院分割以原物分配為優先，必要時得變賣或補償。","§821：各共有人得為全體利益，請求無權占有人返還共有物全部。"],"tr":""},{"id":"h:114-17","p":"h","src":"114年第17題","sec":"D5","stem":"依我國民法關於地上權之規定，下列何者正確之論述？","opts":["地上權未定有存續期間者，逾越 30 年後，土地所有人始得向法院請求，定其後續之存續期間，或終止該地上權","地上權人因不可抗力之事由導致妨礙其行使地上權使用時，得拒絕或減少地租之支付","地上權人積欠地租達 2 年總額時，除另有習慣外，土地所有人得逕行終止存續期限尚未屆至之地上權","已設定地上權之土地所有權人，於地上權存續期間讓與該土地所有權與第三人，已預收之地租如已登記，地上權人得以該預付地租對抗受讓之第三人"],"ok":[3],"ex":["§833-1：地上權未定有期限，存續期間逾20年或成立目的已不存在時，法院得因當事人請求定其存續期間或終止；門檻是20年，非30年。","§837：不可抗力妨礙使用，不得拒絕或減少地租之支付。","§836 I：積欠二年總額須先定期催告，逾期不付才得終止，不得逕行終止。","§836-1：預付地租經登記，得對抗土地所有權之受讓人。"],"tr":""},{"id":"h:114-18","p":"h","src":"114年第18題","sec":"D6","stem":"關於占有，下列何者錯誤？","opts":["占有於我國為事實，而非占有權","無權占有人亦有占有物返還請求權","占有與取得時效有關","惡意占有人，因保存占有物所支出之必要費用，不得請求償還"],"ok":[3],"ex":["占有為事實，非權利；占有權之說法不採（§940）。","無權占有人亦受占有保護，§962 占有人被侵奪得請求返還。","§768、§769、§770：時效取得須以占有為要件之一。","§957：惡意占有人因保存占有物支出之必要費用，得依無因管理規定請求償還，並非不得請求。"],"tr":""},{"id":"h:114-19","p":"h","src":"114年第19題","sec":"D4","stem":"甲所有的 A 地與乙所有的 B 地相鄰。下列何者正確？","opts":["A 地兩面環山、第三面環河，僅能經過 B 地通行於道路，則甲須經乙的同意，始得取得對 B 地的通行權","A 地一面環山、一面環河、一面接著大馬路、一面緊鄰 B 地，甲聽信風水師的建議，將面臨大馬路的那一面築起無門的高牆因此無法通行，則甲須經乙的同意，始得取得對 B 地的通行權","袋地通行權性質上並非供役地所有權本質上的限縮","若甲在 A 地上蓋房子，因為土地測量單位的疏失，該建築有 30 公分越界到 B 地，此時乙得知此狀況，若沒有馬上阻止，則之後仍可請求甲拆屋還地"],"ok":[1],"ex":["袋地所有人依§787得通行周圍地以至公路，屬法定通行權，不須經鄰地所有人同意。","§787 I但書：袋地因土地所有人之任意行為所生者，不得主張通行權；甲自築高牆致無法通行，欠缺法定通行權，須與乙協商取得約定通行權（乙同意）。","袋地通行權使供役地所有人負容忍義務，對供役地而言構成所有權行使的限制（§787）。","§796：越界建築非因故意或重大過失，鄰地所有人知其越界而不即異議者，不得請求移去或變更建築物，僅得請求土地所有人以相當價額購買越界部分土地及因此形成之畸零地（§796 II），並請求支付損害之償金（§796 I 但書），故不能請求拆屋還地。"],"tr":""},{"id":"h:114-20","p":"h","src":"114年第20題","sec":"E2","stem":"甲、乙結婚後未約定夫妻財產制時，下列有關甲、乙間之配偶財產關係之論述，何者錯誤？","opts":["甲所有之婚前購買之有價證券，於甲、乙婚後，甲取得該有價證券分配之股息或利息，於甲、乙離婚時，乙得主張該分配之股息或利息，納入剩餘財產為分配計算之標的","甲於婚後以自己之財產清償乙所負之債務後，即使在婚姻關係中，仍得請求乙償還","甲、乙離婚時，對於婚後乙受贈之財產，如未經贈與人以書面聲明為乙之特有財產時，即應納入乙之婚後財產，成為剩餘財產分配計算之標的","甲、乙離婚時，乙知悉剩餘財產分配計算之差額，僅得自法定財產關係消滅時起 2 年內，向甲主張給付該差額之二分之一"],"ok":[2],"ex":["§1017 II：婚前財產之孳息視為婚後財產，離婚時屬剩餘財產分配計算範圍（§1030-1）。","§1023 II：夫妻之一方以自己財產清償他方之債務時，雖於婚姻關係存續中，亦得請求償還。","婚後受贈財產屬無償取得，依§1030-1 I①不列入剩餘財產分配，無須贈與人書面聲明。","平均分配（二分之一）正確，但請求權時效依§1030-1V是「自知有剩餘財產之差額時起2年」，或「自法定財產制關係消滅時起逾5年」，選項寫「消滅時起2年」與條文不符，D亦屬錯誤敘述。本題依條文C、D皆錯，官方答案為C；作答依官方答案選C。"],"tr":""},{"id":"h:114-21","p":"h","src":"114年第21題","sec":"E4","stem":"民法對於法定繼承人及其順序，於第 1138 條設有明文規定。下列相關之說明，何者正確？","opts":["被繼承人死亡時之配偶，於被繼承人死亡後 2 年內再婚者，喪失其原已取得之繼承權","被繼承人死亡時，其已出家之子女，無繼承之資格與地位","養子女與養父母之親生子女，雖因法律擬制而為旁系親屬，然因欠缺真實血緣關係，非屬民法第 1138 條第 3 順位之法定繼承人","父再婚之後妻，與前妻之子女，僅為直系姻親關係，因此後妻對於前妻子女之死亡，無繼承其遺產之權利"],"ok":[3],"ex":["§1138配偶繼承權不因被繼承人死亡後再婚而喪失。","出家不影響繼承資格，子女仍為第一順序繼承人。","養子女視為婚生子女（§1077 I），與養父母之婚生子女互為兄弟姊妹，屬第三順序兄弟姊妹。","後妻與前妻子女為直系姻親，非血親，無繼承權（§1138僅配偶及血親）。"],"tr":""},{"id":"h:114-22","p":"h","src":"114年第22題","sec":"E4","stem":"我國現行民法對於繼承制度，原則上採取概括繼承有限責任之規範型態。下列何者屬於正確之敘述？","opts":["概括繼承人如對於被繼承人生前享有權利或負擔義務，不因被繼承人之死亡而隨之消滅","第 1138 條所定第 1 順序之繼承人中有拋棄繼承權者，其應繼分應由其直系血親卑親屬代位繼承之","繼承人對於被繼承人所遺留之債務，對於被繼承人之債權人，負連帶清償之責任","拋棄繼承者，就自己所管理之遺產，於其他繼承人或遺產管理人開始管理前，應以善良管理人之注意義務，繼續管理該遺產"],"ok":[0],"ex":["§1148 I：繼承人自繼承開始時概括承受被繼承人財產上之一切權利義務（專屬者除外），權利義務不因死亡而消滅。","代位繼承限於先死亡或喪失繼承權（§1140），拋棄不代位。","§1153 I：繼承人對被繼承人債務係「以所得遺產為限」負連帶責任，選項漏此限制。","§1176-1：拋棄繼承者就所管理之遺產，應與處理自己事務為同一之注意，非善良管理人注意。"],"tr":""},{"id":"h:114-23","p":"h","src":"114年第23題","sec":"E4","stem":"依我國民法有關遺囑之規定，下列敘述何者錯誤？","opts":["甲立遺囑，遺囑中將 A 地贈與好友乙。乙於甲之遺囑生效前意外死亡，其後甲重病身亡，乙之繼承人丙得向甲之繼承人丁請求移轉交付 A 地所有權予自己","甲遺囑中遺贈予乙之 A 車，因丙之過失毀損，甲之遺囑生效時，推定對丙之權利成為遺贈之客體，乙得向甲之繼承人丁請求移轉該權利予自己","甲以遺囑贈與 A 屋予好友乙，遺囑生效時，甲之繼承人丙寄存證信函請求乙 30 日內回函確認，乙置之不理，期限屆滿時，該遺囑中之遺贈，仍然確定生效","甲以遺囑贈與 A 屋予好友乙，遺囑生效前，甲將 A 屋出賣予丙取得價金 1 千萬元之債權，甲請求丙將該價金 1 千萬元直接捐贈予丁慈善基金會。甲之遺囑生效時，遺囑中 A 屋之遺贈應屬無效"],"ok":[0],"ex":["§1201：受遺贈人於遺囑發生效力前死亡者，其遺贈不生效力，丙不得請求。","§1203：遺贈物因毀損而對他人取得權利者，推定以其權利為遺贈，乙得請求移轉該權利。","§1207：繼承人得定期限請求受遺贈人表示承認與否，期限屆滿未表示者視為承認遺贈，遺贈確定生效。","§1221：遺囑人為遺囑後所為行為與遺囑相牴觸者，牴觸部分遺囑視為撤回，A屋遺贈不生效力。"],"tr":""},{"id":"h:114-24","p":"h","src":"114年第24題","sec":"E4","stem":"關於生前特種贈與的歸扣，下列何者錯誤？","opts":["生前特種贈與，包括因結婚、分居、營業所為之贈與","須有其他繼承人行使歸扣權，始須歸扣","一般認為，生前特種贈與之被繼承人有應繼分前付之意思","即使被繼承人於贈與時有反對意思表示，仍應歸扣"],"ok":[3],"ex":["§1173 I：因結婚、分居、營業所受之贈與屬歸扣範圍。","歸扣係繼承人間公平機制（§1173），由其他繼承人於分割時主張，始將贈與價額列入計算（§1173條文未明定行使方式，此為命題採取之學說見解）。","通說認為特種贈與係被繼承人預先給付之應繼分（應繼分前付）。","§1173 I但書：被繼承人於贈與時有反對意思表示者，不在此限，無須歸扣。"],"tr":""},{"id":"h:114-25","p":"h","src":"114年第25題","sec":"E4","stem":"甲夫乙妻，一起到夏威夷旅遊，租車亂跑，不幸墜入山谷。下列何者錯誤？","opts":["甲、乙被發現時，由屍體的腐壞程度可以斷定甲比乙早 10 小時死亡，則乙為甲的繼承人","甲、乙被發現時，即使經過法醫相驗，也無法確定誰先死，則雙方互為繼承人","3 年前，甲的家人為了擔心乙分家產，要求甲把全部的財產贈與給甲母，才允許雙方登記結婚此次事故甲死乙傷，乙無法對甲母主張詐害債權的撤銷","該事故實則是乙為了取得甲大筆的遺產所製造的車禍，若甲死乙傷，乙將喪失對甲的繼承權"],"ok":[1],"ex":["可證明甲先死，則乙於甲死亡時尚生存，為配偶繼承人（§1138、§1144）。","§11：二人以上同時遇難，不能證明死亡先後時，推定為同時死亡，同時死亡者互無繼承權。","贈與發生於結婚前，乙非當時債權人，無從依§244行使詐害債權之撤銷權。","§1145 I①：故意致被繼承人於死者喪失繼承權，乙製造車禍致甲死亡，喪失繼承權。"],"tr":""},{"id":"h:113-1","p":"h","src":"113年第1題","sec":"C1","stem":"甲就其所有之 A 地，先與乙訂立買賣契約，後與丙訂立買賣契約，均未辦理所有權移轉登記。關於二個買賣契約之效力，下列敘述，何者正確？","opts":["前契約有效，後契約無效","前契約無效，後契約有效","前契約有效，後契約有效","前契約無效，後契約無效"],"ok":[2],"ex":["買賣契約為債權契約，負擔行為不以有處分權為要件，後契約不會使前契約失效。","同理，前契約不因後契約而無效，也不因未登記而無效。","一物二賣，債權契約均有效；買賣為債權行為，並無排他性，只是出賣人僅能移轉所有權予一人，另一契約出賣人須負債務不履行責任（§226）。","兩契約皆為有效債權契約，未登記不影響契約效力，僅影響物權變動（§758）。"],"tr":""},{"id":"h:113-2","p":"h","src":"113年第2題","sec":"A1","stem":"有關行為能力之敘述，下列何者正確？","opts":["年滿 30 歲患有精神疾病致無法處理自己事務之甲，當然沒有行為能力","年滿 19 歲之乙可以獨自訂立買賣汽車之契約","受輔助宣告之丙可以不經輔助人丁之同意贈與使用過之筆電給戊","15 歲之庚可以不經法定代理人允許擅自丟棄自有之平板電腦"],"ok":[1],"ex":["成年人有精神疾病，須經法院宣告監護/輔助，才影響行為能力；單純「患有精神疾病」並不當然喪失行為能力，須有法院的監護或輔助宣告。","現行民法（112年起）成年年齡為18歲，年滿19歲之乙已為完全行為能力人，可獨自訂立契約，正確。","受輔助宣告之人為「贈與」（非日常生活所必需），依§15-2Ⅰ，應經輔助人同意，不得自行為之，敘述錯誤。","丟棄（拋棄）財物屬單獨行為，15歲（限制行為能力人）未得法定代理人允許之單獨行為無效（§78），敘述錯誤。"],"tr":""},{"id":"h:113-3","p":"h","src":"113年第3題","sec":"C1","stem":"甲將其所有之名畫出租於乙，並未將代理權授與乙。詎料，乙竟以甲之代理人名義，與善意之丙訂立買賣契約，將名畫出賣並交付於丙。甲不承認乙之無權代理行為，下列敘述，何者正確？","opts":["丙善意取得名畫之所有權","丙得請求乙損害賠償","乙與丙之買賣契約有效","乙與丙之物權契約有效"],"ok":[1],"ex":["乙以甲之名義（無代理權）出賣，乙非以自己名義處分，且非有處分權人，丙不能依善意取得（§801、§948）取得所有權。","§110：無代理權人以他人代理人名義所為法律行為，對善意相對人負損害賠償責任。","無權代理之買賣契約對本人效力未定（§170 I），經本人拒絕後確定不生效力。","物權契約同為無權代理行為，本人甲不承認故對甲不生效力。"],"tr":""},{"id":"h:113-4","p":"h","src":"113年第4題","sec":"C5","stem":"甲對乙有新臺幣（下同）100 萬元之債權，將該債權讓與丙，甲與丙均未通知乙債權讓與之事情。嗣後，乙因不知債權讓與之事情，對甲清償 100 萬元，經甲受領，下列敘述，何者正確？","opts":["甲與丙之債權讓與無效","乙之債務因清償而消滅","應經丙承認，乙之債務始消滅","甲與丙之債權讓與應經乙承認始生效"],"ok":[1],"ex":["債權讓與為準物權行為，只要讓與人與受讓人合意即生效（§294 I），不因未通知而無效。","§297 I：未經通知對債務人不生效力，債務人仍得向讓與人清償，乙善意對甲清償，債務因清償而消滅。","清償效力不須丙承認；§297 的保護對象是債務人，乙清償即生消滅效果。","債權讓與無須債務人同意或承認，§297 只是通知對債務人之對抗要件。"],"tr":""},{"id":"h:113-5","p":"h","src":"113年第5題","sec":"B4","stem":"甲申請之建案因違法無法取得建造許可，遂與乙約定，由甲贈與乙之妻丙 100 萬元後，乙須幫助甲取得建造許可，後來乙收賄之行為經法院判決有罪確定。問甲可否向丙請求返還 100 萬元？","opts":["可以，依據不當得利","不可，100 萬元為不法原因之給付","可以，100 萬為違背公序良俗之給付","可以，依據無因管理"],"ok":[1],"ex":["丙雖受領給付，但§180④ 排除不當得利返還請求權。","§180④：因不法原因而為給付者，不得請求返還，但不法原因僅於受領人一方存在時不在此限；本題雙方均有不法，不得請求返還。","契約雖因違反公序良俗而無效（§72），但給付之返還仍受§180④ 限制。","丙受領贈與並非為甲管理事務，不成立無因管理（§172）。"],"tr":""},{"id":"h:113-6","p":"h","src":"113年第6題","sec":"D2","stem":"甲無權占有乙所有已登記之 A 地 15 年後，乙對甲提起所有物返還請求之訴訟，下列敘述，何者正確？","opts":["甲得對乙為消滅時效之抗辯","乙之回復請求權不罹於消滅時效","甲得對乙主張時效取得 A 地所有權","乙之 A 地所有權因罹於時效而消滅"],"ok":[1],"ex":["§767Ⅰ所有物返還請求權雖屬請求權（§125：請求權十五年間不行使而消滅），但釋字第107號、第164號認為已登記不動產所有人之回復請求權及除去妨害請求權無§125消滅時效之適用，甲占有雖已15年，仍不得為消滅時效抗辯，選項錯誤。","同上，A地已登記，乙之所有物返還請求權不罹於消滅時效，可隨時請求，正確。","§769、§770：取得時效以占有他人「未登記」不動產為限；A地已登記，甲不能時效取得所有權（§772後段「於已登記之不動產亦同」僅適用於所有權以外財產權之取得），選項錯誤。","§125消滅時效只適用於「請求權」，所有權本身為恆久存續之權利，不因不行使而消滅，選項錯誤。"],"tr":""},{"id":"h:113-7","p":"h","src":"113年第7題","sec":"C2","stem":"甲與乙訂立租賃契約，將丙所有之 A 屋出租於乙，並交付於乙。嗣後，丙對乙起訴，請求乙返還A 屋，致乙不能為約定之使用，下列敘述，何者正確？","opts":["甲與乙訂立之租賃契約無效","甲與乙訂立之租賃契約得撤銷","乙得終止與甲訂立之租賃契約","乙得以與甲之租賃契約對抗丙"],"ok":[2],"ex":["租賃為負擔行為，出租人無處分權亦不影響租賃契約之有效性。","本題無錯誤、詐欺等撤銷原因。","第三人丙起訴請求返還致乙不能使用收益，依§436 準用§435，承租人因第三人就租賃物主張權利致不能為約定之使用收益，就不能達租賃目的者，乙得終止契約。","租賃權為債權，僅相對效力，不得對抗所有權人丙。"],"tr":""},{"id":"h:113-8","p":"h","src":"113年第8題","sec":"C2","stem":"甲將其所有之 A 屋出租於乙，乙未經甲之同意，將 A 屋全部轉租於丙。下列敘述，何者正確？","opts":["乙與丙訂立之租賃契約無效","甲與乙訂立之租賃契約無效","乙得終止乙與丙之租賃契約","甲得終止甲與乙之租賃契約"],"ok":[3],"ex":["乙擅自轉租，違反的是§443Ⅰ（非經出租人承諾不得轉租）所生對甲的義務，法律效果是§443Ⅱ 賦予甲終止權，並未規定乙丙間的轉租契約無效；乙丙租賃契約仍有效，選項錯誤。","甲乙間租賃契約並不因乙擅自轉租而無效，法律效果僅是甲得終止（§443Ⅱ），選項錯誤。","§443Ⅱ 賦予「出租人」（甲）終止權，乙擅自轉租並未使乙取得終止乙丙租約的法定權利；乙丙間若要終止須依其契約或租賃一般規定，選項錯誤。","依§443Ⅱ，承租人違反§443Ⅰ 規定（未經出租人承諾，將租賃物轉租於他人），出租人得終止契約；本題乙未經甲同意將A屋全部轉租於丙，甲得終止甲乙租約，正確。"],"tr":""},{"id":"h:113-9","p":"h","src":"113年第9題","sec":"D2","stem":"甲在其所有之 A 地上興建 B 屋後，將 B 屋出售並移轉所有權登記於乙。下列敘述，何者正確？","opts":["推定甲與乙在房屋得使用期限內有租賃關係","視為甲與乙在房屋得使用期限內有租賃關係","推定乙在房屋得使用期限內對 A 地有普通地上權","視為乙在房屋得使用期限內對 A 地有普通地上權"],"ok":[0],"ex":["§425-1，土地及其上建物同屬一人，僅將建物移轉（甲將B屋賣給乙），「推定」（非視為）在房屋得使用期限內，甲乙間有租賃關係，正確。","應為「推定」而非「視為」（視為不可推翻，推定可以反証），選項錯誤。","§425-1規定的是「租賃」關係，並非地上權，且為推定，選項錯誤。","同C，應為推定租賃，非視為地上權。★重要對比：土地房屋一般買賣分離→§425-1推定租賃；抵押拍賣分離→§876視為地上權。"],"tr":""},{"id":"h:113-10","p":"h","src":"113年第10題","sec":"A5","stem":"有關意思表示之敘述，下列何者正確？","opts":["甲與乙本為夫妻，為逃避債務，通謀虛偽離婚，並辦理離婚登記完畢，甲乙間已無婚姻關係","甲無欲為其意思表示之拘束，而向乙表示將贈與新款手機一部，乙雖明知甲心中之真意，贈與契約仍有效","甲誤將丙誤認為乙，與之訂立買賣契約，該契約有效，但甲得撤銷其之意思表示","甲受丙脅迫而與之訂立互易契約，該契約當然無效"],"ok":[2],"ex":["離婚為身分行為，須當事人有離婚的真意；通謀虛偽離婚欠缺離婚真意，依通謀虛偽意思表示之法理（§87Ⅰ：通謀而為虛偽意思表示者無效），離婚無效，婚姻關係仍存在（實務見解），故「已無婚姻關係」錯誤。","依§86但書，相對人明知表意人（甲）無真意，意思表示無效，贈與契約因而無效，並非有效。","甲把丙誤認為乙，是「當事人同一性」的錯誤，通說認為屬§88Ⅰ「意思表示之內容有錯誤」（與§88Ⅱ「當事人之資格」錯誤不同：資格錯誤是人沒認錯、只是誤認其身分條件），以非由表意人自己之過失為限，得撤銷；但撤銷前契約有效（§88為得撤銷非當然無效），正確。","依脅迫而為意思表示（§92）效果為「得撤銷」而非當然無效，在撤銷前契約仍有效，本選項「當然無效」描述錯誤。"],"tr":""},{"id":"h:113-11","p":"h","src":"113年第11題","sec":"C4","stem":"甲與其 20 歲之兒子乙訂立贈與契約，將甲所有之 A 屋贈與乙，並完成所有權移轉登記。嗣後，乙竟不履行對甲之法定扶養義務。下列敘述，何者正確？","opts":["甲得解除贈與契約","甲得終止贈與契約","甲得撤銷贈與契約","甲得撤回贈與契約"],"ok":[2],"ex":["贈與契約之救濟為撤銷，非解除。","終止適用於繼續性契約向將來失效，贈與非此類。","§416 I②：受贈人對贈與人有扶養義務而不履行者，贈與人得撤銷贈與；已完成登記不影響此撤銷權。","§408 之任意撤銷限於「贈與物權利未移轉前」，本題已登記移轉，且民法亦無「撤回」贈與之規定。"],"tr":""},{"id":"h:113-12","p":"h","src":"113年第12題","sec":"C2","stem":"甲於自有土地上建造房屋一棟，因積欠乙銀行巨款，土地及房屋遭乙向法院聲請查封拍賣，土地為丙所拍得，房屋為丁所拍得。下列敘述，何者正確？","opts":["丙可以請求丁拆屋還地","丁必須承租丙之土地","視為丁於土地上有地上權","推定丙與丁間有使用借貸契約"],"ok":[2],"ex":["依§838-1Ⅰ（視為已有地上權之設定），房屋拍定人丁取得地上權，有權使用土地，丙不得請求丁拆屋還地。","丁與丙之間不是租賃（§425-1 是『推定』租賃，適用於房地分別讓與之情形）；此處依§838-1Ⅰ 為法律『視為』已設定地上權，丁並非必須向丙承租。","§838-1Ⅰ：土地及其土地上之建築物同屬於一人所有，因強制執行之拍賣，其土地與建築物之拍定人各異時，視為已有地上權之設定（地租、期間及範圍由當事人協議定之；不能協議者，得請求法院以判決定之）；丁於土地上有地上權，正確。","法律規定的效果是『視為已有地上權之設定』（§838-1），而非『推定使用借貸』；使用借貸（§464）須以物交付他方並約定無償使用，與本題無關。"],"tr":""},{"id":"h:113-13","p":"h","src":"113年第13題","sec":"D2","stem":"甲與乙訂立買賣契約，向乙購買 A 地。下列關於甲何時取得 A 地所有權之敘述，何者正確？","opts":["買賣契約有效成立時","甲付清買賣價金之時","完成所有權移轉登記時","乙將 A 地交付於甲之時"],"ok":[2],"ex":["買賣契約（債權行為）成立，不移轉物權，甲尚未取得所有權，選項錯誤。","付清價金係履行契約義務，不移轉所有權，選項錯誤。","不動產所有權移轉，須「登記」生效（§758），完成移轉登記時甲取得A地所有權，正確。","不動產所有權不以「交付」移轉（動產才以交付移轉），選項錯誤。"],"tr":""},{"id":"h:113-14","p":"h","src":"113年第14題","sec":"D2","stem":"甲乙丙丁分別共有 A 地，甲以乙丙丁為被告提起分割共有物之訴，獲得勝訴確定判決。下列敘述，何者正確？","opts":["甲乙丙丁於判決確定時，各自取得分得部分之所有權","甲根據確定判決，請求乙丙丁辦理登記，始取得分得部分之所有權","共有物分割之判決是確認判決，僅在確認甲乙丙丁之權利義務法律關係","共有物分割之判決是給付判決，甲有權請求乙丙丁給付分得部分之所有權"],"ok":[0],"ex":["分割共有物判決屬形成判決，確定時即生物權變動，各共有人取得分得部分所有權，不待登記（§759、§824-1）。","形成判決確定時即取得所有權，不須再請求辦理登記才取得。","分割判決為形成判決，不是確認判決。","分割判決為形成判決，不是給付判決，無須請求他共有人「給付」所有權。"],"tr":""},{"id":"h:113-15","p":"h","src":"113年第15題","sec":"D5","stem":"甲以行使普通地上權之意思，二十年間和平、公然、繼續在乙已登記之 A 地上有 B 屋，下列敘述，何者正確？","opts":["甲已經取得普通地上權","甲得請求登記為普通地上權人","因乙之 A 地已辦理登記，故甲無法時效取得","甲得直接以乙為被告，起訴請求乙同意甲登記為普通地上權人"],"ok":[1],"ex":["§772準用§769：二十年和平、公然、繼續占有，效果僅是「得請求登記」為地上權人，須經登記才取得地上權（§758Ⅰ），選項說「已經取得」錯誤。","§772準用§769：以行使地上權之意思二十年和平、公然、繼續占有，即使他人不動產已登記（§772後段），仍得請求登記為地上權人，正確。★已登記不動產不能時效取得「所有權」（§769、§770限未登記），但可時效取得地上權等所有權以外之權利。","§772後段規定前五條取得時效之規定「於已登記之不動產亦同」，故已登記之土地仍可時效取得地上權，選項錯誤。","實務見解：依§772 準用§769 時效取得地上權者，取得的是「得請求登記為地上權人」之權，性質上是占有人得向地政機關單獨申請登記，並非對土地所有人之請求權；土地所有人並無協同辦理或同意登記之義務，故占有人不得逕以乙為被告起訴請求乙同意登記，選項錯誤。"],"tr":""},{"id":"h:113-16","p":"h","src":"113年第16題","sec":"A7","stem":"甲以自有土地設定抵押權予乙，以擔保其債權，該債權之請求權於 113 年 3 月 1 日因時效而消滅。下列敘述，何者正確？","opts":["因從屬於擔保債權，故抵押權隨之消滅","抵押權人須於消滅時效完成後，5 年間實行其抵押權","抵押權無消滅時效，可一直存續","從此之後，抵押權之實行須經債務人同意"],"ok":[1],"ex":["消滅時效完成，擔保債權之「請求力」消滅（債務人得拒絕給付），但債權本身及抵押權並未隨之消滅，抵押權仍存在（從屬性並非時效完成即同步消滅）。","依§880，抵押權所擔保之債權，其請求權已因時效消滅，如抵押權人於消滅時效完成後，5年間不實行其抵押權者，抵押權消滅，正確（此為§880的特別規定）。","§880規定抵押權存在有期限限制（時效完成後5年不實行即消滅），並非永遠存續，敘述錯誤。","抵押權實行為抵押權人之權利，無須債務人同意，描述錯誤。"],"tr":""},{"id":"h:113-17","p":"h","src":"113年第17題","sec":"D6","stem":"甲向乙銀行貸款新臺幣 500 萬元，並以甲所有之 A 地為乙設定普通抵押權，雙方約定債權已屆清償期而未為清償時，A 地之所有權移屬於乙。就該流押契約之效力，下列敘述，何者正確？","opts":["絕對無效","相對無效","非經登記，不生效力","非經登記，不得對抗第三人"],"ok":[3],"ex":["流押契約並非絕對無效，§873-1 I 承認其為有效，僅有對抗力之限制。","並無相對無效之規定。","流押約定於當事人間有效，不以登記為生效要件。","§873-1 I：流押約定非經登記，不得對抗第三人。"],"tr":""},{"id":"h:113-18","p":"h","src":"113年第18題","sec":"D6","stem":"甲向乙銀行借貸新臺幣 1000 萬元，並以甲所有之 A 屋為乙設定普通抵押權。嗣後，因第三人丙之過失，致 A 屋滅失，下列敘述，何者正確？","opts":["乙之抵押權因 A 屋滅失而消滅","乙就甲對丙所得行使之賠償請求權有權利質權","乙就甲對丙所得行使之賠償請求權有動產質權","乙就甲對丙所得行使之賠償請求權有普通抵押權"],"ok":[1],"ex":["§881 I 但書：抵押物滅失但因滅失得受賠償金者，抵押權不消滅。","§881 II：抵押權人對抵押物滅失所得賠償金，有權利質權，次序與原抵押權同。","賠償請求權為債權，其上之擔保為權利質權，不是動產質權。","賠償請求權上成立的是權利質權，不是普通抵押權。"],"tr":""},{"id":"h:113-19","p":"h","src":"113年第19題","sec":"E4","stem":"著有數本暢銷理財專書之甲，某日遭汽車駕駛人丙撞傷，卻於與丙損害賠償協議達成前，突發心肌梗塞猝死，留有土地一筆及尚未繳清貸款之房屋一棟，某上市電子公司股份 100 萬股，銀行存款 30 萬元，尚欠有乙銀行之信用貸款 20 萬元。下列何者非屬繼承之標的？","opts":["尚未繳清貸款之房屋","甲所著理財專書之著作權","甲對丙依據民法第 195 條規定可主張之非財產上損害賠償請求權","甲積欠乙銀行之 20 萬信用貸款"],"ok":[1,2],"ex":["房屋及其貸款債務，屬被繼承人財產上之權利義務，為繼承標的（§1148 I）。","著作權含專屬於著作人之著作人格權，不得讓與或繼承（著作權法§21），整體稱「著作權」不全屬繼承標的；考選部多重給分。","民法§195 II：非財產上損害賠償請求權不得讓與或繼承，但已依契約承諾或已起訴者除外，故非繼承標的。","銀行貸款債務為財產上義務，由繼承人承受（§1148 I，限定責任）。"],"tr":""},{"id":"h:113-20","p":"h","src":"113年第20題","sec":"E2","stem":"民法就夫妻財產制採類型法定原則，下列何者並非我國現行民法規定之夫妻財產制類型？","opts":["法定財產制","共同財產制","分別財產制","統一財產制"],"ok":[3],"ex":["法定財產制為現行制度（§1005），為預設之夫妻財產制。","共同財產制為現行約定財產制之一（§1004、§1031以下）。","分別財產制為現行約定財產制之一（§1004、§1044以下）。","民法並無「統一財產制」，現行類型為法定財產制及約定之共同、分別財產制。"],"tr":""},{"id":"h:113-21","p":"h","src":"113年第21題","sec":"E2","stem":"夫妻得於結婚前或結婚後，以契約就民法所定之約定財產制中，選擇其一，為其夫妻財產制。關於夫妻財產制契約，下列敘述，何者錯誤？","opts":["應以書面為之","非經登記，不生效力","非經登記，不得以之對抗第三人","夫妻未以契約訂立夫妻財產制者，原則上以法定財產制，為其夫妻財產制"],"ok":[1],"ex":["§1007：夫妻財產制契約之訂立、變更或廢止，應以書面為之。","§1008 I：非經登記僅不得對抗第三人，並非不生效力。","§1008 I：非經登記，不得以之對抗第三人。","§1005：未以契約訂立者，原則以法定財產制為其夫妻財產制。"],"tr":""},{"id":"h:113-22","p":"h","src":"113年第22題","sec":"E3","stem":"甲男與乙女結婚後，乙女與丙男發生婚外情，並生下丁。下列敘述，何者錯誤？","opts":["丁係在甲與乙婚姻關係存續中受胎，推定為甲乙之婚生子女","甲自知悉丁非其婚生子女時起二年內，得對丁提起否認之訴","丙得以甲與丁為被告，提起否認甲與丁間具有親子關係之訴","丁與乙之關係，視為婚生子女，乙無須出面從事認領之動作"],"ok":[2],"ex":["§1063 I：妻之受胎係在婚姻關係存續中者，推定其所生子女為婚生子女。","§1063 III：夫妻之一方自知悉該子女非婚生之時起二年內得提起否認之訴。","依§1063 II，得提起否認之訴者為夫妻之一方及子女，生父丙不在條文所列原告之列。","§1065 II：非婚生子女與其生母之關係視為婚生，無須認領。"],"tr":""},{"id":"h:113-23","p":"h","src":"113年第23題","sec":"E4","stem":"甲男與乙女結婚後，並無任何子女。嗣後，甲男死亡，繼承人為乙與甲之父母丙丁。關於乙女之應繼分，下列敘述，何者正確？","opts":["乙與丙丁平均繼承，各三分之一","乙女之應繼分為遺產之二分之一","乙女之應繼分為遺產之三分之二","乙女之應繼分為遺產之四分之三"],"ok":[1],"ex":["§1144②：配偶與父母同為繼承時，配偶為二分之一，非平均各三分之一。","§1144②：配偶與第二順序直系血親尊親屬同為繼承時，配偶應繼分為遺產二分之一。","三分之二為配偶與祖父母（第四順序）同為繼承時之應繼分（§1144③）；與兄弟姊妹同為繼承時為二分之一（§1144②）。","四分之三不存在於§1144。"],"tr":""},{"id":"h:113-24","p":"h","src":"113年第24題","sec":"E4","stem":"民法關於特留分比例之規定，下列敘述，何者錯誤？","opts":["直系血親卑親屬之特留分為其應繼分二分之一","父母之特留分為其應繼分二分之一","兄弟姊妹之特留分為其應繼分二分之一","配偶之特留分為其應繼分二分之一"],"ok":[2],"ex":["§1223①：直系血親卑親屬之特留分為應繼分二分之一。","§1223②：父母之特留分為應繼分二分之一。","§1223④：兄弟姊妹之特留分為應繼分「三分之一」，不是二分之一。","§1223③：配偶之特留分為應繼分二分之一。"],"tr":""},{"id":"h:113-25","p":"h","src":"113年第25題","sec":"E4","stem":"甲死亡後留有土地一筆，由其妻乙、兒子丙及女兒丁及戊繼承，因丙不想繼承該筆土地，故向法院以書面聲明拋棄繼承，並通知其他應繼承之人，戊知悉後，則向乙、丙、丁表明，其也要拋棄繼承，並拒絕繳納遺產稅及辦理繼承登記。下列敘述，何者正確？","opts":["丙收到法院寄發之「台端拋棄繼承，准予備查」的函件時，拋棄繼承才生效","丙拋棄繼承時，其子女可代位繼承","戊亦已經拋棄繼承，不得繼承土地所有權","甲之繼承人有乙、丁、戊等三人，應繼分均等"],"ok":[3],"ex":["拋棄係向法院為書面表示之要式行為，法院備查函僅為備查，並非生效要件；拋棄溯及繼承開始（§1175）。","代位繼承僅限於先死亡或喪失繼承權（§1140），拋棄不發生代位。","戊僅口頭向家人表示，未依§1174 II以書面向法院為之，拋棄無效，仍為繼承人。","丙拋棄後，其應繼分歸屬其他同為繼承人（§1176 I），繼承人為乙、丁、戊三人，配偶與第一順序平均（§1144①），均等。"],"tr":""},{"id":"h:112-1","p":"h","src":"112年第1題","sec":"A1","stem":"有關權利能力之敘述，下列何者錯誤？","opts":["人的權利能力始於出生終於死亡，因此胎兒尚未出生所以沒有權利能力","人的權利能力不得拋棄，更不得轉讓","法人除於法令或性質上之限制外，仍享有權利能力","植物人仍享有權利能力"],"ok":[0],"ex":["雖然「始於出生終於死亡」正確（§6），但推論「胎兒尚未出生所以沒有權利能力」不完全正確：§7規定胎兒以將來非死產者為限，關於個人利益之保護，視為既已出生（擬制有限度的權利能力），故「沒有權利能力」之說法過於絕對，為錯誤敘述，應選答案。","依§16，權利能力不得拋棄，此為人格之基本保障，正確。","§26，法人在法令及性質限制範圍內有權利能力，正確。","植物人仍為生存的自然人，生命現象未終止，仍具完整權利能力，正確。"],"tr":""},{"id":"h:112-2","p":"h","src":"112年第2題","sec":"A3","stem":"有關權利客體之敘述，下列何者錯誤？","opts":["甲未經乙的同意在乙的土地上種植樹木，該樹木為乙土地上之部分","甲飼養一頭母牛，後來該母牛生下一頭小牛，小牛所有權仍屬於甲所有","為收容災民而臨時拼裝之貨櫃屋，仍為定著物，性質上為不動產","主物之處分效力及於從物，所以購買汽車之契約效力及於備胎"],"ok":[2],"ex":["乙土地上尚未與土地分離的樹木，屬不動產之出產物，為該不動產之部分（§66Ⅱ）；甲未經同意種植，樹木附合於乙之土地而成為重要成分，由土地所有人乙取得所有權（§811：動產因附合為不動產重要成分者，不動產所有人取得動產所有權），正確。","小牛屬動物之產物，為天然孳息（§69Ⅰ）；有收取天然孳息權利之人（母牛所有人甲），於權利存續期間內取得與原物分離之孳息（§70Ⅰ），故小牛歸甲所有，正確。","不動產指土地及其定著物（§66Ⅰ）；定著物須固定附著於土地、具繼續性使用而非可隨時移動。臨時拼裝、可隨時移動的貨櫃屋欠缺「定著」性，不是定著物，性質上為動產，本選項說是不動產，錯誤，為應選答案。","§68：非主物之成分、常助主物效用而同屬一人者為從物（Ⅰ）；主物之處分，及於從物（Ⅱ）。汽車為主物、備胎為從物，買賣汽車之效力及於備胎，正確。"],"tr":""},{"id":"h:112-3","p":"h","src":"112年第3題","sec":"A1","stem":"有關限制行為能力之敘述，下列何者正確？","opts":["滿 16 歲之未成年人寫遺囑時，仍須經法定代理人同意，否則效力未定","16 歲之甲偽造身分證，使相對人乙誤信甲已滿 18 歲，而與甲簽訂買賣契約，該買賣契約有效","限制行為能力人為代理人時，代理人受領代理權仍須經法定代理人之同意","法定代理人可以概括允許限制行為能力人為法律行為"],"ok":[1],"ex":["§1186Ⅱ明定，滿16歲之未成年人，「得自行訂立遺囑」（身分行為之特別規定），不須法定代理人同意，本選項與法條相反。","限制行為能力人使用詐術（偽造身分證），依§83，其法律行為有效（排除保護），正確。","代理人不以有行為能力為必要（§104），限制行為能力人受領代理權（代理人之地位）無須法定代理人同意，此為代理制度特別規定。","§77本文：限制行為能力人為意思表示，應得法定代理人之「允許」。依學說，允許應就特定行為或特定範圍為之；若允許其為「一切」法律行為，等於使限制行為能力人取得完全行為能力，架空限制行為能力制度的保護目的，故不得概括允許，選項過於絕對，錯誤。"],"tr":""},{"id":"h:112-4","p":"h","src":"112年第4題","sec":"A4","stem":"下列情形，那一行為需向法院聲請撤銷，才會發生撤銷之效力？","opts":["通謀虛偽意思表示所為之法律行為","因錯誤或誤傳之意思表示而為法律行為","被詐欺而為意思表示之法律行為","因暴利行為所為之法律行為"],"ok":[3],"ex":["通謀虛偽意思表示依§87Ⅰ當然無效（但不得對抗善意第三人），無須撤銷。","因錯誤（§88）或傳達不實（§89）而撤銷，是以意思表示為之（§116Ⅰ：撤銷應以意思表示為之；相對人確定者向相對人為之，§116Ⅱ），並非向法院聲請，無須法院撤銷即生效力。","因詐欺、脅迫而撤銷（§92Ⅰ），同樣依§116以意思表示向相對人為之，無須向法院聲請。","§74Ⅰ暴利行為，須由利害關係人向「法院聲請」撤銷（或減輕給付）才發生效力，與其他撤銷（以意思表示為之）不同，為應選答案，正確。"],"tr":""},{"id":"h:112-5","p":"h","src":"112年第5題","sec":"C1","stem":"甲向乙推銷一只古董錶，甲出價新臺幣（下同）10 萬元問乙要不要買，乙答覆說：「如果 8 萬元我就買」，請問乙的答覆性質上為何？","opts":["要約之引誘","承諾","要約","意思實現"],"ok":[2],"ex":["要約引誘是邀請他人向自己為要約（如價目表寄送、一般廣告，§154 Ⅱ），本題乙已明確表示「8萬元我就買」，內容具體、可一經承諾即成立契約，不是單純邀請。","承諾須對原要約為完全同意；乙將價金由10萬元改為8萬元，已變更要約內容，依§160 Ⅱ不是承諾。","依§160 Ⅱ：將要約擴張、限制或為其他變更而承諾者，視為拒絕原要約而為新要約；乙把10萬元改為8萬元，即為（反）要約，正確。","意思實現（§161 Ⅰ）：依習慣或事件性質承諾無須通知者，在相當時期內有可認為承諾之事實時，契約即成立（如逕行履行）；本題乙只是以言語表示「8萬元就買」，並非以履行等事實承諾，不是意思實現。"],"tr":""},{"id":"h:112-6","p":"h","src":"112年第6題","sec":"C1","stem":"甲向乙購買乙對於丙的債權，但丙已於買賣前清償系爭債權而使該債權消滅，請問該買賣契約之效力如何？","opts":["債權不得作為買賣之標的所以無效","該買賣標的權利自始不存在，屬於標的不能而無效","該買賣標的權利雖然不存在，但契約仍有效，甲可對乙主張權利瑕疵擔保","甲可依締約上過失向乙請求損害賠償"],"ok":[2],"ex":["債權為財產權，得為買賣標的（§348 II 權利買賣），並非不得為標的。","買賣債權時債權已不存在，依§350 出賣人應擔保債權確係存在，足見契約仍屬有效，並非因標的不能而當然無效。","契約有效，債權不存在屬權利瑕疵，出賣人應負權利瑕疵擔保責任（§349、§350）。","§245-1 的締約上過失以「契約未成立」為要件（契約因給付不能而無效時的信賴利益賠償，另規定於§247）；本題買賣契約已成立且有效，債權不存在依§350 屬出賣人應擔保之權利瑕疵，應依權利瑕疵擔保處理，不適用§245-1。"],"tr":""},{"id":"h:112-7","p":"h","src":"112年第7題","sec":"B1","stem":"依民法之規定，約定利率超過週年百分之多少，則超過之部分會無效？","opts":["12","16","20","25"],"ok":[1],"ex":["12% 是§204Ⅰ的數字：約定利率逾週年12%者，經一年後債務人得隨時清償原本（須一個月前預告），不是§205的上限；§205上限為16%。","§205：約定利率超過週年16%者，超過部分之約定無效。","20% 為修正前舊上限，現行§205 為16%。","25% 與民法§205 規定不符。"],"tr":""},{"id":"h:112-8","p":"h","src":"112年第8題","sec":"C4","stem":"下列何種契約性質上屬於要物契約？","opts":["消費借貸契約","房屋租賃契約","贈與契約","合會契約"],"ok":[0],"ex":["消費借貸（§474），須「物之交付」才成立，屬要物契約，正確。","房屋租賃為諾成契約，雙方合意即成立，不以交付為成立要件。","贈與為諾成契約，合意即成立，並非要物契約；贈與人於「贈與物之權利未移轉前」得撤銷（§408Ⅰ，不動產以登記移轉為準，不是交付），但經公證或為履行道德上義務之贈與不得撤銷（§408Ⅱ）。","合會（§709-3以下）為諾成性質，依法成立後各方依約履行，不以物之交付為成立要件。★要物契約記法：使用借貸（§464）、消費借貸（§474）均為要物契約；定金（§248）亦是要物性質。"],"tr":""},{"id":"h:112-9","p":"h","src":"112年第9題","sec":"C2","stem":"依民法之規定，有關租賃契約之效力，下列何者錯誤？","opts":["租賃物有修繕之必要時，原則上承租人可直接自行修繕後再請求出租人給付修繕費用","如租賃物是房屋時，倘出租人無反對之約定，承租人可以將房屋一部轉租","租賃物因承租人失火而造成損害，承租人僅就重大過失負賠償責任","租賃物應納之一切稅捐，由出租人負擔"],"ok":[0],"ex":["§430：租賃物有修繕必要時，承租人須先定期催告出租人修繕，逾期仍不修繕才得自行修繕並請求償還；非原則上得直接自行修繕。","§443 I 但書：租賃物為房屋者，除有反對約定外，承租人得將其一部分轉租。","§434：租賃物因承租人重大過失致失火而毀損滅失者，承租人負損害賠償責任，輕過失不負責。","§427：就租賃物應納之一切稅捐，由出租人負擔。"],"tr":""},{"id":"h:112-10","p":"h","src":"112年第10題","sec":"D2","stem":"為動產物權讓與之交付，倘受讓人已先占有動產，於讓與合意時即生動產所有權取得之效力，學理上稱之為何？","opts":["現實交付","占有改定","簡易交付","指示交付"],"ok":[2],"ex":["現實交付（§761Ⅰ本文）：動產物權讓與須將動產交付，指實際移轉占有；本題受讓人已先占有動產，無須再實際交付。","占有改定（§761Ⅱ）：讓與人仍繼續占有動產，雙方訂契約使受讓人取得間接占有以代交付；本題是受讓人已占有，非讓與人繼續占有。","簡易交付（§761Ⅰ但書）：受讓人已占有動產者，於讓與合意時即生效力，無須再行交付，正確。","指示交付（§761Ⅲ）：動產由第三人占有時，讓與人以對第三人之返還請求權讓與受讓人以代交付；本題動產由受讓人自己占有，無第三人。"],"tr":""},{"id":"h:112-11","p":"h","src":"112年第11題","sec":"D1","stem":"果實自落於鄰地者，果實之所有權為鄰地所有權人所有，倘鄰地係公有用地時，該自落之果實為何人所有？","opts":["國家所有","該果實為無主物，誰先占即取得所有","為該果實之果樹所有權人所有","由國家及果樹所有權人所共有"],"ok":[2],"ex":["§798但書：鄰地為公用地者，不適用「視為屬於鄰地所有人」之規定，但這只是排除例外，並未規定改歸國家所有；果實仍依一般規則歸收取權人，選項錯誤。","果實並非無主物：§70Ⅰ有收取天然孳息權利之人，取得與原物分離之孳息，果樹所有人即為收取權人，不適用先占，選項錯誤。","§798本文：果實自落於鄰地者，視為屬於鄰地所有人，但書排除鄰地為公用地之情形；於公用地時回歸§70Ⅰ，由有收取天然孳息權利之人（果樹所有人）取得與原物分離之孳息，正確。","國家與果樹所有人之間並無共有之法律基礎，果實全部歸果樹所有人，選項錯誤。"],"tr":""},{"id":"h:112-12","p":"h","src":"112年第12題","sec":"D3","stem":"有關遺失物拾得之敘述，下列何者錯誤？","opts":["遺失物自通知或最後招領日起逾 6 個月，未有受領人認領者，由拾得人取得遺失物之所有權","受領權人認領遺失物時，拾得人原則上可以請求報酬，但不得超過遺失物價值之十分之三","拾得人之報酬請求權因 6 個月不行使而消滅","倘受領權人為低收入戶時，依法可以拒絕拾得人之報酬請求"],"ok":[1],"ex":["§807 I：遺失物自通知或最後招領之日起逾6個月未認領者，由拾得人取得所有權。","§805 Ⅱ：拾得人得請求報酬，但不得超過其物財產上價值之十分之一（不是十分之三），故本選項錯誤。","§805 IV：拾得人之報酬請求權，因6個月間不行使而消滅。","§805-1：受領權人為低收入戶等法定情形時，得拒絕拾得人之報酬請求。"],"tr":""},{"id":"h:112-13","p":"h","src":"112年第13題","sec":"D6","stem":"抵押權人僅就土地設定抵押權，因債權已屆清償期而未清償而實行抵押權，下列何者錯誤？","opts":["於設定抵押權時，該土地上已存在房屋，實行抵押權之範圍僅限於土地本身，不得就房屋併付拍賣","於設定抵押權時，土地上並無房屋，於實行抵押權時土地所有人已營造房屋，抵押權人必要時得聲請併付拍賣","抵押權人聲請併付拍賣時，如房屋有存在他人之租賃權，抵押權人得聲請法院除去房屋之租賃權後再執行拍賣","抵押權人將土地與房屋併付拍賣後，對於土地及房屋賣得之價金，抵押權人均有優先受償之權利"],"ok":[3],"ex":["§877 僅適用設定抵押權「後」營造之建築物；設定時已存在之房屋不得併付拍賣。","§877 I：設定抵押權後營造房屋者，抵押權人於必要時得聲請併付拍賣。","§866 II：土地所有人於設定抵押權後設定之權利或成立之租賃關係影響抵押權者，抵押權人得聲請法院除去後拍賣（§877 II 則規定§866 II、III 之權利人營造之建築物亦得併付拍賣）。","§877 I 但書：對房屋價金無優先受償權，僅就土地賣得價金優先受償。"],"tr":""},{"id":"h:112-14","p":"h","src":"112年第14題","sec":"A1","stem":"民法關於死亡宣告的規定，下列何者正確？","opts":["失蹤人失蹤滿三年後，法院得因利害關係人之聲請，為死亡之宣告","受死亡宣告者，以判決內所確定死亡之時，推定其為死亡","遺產稅捐徵收機關得為失蹤人向法院聲請死亡宣告","死亡宣告會剝奪失蹤人之權利能力"],"ok":[1],"ex":["§8Ⅰ一般失蹤失蹤期間須滿「七年」（或特殊情形如危難中滿一年）始得聲請，三年不足，敘述錯誤。","依§9，受死亡宣告者，以判決內所確定死亡之時（§9Ⅱ：應為§8各項所定期間最後日終止之時），「推定」其為死亡（非確定死亡），正確。","依§8，死亡宣告之聲請人為「利害關係人或檢察官」，稅捐機關並非明文規定之聲請權人，敘述錯誤。","死亡宣告為「推定死亡」，失蹤人若仍生存，其權利能力不受影響，死亡宣告不剝奪權利能力，選項描述錯誤。"],"tr":""},{"id":"h:112-15","p":"h","src":"112年第15題","sec":"A7","stem":"甲於民國（下同）107 年 9 月間向乙租車公司租用自小客車環島，然卻積欠乙租金新臺幣 3 萬元，乙於 108 年 9 月催告後甲仍不為給付，乙便於 109 年 8 月訴請甲給付租金，於 110 年 9 月獲勝訴判決確定。下列何者正確？","opts":["乙租車公司的租金請求權時效本為 5 年","乙於 108 年 9 月催告後 6 個月內未起訴，仍生中斷時效之效力","乙於 109 年 8 月訴請甲給付租金時，時效不完成","判決確定後，時效重新起算 5 年"],"ok":[3],"ex":["以租賃動產為營業者之租價，請求權時效為二年（§127③），並非五年。","§130：時效因請求而中斷者，若於請求後六個月內不起訴，視為不中斷；故催告後未於六個月內起訴，不生中斷效力。","§129 I③：起訴為時效中斷事由，並非時效不完成。","§137 I、II、III：時效因起訴中斷，確定判決後重行起算；原期間不滿五年者，重行起算之期間為五年（§137 III）。"],"tr":""},{"id":"h:112-16","p":"h","src":"112年第16題","sec":"C3","stem":"甲委託乙代為尋覓對象結婚，並承諾事成後給予乙報酬新臺幣 10 萬元。關於婚姻居間契約，下列何者正確？","opts":["甲乙間的契約，無效","乙得對甲請求給付報酬","乙對甲無報酬請求權","婚姻居間契約不得約定報酬"],"ok":[2],"ex":["依§573，婚姻居間契約約定報酬者，法律只是規定居間人「就其報酬無請求權」，並未規定契約無效；選項說契約無效，與條文不符。","依§573，因婚姻居間而約定報酬者，就其報酬無請求權；甲雖承諾事成給付10萬元，乙也不得向甲請求給付，選項說「乙得請求」與條文相反，錯誤。","依§573，婚姻居間約定報酬者，居間人就其報酬無請求權，所以乙對甲沒有10萬元報酬請求權，正確。","§573 的文字是「因婚姻居間而約定報酬者，就其報酬無請求權」，可見法律承認當事人可以「約定」報酬，只是居間人不能請求；選項說「不得約定報酬」錯誤。"],"tr":""},{"id":"h:112-17","p":"h","src":"112年第17題","sec":"D4","stem":"土地所有人非因故意或重大過失逾越地界建築房屋，而鄰地所有人知其越界，卻不即時提出異議者，下列何者正確？","opts":["鄰地所有人不為異議，即表示拋棄所有權利，不得再為主張","土地所有人有權得請求購買越界之土地","鄰地所有人得請求移去或變更越界建築之房屋，並請求支付償金","鄰地所有人不得請求移去或變更越界建築之房屋，但得請求所受損害之償金"],"ok":[3],"ex":["§796Ⅰ：鄰地所有人知其越界而不即提出異議，效果僅是不得請求移去或變更房屋，並非拋棄一切權利；仍得請求償金（§796Ⅰ但書）及請求購買越界部分（§796Ⅱ），選項過於絕對，錯誤。","§796Ⅱ：得請求以相當價額購買越界部分土地及因此形成之畸零地者，是「鄰地所有人」請求「土地所有人」，並非土地所有人有權請求，主體顛倒，錯誤。","§796Ⅰ本文：鄰地所有人知其越界而不即提出異議，不得請求移去或變更其房屋，選項說「得請求移去或變更」錯誤。","§796Ⅰ：鄰地所有人不得請求移去或變更房屋，但土地所有人對鄰地因此所受之損害應支付償金，故得請求所受損害之償金，正確。"],"tr":""},{"id":"h:112-18","p":"h","src":"112年第18題","sec":"D2","stem":"關於民法區分所有建築物規定之敘述，下列何者錯誤？","opts":["專有部分與其所屬之共有部分及其基地之權利，得分離而為移轉或設定負擔","就區分所有建築物共有部分及基地之應有部分，區分所有人得約定其比例","專有部分得經其所有人之同意，依規約之約定供區分所有建築物之所有人共同使用","共有部分除法律另有規定外，得經規約之約定供區分所有建築物之特定所有人使用"],"ok":[0],"ex":["§799 V：專有部分與其所屬之共有部分及基地之權利，不得分離而為移轉或設定負擔。","§799 IV：共有部分及基地之應有部分，依專有部分面積比例，但另有約定者從其約定。","§799 III：專有部分經所有人之同意，得依規約約定供區分所有建築物之所有人共同使用。","§799 III：共有部分除法律另有規定外，得經規約約定供特定所有人使用。"],"tr":""},{"id":"h:112-19","p":"h","src":"112年第19題","sec":"C1","stem":"甲在其所有 A 地上興建 B 屋，但 B 屋為未辦理建物所有權第一次登記的違章建物，嗣後甲與乙訂立 A 地與 B 屋的買賣契約，下列何者錯誤？","opts":["B 屋雖為違章建築亦為融通物，得為交易之客體","甲應將 A 地所有權辦妥移轉登記給乙，乙始取得 A 地所有權","興建 B 屋時因未為建物所有權保存登記，故甲未取得 B 屋所有權","甲將B屋讓與乙，乙僅取得對B屋之事實上處分權"],"ok":[2],"ex":["違章建築仍為有體物，得為交易客體，屬融通物。","§758 I：不動產物權依法律行為而取得者，非經登記不生效力；故A地所有權於移轉登記時取得。","建物於起造完成時，起造人原始取得（事實行為，§759 之反面），不以保存登記為要件，故甲取得B屋所有權（僅無法處分登記）。","違章建築未能辦理移轉登記，買受人僅取得事實上處分權，非所有權。"],"tr":""},{"id":"h:112-20","p":"h","src":"112年第20題","sec":"D6","stem":"關於善意占有人之敘述，下列何者錯誤？","opts":["善意占有人於本權訴訟敗訴時，自判決確定之日起，視為惡意占有人","善意占有人自確知其無占有本權時起，為惡意占有人","善意占有人因保存占有物所支出之必要費用，得向回復請求人請求償還","善意占有人，因改良占有物所支出之有益費用，於其占有物現存之增加價值限度內，得向回復請求人，請求償還"],"ok":[0],"ex":["§959 II：善意占有人於本權訴訟敗訴時，自「訴狀送達之日」起視為惡意占有人，不是判決確定之日。","§959 I：善意占有人自確知其無占有本權時起，為惡意占有人。","§954：善意占有人因保存占有物支出之必要費用，得向回復請求人請求償還。","§955：善意占有人因改良占有物支出之有益費用，於現存增加價值限度內得請求償還。"],"tr":""},{"id":"h:112-21","p":"h","src":"112年第21題","sec":"E2","stem":"就法定夫妻財產制之敘述，下列何者錯誤？","opts":["夫或妻婚前財產，於婚姻關係存續中所生之孳息，視為婚後財產","不能證明為夫或妻所有之財產，視為夫妻共有","夫或妻之財產分為婚前財產與婚後財產，由夫妻各自所有","夫妻各自對其債務負清償之責"],"ok":[1],"ex":["§1017 II：婚前財產於婚姻關係存續中所生孳息，視為婚後財產。","§1017 I：不能證明為夫或妻所有之財產，是「推定」為夫妻共有，不是「視為」共有（可反證推翻）。","§1017 I：夫或妻之財產分為婚前與婚後財產，由夫妻各自所有。","§1023 I：夫妻各自對其債務負清償之責。"],"tr":""},{"id":"h:112-22","p":"h","src":"112年第22題","sec":"E2","stem":"關於民法第 1031 條之 1 夫妻財產制中之特有財產之敘述，下列何者錯誤？","opts":["甲在婚前取得之受贈物 A 屋，若贈與人甲父以書面聲明甲日後結婚時，該 A 屋為特有財產，則該 A 屋亦屬特有財產","夫或妻在家中共同使用的茶杯、桌椅等動產，非特有財產","夫是音樂家，則其演奏時所需之樂器為特有財產","夫或妻雖以受贈之特有財產之金錢購買不動產一筆，惟該受贈物狀態已變更，則該不動產非特有財產"],"ok":[3],"ex":["§1031-1 I③：受贈物經贈與人以書面聲明為特有財產者，為特有財產；贈與人書面聲明有效。","共同使用之茶杯桌椅非「專供個人使用」，不屬特有財產（§1031-1 I①）。","夫或妻職業上必需之物為特有財產（§1031-1 I②），樂器屬之。","特有財產以其價金等換得之財產，通說認為因物上代位仍屬特有財產，不因形態變更而喪失性質。"],"tr":""},{"id":"h:112-23","p":"h","src":"112年第23題","sec":"E4","stem":"關於遺產繼承之敘述，下列何者錯誤？","opts":["非婚生子女非經生父認領或準正，不得繼承其生父之遺產","遺產繼承人，除配偶外，其繼承順序為直系血親卑親屬、父母、兄弟姊妹、祖父母","配偶與被繼承人直系血親尊親屬同為繼承時，其應繼分為遺產之三分之一","特留分之規定，係為保障法定繼承人之權利免受侵害"],"ok":[2],"ex":["非婚生子女須經生父認領或準正才視為婚生（§1064、§1065 I），才得繼承生父遺產。","§1138：配偶之外，順序為直系血親卑親屬、父母、兄弟姊妹、祖父母。","配偶與父母（第二順序）同為繼承時，配偶應繼分為遺產二分之一（§1144②）；與祖父母（第四順序）同為繼承時為三分之二（§1144③）。直系血親尊親屬無論父母或祖父母，配偶都不是三分之一。","特留分制度（§1223）旨在保障特定繼承人之最低繼承利益，免受遺囑處分侵害。"],"tr":""},{"id":"h:112-24","p":"h","src":"112年第24題","sec":"E4","stem":"關於回復喪失繼承權之敘述，下列何者錯誤？","opts":["子女為了遺產而謀殺父親，即喪失對父親之繼承權，因被繼承人原諒繼承人之行為而回復繼承權","偽造、變造、隱匿、湮滅被繼承人關於繼承之遺囑者，喪失繼承權，得因被繼承人原諒繼承人之行為而回復其繼承權","對於被繼承人有重大之虐待或侮辱情事，經被繼承人表示其不得繼承時，喪失繼承權，但之後仍可因獲得被繼承人之原諒而回復繼承權","以詐欺或脅迫妨害被繼承人為關於繼承之遺囑，或妨害其撤回或變更者，喪失繼承權，得因被繼承人原諒繼承人之行為而回復其繼承權"],"ok":[0],"ex":["故意致被繼承人於死屬§1145 I①，不在宥恕範圍；§1145 II 宥恕限於第2至4款（遺囑相關），不能回復。","偽造、變造、隱匿、湮滅遺囑者，經被繼承人宥恕，繼承權不喪失（§1145 II）。","對被繼承人重大虐待或侮辱（第5款）以被繼承人表示不得繼承為要件；依通說，被繼承人得撤回該表示而回復繼承權（非§1145 II 宥恕明文）。","以詐欺或脅迫妨害遺囑之作成、撤回或變更者，經被繼承人宥恕，其繼承權不喪失（§1145 II）。"],"tr":""},{"id":"h:112-25","p":"h","src":"112年第25題","sec":"E4","stem":"關於拋棄繼承之敘述，下列何者錯誤？","opts":["應於知悉其得繼承之時起三個月內，以書面向法院為之","拋棄繼承後，應通知因其拋棄而應為繼承之人。未為通知者，不生拋棄繼承之效力","配偶拋棄繼承權者，其應繼分歸屬於與其同為繼承之人","繼承之拋棄，溯及於繼承開始時發生效力"],"ok":[1],"ex":["§1174 II：應於知悉得繼承之時起三個月內，以書面向法院為之。","§1174 III僅要求拋棄後應以書面通知因其拋棄而應為繼承之人，未通知並不影響拋棄效力。","§1176 IV：配偶拋棄繼承權者，其應繼分歸屬於與其同為繼承之人。","§1175：繼承之拋棄，溯及於繼承開始時發生效力。"],"tr":""},{"id":"h:111-1","p":"h","src":"111年第1題","sec":"E4","stem":"依我國民法第 1173 條有關歸扣之規定，下列何種被繼承人生前將財產贈與某特定繼承人，無須將該贈與價額，於遺產分割時，由該繼承人之應繼分中扣除？","opts":["因該特定繼承人結婚時之贈與","因該特定繼承人重大災難生還時之贈與","因該特定繼承人從家裡決定分居時之贈與","因該特定繼承人決定經營事業時之贈與"],"ok":[1],"ex":["因結婚所為之贈與，屬§1173 I列舉之特種贈與，須歸扣。","重大災難生還之贈與不屬§1173 I所列「結婚、分居、營業」，無須歸扣。","因分居所為之贈與，屬§1173 I列舉事由，須歸扣。","因營業所為之贈與，屬§1173 I列舉事由，須歸扣。"],"tr":""},{"id":"h:111-2","p":"h","src":"111年第2題","sec":"E1","stem":"下列何種情況是非屬於近親禁止結婚之規範範圍？","opts":["與離婚後無依無靠之前小姨子結婚","與終止收養後之前養女結婚","與自己兒子離婚後之前媳婦結婚","與叔叔死亡後孤苦守寡之叔母結婚"],"ok":[0],"ex":["前小姨子為旁系姻親（二親等、同輩），§983 I③僅禁止「輩分不同」之旁系姻親五親等內結婚，故不在禁止範圍。","前養女與養父為因收養成立之直系血親，終止收養後仍適用禁止（§983 III），屬禁婚範圍。","前媳婦為直系姻親，姻親關係消滅後仍禁止結婚（§983 II），屬禁婚範圍。","叔母為旁系姻親三親等且輩分不同，屬§983 I③禁婚範圍；姻親關係只因離婚或結婚撤銷而消滅（§971），叔叔死亡不消滅姻親關係。"],"tr":""},{"id":"h:111-3","p":"h","src":"111年第3題","sec":"E4","stem":"下列何者得為被繼承人親屬中之法定繼承人？","opts":["被繼承人兄弟之配偶","被繼承人父親之兄弟","被繼承人母親之兄弟之配偶","被繼承人所認領之非婚生子女"],"ok":[3],"ex":["兄弟之配偶為旁系姻親，非§1138所列血親繼承人（僅配偶為例外）。","父親之兄弟為三親等旁系血親（伯叔），不在§1138所列順序（兄弟姊妹、祖父母止）。","母親之兄弟之配偶為姻親，非繼承人。","認領之非婚生子女視為婚生子女（§1065 I），屬第一順序直系血親卑親屬（§1138①）。"],"tr":""},{"id":"h:111-4","p":"h","src":"111年第4題","sec":"C1","stem":"下列敘述，何者錯誤？","opts":["使用借貸契約必須是無償的契約","借用人得主張買賣不破使用借貸之抗辯","借用物為動物時，飼養費原則上應由借用人承擔","借用人對於借用物原則上並無轉租收益之權限"],"ok":[1],"ex":["使用借貸（§464）本質為無償（若有償則為租賃），正確。","「買賣不破使用借貸」並無民法明文規定（§425買賣不破租賃適用於租賃，不及於使用借貸），使用借貸為無償，無類推適用§425之保護，故借用人不能主張買賣不破使用借貸，本選項說「得主張」錯誤，為應選答案。","使用借貸，借用物之管理費用（如飼養費）由借用人負擔（§469），正確。","§467Ⅱ：借用人非經貸與人之同意，不得允許第三人使用借用物；借用人原則上只能自己使用，不得擅自轉租收益，正確。"],"tr":""},{"id":"h:111-5","p":"h","src":"111年第5題","sec":"D2","stem":"依現行民法之規定，下列何者非為不動產登記前，即能取得不動產之所有權？","opts":["不動產所有權因繼承而取得","不動產所有權之時效取得","不動產所有權因徵收而取得","不動產所有權因強制執行而取得"],"ok":[1],"ex":["§759：因繼承於登記前已取得不動產物權（僅處分時須先登記），屬不登記即能取得，選項排除。","§769、§770：占有人經二十年（或善意無過失十年）和平、公然、繼續占有未登記不動產，只是「得請求登記為所有人」，須登記後才取得所有權，故非「登記前即能取得」，為應選答案。","§759：因徵收於登記前已取得不動產物權（處分時須先登記），屬不登記即能取得，選項排除。","§759：因強制執行於登記前已取得不動產物權（處分時須先登記），屬不登記即能取得，選項排除。★§759列舉：繼承、強制執行、徵收、法院判決等非因法律行為取得，登記前已取得；時效取得則須先登記（§769、§770）。"],"tr":""},{"id":"h:111-6","p":"h","src":"111年第6題","sec":"B1","stem":"下列何種情形，債務人之原有債務不會發生消滅之效果？","opts":["債權人受領債務人以代物清償方式清償原有之債務","債務人對債權人已屆清償期之債權行使抵銷權，彼此間在抵銷數額之債權債務","債權與其債務發生混同之情形","債務人以間接給付之方式清償原有之債務"],"ok":[3],"ex":["代物清償（§319）：經債權人同意以他種給付代原定給付，經受領後原債務即消滅。","抵銷（§334 I）：二人互負債務、種類相同且均屆清償期，經意思表示即各按債務額同時消滅。","混同（§344）：債權與其債務同歸一人，債之關係消滅（但法律另有規定或債權為他人權利標的者例外）。","間接給付（§320）：因清償舊債而負擔新債，除另有意思表示外，新債務不履行時舊債務仍不消滅；新債務履行後舊債務才隨之消滅，故不會因『約定』當下消滅。"],"tr":""},{"id":"h:111-7","p":"h","src":"111年第7題","sec":"B5","stem":"在無因管理之規定中，若管理人管理事務時，利於本人，且不違反本人明示或可得推知之意思者，管理人不得向本人主張下列那種請求權？","opts":["管理人管理本人事務之有益費用支出償還請求權","清償管理人因管理事務所負債務之請求權","管理人因管理事務所受損害之賠償請求權","管理人管理本人事務之報酬請求權"],"ok":[3],"ex":["§176 I：管理事務利於本人且不違反其明示或可得推知之意思者，管理人得請求償還支出之有益費用及利息。","§176 I：管理人得請求本人清償其因管理事務所負擔之債務。","§176 I：管理人因管理事務所受之損害，得請求本人賠償。","無因管理規定中無報酬請求權之明文，管理人僅能請求費用、債務清償及損害賠償，不得請求報酬。"],"tr":""},{"id":"h:111-8","p":"h","src":"111年第8題","sec":"A6","stem":"有關現行民法代理制度之介紹，下列何者錯誤？","opts":["未經本人事前同意之自己代理，對於本人而言，係無效之代理行為","民法第 169 條表見代理效力之發生，須無本人之授予代理權為其要件","間接代理人之代理行為不會對本人直接發生效力","代理人為代理行為時，被相對人詐欺，本人得自行撤銷該代理行為"],"ok":[0],"ex":["§106規定，代理人非經本人許諾，不得自己代理（自己代理禁止）；未經許諾之自己代理行為效果應為「效力未定」（須本人承認始生效）而非「無效」，將其定性為「無效」描述錯誤，為本題應選答案。","表見代理（§169）的前提是本人並未授與代理權，但因本人的行為或不作為使第三人信賴有代理權而保護之，正確。","間接代理（如行紀）是代理人以自己名義為法律行為，法律效果歸屬代理人，再由代理人移轉給本人，並非直接對本人發生效力，正確。","代理人（乙）受相對人詐欺，意思表示瑕疵依§105以代理人決之，撤銷權歸屬本人（甲），本人得撤銷（以代理人之知情與否決定本人得否撤銷），正確。"],"tr":""},{"id":"h:111-9","p":"h","src":"111年第9題","sec":"A2","stem":"對於民法上有關法人規定之說明，下列何者正確？","opts":["財團法人具有自律法人之性質","社員資格須經社團之董事會特別決議同意，且有正當理由時，方能開除之","財團法人之設立，得以遺囑為之","社團法人以社團董事會為其最高意思機關"],"ok":[2],"ex":["財團法人之設立目的及章程由捐助人設定，組織較固定，屬「他律法人」（受外部章程拘束），而「自律法人」是指可自行制訂規範（如社團法人），本選項財團法人之說法相反。","開除社員屬社團總會的決議事項，且須有正當理由（§50Ⅱ：變更章程、任免董事及監察人、開除社員等應經總會決議，其中開除社員以有正當理由為限）；並非由董事會特別決議，選項把決議機關誤為董事會，錯誤。（§54是社員退社的規定，勿與開除混淆。）","§60Ⅰ但書：設立財團原則上應訂立捐助章程，但以遺囑捐助者，不在此限，亦即財團得以遺囑設立；§60Ⅲ並規定無遺囑執行人時，法院得指定遺囑執行人，正確。","§50Ⅰ：社團以「總會」（社員大會）為最高機關；董事是執行及對外代表機關，並非最高意思機關，錯誤。"],"tr":""},{"id":"h:111-10","p":"h","src":"111年第10題","sec":"A1","stem":"依現行民法有關住所之規定，下列何者錯誤？","opts":["夫妻於雙方共同協議前，推定以共同戶籍地為其法定之住所","意定住所之設定須具備久住之意思及居住之事實","因特定行為選定居所，關於其行為，不得視為住所","16 歲之年輕人，僅能以其父母之住所為法定住所"],"ok":[2],"ex":["§1002：夫妻之住所由雙方共同協議；未協議或協議不成時，得聲請法院定之；法院裁定前，以夫妻共同戶籍地推定為其住所，正確。","§20Ⅰ：依一定事實，足認以「久住之意思」住於一定地域者，即設定其住所於該地，所以須有久住意思與居住事實（主觀＋客觀），正確。","§23：因特定行為選定居所者，關於其行為，「視為住所」；本選項說「不得視為住所」，與條文相反，為錯誤選項，即應選答案。","§21：無行為能力人及限制行為能力人，以其法定代理人之住所為住所；16歲為限制行為能力人（§13Ⅱ：滿七歲以上之未成年人），其法定代理人通常為父母，故以父母住所為法定住所，正確。"],"tr":""},{"id":"h:111-11","p":"h","src":"111年第11題","sec":"A4","stem":"關於民法第 74 條暴利行為之規定，下列敘述何者正確？","opts":["當事人無論於財產給付前或給付後，均得聲請撤銷該暴利行為","撤銷權自該法律行為成立時起一年內不行使，罹於消滅時效而消滅","行使暴利行為之撤銷權時，應以意思表示向相對人為之","暴利行為自始當然無效"],"ok":[0],"ex":["§74Ⅰ：乘他人急迫、輕率或無經驗，使其為財產上之給付「或為給付之約定」而顯失公平者，法院得因利害關係人之聲請撤銷其法律行為或減輕其給付；不論尚未給付（只有約定）或已給付，均可聲請，正確。","§74Ⅱ：聲請應於法律行為後一年內為之，此一年屬「除斥期間」（期間屆滿權利即消滅），並非「消滅時效」；選項誤稱消滅時效，錯誤。","§74Ⅰ是由利害關係人「聲請法院」撤銷或減輕給付，而非以意思表示向相對人為之（錯誤、詐欺、脅迫的撤銷才是依§116以意思表示向相對人為之），此為重要區別。","暴利行為非當然無效，須利害關係人積極向法院「聲請撤銷」後，才失其效力；未聲請前契約仍有效。"],"tr":""},{"id":"h:111-12","p":"h","src":"111年第12題","sec":"B3","stem":"下列何者非法律明文規定屬於連帶債務之性質？","opts":["合夥財產不足清償合夥債務時，各合夥人對於該不足額之債務","數人共同不法侵害他人權利所生之損害賠償債務","共同繼承人對於被繼承人，於繼承所得遺產限度內之遺產債務","共有人對於他共有人因分割而得之物，所負之擔保責任債務"],"ok":[3],"ex":["§681：合夥財產不足清償合夥債務時，各合夥人對不足額連帶負責，屬法律明文之連帶債務。","§185 I：數人共同不法侵害他人權利者，連帶負損害賠償責任。","§1153 I：繼承人對被繼承人之債務，以因繼承所得遺產為限，負連帶責任。","§825：各共有人對他共有人因分割所得之物，按其應有部分負與出賣人相同之擔保責任，是分擔而非連帶。"],"tr":""},{"id":"h:111-13","p":"h","src":"111年第13題","sec":"C4","stem":"下列何者非屬贈與人或其繼承人，得主張撤銷贈與契約之原因？","opts":["附有負擔之贈與，贈與人已為給付而受贈人因過失不履行其負擔者","受贈人對於贈與人有扶養義務而不履行義務者","受贈人因故意不法行為致贈與人死亡者","定期給付之贈與，而受贈人已死亡者"],"ok":[3],"ex":["§412 I：附負擔之贈與，贈與人已給付而受贈人不履行負擔時，贈與人得請求履行或撤銷贈與。","§416 I②：受贈人對贈與人有扶養義務而不履行者，贈與人得撤銷贈與。","受贈人因故意不法行為致贈與人死亡者，贈與人之繼承人得撤銷贈與（§417）。","定期給付之贈與，因贈與人或受贈人死亡而失其效力（§415），屬契約失效，並非撤銷原因。"],"tr":""},{"id":"h:111-14","p":"h","src":"111年第14題","sec":"D2","stem":"關於共有不動產分管契約之敘述，下列何者正確？","opts":["分管契約應以共有人半數以上及其應有部分合計過半數，或應有部分合計逾三分之二之同意訂定之","分管契約訂定後，若因情事變更難以繼續時，法院得因任何共有人之聲請，以裁定變更之","共有人對於分管契約無法達成協議時，得訴請法院裁判定分管方式","分管契約訂定後，對於應有部分之受讓人於受讓時知悉其情事者，亦具有效力"],"ok":[1],"ex":["§820 I 之門檻為「共有人過半數及其應有部分合計過半數」（應有部分合計逾三分之二者人數不計），選項寫「半數以上」與條文不符（分管屬共有物之管理，現行§820 I 得以多數決訂定；修法前實務採須全體同意）。","§820 III：共有物管理因情事變更難以繼續時，法院得因任何共有人之聲請以裁定變更之。","分管無法達成協議時，法院無從替當事人訂立分管契約；欲終止共有關係須依§824 請求分割。","§826-1 I：不動產分管約定須經登記，對受讓人才有效力；單純知悉不足，「知悉或可得而知」者限於動產共有。"],"tr":""},{"id":"h:111-15","p":"h","src":"111年第15題","sec":"E4","stem":"甲與乙結婚，生有三個女兒丙、丁、戊。丙因未婚生有二子庚及辛，曾與其母乙發生重大爭吵及言語侮辱情事，而遭甲表示剝奪其繼承權。丁則於甲生前即已向甲表示，當甲百年後將拋棄繼承權。設甲死亡時留有遺產現金 600 萬元，並未立有遺囑。問：甲之遺產依法應如何分配？","opts":["乙、丙、丁、戊各 150 萬元","乙、戊各 200 萬元，庚、辛各 100 萬元","乙、丁、戊各 150 萬元，庚、辛各 75 萬元","乙、戊各 300 萬元"],"ok":[0],"ex":["丙對母乙侮辱，並非對「被繼承人甲」，不符§1145 I⑤，未喪失繼承權；丁於繼承開始前表示拋棄無效（§1174僅繼承開始後可為）。繼承人乙＋丙丁戊共四人平均（§1144①），各150萬。","丙未喪失繼承權，庚辛無代位繼承（§1140）；且丁未有效拋棄。","丁預先之拋棄無效，仍為繼承人，且庚辛無代位原因。","丙、丁均仍為繼承人，不能僅由乙、戊分配。"],"tr":""},{"id":"h:111-16","p":"h","src":"111年第16題","sec":"E4","stem":"關於限定繼承之敘述，下列何者正確？","opts":["限定繼承係指繼承人自繼承開始時，僅承受被繼承人財產上之權利，而不繼承其債務","繼承人縱未依法開具遺產清冊陳報法院，並不當然喪失限定繼承之利益","繼承人隱匿被繼承人之遺產而情節重大者，仍可主張限定繼承之利益","繼承人應先對受遺贈人交付遺贈，其次償還優先權之債務，再清償普通債務"],"ok":[1],"ex":["§1148 II：限定繼承是仍繼承債務，但責任以所得遺產為限，並非不繼承債務。","現行§1148 II採有限責任為原則，未陳報遺產清冊並不當然喪失利益；喪失事由限於§1163所列。","§1163：隱匿遺產情節重大者，不得主張§1148 II之利益。","§1159 I但書、§1160：應先償還債權人（不得害及有優先權人之利益），清償後才得對受遺贈人交付遺贈。"],"tr":""},{"id":"h:111-17","p":"h","src":"111年第17題","sec":"E2","stem":"關於夫妻法定財產制之規定，下列敘述何者正確？","opts":["夫或妻之財產分為婚前財產與婚後財產，婚前財產由夫妻各自所有，婚後財產則由夫妻共有","夫或妻於婚姻關係存續中就其婚後財產所為之無償行為，應將該財產追加計算，視為現存之婚後財產","夫或妻各自管理、使用、收益及處分其婚前及婚後財產，並各自對其債務負清償之責","剩餘財產差額分配請求權屬一身專屬性之權利，請求權人自法定財產制關係消滅時起，二年間不行使而消滅"],"ok":[2],"ex":["§1017 I：婚前、婚後財產均各自所有，婚後財產不是共有。","§1030-3：須「為減少他方分配」且於關係消滅前五年內處分，才追加計算，選項未載此要件。","§1018、§1023 I：夫妻各自管理、使用、收益、處分其婚前婚後財產，並各自負清償債務之責。","§1030-1：請求權自知有差額時起2年、關係消滅時起逾5年消滅；選項「消滅時起二年」錯誤。"],"tr":""},{"id":"h:111-18","p":"h","src":"111年第18題","sec":"D6","stem":"甲將其 A 地設定地上權予乙，乙於 A 土地上興建 B 屋一棟。其後甲為貸款擔保而將其 A 地設定抵押權予丙，乙亦因其貸款擔保而將 B 屋設定抵押權予丁。下列敘述何者正確？","opts":["若丁實行抵押權拍賣 B 屋時，A 地所有權應併付拍賣之","若丁實行抵押權拍賣 B 屋時，地上權應併付拍賣之","若丙實行抵押權拍賣 A 地所有權時，B 屋應併付拍賣之","若丙實行抵押權拍賣 A 地所有權時，地上權應併付拍賣之"],"ok":[1],"ex":["丁實行的是B屋抵押權；§877-1 只規定建築物存在所必要之「權利」（本題即乙的地上權）應併付拍賣。A地所有權屬甲，既非抵押物，也不是B屋存在所必要之「權利」，不會併付拍賣。","§877-1：以建築物設定抵押權者，其存在所必要之地上權（得讓與者）應併付拍賣，但無優先受償權。","§877 I 限於土地所有人於設定抵押後營造建物；B屋由地上權人乙營造且地上權在先，不適用。","地上權設定在抵押權之前，不受抵押權影響，拍賣A地所有權時地上權仍存在，不併付拍賣。"],"tr":""},{"id":"h:111-19","p":"h","src":"111年第19題","sec":"D1","stem":"甲無權占有乙之土地種植果樹，其果實歸屬於何人？","opts":["果實在與果樹分離前或分離後，均屬於甲所有","果實在與果樹分離前或分離後，均屬於乙所有","果實在與果樹分離前屬於甲所有，分離後屬於乙所有","果實在與果樹分離前屬於乙所有，分離後屬於甲所有"],"ok":[1],"ex":["果樹栽種於乙之土地附合於土地（§811），不屬甲，分離前後都不屬甲。","果樹附合於土地屬乙（§811），果實分離前為原物之部分（§66 II），分離後由有收取權之乙取得（§70 I）。","分離前亦屬乙，非屬甲。","分離後亦由乙取得，非由甲取得。"],"tr":""},{"id":"h:111-20","p":"h","src":"111年第20題","sec":"C1","stem":"特定物買賣，若因物有瑕疵而出賣人依法應負物之瑕疵擔保責任時，下列何者非買受人依法所得主張之權利？","opts":["解除買賣契約","請求減少買賣價金","請求另行交付無瑕疵之物","故意不告知瑕疵時，請求損害賠償"],"ok":[2],"ex":["依§359，出賣人應負物之瑕疵擔保責任時，買受人得解除契約或請求減少價金；但依情形解除契約顯失公平者，僅得請求減少價金。故解除契約原則上可主張，不是答案。","同§359，買受人得請求減少價金，不是答案。","依§364Ⅰ，「另行交付無瑕疵之物」限於買賣標的「僅指定種類」（種類物）；本題是特定物，標的唯一，無從以他物替代，買受人不得請求另行交付，故為應選答案。","依§360 後段，出賣人故意不告知物之瑕疵者，買受人得不解除契約或請求減少價金，而請求不履行之損害賠償，可主張，不是答案。"],"tr":""},{"id":"h:111-21","p":"h","src":"111年第21題","sec":"C2","stem":"關於租賃法律關係之敘述，下列何者正確？","opts":["期限逾一年之不動產租賃契約，應以字據訂立之，否則契約無效","定有期限之不動產租賃，因其價值之昇降，當事人得聲請法院增減其租金","不動產之出租人就租金債權，對於承租人之物置於該不動產者，有法定質權","租用基地建築房屋者，承租人於契約成立後，得請求出租人為地上權之登記"],"ok":[3],"ex":["§422：不動產租賃逾一年未以字據訂立者，視為不定期租賃，並非無效。","§442：定有期限之租賃不得聲請法院增減租金；僅不定期租賃可增減。","§445：不動產出租人就租金債權，對於承租人置於該不動產之物享有留置權，而非法定質權。","§422-1：租用基地建築房屋者，承租人於契約成立後，得請求出租人為地上權之登記。"],"tr":""},{"id":"h:111-22","p":"h","src":"111年第22題","sec":"B1","stem":"二人互負債務而其給付種類相同，並均屆清償期者，得以其債務與他方之債務互為下列何項主張，以消滅其債務？","opts":["抵銷","抵充","免除","混同"],"ok":[0],"ex":["§334，雙方互負同種類債務（如均為金錢債務）且均屆清償期，得主張「抵銷」，在抵銷數額內同時消滅，正確。","抵充（§321以下）：同一債務人對同一債權人有數個債務，清償時指定以何者抵充（清償抵充），與本題雙方互負不同，概念不符。","免除（§343）：債權人向債務人表示免除其債務，單方意思表示，與本題互相抵銷不同。","混同（§344）：同一人同時為債權人及債務人，債權因混同而消滅，與本題兩人各有債務不同。"],"tr":""},{"id":"h:111-23","p":"h","src":"111年第23題","sec":"A1","stem":"滿 17 歲且未受監護或輔助宣告之甲男，其所為之下列何種行為，依法須得法定代理人之同意始為有效？","opts":["訂立遺囑為遺贈之行為","純獲法律上利益之行為","就他人之物所為之無權處分行為","授予他人代理權之行為"],"ok":[3],"ex":["§1186Ⅱ 限制行為能力人（滿16歲）得為遺囑，無須法定代理人允許。","§77但書 純獲法律上利益之行為不須法定代理人允許即有效。","無權處分之效力取決於權利人承認或取得處分權（§118），法定代理人同意無從補正處分權。","授權行為為單獨行為，非純獲利益，限制行為能力人須得法定代理人允許（§77）；欠缺者無效（§78）。"],"tr":""},{"id":"h:111-24","p":"h","src":"111年第24題","sec":"A2","stem":"關於財團法人之敘述，下列何者正確？","opts":["財團法人得為公益或營利之目的而設立","財團法人於設立登記前，應得主管機關之許可","財團法人之最高意思機關為總會，且為必設之機關","財團法人若以營利為目的設立，其取得法人資格，依特別法之規定"],"ok":[1],"ex":["民法僅在§45規定營利「社團」得依特別法取得法人資格，並無營利「財團」的設計；財團法人以捐助財產為基礎，依通說須以公益為目的，不得為營利目的，故「公益或營利均可」錯誤。","§59：財團於登記前，應得主管機關之許可；即未經許可不得辦理設立登記，正確。","總會是社團法人的最高意思機關，財團法人無社員總會，其設立目的及章程由捐助人決定，無「總會」機關設計。","§45：「以營利為目的之社團」，其取得法人資格依特別法（如公司法）之規定，適用對象是「社團」而非「財團」；財團法人並無此規定，選項張冠李戴，錯誤。"],"tr":""},{"id":"h:111-25","p":"h","src":"111年第25題","sec":"A4","stem":"下列何者屬於當然無效之法律行為？","opts":["單獨虛偽意思表示而該情形為相對人所明知者","詐欺之意思表示係由第三人所為，而相對人明知其事實或可得而知者","無權利人就權利標的物為處分後，取得其權利者","限制行為能力人用詐術使人信其為有行為能力人，所為之法律行為"],"ok":[0],"ex":["依§86但書，單獨虛偽意思表示（心中保留），若相對人明知，則意思表示「無效」（當然無效），正確。","§92Ⅰ但書：詐欺由第三人所為者，以相對人明知其事實或可得而知者為限，表意人始得「撤銷」其意思表示；撤銷前法律行為仍有效，屬「得撤銷」而非當然無效。","無權利人處分後取得其權利，該處分行為「溯及發生效力」（§118Ⅱ），即補正為有效，並非無效。","限制行為能力人用詐術，依§83，其法律行為「有效」，並非無效。"],"tr":""},{"id":"h:110-1","p":"h","src":"110年第1題","sec":"C1","stem":"甲與乙訂立買賣契約，契約條款記載「...價金新臺幣陸拾捌萬元整(NT$860,000)。前揭捌拾陸萬元價金應於訂約後 10 日內支付。」 若嗣後雙方就價金金額爭訟時，法院應如何決定價金？","opts":["應認為價金為最後書寫之文字：捌拾陸萬元","應先探求當事人原意","應認為價金為兩項金額之平均值：柒拾柒萬元","如法院不能決定當事人原意，應以數字為準：NT$860,000"],"ok":[1],"ex":["契約解釋不是以最後書寫之文字為準，法無此規定。","§98：解釋意思表示，應探求當事人之真意，不得拘泥於所用之辭句；文字與數字不符時，應先探求真意。","法無「取平均值」之解釋規則，亦非探求真意之方法。","依民法§4，文字與號碼不符、法院不能決定當事人原意時，應以「文字」為準，不是以數字為準，本選項錯誤。"],"tr":""},{"id":"h:110-2","p":"h","src":"110年第2題","sec":"A1","stem":"關於胎兒的敘述，下列何者正確？","opts":["人之權利能力，始於出生，終於死亡。胎兒無權利能力","胎兒以將來非死產者為限，關於其個人利益之保護，視為既已出生","胎兒為繼承人時，於胎兒出生前，他繼承人不得分割遺產","胎兒為繼承人時，以其母為繼承人"],"ok":[1],"ex":["前半句正確（§6：人之權利能力始於出生、終於死亡），但「胎兒無權利能力」說得太絕對：§7規定胎兒以將來非死產者為限，關於其個人利益之保護，視為既已出生（例如可繼承，見§1166），故此句錯誤。","§7：胎兒只要將來不是死產（活著出生），關於其個人利益的保護，就當作已經出生；這是條文明文規定，正確。","§1166Ⅰ：胎兒為繼承人時，「非保留其應繼分」，他繼承人不得分割遺產，也就是只要先保留胎兒的應繼分，其他繼承人仍可分割；本選項說胎兒出生前「不得分割」過於絕對，錯誤。（考試陷阱：條文是「非保留應繼分不得分割」，不是「一律不得分割」。）","胎兒本身就是繼承人（§7、§1166Ⅰ），並非「以其母為繼承人」；§1166Ⅱ只規定胎兒關於遺產分割，以其母為「代理人」，是代理關係而非繼承人身分，選項把「代理人」誤為「繼承人」，錯誤。"],"tr":""},{"id":"h:110-3","p":"h","src":"110年第3題","sec":"A1","stem":"關於失蹤人的敘述，下列何者正確？","opts":["失蹤人失蹤滿七年後，法院得因利害關係人或檢察官之聲請，為死亡之宣告","失蹤人為八十歲以上者，得於失蹤滿五年後，為死亡之宣告","失蹤人為遭遇特別災難者，得於特別災難終了滿三個月後，為死亡之宣告","失蹤人失蹤後，未受死亡宣告前，其財產之管理，除其他法律另有規定者外，依破產法之規定"],"ok":[0],"ex":["§8Ⅰ 失蹤滿7年，法院得因利害關係人或檢察官聲請為死亡宣告。","§8Ⅱ 八十歲以上者為失蹤滿3年，非5年。","§8Ⅲ 遭遇特別災難者，得於災難終了滿1年後宣告，非3個月。","§10 失蹤人財產管理，除其他法律另有規定者外，依家事事件法之規定，非破產法。"],"tr":""},{"id":"h:110-4","p":"h","src":"110年第4題","sec":"A1","stem":"關於行為能力之敘述，下列何者錯誤？","opts":["受監護宣告之人之意思表示，無效，應由其法定代理人代為意思表示，並代受意思表示","限制行為能力人未得法定代理人之允許，所為之單獨行為，無效","未滿法定結婚年齡之男女，其結婚之法律效果並非無效，而是得撤銷","為保障胎兒之行為能力，胎兒以將來非死產者為限，關於其個人利益之保護，視為既已出生"],"ok":[3],"ex":["§15：受監護宣告之人無行為能力；§75前段：無行為能力人之意思表示無效；§76：無行為能力人由法定代理人代為意思表示，並代受意思表示。三者合併，本選項正確。","§78：限制行為能力人未得法定代理人允許所為之「單獨行為」無效（不同於契約行為，依§79為效力未定，須經承認），正確。","§989：結婚違反§980（法定結婚年齡）者，當事人或其法定代理人得向法院請求撤銷，效果是「得撤銷」而非無效，正確。","§7所保護的是「權利能力」而非「行為能力」；胎兒本身未出生，毫無行為能力（無能力為意思表示），§7是以「將來非死產為限」擬制其已有部分「權利能力」以保護其利益，並非給予行為能力，本選項將「權利能力」說成「行為能力」，概念完全錯誤，為應選答案。"],"tr":""},{"id":"h:110-5","p":"h","src":"110年第5題","sec":"A6","stem":"關於代理的敘述，下列何者正確？","opts":["代理權係以法律行為授與者，其授與應向代理人或向代理人對之為代理行為之第三人，以書面授權方式代理為之","代理人有數人者，其代理行為應單獨為之。但法律另有規定或本人另有意思表示者，不在此限","由自己之行為表示以代理權授與他人，或知他人表示為其代理人而不為反對之表示者，對於第三人應負授權人之責任。但第三人明知其無代理權或可得而知者，不在此限","代理人於代理權限內，以本人名義所為之意思表示，直接對本人發生效力。而無代理權人以代理人之名義所為之法律行為則為無效"],"ok":[2],"ex":["代理權授與不以書面為必要，口頭授與亦可（法律另有規定除外），本選項「以書面授權方式」之限制不正確。","依§168，代理人有數人者，其代理行為應「共同」為之（非單獨），但法律另有規定或本人另有意思表示者不在此限，本選項把「共同」說成「單獨」，相反。","此描述為§169表見代理的規定：本人以行為表示授與代理權，或知他人以其名義為代理人而不反對者，對善意第三人負授權人責任；但第三人明知其無代理權「或可得而知」者，不在此限。正確。","前半段（有代理權之代理行為對本人生效）正確，但後半段「無代理權→無效」錯誤：無權代理之效果為「效力未定」（§170），而非無效（須本人不承認才確定不生效）。"],"tr":""},{"id":"h:110-6","p":"h","src":"110年第6題","sec":"A4","stem":"下列何種法律行為屬法定書面要式行為？","opts":["動產所有權之拋棄","子女之收養","贈與契約","演藝經紀契約"],"ok":[1],"ex":["動產所有權之拋棄以「占有之拋棄」為之，並不以書面為必要，並非法定要式行為。","收養子女依§1079Ⅰ，應以書面為之，並向法院聲請認可，屬法定書面要式行為，正確。","贈與契約（§406）為諾成、不要式契約，口頭贈與即有效（但未移轉前得任意撤銷，此為另一層問題），並非法定書面要式。","演藝經紀契約在民法並無明文規定書面要式，依契約自由原則為不要式契約（特別法另有規定者除外）。"],"tr":""},{"id":"h:110-7","p":"h","src":"110年第7題","sec":"A5","stem":"關於意思表示不一致的敘述，下列何者正確？","opts":["表意人無欲為其意思表示所拘束之意，而為意思表示者，其意思表示無效","表意人無欲為其意思表示所拘束之意，而為意思表示，其情形為相對人所明知者，其意思表示有效","表意人與相對人通謀而為虛偽意思表示者，其意思表示不因之無效","虛偽意思表示，隱藏他項法律行為者，適用關於該項法律行為之規定"],"ok":[3],"ex":["依§86，表意人心中保留（無欲受拘束之意），其意思表示「原則上有效」，僅在相對人明知時才無效，並非當然無效。","相對人明知表意人無真意，依§86但書，其意思表示「無效」，並非有效，本選項與法條規定相反。","通謀虛偽意思表示，依§87Ⅰ，其意思表示「無效」，並非不因之無效（因之無效），選項與法條相反。","依§87Ⅱ，通謀虛偽意思表示若「隱藏他項法律行為」（如以買賣外衣隱藏贈與），該虛偽表示雖無效，但所隱藏之真實法律行為（贈與）仍適用其規定（若符合要件則有效），正確。"],"tr":""},{"id":"h:110-8","p":"h","src":"110年第8題","sec":"D6","stem":"關於抵押權所擔保而得優先受償之利息，以於抵押權人實行抵押權聲請強制執行前幾年內發生及於強制執行程序中發生者為限？","opts":["二年","五年","十年","十五年"],"ok":[1],"ex":["§861Ⅱ得優先受償之利息等以聲請執行前「五年」內發生者為限，並非二年（§861Ⅱ中「一年」是指違約金限一年或不及一年之定期給付，勿與利息期間混淆）。","§861Ⅱ：得優先受償之利息、遲延利息、一年或不及一年定期給付之違約金債權，以抵押權人實行抵押權聲請強制執行前「五年」內發生及於強制執行程序中發生者為限，正確。","十年是§770善意無過失占有他人未登記不動產之取得時效期間，與抵押權利息優先受償期間無關。","十五年是§913典權絕賣條款之門檻（約定期限不滿十五年者不得附到期不贖即作絕賣之條款）與§125請求權時效期間，與§861Ⅱ無關。★§861Ⅱ重點：利息五年內（聲請執行前五年）方優先受償。"],"tr":""},{"id":"h:110-9","p":"h","src":"110年第9題","sec":"D2","stem":"依現行民法規定，下列何者須經登記始生法律效力？","opts":["遺產之繼承","土地買賣契約","設定抵押權之物權行為","夫妻就共同財產制之約定"],"ok":[2],"ex":["§759：繼承於登記前即已取得不動產物權，僅處分時須先登記，不以登記為取得要件，選項排除。","§345：土地買賣「契約」為債權行為，當事人就標的物及價金互相同意即成立，不以登記為生效要件，選項排除。","§758Ⅰ：不動產物權依法律行為而取得、設定、喪失及變更者，非經登記不生效力；設定抵押權之物權行為屬之，正確。","§1007：夫妻財產制契約應以書面為之；§1008Ⅰ：非經登記不得對抗第三人，登記僅關乎對抗第三人，並非契約生效要件，選項排除。"],"tr":""},{"id":"h:110-10","p":"h","src":"110年第10題","sec":"A6","stem":"下列何者屬於授與代理權？","opts":["甲創作民法總則一書，授權乙出版社於五年間印製出版該書","甲有一 A 車，授權乙以甲本人名義買賣 A 車","甲為知名影星，授權乙週刊使用甲肖像照片","甲有一昆蟲標本，授權乙予以拍攝"],"ok":[1],"ex":["授權出版是著作財產權的授權（「利用授權」），並非民法代理權的授與；乙出版是以乙自己名義出版，並非以甲名義為甲辦理法律行為。","甲授權乙「以甲本人名義」買賣A車，即乙以甲名義對外為法律行為，效果歸屬於甲，此為代理（意定代理）的核心定義，正確。","肖像使用授權是人格權授權，乙使用甲肖像是乙自己的行為，並非代理甲對外為法律行為。","授權拍攝是著作/財產使用授權，乙拍攝以乙名義進行，非代理。"],"tr":""},{"id":"h:110-11","p":"h","src":"110年第11題","sec":"B3","stem":"民法於保證契約一節中規定，保證人於債權人未就主債務人之財產強制執行而無效果前，對於債權人得拒絕清償，概念上一般稱為？","opts":["同時履行抗辯","撤銷訴權","追索權抗辯","先訴抗辯"],"ok":[3],"ex":["同時履行抗辯（§264）：雙務契約一方未提出履行，他方得拒絕己方給付，與保證無關。","撤銷訴權（§244）：債權人撤銷債務人詐害行為之權利，與保證抗辯無關。","追索權見於票據法（票據不獲付款後向前手追索），與民法保證無關。","§745「先訴抗辯」（或稱「先訴利益」）：保證人於債權人未先就主債務人財產強制執行無效果前，得拒絕清償，此即先訴抗辯，正確。"],"tr":""},{"id":"h:110-12","p":"h","src":"110年第12題","sec":"B3","stem":"關於連帶債務的敘述，下列何者正確？","opts":["連帶債務人相互間，縱因債務人中之一人應單獨負責之事由所致之損害及支付之費用，仍應平均分擔義務","連帶債務人中之一人，因清償、代物清償、提存、抵銷或混同，致他債務人同免責任者，得向他債務人請求償還各自分擔之部分，但不得請求利息","連帶債務人中之一人，不能償還其分擔額者，其不能償還之部分，由求償權人與他債務人按照比例分擔之","連帶債務人中之一人，不能償還其分擔額，而他債務人中之一人應分擔之部分已免責者，無須負其責任"],"ok":[2],"ex":["§280 但書：因債務人中之一人應單獨負責之事由所致損害及費用，由該債務人負擔，並非平均分擔。","§281 I：求償得包括自免責時起之利息。","§282 I：連帶債務人中之一人不能償還其分擔額者，其不能償還之部分，由求償權人與他債務人按比例分擔。","§282 II：他債務人中之一人應分擔部分已免責者，仍應按比例分擔。"],"tr":""},{"id":"h:110-13","p":"h","src":"110年第13題","sec":"A4","stem":"下列何種情形，當事人一方須以向法院聲請撤銷方式為之？","opts":["因受詐欺所為之意思表示","債務人所為之無償行為，有害及債權者","締結違反公共秩序之契約","違反民法第 983 條特定親屬間禁止結婚規定之結婚行為"],"ok":[1],"ex":["§92 受詐欺所為意思表示由表意人向相對人以意思表示撤銷，無須聲請法院。","§244Ⅰ 債權人撤銷權須聲請法院撤銷債務人有害債權之無償行為。","§72 違反公共秩序之契約無效，不須撤銷。","§988② 違反§983 近親禁婚規定之結婚無效，非聲請法院撤銷。"],"tr":""},{"id":"h:110-14","p":"h","src":"110年第14題","sec":"C4","stem":"關於合夥的敘述，下列何者正確？","opts":["各合夥人之出資及其他合夥財產，為合夥人全體之分別共有","合夥人除有特別訂定外，無於約定出資之外增加出資之義務。因損失而致資本減少者，合夥人無補充之義務","合夥財產不足清償合夥之債務時，各合夥人對於不足之額，無須負其責任","合夥人退夥後，對於其退夥前合夥所負之債務，無須負其責任"],"ok":[1],"ex":["§668：合夥人之出資及其他合夥財產，為合夥人全體之公同共有，非分別共有。","§669：除有特別訂定外，合夥人無於約定出資外增加出資之義務；因損失致資本減少者，亦無補充義務。","§681：合夥財產不足清償合夥債務時，各合夥人對不足之額連帶負責。","§690：合夥人退夥後，對於其退夥前合夥所負之債務，仍應負責。"],"tr":""},{"id":"h:110-15","p":"h","src":"110年第15題","sec":"C1","stem":"關於買賣瑕疵擔保的敘述，下列何者正確？","opts":["買受人對於由他地送到之物，主張有瑕疵，不願受領者，買受人無暫為保管之責","從物有瑕疵者，買受人得就主物併同從物，解除全部契約","為買賣標的之數物中，一物有瑕疵者，買受人僅得就有瑕疵之物為解除，但當事人之任何一方，如因有瑕疵之物，與他物分離而顯受損害者，得解除全部契約","買賣之物，僅指定種類者，如其物有瑕疵，買受人得不解除契約或請求減少價金，而即時請求另行交付無瑕疵之物。出賣人就另行交付之物，不負擔保責任"],"ok":[2],"ex":["§358（買受人保管義務）：由他地送到之物，買受人主張瑕疵不願受領時，如出賣人於受領地無代理人，買受人有暫為保管之責。","§362：因主物有瑕疵而解除者效力及於從物；從物有瑕疵者，買受人僅得就從物為解除，不得解除主物或全部契約。","§363：數物買賣中一物有瑕疵者，僅就瑕疵物解除；但因瑕疵物與他物分離而顯受損害者，當事人任何一方得解除全部契約。","§364 II：另行交付之物，出賣人仍負擔保責任，並非免責。"],"tr":""},{"id":"h:110-16","p":"h","src":"110年第16題","sec":"D1","stem":"關於果實自落於鄰地，而鄰地非為公用地者，下列何者正確？","opts":["視為遺失物","視為無主物","視為屬於鄰地所有人","視為屬於原土地所有人"],"ok":[2],"ex":["果實自落鄰地係法律擬制取得，非遺失物。","果實有所有人，非無主物。","§798：果實自落於鄰地者，視為屬於鄰地所有人；但鄰地為公用地者，不在此限。","鄰地非公用地時不歸原土地所有人，而是擬制歸鄰地所有人。"],"tr":""},{"id":"h:110-17","p":"h","src":"110年第17題","sec":"D5","stem":"地上權未定有期限者，存續期間逾多少年或地上權成立之目的已不存在時，法院得因當事人之請求，斟酌地上權成立之目的、建築物或工作物之種類、性質及利用狀況等情形，定其存續期間或終止其地上權。下列何者正確？","opts":["二十年","十五年","十年","五年"],"ok":[0],"ex":["§833-1：地上權未定有期限者，存續期間逾二十年或地上權成立之目的已不存在時，法院得因當事人之請求，斟酌各種情形定其存續期間或終止其地上權，正確。","十五年是§913典權絕賣條款之門檻（約定期限不滿十五年者，不得附有到期不贖即作絕賣之條款），與地上權無關。","十年是§770善意無過失占有他人未登記不動產之取得時效期間，非§833-1所定數字。","五年是§861Ⅱ抵押權利息優先受償之期間（聲請執行前五年內），非§833-1所定數字。★§833-1：未定期限地上權→逾20年，法院得介入。"],"tr":""},{"id":"h:110-18","p":"h","src":"110年第18題","sec":"D6","stem":"依民法第 880 條規定，實行抵押權期間以抵押權擔保之債權，其請求權已因時效而消滅，如抵押權人，於消滅時效完成後，幾年間不實行其抵押權者，其抵押權消滅？","opts":["一","二","三","五"],"ok":[3],"ex":["§880 規定為5年，而非1年。","§880 規定為5年，而非2年。","§880 規定為5年，而非3年。","§880：消滅時效完成後5年間不實行抵押權，抵押權消滅。"],"tr":""},{"id":"h:110-19","p":"h","src":"110年第19題","sec":"E2","stem":"關於夫妻財產制契約的敘述，下列何者正確？","opts":["夫妻得於結婚前以契約就民法所定之約定財產制中，選擇其一，為其夫妻財產制。結婚後則不行","夫妻未以契約訂立夫妻財產制者，除民法另有規定外，以聯合財產制，為其夫妻財產制","夫妻財產制契約之訂立、變更或廢止，非經登記，不生效力","夫妻財產制契約之登記，不影響依其他法律所為財產權登記之效力"],"ok":[3],"ex":["§1004：夫妻得於結婚前「或結婚後」以契約選擇約定財產制，婚後亦可（另見§1012）。","§1005：未訂立契約者，以「法定財產制」為其夫妻財產制，聯合財產制已不存在。","依§1008 I，未登記僅「不得對抗第三人」，非不生效力。","§1008 II：夫妻財產制契約之登記，不影響依其他法律所為財產權登記之效力。"],"tr":""},{"id":"h:110-20","p":"h","src":"110年第20題","sec":"E2","stem":"分別財產制有關夫妻債務的敘述，下列何者正確？","opts":["夫妻於行為時明知有損於婚姻關係消滅後他方之剩餘財產分配請求權者，以受益人受益時亦知其情事者為限，他方得聲請法院撤銷之","夫妻之一方以自己財產清償他方之債務時，於婚姻關係存續中，不得請求償還。但於婚姻關係消滅時，夫或妻現存之婚後財產，扣除婚姻關係存續所負債務後，如有剩餘，其雙方剩餘財產之差額，應平均分配","夫妻之一方以自己財產清償他方之債務時，於婚姻關係存續中，不得請求償還。但於婚姻關係消滅時，應分別納入現存之婚後財產或婚姻關係存續中所負債務計算","夫妻各自對其債務負清償之責"],"ok":[3],"ex":["A所述為法定財產制剩餘財產分配之撤銷規定（§1020-1），並非分別財產制。","B所述剩餘財產差額平均分配為法定財產制規則（§1030-1），分別財產制無此制度。","分別財產制依§1046適用§1023：夫妻一方以自己財產清償他方之債務時，雖於婚姻關係存續中亦得請求償還（§1023Ⅱ），選項說「不得請求」錯誤；「消滅時納入計算」係法定財產制§1030-2之規定，分別財產制無剩餘財產分配。","§1046：分別財產制有關夫妻債務之清償，適用§1023；§1023Ⅰ：夫妻各自對其債務負清償之責。（§1044只規定分別財產各自保有所有權及管理、使用、收益、處分。）"],"tr":""},{"id":"h:110-21","p":"h","src":"110年第21題","sec":"E2","stem":"關於共同財產所負之債務，而以共同財產清償者，下列何者正確？","opts":["不生補償請求權","不生補償請求權，但於共同財產制關係消滅時，應分別納入現存之婚後財產或婚姻關係存續中所負債務計算","有補償請求權，但於婚姻關係存續中，不得請求","有補償請求權，雖於婚姻關係存續中，亦得請求"],"ok":[0],"ex":["§1038Ⅰ明文：共同財產所負之債務，而以共同財產清償者，不生補償請求權。白話：共同財產所負之債務以共同財產清償，債務與清償財源同屬一個財產池，只是左手還右手，不生補償請求權。","選項所述『關係消滅時分別納入現存婚後財產或所負債務計算』是法定財產制§1030-2（婚前／婚後財產互相清償債務）的規定，與共同財產清償共同財產債務無關。","共同財產清償共同財產債務根本不發生補償請求權，無所謂『婚姻關係存續中不得請求』。","補償請求權只發生於共同財產與特有財產互相清償對方債務之情形（§1038），同為共同財產則無補償問題（補償請求權成立時，依§1038Ⅱ婚姻存續中亦得請求）。"],"tr":""},{"id":"h:110-22","p":"h","src":"110年第22題","sec":"E3","stem":"民法關於非婚生子女之規定，下列何者錯誤？","opts":["如有受推定為婚生子女情形，夫妻之一方或子女能證明子女非為婚生子女者，得提起認領之訴","非婚生子女，其生父與生母結婚者，視為婚生子女","非婚生子女經生父認領者，視為婚生子女","非婚生子女或其生母，對於生父之認領，得否認之"],"ok":[0],"ex":["§1063 II：推定婚生子女，夫妻之一方或子女能證明非婚生者，提起的是「否認之訴」，不是認領之訴。","§1064：非婚生子女，其生父與生母結婚者，視為婚生子女（準正）。","§1065 I：非婚生子女經生父認領者，視為婚生子女。","§1066：非婚生子女或其生母，對於生父之認領，得否認之。"],"tr":""},{"id":"h:110-23","p":"h","src":"110年第23題","sec":"E4","stem":"甲早年父母雙亡，僅有一兄長乙，甲與配偶離異後獨自養育一子丙。某日甲死亡，於丙拋棄繼承前，乙亦不幸意外死亡，留下乙之配偶丁。下列何者錯誤？","opts":["甲之遺產繼承人順序，丙優先於乙","配偶丁與乙有相互繼承遺產之權","就甲之遺產，既然丙已拋棄繼承，應由次順序之乙繼承，雖然乙早於丙拋棄繼承前死亡，仍應由丁繼承乙所繼承自甲之遺產","拋棄繼承權，應於知悉其得繼承之時起三個月內，以書面向法院為之"],"ok":[2],"ex":["§1138：第一順序為直系血親卑親屬，第三順序才是兄弟姊妹，丙優先於乙。","配偶互為繼承人（§1144），丁與乙有相互繼承權。","本題命題者見解：次順序繼承人須在前順序拋棄、繼承權移轉時仍生存，才能依§1176VI遞補；乙於丙拋棄前已死亡，不能遞補，丁自無從經由乙取得甲之遺產。惟§1175規定拋棄溯及繼承開始時生效，乙於甲死亡（繼承開始）時仍生存，另有見解認為乙仍為繼承人，其繼承人得再轉繼承。此點有爭議，作答依命題者見解選C。","§1174 II：拋棄繼承權，應於知悉其得繼承之時起三個月內，以書面向法院為之。"],"tr":""},{"id":"h:110-24","p":"h","src":"110年第24題","sec":"E4","stem":"關於喪失繼承權情事的敘述，下列何者正確？","opts":["故意致被繼承人或應繼承人於死，或雖未致死因而受刑之宣告者","以詐欺或脅迫使被繼承人為關於繼承之遺囑，或使其撤回或變更之，因而受刑之宣告者","以詐欺或脅迫妨害被繼承人為關於繼承之遺囑，或妨害其撤回或變更之，因而受刑之宣告者","偽造、變造、隱匿或湮滅被繼承人關於繼承之遺囑，因而受刑之宣告，但經被繼承人宥恕者"],"ok":[0],"ex":["§1145 I①：故意致被繼承人或應繼承人於死，或雖未致死因而受刑之宣告者，喪失繼承權。","§1145 I②：以詐欺或脅迫使被繼承人為遺囑或使其撤回、變更者即喪失，條文並無「因而受刑之宣告」之要件。","§1145 I③：妨害遺囑之作成、撤回或變更者即喪失繼承權，無須受刑之宣告。","§1145 I④：偽造、變造、隱匿或湮滅遺囑者喪失，不須受刑宣告；宥恕係另在§1145 II規定，選項把要件混入。"],"tr":""},{"id":"h:110-25","p":"h","src":"110年第25題","sec":"E4","stem":"關於遺產分割的敘述，下列何者正確？","opts":["繼承人於服喪三年後得隨時請求分割遺產","遺囑禁止遺產之分割者，其禁止之效力以二十年為限","遺產分割後，各繼承人按其所得部分，對於他繼承人因分割而得之債權，就應清償時債務人之支付能力，負擔保之責","繼承人之連帶責任，自遺產分割時起，如債權清償期在遺產分割後者，自清償期屆滿時起，經過五年而免除"],"ok":[3],"ex":["§1164：繼承人得隨時請求分割遺產（法律另有規定或契約另有訂定者除外），並無「服喪三年」之限制。","§1165 II：遺囑禁止遺產分割之效力以「十年」為限，不是二十年。","§1169 I：擔保責任原則上就「遺產分割時」債務人之支付能力負責；只有債權附停止條件或未屆清償期時，才就「應清償時」之支付能力負責（§1169 II）。選項把例外寫成一般規則，錯誤。","§1171 II：繼承人連帶責任，自遺產分割時起，如債權清償期在分割後者自清償期屆滿時起，經過五年而免除。"],"tr":""},{"id":"h:109-1","p":"h","src":"109年第1題","sec":"A3","stem":"下列關於法律上之物的敘述，何者正確？","opts":["從物在客觀上需常助主物之效用，且與主物為各自獨立之兩個物，動產或不動產均可為從物","物之成分或其天然孳息，分離後原則上屬於該成分或天然孳息之占有人","無權占有他人土地建築房屋，建築完成時，該房屋原則上屬於土地所有人所有","已足避風雨，可達經濟上使用目的，但屋頂尚未完全完工之房屋，屬土地之成分"],"ok":[0],"ex":["依§68，從物是非主物之成分、常助主物效用、同屬一人所有的物；重點：「各自獨立」（非主物成分）且「客觀上常助主物效用」；動產或不動產均可為從物，正確。","§766：物之成分及其天然孳息，分離後除法律另有規定外，仍屬於其物之「所有人」，而非占有人；另§70Ⅰ：有收取天然孳息權利之人，於權利存續期間取得分離之孳息。占有人並不當然取得，故B錯誤。","§66Ⅰ：不動產指土地及其定著物，土地與其上房屋是各自獨立的不動產；無權占有他人土地建築房屋，房屋由建造人取得所有權，並非歸土地所有人（§811附合規定僅適用於動產附合於不動產而成重要成分，不適用於房屋），土地所有人是請求拆屋還地。","已足避風雨可使用之房屋（即便屋頂未完工）屬獨立建築物（定著物），而非土地之「成分」（成分是不可與主物分離之部分），敘述錯誤。"],"tr":""},{"id":"h:109-2","p":"h","src":"109年第2題","sec":"A7","stem":"下列何者非消滅時效適用之客體？","opts":["人格權受侵害時之除去妨害請求權","夫妻因離婚所約定之贍養費請求權","繼承權受侵害時之回復請求權","未登記不動產所有權人之返還請求權"],"ok":[0],"ex":["人格權之除去妨害請求權在侵害持續期間，性質上不適用消滅時效，不屬消滅時效客體。","§126 贍養費等定期給付請求權，5年間不行使而消滅。","§1146Ⅱ 繼承回復請求權2年或10年間不行使而消滅。","釋字第107號、第164號：已登記不動產回復請求權不適用時效；未登記不動產所有人之返還請求權仍適用消滅時效（§125）。"],"tr":""},{"id":"h:109-3","p":"h","src":"109年第3題","sec":"C1","stem":"甲與乙訂立買賣契約，將其二手汽車出賣予乙，若當事人間無特別約定者，關於該汽車之利益及危險，下列何者正確？","opts":["於甲與乙簽訂汽車買賣契約時起，由乙承受","自該車辦理過戶登記於乙時，由乙承受","自該車交付於乙時起，由乙承受","於乙支付價金完畢時，由乙承受"],"ok":[2],"ex":["買賣契約成立時，危險尚未移轉（交付前仍在甲），成立時由甲承受。","動產危險移轉以「交付」為準（§373），並非以登記（過戶）為準；不動產所有權移轉以登記，但危險移轉仍以「交付」為準，選項錯誤。","§373，買賣標的物之利益及危險，自「交付」時起由買受人（乙）承受，無特別約定時以交付為準，正確。","價金支付非危險移轉的依據，依法以交付為準，選項錯誤。"],"tr":""},{"id":"h:109-4","p":"h","src":"109年第4題","sec":"B1","stem":"下列有關契約成立之敘述，何者錯誤？","opts":["契約得以要約與承諾之意思表示合致而成立","契約得以要約交錯之方式而成立","契約得以承諾交錯之方式而成立","契約得以要約與意思實現方式而成立"],"ok":[2],"ex":["契約由要約與承諾之意思表示一致而成立（§153 Ⅰ：當事人互相表示意思一致者，無論明示或默示，契約即成立；§154 起規範要約之拘束力、承諾等），為最基本的成立方式，正確。","要約交錯：雙方各自獨立向對方為內容一致之要約，構成「互相表示意思一致」，依§153 Ⅰ契約成立（通說），正確。","承諾必須針對對方已發出之要約而為，民法並無「承諾交錯」這種契約成立方式；民法承認的是要約交錯（§153）與意思實現（§161），本選項描述不存在的成立方式，錯誤，為應選答案。","意思實現（§161 Ⅰ）：依習慣或依事件之性質，承諾無須通知者，在相當時期內有可認為承諾之事實時，契約即為成立（如逕行履行），正確。"],"tr":""},{"id":"h:109-5","p":"h","src":"109年第5題","sec":"B1","stem":"下列關於利息之敘述，何者正確？","opts":["應付利息之債務，其利率未經約定亦無法律可據者，原則上以週年利率為百分之六計算","約定利率逾週年百分之十二者，經一年後，債務人得隨時清償原本。但須於一個月前預告債權人","約定利率，超過週年百分之二十者，其約定當然無效，此時應以法定利率計算應給付之利息","債權人受領超過最高利率之利息，對於超過部分之利息係不當得利，應返還債務人"],"ok":[1],"ex":["§203：未約定利率亦無法律可據者，週年利率為5%，不是6%。","§204 I：約定利率逾週年12%者，經一年後債務人得隨時清償原本，但須於一個月前預告債權人。","出題年（109年）舊§205：超過週年20%者，債權人對超過部分之利息「無請求權」；現行§205：超過週年16%者，超過部分之約定無效。新舊法都只處理「超過部分」，未超過部分仍依約定利率計算，不是整個利息約定當然無效、改依法定利率。","依現行§205超過部分之約定無效，債權人受領該部分欠缺法律上原因；但債務人給付時若明知無給付義務，依§180③不得請求返還，故不能一概說都須返還。依出題年舊法，超過部分只是債權人「無請求權」，債務人任意給付時債權人受領並非無法律上原因（實務見解），更不成立不當得利。新舊法下D都錯。"],"tr":""},{"id":"h:109-6","p":"h","src":"109年第6題","sec":"C1","stem":"下列有關定金之敘述，何者正確？","opts":["訂約當事人之一方，由他方受有定金時，其契約視為成立","定金為諾成契約，於當事人約定時即成立","契約因可歸責於付定金當事人之事由，致不能履行時，定金不得請求返還","契約因不可歸責於雙方當事人之事由，致不能履行時，定金視為債務不履行損害賠償之總額"],"ok":[2],"ex":["§248：由他方受有定金時，是「推定」契約成立，並非視為成立。","定金契約為要物契約，須交付定金才成立，並非諾成。","§249 (2)：契約因可歸責於付定金當事人之事由致不能履行時，定金不得請求返還。","§249 (4)：契約因不可歸責於雙方之事由致不能履行時，定金應返還。"],"tr":""},{"id":"h:109-7","p":"h","src":"109年第7題","sec":"B1","stem":"甲借給乙 100 萬元，借期屆至，甲請求乙返還 100 萬元借款，乙因此開立 100 萬元之本票交由甲受領。下列敘述，何者正確？","opts":["甲所受領乙開立的 100 萬元本票，是債之內容更改","甲所受領乙開立的 100 萬元本票，是抵銷","甲所受領乙開立的 100 萬元本票，是代物清償","甲所受領乙開立的 100 萬元本票，是新債清償"],"ok":[3],"ex":["債之更改是以新債務取代舊債務、使舊債務消滅；但依§320，因清償債務而對債權人負擔新債務者，除當事人另有意思表示外，舊債務並不消滅，本題無使舊債務消滅之意思表示，不能認為更改。","抵銷（§334）須二人互負債務、給付種類相同且均屆清償期；本題只有乙對甲負借款債務，甲對乙並無相對債務，無從抵銷。","代物清償（§319）是債權人受領「他種給付」以代原定給付，債之關係即消滅；本題乙只是開立本票（負擔新債務），並非已以他種給付取代借款，且本票若不獲兌現，借款仍在，故非代物清償。","新債清償（§320）：因清償債務而對債權人負擔新債務者，除當事人另有意思表示外，若新債務不履行時，舊債務仍不消滅；乙為清償100萬元借款而開立100萬元本票，即屬此類，正確。"],"tr":""},{"id":"h:109-8","p":"h","src":"109年第8題","sec":"C2","stem":"下列關於房屋租賃之敘述，何者正確？","opts":["出租人將租賃之房屋交付承租人後，非經承租人同意，不得將其所有權讓與第三人","出租人出賣租賃之房屋時，承租人有依同樣條件優先承買之權利","除有反對之約定外，承租人依法得將其一部分轉租於他人","房屋租賃之租金，當事人得因其價值之昇降，聲請法院增減之，但以定期租賃為限"],"ok":[2],"ex":["§425 I 買賣不破租賃：房屋交付後出租人讓與所有權，租約對受讓人繼續存在，無須承租人同意。","一般房屋租賃之承租人無優先承買權；§426-2 的優先承買權僅限於租用基地建築房屋之情形。","§443 I 但書：租賃物為房屋者，除有反對約定外，承租人得將其一部分轉租他人。","§442：不動產租賃租金得聲請法院增減，但其租賃定有期限者，不在此限，故並非以定期租賃為限（反而排除之）。"],"tr":""},{"id":"h:109-9","p":"h","src":"109年第9題","sec":"C1","stem":"甲將其名下之房屋出售並交付乙占有，惟尚未辦理所有權登記之前，甲又出售該屋於善意之丙且辦理所有權登記完畢。則乙對丙之主張，下列何者正確？","opts":["乙得依據其與甲所訂立之買賣契約而請求丙塗銷房屋所有權登記","乙得向丙主張不當得利而請求丙塗銷房屋所有權登記","乙得向丙主張撤銷權而請求丙塗銷房屋所有權登記","乙無法請求丙塗銷房屋所有權登記，只得向甲請求債務不履行之損害賠償"],"ok":[3],"ex":["乙之債權只能對甲主張，債權相對性，不能請求丙塗銷登記。","丙是向所有人甲買受並辦理登記（§758），屬有權處分而取得所有權，取得基於有效的買賣契約，有法律上原因，無不當得利；丙是否善意與此無關（這不是無權處分下的善意取得）。","乙之債權係以給付特定物（移轉該屋所有權）為標的，依§244Ⅲ 僅有害於以給付特定物為標的之債權者，不適用撤銷權規定；故不論丙善意惡意，乙均不得撤銷。","乙無法請求丙塗銷登記，只能向甲請求債務不履行（給付不能）之損害賠償（§226）。"],"tr":""},{"id":"h:109-10","p":"h","src":"109年第10題","sec":"D2","stem":"甲將其土地出售乙，但因價金給付方式仍有爭議，故甲拒絕交付予乙，亦不辦理登記，乙起訴請求甲履行買賣契約之給付義務，經判決勝訴確定。下列敘述，何者正確？","opts":["因甲已將其土地出售乙，故所有權屬於乙","因乙已取得土地買賣契約給付請求權勝訴確定，故所有權屬於乙","因甲尚未辦理土地所有權移轉登記於乙，故所有權仍屬於甲","因該地尚未交付予乙占有，故所有權仍屬於甲"],"ok":[2],"ex":["買賣僅生債權債務關係，不動產所有權變動須登記（§758 I）。","勝訴判決確認的是給付請求權，並非所有權移轉；須履行或強制執行辦理登記。","§758 I：依法律行為取得不動產物權，非經登記不生效力；未登記所有權仍屬甲。","不動產物權之變動以登記為要件，與是否交付占有無關。"],"tr":""},{"id":"h:109-11","p":"h","src":"109年第11題","sec":"C3","stem":"關於委任契約受任人之報酬，下列敘述，何者錯誤？","opts":["委任關係因可歸責於受任人之事由，而於委任事務處理完畢前經終止者，受任人仍得就已經處理之部分比例請求報酬","受任人受有報酬之注意義務，高於受任人未受報酬之注意義務","當事人縱未約定報酬，但依交易習慣或委任事務之性質應給與報酬者，受任人得請求報酬","除契約另有規定外，原則上於委任關係終止時，受任人須明確報告始末後才能請求報酬"],"ok":[0],"ex":["§548 II：僅「非可歸責於受任人」之事由而提前終止時，受任人才得就已處理部分比例請求報酬；因可歸責於受任人而終止者不適用。","§535：有報酬者以善良管理人注意，無報酬者以處理自己事務同一之注意，前者義務較重。","§547：報酬縱未約定，如依習慣或依委任事務之性質，應給與報酬者，受任人得請求報酬。","§548 I：應受報酬之受任人，除契約另有訂定外，於委任關係終止及明確報告顛末後，得請求報酬。"],"tr":""},{"id":"h:109-12","p":"h","src":"109年第12題","sec":"C2","stem":"甲將自己所有的違章建築 A 屋賣給乙，有關於買賣違章建築之法律關係。下列敘述，依實務見解，何者錯誤？","opts":["土地與土地上之違章建築同屬於一人所有，嗣將違章建築與土地分別讓與相異之人，仍有民法第 425 條之 1 推定租賃關係規定之適用","違章建築之買受人對於無權占用房屋之人，得行使民法第 767 條之物上請求權","違章建築遭拍賣，拍定人自取得法院權利移轉證書之日起，取得該違章建築之權利","甲、乙買賣違章建築，所讓與的是事實上之處分權"],"ok":[1],"ex":["實務認為違章建築與土地原屬同一人，其後分別讓與不同人時，類推適用§425-1 推定租賃關係。","違章建築（未辦保存登記）買受人僅取得事實上處分權，並非所有權人，不得行使§767 物上請求權。","實務見解：拍賣違章建築，拍定人自取得權利移轉證書之日起取得其權利（事實上處分權）。","違章建築買賣所讓與者為事實上處分權，非所有權移轉。"],"tr":""},{"id":"h:109-13","p":"h","src":"109年第13題","sec":"D2","stem":"甲乙丙共同出資購買一筆 A 土地，應有部分各三分之一。下列何種行為應經甲乙丙三個共有人全體同意，始為有效？","opts":["共有人之一將其應有部分移轉予第三人","共有人之一將其應有部分設定抵押權予第三人","共有人之一將 A 土地設定抵押權予第三人","共有人之一將 A 土地設定有償之地上權予第三人"],"ok":[2],"ex":["§819 I：共有人得自由處分其應有部分，不須他共有人同意。","應有部分之設定抵押屬處分自己權利，§819 I 得自由為之。","§819 II：共有物之處分、變更及設定負擔，應得共有人全體同意；將土地全部設定抵押權屬設定負擔。","設定地上權：土地法§34-1Ⅰ 明列得以多數決行之（共有人過半數＋應有部分過半；逾 2/3 人數不計），不須全體同意。"],"tr":""},{"id":"h:109-14","p":"h","src":"109年第14題","sec":"D2","stem":"下列何者非屬公同共有之性質？","opts":["繼承人有數人時，其繼承取得之遺產","合夥人之合夥財產","屬於社團法人名下之財產","屬於夫妻共同財產制下之財產"],"ok":[2],"ex":["繼承人有數人時，遺產為繼承人公同共有（§1151）。","合夥財產為合夥人公同共有（§668）。","社團法人具有權利能力，財產為法人單獨所有，非公同共有。","夫妻共同財產制下之共同財產，屬夫妻公同共有（§1031）。"],"tr":""},{"id":"h:109-15","p":"h","src":"109年第15題","sec":"D3","stem":"甲現年十七歲，在山中拾獲名貴木材一塊，嗣後該木材遭乙竊取，乙請人雕刻成名貴的佛像，以高價出售於惡意的丙，並交付之。下列敘述，何者正確？","opts":["甲因未滿二十歲，不得占有該木材","乙不能取得名貴的佛像所有權","乙將名貴的佛像讓與並交付予丙，係屬無權處分","甲得向乙請求償還該木材的價額"],"ok":[3],"ex":["占有為事實，只要對物有事實上管領之力即為占有人（§940），不以行為能力為要件，未成年人亦得占有。成年年齡：依出題年（109年）舊法，滿20歲為成年，甲17歲未成年；依現行法（112.1.1起§12 滿十八歲為成年），甲17歲仍未成年。兩種法下甲都是未成年人，但都不影響其占有，選項錯誤。","乙加工後，加工價值顯逾材料價值時，加工物所有權歸加工人（§814），乙可取得佛像所有權。","乙已取得佛像所有權，其讓與並交付為有權處分，並非無權處分。","題目設定木材是甲在山中拾得之無主動產，甲以所有之意思占有，依§802 先占取得所有權；乙加工後，因加工所增價值顯逾材料價值，佛像所有權依§814 但書歸乙，甲之材料所有權因而喪失，甲得依§816「依關於不當得利之規定」（§179）請求乙償還木材價額。"],"tr":""},{"id":"h:109-16","p":"h","src":"109年第16題","sec":"D2","stem":"甲、乙共有一筆 A 土地，面積 400 坪，應有部分各為二分之一。下列敘述，何者正確？","opts":["甲、乙對於共有之 A 土地，各有一個所有權，但其權利之行使應受應有部分之限制","甲、乙對於共有之 A 土地，各有 200 坪所有權","應有部分各為二分之一是甲、乙對於共有土地所有權之比例","對於共有之 A 土地，甲、乙分別享有處分權及管理權"],"ok":[2],"ex":["一物之上僅有一個所有權，共有是數人分享該所有權，並非各有一個所有權。","共有採分別共有，不是將土地實際切成各200坪；應有部分是比例，非特定面積。","應有部分是各共有人對於共有物所有權之比例（§817 I）。","處分權與管理權須依§819、§820分別以全體或多數決行使，並非各人分享不同權能。"],"tr":""},{"id":"h:109-17","p":"h","src":"109年第17題","sec":"D2","stem":"甲、乙、丙、丁四人共有一筆 A 土地，應有部分各登記為四分之一，甲未經乙、丙、丁之同意，擅自占有 A 土地四分之三面積的土地，在其上興建一 B 屋。下列敘述，何者正確？","opts":["乙、丙、丁僅得分別請求甲返還占用 A 土地四分之一之土地","乙、丙、丁得分別請求甲返還所占用 A 土地四分之三之土地","乙、丙、丁應共同請求甲返還所占用 A 土地四分之一之土地","乙、丙、丁應共同請求甲返還所占用 A 土地四分之三之土地"],"ok":[1],"ex":["§821：各共有人得就共有物之全部為本於所有權之請求，不以其應有部分為限。","甲雖為共有人，但未經他共有人同意擅自占用A地特定部分興建B屋，實務見解認其對他共有人構成無權占有；§821 條文雖以「對於第三人」為對象，實務於此情形同樣允許各共有人單獨請求，但回復共有物之請求僅得為共有人全體之利益為之。故乙、丙、丁得分別請求甲返還所占用之四分之三土地（返還於共有人全體）。","各共有人得單獨請求，並不必共同為之。","同上，不須共同，且範圍為被占用之全部，不限於四分之一。"],"tr":""},{"id":"h:109-18","p":"h","src":"109年第18題","sec":"D5","stem":"下列關於地上權之敘述，何者正確？","opts":["地上權人若因不可抗力，妨礙其土地之使用，依法即得請求免除或減少租金","土地所有權讓與時，地上權人已預付之地租，非經登記，不得對抗第三人","地上權人須連續積欠地租達二年，土地所有人始得終止地上權","地上權無支付地租之約定者，地上權人應於一年前通知土地所有人，始得拋棄其權利"],"ok":[1],"ex":["§837：不可抗力妨礙使用，地上權人仍不得請求免除或減少租金。","§836-1：土地所有權讓與時，已預付之地租，非經登記不得對抗第三人。","§836 I：積欠地租達二年之總額即得催告，並非須「連續」積欠；並須定期催告，不付才得終止。","§834：無支付地租約定者，地上權人得隨時拋棄；有地租約定者：定有期限須支付未到期之三年分地租（§835 I）；未定期限須一年前通知或支付未到期之一年分地租（§835 II）。"],"tr":""},{"id":"h:109-19","p":"h","src":"109年第19題","sec":"D6","stem":"以建築物設定抵押權者，下列何者非抵押權效力所及之標的物範圍？","opts":["抵押物扣押後，抵押人就抵押物所得收取之租金","抵押之建築物存在所必要且性質上得讓與之權利","設定抵押權後所增建附加於該建築物，而不具獨立性之部分","抵押之建築物滅失後殘餘之鋼筋"],"ok":[1],"ex":["屬效力所及：§863、§864，抵押物扣押後抵押人就抵押物得收取之法定孳息（租金），為抵押權效力所及。","§877-1：建築物拍賣時，存在所必要且性質上得讓與之權利應併付拍賣，但抵押權人就該權利價金無優先受償權，故非抵押權效力所及。","屬效力所及：§862 III，附加於建築物而不具獨立性之部分，為效力所及。","屬效力所及：抵押物滅失之殘餘物，仍為抵押權效力所及（§862-1Ⅰ）。"],"tr":""},{"id":"h:109-20","p":"h","src":"109年第20題","sec":"E2","stem":"下列關於夫妻財產制契約之訂立，何者正確？","opts":["夫妻於結婚前或結婚後，均得以書面約定夫妻財產制契約","夫妻財產制契約之訂立應經登記，否則不生效力","夫妻財產制契約之訂立，當事人如為未成年人時，應得其法定代理人之同意始為有效","夫妻於婚姻關係存續中，得以契約廢止其財產制契約，或改用他種約定財產制，但以一次為限"],"ok":[0],"ex":["§1004、§1007：夫妻於結婚前或結婚後，均得以書面訂立夫妻財產制契約，選擇約定財產制之一。","依§1008 I，契約之訂立、變更或廢止非經登記，僅「不得對抗第三人」，並非不生效力。","民法對夫妻財產制契約僅要求書面（§1007），並無須法定代理人同意之特別規定；當時未成年已結婚者有行為能力（舊§13 III）。現行法：112.1.1起男女須滿18歲始得結婚且18歲成年（§12），已不存在未成年夫妻，此題情境不再發生。","§1012：婚姻關係存續中得以契約廢止財產制契約或改用他種約定財產制，條文並無「以一次為限」之限制。"],"tr":""},{"id":"h:109-21","p":"h","src":"109年第21題","sec":"E2","stem":"甲、乙結婚並約定共同財產制為夫妻財產制，共同財產制關係存續中二人之共同財產為 2000 萬元，若甲、乙離婚而無特別約定時，則乙可分得若干共同財產？","opts":["2000 萬元","1000 萬元","1500 萬元","500 萬元"],"ok":[1],"ex":["共同財產制關係消滅時，除另有約定外，各得共同財產之半數（§1040），並非全部歸乙。","離婚使共同財產制消滅，無特別約定時各得共同財產之半數（§1040 II），2000萬×1/2＝1000萬。","並無依比例分得四分之三之規定，法定為各得半數。","500萬為四分之一，與法定半數不符。"],"tr":""},{"id":"h:109-22","p":"h","src":"109年第22題","sec":"E2","stem":"下列關於夫妻法定財產制之敘述，何者正確？","opts":["於法定財產制下，夫或妻之財產分為婚前財產與婚後財產，婚前財產由夫妻各自所有，婚後財產則由夫妻共有","於法定財產制下，夫或妻之婚前及婚後財產，於婚姻關係存續中所生之孳息，均屬於婚後財產之範圍","無論採何種約定財產，當夫或妻其財產不足清償其債務時，法院得因他方之請求，宣告改用法定財產制","夫或妻各自管理、使用、收益其婚前財產與婚後財產，但對於婚後財產為處分時，應得他方之同意"],"ok":[1],"ex":["§1017 I：婚前、婚後財產均「由夫妻各自所有」，婚後財產並非共有。","§1017 II：婚前財產之孳息視為婚後財產；婚後財產之孳息本屬婚後財產，故二者之孳息均在婚後財產範圍。","依§1010I②，夫或妻之財產不足清償其債務時，法院因他方請求得宣告改用「分別財產制」，不是改用法定財產制；選項把改用的目標制度換掉了。","§1018：夫妻各自管理、使用、收益及處分其財產，處分婚後財產無須他方同意（§1018-1 自由處分金為另一制度）。"],"tr":""},{"id":"h:109-23","p":"h","src":"109年第23題","sec":"E4","stem":"甲乙夫妻育有丙、丁二子及戊女。丙與己女結婚，婚後育有一子庚，戊女未婚生下一子辛。多年後甲死亡，而戊早於甲死亡，丙則拋棄繼承。設甲留有遺產 900 萬元，則甲之遺產應如何繼承？","opts":["乙、丁、庚各繼承 300 萬元","乙、丁、辛各繼承 300 萬元","乙、丁各繼承 450 萬元","乙、丁、庚、辛各繼承 225 萬元"],"ok":[1],"ex":["庚為丙之子，但丙係拋棄繼承，拋棄不發生代位繼承（§1140僅限先死亡或喪失繼承權），庚不得繼承。","戊先於甲死亡，其非婚生子女辛與生母戊之關係視為婚生（§1065 II），得代位繼承（§1140）；丙拋棄，故繼承人為乙、丁、辛三人，配偶與第一順序平均（§1144①），各300萬。","遺漏辛之代位繼承，且乙、丁各450萬之算法不成立。","庚因丙拋棄而無繼承權，四人均分之說法錯誤。"],"tr":""},{"id":"h:109-24","p":"h","src":"109年第24題","sec":"E4","stem":"甲、乙為夫妻，並無子女。丙、丁為甲之父母。甲死亡時留有 350 萬元之現金及對丙有 50 萬元之債權。試問，於遺產分割時，丙可以分得多少遺產？","opts":["50 萬元","100 萬元","200 萬元","350 萬元"],"ok":[0],"ex":["遺產含現金350萬與對丙之50萬債權共400萬（§1148 I）；丙為第二順序，與配偶乙同為繼承，丙應繼分1/4（§1144②：配偶1/2，父母二人平分另1/2）＝100萬，但丙對被繼承人負債50萬，分割時依§1172自其應繼分內扣還，實得50萬。","100萬為應繼分數額，未扣還丙對甲之50萬債務（§1172）。","200萬誤把父母二人合計當丙一人，或誤算配偶應繼分。","350萬僅為現金總額，忽略應繼分比例與債務扣還。"],"tr":""},{"id":"h:109-25","p":"h","src":"109年第25題","sec":"E4","stem":"甲乙夫妻婚後育有一子丙，三人與甲寡居之母親丁同住。甲乙兩人因感情不睦，故協議離婚，惟某日前往辦理離婚登記途中，甲不幸發生事故身亡。甲生前曾預立有效遺囑一份，記載將來所有遺產均由獨子丙繼承。甲身後遺有現金 600 萬元。若繼承人主張特留分扣減權時，甲之遺產應如何分配？","opts":["乙繼承 300 萬元，丙繼承 300 萬元","乙繼承 150 萬元，丙繼承 450 萬元","乙繼承 200 萬元，丁繼承 200 萬元，丙繼承 200 萬元","乙繼承 100 萬元，丁繼承 100 萬元，丙繼承 400 萬元"],"ok":[1],"ex":["乙、丙各300萬是沒有遺囑時的應繼分；本題遺囑把全部給丙，乙只能就被侵害的「特留分」（應繼分1/2×1/2＝1/4，即150萬）行使扣減，不能拿回完整應繼分300萬。","離婚須登記才生效（§1050），乙仍為配偶。應繼分乙、丙各1/2；特留分均為應繼分1/2（§1223①③；該條115.8.17修正公布尚未施行，115年11月考試依修正前條文），乙特留分150萬，經扣減後乙150萬、丙450萬。","丁為第二順序，有第一順序丙時不得繼承（§1138、§1139），不應分得遺產。","同樣誤把丁列為繼承人，且乙特留分金額錯誤。"],"tr":""},{"id":"h:108-1","p":"h","src":"108年第1題","sec":"A3","stem":"下列何者非屬我國民法上所稱之「土地的定著物」？","opts":["燈塔","房屋","柏油馬路","蓄水池"],"ok":[2],"ex":["燈塔繼續附著於土地、具獨立經濟價值，屬定著物。","房屋為典型之定著物。","柏油馬路為土地之構成部分，並非獨立之定著物，不具獨立所有權。","蓄水池於土地上構築，繼續附著並具獨立經濟價值，通說認屬定著物。"],"tr":""},{"id":"h:108-2","p":"h","src":"108年第2題","sec":"A1","stem":"依我國民法之規定，以下關於行為能力之敘述，何者錯誤？","opts":["無行為能力人之意思表示，無效","限制行為能力人未得法定代理人之允許，所為之單獨行為，效力未定","限制行為能力人所訂立之契約，未經承認前，相對人得撤回之","限制行為能力人用詐術使人信其為有行為能力人或已得法定代理人之允許者，其法律行為為有效"],"ok":[1],"ex":["受監護宣告之無行為能力人意思表示無效（§75），未滿7歲之未成年人亦同，正確。","限制行為能力人未得法定代理人允許之「單獨行為」→「無效」（§78），並非效力未定；效力未定是「契約行為」未得允許之效果（§79）。本選項將單獨行為的效果說成「效力未定」，錯誤，此為最重要必考對比考點。","§82：限制行為能力人所訂立之契約，未經法定代理人承認前，相對人得撤回之（但訂約時知其未得允許者除外），正確。","使用詐術者，依§83，其法律行為有效（排除限制行為能力之保護），正確。"],"tr":""},{"id":"h:108-3","p":"h","src":"108年第3題","sec":"A5","stem":"甲受丙之詐欺，而授權乙向不知情的丁購買 A 屋，請問依我國民法的規定，下列敘述何者正確？","opts":["甲因受丙之詐欺而為意思表示，故可撤銷其授權乙之行為","甲因受丙之詐欺而為意思表示，故可撤銷 A 屋之買賣契約","甲若欲行使民法第 92 條之撤銷權，應於發現詐欺後，一年內為之。但自意思表示後，經過十年，不得撤銷","甲因受丙之詐欺而為授權行為，其撤銷意思表示時，可以對抗善意第三人"],"ok":[2],"ex":["丙是第三人，其詐欺使甲授權乙；依§92Ⅰ但書，第三人詐欺須「相對人明知其事實或可得而知」才得撤銷。本題未表示授權的相對人（乙）知情，故不能逕認甲可撤銷授權。","買賣契約是乙與丁訂立，丁不知丙詐欺；依§92Ⅰ但書，第三人詐欺須相對人（丁）明知或可得而知方得撤銷，丁善意不知情，甲不得以丙詐欺撤銷A屋買賣契約。更根本的是：買賣的意思表示是代理人乙所為，依§105本文，意思表示是否被詐欺「應就代理人決之」，乙並未被詐欺，買賣契約本身沒有可撤銷的瑕疵；甲被詐欺的只是授權行為。","依§93，因詐欺而為意思表示之撤銷，應於「發現詐欺後一年內」為之，且「自意思表示後十年」不得撤銷，此即撤銷權之除斥期間，正確。","§92Ⅱ：被詐欺而為之意思表示，其撤銷不得以之對抗善意第三人，與選項「可以對抗善意第三人」正好相反，錯誤。"],"tr":""},{"id":"h:108-4","p":"h","src":"108年第4題","sec":"D6","stem":"依我國民法的規定，下列關於最高限額抵押權之敘述，何者錯誤？","opts":["稱最高限額抵押權者，謂債務人或第三人提供其不動產為擔保，就債權人對債務人一定範圍內之不特定債權，在最高限額內設定之抵押權","最高限額抵押權人就已確定之原債權，僅得於其約定之最高限額範圍內，行使其權利","最高限額抵押權所擔保之原債權，未約定確定之期日者，抵押人或抵押權人得隨時請求確定其所擔保之原債權","最高限額抵押權得約定其所擔保原債權應確定之期日，並得於確定之期日後，不待變更登記即變更之"],"ok":[3],"ex":["§881-1 I：最高限額抵押權為就一定範圍內之不特定債權，在最高限額內設定之抵押權。","§881-2 I：就已確定之原債權，僅得於約定最高限額範圍內行使抵押權。","§881-5 I：未約定確定期日者，抵押人或抵押權人得隨時請求確定原債權。","§881-4 I：確定期日係得於「確定期日前」約定變更；期日屆至後原債權即確定，不得事後再變更，D所述順序顛倒。"],"tr":""},{"id":"h:108-5","p":"h","src":"108年第5題","sec":"E2","stem":"依我國民法之規定，下列關於夫妻財產制之敘述，何者錯誤？","opts":["夫妻未以契約訂立夫妻財產制者，除民法另有規定外，以共同財產制，為其夫妻財產制","夫妻財產制契約之訂立、變更或廢止，應以書面為之","夫妻財產制契約之訂立、變更或廢止，非經登記，不得以之對抗第三人","夫妻於婚姻關係存續中，得以契約廢止其財產契約，或改用他種約定財產制"],"ok":[0],"ex":["夫妻未訂立契約者，以法定財產制為其夫妻財產制（§1005），不是共同財產制，敘述錯誤。","夫妻財產制契約之訂立、變更或廢止，應以書面為之（§1007），正確。","非經登記，不得以之對抗第三人（§1008I），正確。","婚姻關係存續中得以契約廢止財產契約，或改用他種約定財產制（§1012），正確。"],"tr":""},{"id":"h:108-6","p":"h","src":"108年第6題","sec":"E3","stem":"依我國民法之規定，下列關於監護之敘述，何者正確？","opts":["已結婚的未成年人而無父母，或父母均不能行使、負擔對於其未成年子女之權利、義務時，應置監護人","父母對其未成年之子女，得因特定事項，於一定期限內，以書面委託他人行使監護之職務","為保護未成年子女之權益，監護人不得辭任其職務","監護人得受讓受監護人之財產"],"ok":[1],"ex":["依出題年（108年）舊法§1091但書，未成年人已結婚者不置監護人（當時未成年人結婚即有行為能力），故此敘述錯誤。現行法：§1091已無該但書，且112.1.1起男女須滿18歲始得結婚、18歲即成年（§12），已不存在「已結婚之未成年人」。","父母對未成年子女，得因特定事項於一定期限內，以書面委託他人行使監護職務（§1092），正確。","監護人有正當理由經法院許可得辭任（§1095），非不得辭任。","監護人不得受讓受監護人之財產（§1102），敘述錯誤。"],"tr":""},{"id":"h:108-7","p":"h","src":"108年第7題","sec":"D6","stem":"依我國民法的規定，下列關於抵押權之敘述，何者錯誤？","opts":["稱普通抵押權者，謂債權人對於債務人或第三人不移轉占有而供其債權擔保之不動產，得就該不動產賣得價金優先受償之權","抵押權所擔保者為原債權、利息、遲延利息、違約金及實行抵押權之費用。但契約另有約定者，不在此限","抵押權之效力，及於抵押物之從物而不及於從權利","不動產所有人設定抵押權後，得將不動產讓與他人。但其抵押權不因此而受影響"],"ok":[2],"ex":["§860：普通抵押權為不移轉占有而就供擔保之不動產賣得價金優先受償之權。","§861 I：擔保範圍含原債權、利息、遲延利息、違約金及實行費用，契約另有約定從其約定。","§862 I：抵押權效力及於抵押物之從物與從權利，並非「不及從權利」。","§867：設定抵押權後仍得讓與不動產，抵押權不受影響（追及效力）。"],"tr":""},{"id":"h:108-8","p":"h","src":"108年第8題","sec":"D5","stem":"依我國民法，下列關於地上權之敘述，何者錯誤？","opts":["地上權設定後，因土地價值之昇降，依原定地租給付顯失公平者，當事人得請求法院增減之","地上權人，縱因不可抗力，妨礙其土地之使用，不得請求免除或減少租金","地上權人得將其權利讓與他人或設定抵押權。但契約另有約定或另有習慣者，不在此限","地上權人積欠地租達一年之總額，除另有習慣外，土地所有人得定相當期限催告地上權人支付地租"],"ok":[3],"ex":["§835-1 I：地上權設定後因土地價值昇降，依原定地租給付顯失公平者，當事人得請求法院增減之。","§837：地上權人縱因不可抗力妨礙土地使用，不得請求免除或減少租金。","§838 I：地上權人得讓與其權利或設定抵押權，但契約另有約定或習慣者不在此限。","§836 I：積欠地租須「達二年之總額」，非一年；土地所有人並須先定相當期限催告，逾期不付始得終止。"],"tr":""},{"id":"h:108-9","p":"h","src":"108年第9題","sec":"C2","stem":"依我國民法之規定，下列關於租賃契約之敘述何者正確？","opts":["甲將自己所有之 A 屋租予乙後，又將 A 屋租予丙並交付占有予丙，乙得知後可向丙主張交付A 屋","甲將自己所有之 A 屋租予乙，並交付占有予乙後，A 屋竟遭丙無權占有。此時，乙可對丙主張占有物返還請求權","甲將自己所有之 A 屋租予乙供居住之用，乙雖於訂約時已知 A 屋為輻射屋，但因輻射屋會危及乙的健康，故乙仍得主張減少價金","甲將自己所有之 A 屋租予乙，約定由甲負修繕義務。按民法規定，乙得自行修繕再請求出租人償還費用"],"ok":[1],"ex":["一物二租，兩租賃契約均有效；丙已取得占有，乙不得向丙請求交付，只能向甲主張債務不履行責任。","承租人乙為直接占有人（§941），租賃物被丙無權占有（侵奪）時，乙得依§962 行使占有物返還請求權。","§424：租賃物危及承租人健康或安全者，承租人雖訂約時已知其瑕疵，仍得終止契約；法律效果是終止，不是減少價金。","§430：出租人負修繕義務而延不修繕時，承租人須先定期催告，逾期仍不修繕，才得自行修繕並請求償還費用；不得未經催告逕自修繕。"],"tr":""},{"id":"h:108-10","p":"h","src":"108年第10題","sec":"E4","stem":"甲未婚生有乙、丙、丁三子，某日甲因細故與乙口角，乙遂憤而毆打甲成傷，當時丙雖在場，然畏懼乙身強體壯，並未勸阻。甲心灰意冷，當場表示自己百年後，乙不得繼承其財產；事後更逢人便訴說丙也不孝，未挺身護甲。丙得知此事甚為憤怒，認為自己僅求自保並沒有錯，遂在某日憤而持刀殺甲，經丁阻止而未得逞，但日後仍經法院判決殺人未遂而受刑之宣告確定。不久甲因年老體衰而去世，請問下列敘述，何者正確？","opts":["甲僅表示乙不得繼承其財產，未表示丙不得繼承，故丙仍可繼承其財產","甲雖表示乙不得繼承其財產，但並未追訴乙之傷害罪，乙既未受刑之宣告，故乙仍得繼承甲的財產","甲若宥恕丙之行為，則乙、丙、丁三人可以一起繼承甲的財產","僅有丁可以繼承甲的財產"],"ok":[3],"ex":["丙殺人未遂受刑之宣告，依§1145I①喪失繼承權，不可再繼承。","乙毆打甲屬重大虐待，經被繼承人表示不得繼承，依§1145I⑤喪失繼承權，不以受刑宣告為要件。","甲宥恕效力僅及第二款至第四款（§1145II），不適用第一款殺人未遂；乙、丙仍喪失繼承權。","乙、丙均喪失繼承權，僅丁可繼承（§1145I①⑤），正確。"],"tr":""},{"id":"h:108-11","p":"h","src":"108年第11題","sec":"C3","stem":"依我國民法之規定，下列關於居間契約之敘述何者錯誤？","opts":["稱居間者，謂當事人約定，一方為他方報告訂約之機會或為訂約之媒介，他方給付報酬之契約","約定之報酬，較居間人所任勞務之價值，為數過鉅失其公平者，法院得因報酬給付義務人之請求酌減之。報酬已給付者，得請求返還","因婚姻居間而約定報酬者，就其報酬無請求權","居間人就其媒介所成立之契約，無為當事人給付或受領給付之權"],"ok":[1],"ex":["§565：居間為當事人約定，一方為他方報告訂約機會或為訂約媒介，他方給付報酬之契約。","§572：報酬過鉅失公平，法院得因給付義務人之請求酌減，但報酬已給付者，不得請求返還。","§573：因婚姻居間而約定報酬者，就其報酬無請求權（現行條文未規定約定無效）。","§574：居間人就其媒介所成立之契約，無為當事人給付或受領給付之權。"],"tr":""},{"id":"h:108-12","p":"h","src":"108年第12題","sec":"B6","stem":"10 歲的男童 A 去同學 B 家中一起打電動遊戲時，因一言不合吵起來，一氣之下摔壞 B 父甲新購買的筆電。請問下列敘述何者錯誤？","opts":["若摔壞筆電時 A 有識別能力，則由 A 單獨負責，甲不可向 A 之法定代理人乙求償","若摔壞筆電時 A 有識別能力，則 A 和其法定代理人乙必須連帶負賠償責任","若摔壞筆電時 A 無識別能力，則 A 無須負責","若摔壞筆電時 A 無識別能力，則由其法定代理人乙單獨負責，但乙可舉證免責"],"ok":[0],"ex":["§187 I：A有識別能力，與法定代理人乙連帶負責，甲可向乙求償。","§187 I：有識別能力時，行為人與法定代理人連帶負責。","§187 I：行為時無識別能力者，原則由法定代理人負責，A本人原則上無須負責；例外是被害人不能依§187Ⅰ、Ⅱ受賠償時（例如乙舉證監督無疏懈而免責），法院得依§187Ⅲ斟酌經濟狀況，令行為人A為全部或一部之賠償（衡平責任）。","§187 I 後段、II：無識別能力時由法定代理人單獨負責，乙得舉證監督無疏懈而免責。"],"tr":""},{"id":"h:108-13","p":"h","src":"108年第13題","sec":"A5","stem":"甲並無將其所有價值十萬元之 A 手錶出售的意思，卻向乙表示欲以五千元出售之，乙明知甲無出售 A 手錶之意思，仍當場表示願意以五千元購買時，甲出售 A 手錶之意思表示的效力如何？","opts":["有效","無效","甲得撤銷","效力未定"],"ok":[1],"ex":["甲之意思表示屬「心中保留（單獨虛偽意思表示）」（§86），原則上有效，但以相對人不知情為前提。","依§86但書，若相對人（乙）明知表意人（甲）無真正意思，則該意思表示無效，本題乙明知甲無出售意思，故甲之意思表示無效，買賣契約因而無效，正確。","心中保留並非「得撤銷」而是依相對人知情與否決定有效或無效，無撤銷問題。","效力未定通常用於限制行為能力人或無權代理，心中保留效果非效力未定。"],"tr":""},{"id":"h:108-14","p":"h","src":"108年第14題","sec":"A6","stem":"甲授與甫滿十八歲之乙代理權，由乙處理出售甲所有之 A 機車的事宜。乙乃以甲之代理人的名義，以一萬元價金與丙訂立買賣 A 機車的契約。乙與丙所締結之買賣契約的效力如何？","opts":["對甲發生效力","甲未承認前，效力未定","乙之法定代理人未承認前，效力未定","乙之法定代理人得撤銷之"],"ok":[0],"ex":["依§104，代理人不以有行為能力為必要，限制行為能力人（出題年舊法下18歲之乙即是；現行法§12滿18歲已成年，更無疑問）亦得為代理人；代理人在代理權限內以本人名義所為之意思表示，直接對本人發生效力（§103），故乙代甲與丙訂立買賣契約，效力直接對甲（本人）發生，正確。","既然代理人不以有行為能力為必要，乙雖為限制行為能力人，其代理行為仍有效，無須甲另行承認。","乙是作為代理人（代甲行為），其法律行為效力歸屬於本人甲，乙之法定代理人不涉入此代理行為的效力判斷。","§104：代理人所為或所受意思表示之效力，不因其為限制行為能力人而受影響；乙雖為限制行為能力人，代理行為仍有效並對甲發生效力，其法定代理人既無須承認，也無從撤銷，故D錯誤。"],"tr":""},{"id":"h:108-15","p":"h","src":"108年第15題","sec":"B2","stem":"甲、乙締結買賣甲所有之 A 屋的契約，乙並先為部分價金之給付。其後，乙未依約定期限給付剩餘價金。就甲以乙履行遲延而解除 A 屋買賣契約之情形，下列敘述，何者正確？","opts":["經甲定期間催告乙履行，甲得於經相當期限後，不須再為催告，即得解除契約","甲僅限於法律規定之事由始得解除，不得與乙約定合意解除之事由","契約經解除後，甲、乙互負回復原狀的義務，甲不得向乙請求損害賠償","契約經解除後，因乙有可歸責事由，甲返還乙已給付之價金時，不須附加利息"],"ok":[0],"ex":["§254：定期間催告而債務人仍不履行，期限屆滿後得解除，不須再催告。","解除權除法定（如§254～§256）外，當事人亦得依契約自由約定（約定解除權），並非僅限法定事由。","§260：解除不妨礙損害賠償之請求。","§259 (2)：返還金錢者，應附加自受領時起之利息。"],"tr":""},{"id":"h:108-16","p":"h","src":"108年第16題","sec":"D2","stem":"就下列甲、乙間之法律關係，何者為非經登記不生效力的情形？","opts":["甲、乙間締結買賣甲之不動產的契約時","乙繼承被繼承人甲之不動產時","甲以其土地供乙設定不動產役權時","甲將其有抵押權擔保之債權讓與予乙時"],"ok":[2],"ex":["§345：當事人就標的物及價金互相同意，買賣契約即成立；不動產買賣之債權契約不以登記為生效要件（登記是物權變動的要件），選項排除。","§1147、§759：繼承因被繼承人死亡而開始，繼承人於登記前即已取得不動產物權，僅處分時須先登記，故繼承不屬「非經登記不生效力」，選項排除。","§851、§758Ⅰ：設定不動產役權是依法律行為設定不動產物權，非經登記不生效力（§758Ⅱ另要求應以書面為之），正確。","§294、§297：債權讓與經通知債務人即對債務人生效，不以登記為要件；§295Ⅰ、§870規定從屬之抵押權隨債權移轉，是法律規定之當然移轉，不屬§758「依法律行為而取得」之登記生效要件，選項排除。"],"tr":""},{"id":"h:108-17","p":"h","src":"108年第17題","sec":"B3","stem":"就甲、乙、丙三人對丁負有平均分擔之 300 萬元連帶債務的情形，下列敘述，何者正確？","opts":["甲對丁為債務之承認而中斷時效時，其效力亦及於乙、丙之債務","丁請求甲支付全額獲勝訴判決後，仍未能自甲受償時，得再請求乙支付全額","甲清償全額後，如乙不能償還其分擔額，甲亦僅能向丙求償 100 萬元","甲對丁清償 100 萬元後，丁即不得再次向甲請求支付剩餘之 200 萬元"],"ok":[1],"ex":["§279：債務承認為相對效力事由，僅對甲生效。","§273：債權人得對連帶債務人中之一人或數人或全體，同時或先後請求全部或一部給付。","§282 I：乙不能償還之100萬由甲、丙平均分擔，甲得向丙求償150萬，並非100萬。","§273 II：連帶債務未全部履行前，全體債務人仍負連帶責任，丁仍得向甲請求剩餘200萬。"],"tr":""},{"id":"h:108-18","p":"h","src":"108年第18題","sec":"D2","stem":"甲、乙分別共有 A 地，各有二分之一應有部分。在甲乙未有任何協議之情形下，下列敘述，何者正確？","opts":["甲得以其應有部分供丙設定普通地上權","甲不得將其應有部分出賣、並移轉登記予丁","甲僅得於其應有部分種植作物","甲得以其應有部分供戊設定普通抵押權"],"ok":[3],"ex":["地上權須使用土地之特定部分，是對共有物本身設定負擔，不是處分甲自己的應有部分，不能依§819 I 由甲單獨為之。A地為土地，設定地上權依土地法§34-1 I 須「共有人過半數及其應有部分合計過半數」同意（應有部分合計逾三分之二者人數不計），未達者回到§819 II 全體同意；本題只有甲一人、應有部分二分之一，人數與應有部分均未過半，乙又未同意，甲不能單獨為之，選項錯誤。","§819Ⅰ：各共有人得自由處分其應有部分，甲可將應有部分出賣並移轉登記予丁，選項說「不得」錯誤。","§818：各共有人除契約另有約定外，按其應有部分對共有物之「全部」有使用收益之權，並非僅得於應有部分種植，選項錯誤。","§819Ⅰ：各共有人得自由處分其應有部分，包含以應有部分設定抵押權，無須經他共有人同意，正確。"],"tr":""},{"id":"h:108-19","p":"h","src":"108年第19題","sec":"D6","stem":"下列何者不得為抵押權之標的物？","opts":["不動產役權","地上權","農育權","典權"],"ok":[0],"ex":["不動產役權附隨於需役地，不能單獨讓與（§853），亦不能單獨設定抵押，「不得」為抵押標的，正確為應選答案。","§882，地上權「得」為抵押標的，選項排除。","§882，農育權「得」為抵押標的，選項排除。","§882，典權「得」為抵押標的，選項排除。★記法：地上權、農育權、典權可抵押（§882）；不動產役權不可單獨抵押（附隨性）。"],"tr":""},{"id":"h:108-20","p":"h","src":"108年第20題","sec":"E1","stem":"甲育有子女乙，丙育有子女丁、戊，乙男與丁女結婚後育有子女己。就此情形，下列敘述何者錯誤？","opts":["甲、丁為直系姻親","乙、戊為旁系姻親","甲、丙為旁系姻親","己、戊為旁系血親"],"ok":[2],"ex":["丁為甲之子乙之配偶，屬血親之配偶，為直系姻親（§969、§970），正確。","戊為乙之配偶丁之血親（妹），為配偶之血親，旁系姻親（§970②），正確。","甲與丙為親家關係，屬血親之配偶之血親，不屬§969所列姻親，敘述錯誤。","己為丁之子，戊為丁之手足，為舅姨與外甥關係，三親等旁系血親，正確。"],"tr":""},{"id":"h:108-21","p":"h","src":"108年第21題","sec":"C2","stem":"甲將其所有之 A 土地上之 B 建物讓與乙時，在房屋得使用期限內，乙與甲間有何法律關係？","opts":["推定有租賃關係","視為有租賃關係","推定有普通地上權關係","視為有普通地上權關係"],"ok":[0],"ex":["§425-1，土地及其上之房屋同屬一人，而僅將房屋讓與他人（未讓與土地），在房屋使用期限內，「推定」（非「視為」）土地與房屋間有租賃關係，正確。★關鍵區分：一般買賣分離→推定租賃（§425-1）；抵押拍賣分離→視為地上權（§876），務必分清。","應為「推定」而非「視為」，兩者重要差別：「推定」可被反証推翻；「視為」法律擬制，不可推翻，本選項說「視為」錯誤。","地上權適用於抵押拍賣場合（§876），一般買賣分離適用租賃（§425-1），選項適用規定錯誤。","同C，且「視為」二字亦不正確。"],"tr":""},{"id":"h:108-22","p":"h","src":"108年第22題","sec":"E4","stem":"甲、乙婚後生育有子女丙、丁、戊。戊與己結婚生育有子女庚、辛後，不幸早於其父母去世。就甲高齡過世後遺下之財產，下列法定繼承人之應繼分比例，何者正確？","opts":["乙二分之一、丙四分之一、丁四分之一","乙三分之一、丙三分之一、丁三分之一","乙四分之一、丙四分之一、丁四分之一、己四分之一","乙四分之一、丙四分之一、丁四分之一、庚八分之一、辛八分之一"],"ok":[3],"ex":["乙為配偶，與第一順位繼承人同為繼承時應繼分平均（§1144①），不是二分之一。","並非三等分，戊雖早亡，其直系血親卑親屬庚、辛代位繼承其應繼分（§1140）。","己為戊之配偶，不得代位，不得繼承甲之遺產。","乙、丙、丁及戊之份各1/4（配偶與子女平均），庚、辛代位繼承戊之1/4，各1/8（§1140、§1144①），正確。"],"tr":""},{"id":"h:108-23","p":"h","src":"108年第23題","sec":"E4","stem":"下列關於遺囑之敘述，何者正確？","opts":["十八歲之限制行為能力人所為之遺囑，當然無效","受輔助宣告之成年人所為之遺囑，當然無效","口授遺囑，自遺囑人能依其他方式為遺囑之時起，經過三個月而失其效力","公證人的受僱人得為公證遺囑之見證人"],"ok":[2],"ex":["依出題年（108年）舊法，20歲成年，18歲為限制行為能力人，但滿16歲即得為遺囑，無須法定代理人允許（§1186II），並非當然無效。現行法112.1.1起18歲即成年（§12），18歲者有完全行為能力，更非無效。","受輔助宣告者並不當然喪失行為能力（§15-1），遺囑僅排除無行為能力人（§1186I），並非當然無效。","口授遺囑自遺囑人能依其他方式為遺囑之時起，經過三個月失其效力（§1196），正確。","公證人之受僱人不得為遺囑見證人（§1198⑤），敘述錯誤。"],"tr":""},{"id":"h:108-24","p":"h","src":"108年第24題","sec":"E3","stem":"依我國民法之規定，下列關於子女姓氏之敘述，何者錯誤？","opts":["父母於子女出生登記前，應以書面約定子女從父姓或母姓。未約定或約定不成者，於戶政事務所抽籤決定之","子女經出生登記後，於未成年前，得由父母以書面約定變更為父姓或母姓","子女已成年者，得變更為父姓或母姓","非婚生子女從母姓。經生父認領者，從父姓"],"ok":[3],"ex":["§1059 I：父母於子女出生登記前，應以書面約定從父姓或母姓；未約定或約定不成者，於戶政事務所抽籤決定。","§1059 II：子女出生登記後、未成年前，得由父母以書面約定變更為父姓或母姓（變更以一次為限）。","§1059 III：子女已成年者，得變更為父姓或母姓。","§1059-1 I：非婚生子女從母姓；經生父認領後，是適用§1059 II至IV，由父母書面約定變更，並非當然改從父姓。"],"tr":""},{"id":"h:108-25","p":"h","src":"108年第25題","sec":"E4","stem":"甲乙為夫妻，育有一子丙，並共同收養丁為養子。某日甲因交通意外去世，未留有遺囑，請問依我國民法的規定，下列敘述，何者錯誤？","opts":["乙、丙、丁三人得以繼承","乙、丙、丁三人之應繼分各為三分之一","在分割遺產前，乙、丙、丁三人對於遺產全部按其應繼分為分別共有","繼承人對於甲之債務，以因繼承所得遺產為限，負清償責任"],"ok":[2],"ex":["乙為配偶（§1144），丙為婚生子女，丁為養子；養子女與養父母之婚生子女地位相同（§1077 I），同為繼承人。","配偶與第一順序直系血親卑親屬同為繼承時，按人數平均（§1144①），乙丙丁三人各三分之一。","分割前繼承人對遺產全部為「公同共有」（§1151），不是分別共有。","§1148 II：繼承人對被繼承人債務，以因繼承所得遺產為限負清償責任（限定責任）。"],"tr":""},{"id":"h:107-1","p":"h","src":"107年第1題","sec":"D2","stem":"甲有 A、B、C 三台車，以總價 50 萬元出售給乙，其後甲將其對乙的債權贈與於丙，並讓與之。於乙將 50 萬元現金支付於丙後，甲將 A、B、C 三台車交付給乙並移轉所有權。試問甲、乙、丙間共有多少法律行為？","opts":["4","5","6","7"],"ok":[3],"ex":["只計4個漏算多項：買賣、債權贈與、債權讓與、現金給付、三車之物權移轉都各是法律行為。","5個仍不足，三台車各為獨立物，所有權移轉須各別讓與合意與交付。","6個仍少算一個，須逐項列舉（見D）。","買賣契約1＋贈與契約1＋債權讓與（準物權行為）1＋乙交付現金移轉所有權1＋A、B、C三車所有權移轉各1＝7個。"],"tr":""},{"id":"h:107-2","p":"h","src":"107年第2題","sec":"A6","stem":"A 公司董事長甲於 5 月 1 日上午告訴其助理乙致函於丙，表示願以一億元購買其工廠。乙於 5 月2 日上午發信，信於 5 月 4 日到達丙處。經查，甲於 5 月 2 日晚上心肌梗塞死亡，丙於 5 月 6 日函覆 A 公司為承諾，試問買賣契約是否成立？","opts":["買賣契約不成立","買賣契約效力未定，需視 A 公司繼任董事長是否承認決定其效力","買賣契約效力未定，需視甲之繼承人是否承認決定其效力","買賣契約成立"],"ok":[3],"ex":["要約於發出後表意人死亡不失其效力（§95Ⅱ），到達後即生效，丙承諾後契約成立。","要約人為A公司而非甲個人，甲死亡不影響要約效力，也無須等待繼任董事長承認。","要約人是A公司，非甲，甲之繼承人不是契約當事人，與繼承無關。","§95Ⅰ 非對話意思表示於到達相對人時生效，§95Ⅱ 表意人發出後死亡，意思表示不失效力；丙之承諾使契約成立（§153）。"],"tr":""},{"id":"h:107-3","p":"h","src":"107年第3題","sec":"A6","stem":"下列有關使者之敘述，何者錯誤？","opts":["使者係在傳達他人的意思表示","使者得為無行為能力人","身分行為不可藉使者傳達其意思表示","使者未適時傳達的危險由表意人承擔"],"ok":[2],"ex":["使者（messenger）的功能是傳達他人（表意人）已決定的意思表示，有別於代理人（自行決定意思表示內容），正確。","使者僅係傳達機器，不自行決定意思內容，故不需具有行為能力，無行為能力人亦得充任使者，正確。","使者只是「傳達」本人已經決定、完成的意思表示，意思仍是本人所為；身分行為（如結婚、離婚）因高度屬人性而不得「代理」（由他人代為決定意思），但不等於不能由使者傳達本人自己的意思。「身分行為不可藉使者傳達」過於絕對，錯誤，為應選答案。","使者未適時傳達之風險（如信件延誤），由表意人（發出意思表示之人）承擔，正確。"],"tr":""},{"id":"h:107-4","p":"h","src":"107年第4題","sec":"B1","stem":"種類之債係以不特定物之給付為標的，為使債之實現，於履行前應為特定。下列有關種類之債特定之方法，何者正確？","opts":["種類之債只能依法定方法為特定","往取之債於債務人具體指定給付物，並將準備給付之情事，通知債權人時，種類之債即為特定","送赴之債於債務人將給付物送至債權人住所地，使債權人處於得隨時受領之狀態時，種類之債即為特定","赴償之債於債務人交付其物於運送之人時，種類之債即為特定"],"ok":[1],"ex":["特定方法不限法定，經債權人同意指定其物者亦可（§200 II）。","往取之債，債務人具體指定給付物並通知債權人準備給付（§235 但書），必要行為完成，種類之債即特定。","「送赴之債」在通說用語中指寄送之債（債務人應將標的物送往清償地以外之處所），於債務人將給付物交付運送人時特定。選項所描述「送至債權人住所地、使債權人處於得隨時受領之狀態」，其實是赴償之債在債權人住所依債務本旨現實提出（§235本文）的特定方式；選項把赴償之債的規則套在送赴之債上，故錯誤。","交付運送人即特定，是送赴（寄送）之債的規則；赴償之債須在債權人住所地依債務本旨現實提出（§235本文）才完成必要行為而特定（§200Ⅱ）。選項把寄送規則套在赴償之債，錯誤。C、D正好是名稱與規則對調。"],"tr":""},{"id":"h:107-5","p":"h","src":"107年第5題","sec":"D6","stem":"甲向乙貸款新臺幣 500 萬元，以其所有之 A 地及其上之 B 屋設定抵押權給乙作擔保。試問下列何者非屬抵押權效力所及？","opts":["B 屋抵押權設定後，甲於 B 屋上增建無獨立出入口之頂樓","B 屋抵押權設定前，甲於 B 屋旁增建有獨立出入口之車庫","A 地抵押權設定前，甲於 A 地栽種之果樹","A 地扣押前，自甲於 A 地栽種果樹所分離之果實"],"ok":[3],"ex":["屬效力所及，不是答案：§862 III，附加於建築物而不具獨立性之部分，為抵押權效力所及。","屬效力所及，不是答案：車庫於抵押權設定前即已存在，供B屋使用、常助B屋之效用且同屬甲所有，屬B屋之從物（§68 I），依§862 I 抵押權效力及於抵押物之從物；§862 III 但書（準用§877 併付拍賣、無優先受償）只規範「設定後」才附加之獨立物，本選項是設定前，不適用。","屬效力所及，不是答案：未分離之果樹為土地之成分，隨土地為抵押標的。","§863：抵押權效力僅及扣押後抵押人就抵押物得收取之天然孳息；扣押前已分離之果實為獨立動產，不屬效力所及。"],"tr":""},{"id":"h:107-6","p":"h","src":"107年第6題","sec":"D6","stem":"債務人甲所有之抵押物上，設有擔保乙 200 萬元債權之第一次序抵押權、丙 120 萬元債權之第二次序抵押權及丁 50 萬元債權之第三次序抵押權。抵押物拍賣所得價金為 300 萬元。乙將其第一次序之優先受償利益拋棄予丁，則應如何分配拍賣所得之金額？","opts":["乙 150 萬元，丙 0 元，丁 50 萬元","乙 160 萬元，丙 100 萬元，丁 40 萬元","乙 0 元，丙 100 萬元，丁 200 萬元","乙 150 萬元，丙 100 萬元，丁 50 萬元"],"ok":[1],"ex":["乙拋棄優先受償利益後與丁同順位，按債權比例分配，非乙150、丁50之分配。","先依原順位分配：乙200、丙100（丙債權120不足）、丁0；乙、丁合計可得200，依債權額200:50＝4:1分配，乙160、丁40，丙仍100，正確（§870-1I②為特定後次序抵押權人之利益拋棄次序，但他抵押權人丙之利益不受影響）。","乙不是全部讓出，仍可就比例受償，不是0元。","乙150、丁50不符比例；乙、丁合計200，應為160:40。"],"tr":""},{"id":"h:107-7","p":"h","src":"107年第7題","sec":"D5","stem":"下列有關農育權之敘述，何者錯誤？","opts":["農育權係用益物權之一種","農育權有支付地租約定者，農育權人因不可抗力致收益減少，得請求減免其地租","農育權原則上係不定期限","農育權人原則上得將其農育權讓與他人"],"ok":[2],"ex":["§850-1：農育權為以農作、森林、養殖、畜牧、種植竹木或保育為目的之用益物權。","§850-4：有支付地租約定者，農育權人因不可抗力致收益減少或全無時，得請求減免地租。","§850-1 Ⅱ：農育權期限不得逾20年，逾20年者縮短為20年（但以造林、保育為目的或法令另有規定者，不在此限），原則上是定有期限，並非原則上不定期限。（§850-2 只處理「未定期限」：除造林、保育目的外得隨時終止，應於6個月前通知。）","§850-3：農育權人得將其權利讓與他人；但契約另有約定或另有習慣者，不在此限。"],"tr":""},{"id":"h:107-8","p":"h","src":"107年第8題","sec":"D2","stem":"甲乙丙丁共有 A 地，各有應有部分四分之一，甲乙丙三人未經丁之同意即將 A 地出賣給戊並為移轉登記，請問此物權移轉行為之效力為何？","opts":["有效","無效","未得共有人全體同意，係屬無權處分效力未定","債權行為效力未定，物權移轉行為亦受其影響而效力未定"],"ok":[0],"ex":["A 是土地，適用土地法§34-1Ⅰ：共有人過半數且應有部分合計過半數同意，即可處分共有土地；應有部分合計逾三分之二者，人數不計。甲乙丙三人（四人中三人）、應有部分合計 3/4，達標，處分有效（前提：依Ⅱ事先書面通知丁；丁有Ⅳ優先承購權）。","土地法§34-1Ⅰ 已授權多數共有人處分共有土地全部，不能說無效。","土地法§34-1 是對多數共有人的特別授權，不是「無權處分」，所以不是效力未定（§118 承認機制不適用）。","買賣為債權行為，不因出賣人無處分權而受影響（§348）；物權行為獨立有因，也不使債權行為效力未定。"],"tr":""},{"id":"h:107-9","p":"h","src":"107年第9題","sec":"E2","stem":"下列有關夫妻分別財產制之規定，下列何者錯誤？","opts":["分別財產制為約定財產制之一種","夫妻各自保有財產之所有權，並各自為管理、使用、收益及處分","夫妻之一方得因他方有花柳病或其他惡疾，向法院請求宣告改用分別財產制","夫妻各自對其債務負清償之責，但夫妻之一方以自己財產清償他方債務時，得請求返還"],"ok":[2],"ex":["分別財產制為約定財產制之一（§1004），正確。","夫妻各保有財產所有權，各自管理、使用、收益及處分（§1044），正確。","宣告改用分別財產制之事由規定於§1010，§1010I列舉不給付家庭生活費用、財產不足清償債務等六款，§1010II另有「不同居已達六個月以上」；條文並無「花柳病或其他惡疾」，敘述錯誤。","夫妻各自對其債務負清償責任，一方以自己財產清償他方債務得請求返還（§1023 II，分別財產制依§1046「適用」之），正確。"],"tr":""},{"id":"h:107-10","p":"h","src":"107年第10題","sec":"E2","stem":"下列有關夫妻法定財產制之敘述，下列何者正確？","opts":["婚前財產由夫妻各自所有，婚後財產由夫妻公同共有","婚前財產及婚後財產均由夫妻各自所有","婚前財產由夫妻各自所有，婚後財產由夫妻分別共有","婚前財產及婚後財產均由夫妻公同共有，且夫妻對其結婚而公同共有之財產均有管理、使用、收益、處分之權利，若將來離婚對他方有請求分割之權利"],"ok":[1],"ex":["婚後財產亦各自所有，非公同共有。","法定財產制下婚前及婚後財產均由夫妻各自所有（§1017I），正確。","並非分別共有，而是各自所有。","公同共有、請求分割為共同財產制之特徵，與法定財產制不符。"],"tr":""},{"id":"h:107-11","p":"h","src":"107年第11題","sec":"B6","stem":"16 歲之甲於騎車上學時，與正在送貨之某公司送貨員乙（30 歲）擦撞，並導致路人丙受傷。若甲與乙均為違規駕駛，下列敘述何者正確？","opts":["丙僅得請求財產上之損害賠償，不得主張非財產上損害賠償","甲為有識別能力人，故丙僅得向甲單獨請求損害賠償，不得向甲之父母求償","我國並無僱傭人責任之規範，僱傭乙之公司不必負損害賠償責任","甲與乙對丙構成共同侵權行為，均須對丙負連帶損害賠償責任"],"ok":[3],"ex":["§195 I：身體、健康受侵害，得請求非財產上損害賠償。","§187 I：甲有識別能力，與其法定代理人連帶負責，丙得向其父母求償（父母可依 §187 II 舉證免責）。","§188 I：民法規定僱用人責任，公司須與受僱人連帶負責。","§185 I：數人共同不法侵害他人權利，連帶負損害賠償責任，甲、乙共同造成丙受傷。"],"tr":""},{"id":"h:107-12","p":"h","src":"107年第12題","sec":"A4","stem":"針對民法有關撤銷權之規範，下列敘述何者正確？","opts":["撤銷權僅能對不健全的意思表示為之，不得對法律行為或法律關係為之","任何撤銷權之行使，均只須以意思表示方式為之，即生法律效果","撤銷權因一定期間內不行使而消滅，此期間稱為消滅時效","撤銷權之法律性質與解除權相同，均屬形成權之一種"],"ok":[3],"ex":["撤銷權不限於撤銷不健全的意思表示，亦可撤銷「法律行為」：如§244債權人得聲請法院撤銷債務人有害債權之行為、§74法院得撤銷乘人急迫輕率無經驗而顯失公平之法律行為（暴利行為），故「不得對法律行為為之」錯誤。","大部分撤銷權以意思表示方式行使即生效，但某些撤銷須向法院聲請（如暴利行為§74、詐害債權§244），並非「任何撤銷權」均以意思表示方式為之。","撤銷權之行使期間為「除斥期間」，不適用消滅時效之中斷、不完成等制度，兩者須嚴格區分，本選項稱為「消滅時效」屬錯誤。","撤銷權（如§92脅迫撤銷）與解除權（如§254違約解除）性質相同，均屬「形成權」，即單方意思表示即可使法律關係發生、變更或消滅，正確。"],"tr":""},{"id":"h:107-13","p":"h","src":"107年第13題","sec":"A1","stem":"18 歲之甲考取大學後，拿著父母親給的住宿費、生活費至北部求學，擬向乙承租 A 屋一年。關於甲乙間租賃契約之效力，下列敘述，何者錯誤？","opts":["甲為限制行為能力人，故甲所締結之租賃契約無效","甲得主張關於租賃契約之意思表示，在現代社會中可認為係依其年齡及身分、日常生活所必需者，例外無須得法定代理人允許，契約仍可成立生效","甲得提出法定代理人就租屋之書面允許，以使契約成立生效","乙得定期限催告法定代理人，確答是否承認甲乙間租賃契約，以使契約成立生效"],"ok":[0],"ex":["依出題年舊法（成年20歲），18歲之甲為限制行為能力人：未得允許所訂契約是「效力未定」（§79：須經法定代理人之承認，始生效力），不是無效；若屬§77但書「依其年齡及身分、日常生活所必需」更無須允許。選項說「無效」錯誤，為本題答案。現行法：§12「滿十八歲為成年」，18歲之甲已成年，租約當然有效，「無效」同樣錯誤。","§77但書：「依其年齡及身分、日常生活所必需者」不須得法定代理人允許。考上大學、帶著父母給的住宿費北上求學而租屋，屬依其年齡及身分所必需之行為，得主張無須允許即有效（出題年舊法下的論點；現行法甲已成年，無此問題）。","§77本文：限制行為能力人為意思表示，應得法定代理人之「允許」。允許不以書面為限，提出法定代理人的書面允許當然足以證明已得允許，租約即有效成立。（原解析只談「給住宿費視為允許」，沒回應選項所說的「書面允許」。）","§80Ⅰ：相對人得定「一個月以上」之期限，催告法定代理人確答是否承認；法定代理人逾期不為確答者，視為拒絕承認（§80Ⅱ）。乙催告可使契約效力確定，正確。"],"tr":""},{"id":"h:107-14","p":"h","src":"107年第14題","sec":"C4","stem":"下列有關贈與之敘述，何者正確？","opts":["贈與係單獨行為","贈與以物之交付為要件，於物之交付後，贈與行為才為生效","經公證之贈與，於贈與物之權利未移轉前，贈與人得隨時撤銷其贈與","贈與得附有負擔"],"ok":[3],"ex":["依§406，贈與是當事人約定一方無償給與財產、他方允受之契約，須雙方意思表示合致（受贈人須允受），不是單獨行為，選項錯誤。","依§406，贈與於雙方約定「無償給與」並經允受時即成立生效（諾成契約），不以物之交付為要件，選項錯誤。","依§408Ⅱ，經公證之贈與（或為履行道德上義務而為之贈與），不適用§408Ⅰ 的任意撤銷，贈與人不得在權利移轉前隨時撤銷；選項說「得隨時撤銷」正好相反，錯誤。","依§412Ⅰ，贈與可以附有負擔；若贈與人已為給付而受贈人不履行其負擔，贈與人得請求受贈人履行負擔，或撤銷贈與，正確。"],"tr":""},{"id":"h:107-15","p":"h","src":"107年第15題","sec":"A2","stem":"民法關於法人之規定，下列敘述，何者錯誤？","opts":["法人可分為財團法人與社團法人","法人於法令限制內，有享受權利負擔義務之能力。但專屬於自然人之權利義務，不在此限","法人應設董事與監察人","法人對於其董事或其他有代表權之人因執行職務所加於他人之損害，與該行為人連帶負賠償之責任"],"ok":[2],"ex":["民法法人依設立基礎分為財團法人（以財產為基礎）與社團法人（以人為基礎），正確。","§26規定法人之權利能力在法令範圍內，且不包含專屬自然人之部分，正確。","法人「應設董事」（§27Ⅰ，必設機關），但「監察人」屬任意機關，法人「得設監察人」（§27Ⅳ），並非必須設置，故「法人應設董事與監察人」之敘述錯誤，此為本題應選答案。","§28，法人對其代表人執行職務所加損害，與行為人連帶負賠償責任，正確。"],"tr":""},{"id":"h:107-16","p":"h","src":"107年第16題","sec":"B6","stem":"關於人格權保護，下列敘述，何者錯誤？","opts":["人格權受侵害時，得請求法院除去其侵害；有受侵害之虞時，得請求防止之","名譽權受侵害時，若法院採取命被告登報道歉作為回復名譽之適當處分，依現行司法實務見解，仍屬合憲","債務人因債務不履行，致債權人之人格權受侵害者，不得請求損害賠償","生命權受侵害時，配偶得請求損害賠償與慰撫金"],"ok":[2],"ex":["§18 I：人格權受侵害，得請求法院除去其侵害；有受侵害之虞時，得請求防止之。","依出題年（107年）的司法院釋字第656號解釋：法院命加害人公開道歉，如未涉及自我羞辱等損及人性尊嚴者，不違憲，故B當時為正確敘述。【新舊見解】其後111年憲判字第2號判決已變更該解釋：§195Ⅰ後段「回復名譽之適當處分」不包括法院以判決命加害人道歉。依現行見解B也是錯誤敘述，本題現行法下B、C皆錯（答案疑義），官方答案C係依出題年見解。","§227-1：債務不履行致人格權受侵害，準用 §192-§195、§197，債權人得請求賠償，包括慰撫金。","§194：不法侵害他人致死者，配偶等得請求非財產上損害賠償相當金額。"],"tr":""},{"id":"h:107-17","p":"h","src":"107年第17題","sec":"C4","stem":"關於僱傭契約，下列敘述，何者錯誤？","opts":["僱傭契約之專屬性較低，故僱用人得將其勞務請求權讓與第三人，無需受僱人同意","受僱人服勞務，因非可歸責於自己之事由致受損害者，得向僱用人請求賠償","定期之僱傭契約，若當事人之一方遇有重大事由，仍得於期限屆至前終止契約","受僱人因執行職務，不法侵害他人之權利者，原則上係由僱用人與受僱人連帶負損害賠償責任"],"ok":[0],"ex":["§484 I：僱用人非經受僱人同意，不得將其勞務請求權讓與第三人，故需受僱人同意。","§487-1 I：受僱人服勞務，因非可歸責於自己之事由致受損害者，得向僱用人請求賠償。","§489 I：當事人之一方遇有重大事由，其僱傭契約縱定有期限，仍得於期限屆滿前終止。","§188 I：受僱人因執行職務不法侵害他人權利，僱用人與行為人連帶負賠償責任（僱用人能證明選任監督無過失者可免責）。"],"tr":""},{"id":"h:107-18","p":"h","src":"107年第18題","sec":"D1","stem":"下列敘述所涉及之物，何者不能單獨作為物權之客體？","opts":["醫療器材店所販售之大腿義肢","已被安裝置入大廈內運作的客製化電梯","區分所有建築物（如大廈）之專有部分","足以遮風避雨的違章建築物"],"ok":[1],"ex":["大腿義肢在店內販售、尚未裝置於人體時，為獨立之動產，可單獨作為物權客體。","§811：動產因附合而為不動產之重要成分者，不動產所有人取得動產所有權；電梯裝入大廈後成為建物之重要成分，已喪失獨立性，不能單獨作為物權客體，正確。","§799Ⅰ、Ⅱ：專有部分在構造上及使用上可獨立、且得單獨為所有權之標的，可單獨作為物權客體，選項排除。","§66Ⅰ：土地及其定著物為不動產；違章建築足以遮風避雨，屬獨立之定著物（不動產），可為物權客體，僅因無法辦理保存登記，實務上另以「事實上處分權」處理（依實務見解），並非「動產」，選項排除。"],"tr":""},{"id":"h:107-19","p":"h","src":"107年第19題","sec":"D3","stem":"甲於颱風過後翌日在河邊拾得從國家森林區漂流而下之珍貴紅檜木，乙自甲處竊取之，並將之以低價出售予不知情之丙。下列敘述，何者正確？","opts":["甲拾得珍貴漂流木，依民法第 802 條無主物先占規定，原始取得其所有權","甲拾得珍貴漂流木，依民法第 810 條適用關於拾得遺失物規定，負通知及交存該物之義務，無法立即取得該物所有權","因天災致國有珍貴林木漂流至國有林區外時，甲得自由撿拾取得所有權，不受民法關於拾得遺失物規定之限制","甲因丙取得漂流木所有權而受損害時，得依關於不當得利之規定請求償還價額"],"ok":[1],"ex":["漂流木來自國家森林，所有人（國家）可得確定，非無主物，不能依§802先占取得。","§810：拾得漂流物、沈沒物或其他因自然力而脫離他人占有之物者，「準用」關於拾得遺失物之規定（選項寫「適用」，用語不精確但結論不變），須通知、交存並待招領，不能立即取得所有權。","§810 對漂流物並無國有林木之例外，故仍受遺失物拾得規定之限制。","甲非所有人，僅為拾得人，丙取得與否不致使甲受有喪失權利之損害，不具§816「因他人取得所有權而受損害」之要件。"],"tr":""},{"id":"h:107-20","p":"h","src":"107年第20題","sec":"D6","stem":"下列何種權利，得為抵押權之標的物？","opts":["地上權","不動產役權","著作權","租賃權"],"ok":[0],"ex":["§882，地上權「得為抵押權之標的物」（得以地上權設定抵押），正確。","不動產役權附隨於需役地，不得單獨讓與（§853），亦不得單獨抵押，選項排除。","著作權為無形財產權，民法物權編之抵押權客體以「不動產」及特定財產權（§882地上權、農育權、典權）為限，著作權不在其中，選項排除。","租賃權為債權，並非民法§882所列得設定抵押之權利，選項排除。"],"tr":""},{"id":"h:107-21","p":"h","src":"107年第21題","sec":"D2","stem":"下列何者並非公同共有關係？","opts":["祭祀公業之派下員對不具法人資格的祭祀公業財產之關係","合夥人對合夥財產之關係","將一筆土地贈與且移轉登記予數人，受贈人對該贈與物之關係","數人繼承遺產，於分割遺產前，各繼承人對於遺產全部之關係"],"ok":[2],"ex":["祭祀公業（未法人化）之財產，由派下員公同共有，屬公同共有，選項排除。","§668，合夥財產為合夥人全體公同共有，選項排除。","數人共同受贈某物並完成移轉登記，彼此之間並無公同關係（§827Ⅰ：公同共有須依法律規定、習慣或法律行為成立公同關係，如繼承、合夥）；依§817數人按其應有部分對一物有所有權者為共有人，故為「分別共有」，並非公同共有，正確為應選答案。★公同共有須有特定「公同關係」（繼承、合夥、祭祀公業等）為基礎；單純多人受贈移轉登記→分別共有。","§1151，繼承人有數人時，在分割遺產前，各繼承人對遺產全部為公同共有，選項排除。"],"tr":""},{"id":"h:107-22","p":"h","src":"107年第22題","sec":"D2","stem":"下列關於物權規定之敘述，何者正確？","opts":["用益物權包括地上權、農育權、不動產役權、典權與質權","違章建築物不能辦理移轉登記，故於建造完成時，建造人無法取得所有權","基於公同關係而共有之房地，各共有人得就其應有部分設定抵押權","稱最高限額抵押權者，謂債務人或第三人提供其不動產為擔保，就債權人對債務人一定範圍內之不特定債權，在最高限額內設定之抵押權"],"ok":[3],"ex":["用益物權：地上權、農育權、不動產役權、典權（§832以下）；「質權」屬「擔保物權」，並非用益物權，選項錯誤。","違章建築雖不能辦理保存登記及移轉登記，但出資興建人於建造完成時即「原始取得」其所有權（非依法律行為取得，不受§758 登記生效要件限制）；只有之後讓與他人時，因無法辦理移轉登記，受讓人僅取得「事實上處分權」（實務見解）。選項說建造人無法取得所有權，錯誤。","公同共有（如遺產）各人「無應有部分」，不得就應有部分設定抵押，選項錯誤（分別共有才有應有部分可設抵押）。","§881-1，最高限額抵押權係就「一定範圍內不特定債權」於最高限額內設定之抵押權，正確。"],"tr":""},{"id":"h:107-23","p":"h","src":"107年第23題","sec":"E2","stem":"甲與乙於民國 100 年結婚，雙方並未約定夫妻財產制，嗣於 105 年乙因外遇而雙方離婚。關於婚後財產，下列敘述何者正確？","opts":["甲於民國 103 年因其父親過世所獲得的遺產 300 萬元是婚後財產","乙於民國 102 年因車禍所獲 50 萬元慰撫金之非財產上損害賠償屬於婚後財產","甲於民國 100 年將婚前所投資之股票出售，獲利 30 萬元，屬於婚後財產","乙於民國 101 年所購入之房屋屬於婚後財產"],"ok":[3],"ex":["本題命題者所稱「婚後財產」，是指應列入剩餘財產分配者：繼承所得依§1030-1I①不列入分配，故判此選項錯誤。但嚴格依§1017I，婚姻關係存續中因繼承取得者仍屬婚後財產，只是不列入分配；此選項在條文上有爭議，作答依命題邏輯選D。","同A：慰撫金依§1030-1I②不列入剩餘財產分配，命題者據此判為錯誤；嚴格依§1017I它仍是婚姻存續中取得之婚後財產，只是排除分配。作答依命題邏輯選D。","婚前所持股票出售所得，是婚前財產之變形，並非婚前財產之孳息，仍為婚前財產（§1017I）。","房屋是乙於婚後（101年）購入，屬婚姻關係存續中有償取得之婚後財產（§1017I），且不屬§1030-1I排除項目，應列入剩餘財產分配。"],"tr":""},{"id":"h:107-24","p":"h","src":"107年第24題","sec":"D4","stem":"關於相鄰地必要通行權，下列敘述何者錯誤？","opts":["通行權人必須為土地所有人","土地因與公路無適宜聯絡即可，無須毫無聯絡方法","通行權人有必要時可以開設道路","通行權人對於通行地因此所受之損害，應支付償金"],"ok":[0],"ex":["§800-1：必要通行權之規定，於地上權人、典權人、農育權人、不動產役權人、承租人等土地使用人準用，非限於所有人。","§787 I：土地因與公路「無適宜之聯絡」致不能為通常使用即可，不須完全無通路。","§788 I：有通行權人於必要時，得開設道路。","§787 II：通行權人對通行地因此所受之損害，應支付償金。"],"tr":""},{"id":"h:107-25","p":"h","src":"107年第25題","sec":"E4","stem":"甲有子女乙丙二人，乙與丁結婚後育有一女戊，丙收養一女己；然乙卻因工時過長，過勞而亡。甲於乙死亡後兩年亦病逝。有關甲遺產之繼承，下列敘述何者正確？","opts":["戊、己得以代位繼承","丙、戊為甲的遺產繼承人","丙、戊、己為甲的遺產繼承人","丙、丁、戊、己均為甲的遺產繼承人"],"ok":[1],"ex":["己為丙之養女，因丙仍生存，己不得代位；代位繼承者僅戊（§1140）。","乙早於甲死亡，其直系血親卑親屬戊代位繼承；丙為第一順位繼承人（§1138①、§1140），故丙、戊為繼承人，正確。","己非繼承人，因被代位之人是乙，且丙仍生存。","丁為乙之配偶，非甲之繼承人，己亦非繼承人。"],"tr":""},{"id":"h:106-1","p":"h","src":"106年第1題","sec":"C1","stem":"下列有關不動產買賣之敘述，何者錯誤？","opts":["不動產仲介公司用與不特定之消費者簽定同類委託銷售不動產而先予擬定之契約，屬於定型化契約","不動產買賣除標的物及價金外，該房地之交付時間、所有權移轉登記時期、價金之給付方式等，通常亦為契約成立之必要之點","居間人已為報告或媒介而契約不成立者，居間人支出之費用均得請求償還","約定之違約金是否過高，可斟酌當事人所受損害情形，及債務人如能依約履行時債權人可享受之一切利益"],"ok":[2],"ex":["消保法§2 ⑦：企業經營者為與不特定消費者訂立同類契約所提出之契約條款，屬定型化契約，仲介公司先予擬定之委託契約屬之。","依§153 II 當事人對於必要之點意思一致，推定契約成立；實務上不動產買賣之交付時間、移轉登記時期、價金給付方式等常被認為必要之點。","§569 II：居間人所支出之費用，非經約定不得請求償還，契約不成立時亦同，並非『均得』請求。","§252：約定之違約金額過高者，法院得減至相當之數額；依實務見解，酌減時應斟酌債務人如能依約履行時債權人可享受之一切利益。"],"tr":""},{"id":"h:106-2","p":"h","src":"106年第2題","sec":"A3","stem":"下列有關從物之敘述，何者錯誤？","opts":["所有權狀為房地不動產之從物","屋頂平台為主物大樓建築之從物","土地共有人出賣房地全棟時，買賣契約效力及於另一共有人原所同意之同宗建築基地依法留設法定保留空地及退縮地之使用權等從權利在內","主物之處分及於從物，於主物與從權利之關係，亦可適用"],"ok":[1],"ex":["所有權狀是不動產管理文件，常助主物（不動產）之效用且各自獨立（土地/建物權狀屬從物），此為實務常見判決見解，正確。","屋頂平台屬建築物之「一部分」（成分），非獨立存在的「從物」；成分與從物的區別：成分是主物不可分的組成部分，從物是獨立存在但常助主物效用的物，本選項將成分誤稱為從物，錯誤，為應選答案。","買賣主物（建物）之效力及於從物及從權利（如基地保留空地使用權），符合§68「主物之處分，及於從物」，正確。","主物之處分及於從物，類推適用於主物與從權利之關係，正確。"],"tr":""},{"id":"h:106-3","p":"h","src":"106年第3題","sec":"C4","stem":"甲乙是大四同班同學，甲平常騎乘其父丙所贈與之電動機車作為交通工具。某日乙向甲借用該部電動機車，以接送其高中同學到學校所在地之風景名勝地區遊玩。下列有關甲乙間之契約關係的敘述何者錯誤？","opts":["甲乙間所訂立之契約為單務契約，乙之返還義務與甲之容忍使用義務間，無同時履行抗辯權之適用","甲乙間所訂立之契約為要物契約，以物之交付為契約成立之特別要件，必待借用物之交付，契約始得成立","甲乙間所訂立之契約為使用借貸契約，乙非經甲之同意，不得允許第三人使用該借用物，否則甲得終止契約","甲乙間所訂立之契約為使用借貸契約，甲對乙不以故意不告知借用物之瑕疵為限，承擔瑕疵擔保的責任，乙因此瑕疵所受之損害，得向甲請求賠償"],"ok":[3],"ex":["使用借貸為無償單務契約，借用人返還義務與貸與人容忍使用義務無對價關係，無§264 同時履行抗辯。","§464：使用借貸為要物契約，須交付借用物始成立。","§467 II：借用人非經貸與人同意不得允許第三人使用借用物，違反時貸與人得依§472 終止契約。","§466：貸與人僅就故意不告知借用物瑕疵致借用人受損害者負賠償責任，並非不以故意為限。"],"tr":""},{"id":"h:106-4","p":"h","src":"106年第4題","sec":"E4","stem":"關於繼承之效力，下列敘述何者錯誤？","opts":["繼承人對於被繼承人之債務，以因繼承所得遺產為限，負清償責任","繼承，因被繼承人死亡而開始","繼承人有數人時，在分割遺產前，各繼承人對於遺產全部為公同共有","繼承人從被繼承人生前所受贈之全部財產，視為其所得遺產"],"ok":[3],"ex":["§1148Ⅱ：繼承人對被繼承人之債務，以因繼承所得遺產為限負清償責任，此敘述正確，故非本題應選。","§1147：繼承因被繼承人死亡而開始，此敘述正確，故非本題應選。","§1151：繼承人有數人時，在分割遺產前，各繼承人對遺產全部為公同共有，此敘述正確，故非本題應選。","§1148-1Ⅰ：繼承人在繼承開始前「二年內」從被繼承人受有財產之贈與者，該財產視為其所得遺產；選項稱「生前所受贈之全部財產」超出二年範圍，錯誤，為應選答案。"],"tr":""},{"id":"h:106-5","p":"h","src":"106年第5題","sec":"A5","stem":"關於意思表示錯誤，下列敘述何者正確？","opts":["當事人資格之錯誤，可能得撤銷之","表意人得向相對人請求損害賠償","動機錯誤，均為意思表示內容之錯誤","表示行為錯誤，不得撤銷"],"ok":[0],"ex":["§88Ⅱ：當事人之資格或物之性質，若交易上認為重要者，其錯誤視為意思表示內容之錯誤；再依§88Ⅰ，只要錯誤非由表意人自己過失所致，即得撤銷。故當事人資格錯誤「可能」得撤銷，正確。","撤銷人（表意人）因錯誤撤銷意思表示，依§91，對於「信其意思表示有效而受損害之相對人」，應負損害賠償責任；是撤銷人對相對人負責，而非「表意人得向相對人請求」，方向相反。","動機錯誤原則上不得撤銷（動機不屬於意思表示內容），僅當事人資格或物之性質之錯誤且依交易上觀念認為重要者，始例外得撤銷，並非「動機錯誤均為意思表示內容之錯誤」。","表示行為錯誤（口誤、筆誤），依通說屬§88Ⅰ後段「表意人若知其事情即不為意思表示」，表意人得撤銷，但以錯誤非由表意人自己之過失為限；並非「不得撤銷」，故本選項錯誤。"],"tr":""},{"id":"h:106-6","p":"h","src":"106年第6題","sec":"A5","stem":"甲有 A 地，且登記為 A 地所有人。甲因乙之脅迫，出賣且交付 A 地於乙，於甲尚未撤銷買賣契約前。試問，下列敘述何者正確？","opts":["甲得撤銷交付 A 地於乙之行為","現占有 A 地之乙為有權占有人","乙因此成為 A 地所有人","甲乙間之 A 地的買賣契約，無效"],"ok":[1],"ex":["§92Ⅰ可撤銷的對象是因脅迫所為的「意思表示」（買賣契約、移轉所有權的合意）；「交付」A地只是移轉占有的事實行為，本身不是意思表示，無從撤銷「交付行為」。不動產物權變動另須登記（§758Ⅰ），甲要回復，是撤銷買賣及物權移轉之意思表示後，依法請求返還。","買賣契約在撤銷前有效，乙取得A地有法律上原因（有效的買賣契約），故乙為「有權占有人」，正確。","不動產所有權移轉須「登記」才生效力（§758Ⅰ）。題目明載A地仍「登記為甲所有」，甲只是出賣且交付，尚未移轉登記，乙只取得占有，並未成為所有人。（買賣契約在撤銷前有效，是乙「有權占有」的依據，見B，但不等於乙已取得所有權。）","脅迫所為之意思表示效果為「得撤銷」（§92），而非當然無效，在撤銷前契約仍有效。"],"tr":""},{"id":"h:106-7","p":"h","src":"106年第7題","sec":"A7","stem":"關於消滅時效，下列敘述何者正確？","opts":["消滅時效之規定，已登記不動產之回復請求權，亦有適用","一般消滅時效期間，乃 20 年","請求權因其消滅時效完成而消滅","以租賃動產為營業者之租價請求權，其消滅時效期間為 2 年"],"ok":[3],"ex":["依司法院釋字第107號、第164號，已登記不動產所有人之回復請求權、除去妨害請求權，無§125（請求權15年不行使而消滅）消滅時效之適用；故「亦有適用」錯誤。","§125：請求權因15年間不行使而消滅（但法律所定期間較短者依其規定），一般消滅時效期間是15年，不是20年。","§144Ⅰ：時效完成後，債務人「得拒絕給付」，即取得抗辯權，請求權本身並未消滅；債務人若仍自願給付，依§144Ⅱ不得以不知時效為由請求返還。故「請求權因時效完成而消滅」錯誤。","§127第3款：以租賃動產為營業者之租價，其請求權因2年間不行使而消滅，正確（§127為2年短期時效，如旅店飲食費、運送費、租賃動產租價、醫藥費、律師會計師報酬等）。"],"tr":""},{"id":"h:106-8","p":"h","src":"106年第8題","sec":"C1","stem":"依民法規定，關於不動產買賣，下列敘述何者正確？","opts":["應作成公證書","非經登記，不生效力","非經交付買賣之不動產，不生效力","因當事人就標的物及其價金互相同意而成立"],"ok":[3],"ex":["一般不動產買賣契約（債權行為）不須公證，選項錯誤。","「非經登記不生效力」適用於不動產「物權」變動（§758），而非「買賣契約」（債權行為）本身；買賣契約不以登記為生效要件，選項混淆債權行為與物權行為。","買賣契約為諾成契約，不以交付為成立或生效要件，選項錯誤。","依§345Ⅱ，買賣契約於當事人就標的物及價金互相同意時成立（諾成契約），正確。"],"tr":""},{"id":"h:106-9","p":"h","src":"106年第9題","sec":"C4","stem":"甲有 A 屋，登記為 A 屋所有人。甲將 A 屋贈與乙女。試問，下列敘述何者正確？","opts":["非經交付 A 屋，該贈與不生效力","該贈與應以書面為之","甲移轉 A 屋所有權予乙前，得撤銷該贈與","甲遲延交付 A 屋予乙時，乙得請求遲延損害賠償"],"ok":[2],"ex":["依§406，贈與是當事人約定一方無償給與財產、他方允受之契約，意思表示合致即成立生效（諾成契約），不以交付為生效要件，選項錯誤。","§406 只要求雙方約定「無償給與」並「允受」，並未規定贈與須以書面為之；書面與否也不是§408 撤銷權的判準（現行例外只有公證或履行道德義務），選項錯誤。","依§408Ⅰ，贈與物之權利未移轉前，贈與人得撤銷其贈與；本題A屋所有權尚未移轉給乙，甲得撤銷，正確。（例外：依§408Ⅱ，經公證之贈與或為履行道德上義務而為之贈與，不得撤銷。）","依§409Ⅱ，贈與人給付遲延時，受贈人只能請求交付贈與物，「不得請求遲延利息或其他不履行之損害賠償」（贈與是無償契約，責任從輕；§410 另規定贈與人僅就故意或重大過失負給付不能之責），所以乙不能請求遲延損害賠償，選項錯誤。"],"tr":""},{"id":"h:106-10","p":"h","src":"106年第10題","sec":"C3","stem":"依民法規定，關於受任人之權利及義務，下列敘述何者正確？","opts":["受任人受有報酬者，應以善良管理人之注意，處理委任事務","受任人未處理委任事務前，不得向委任人請求預付處理委任事務之必要費用","受任人必有代理權","受任人不得隨時終止委任契約"],"ok":[0],"ex":["§535：受任人受有報酬者，應以善良管理人之注意處理委任事務；無報酬者僅負與處理自己事務同一之注意。","§545：受任人因處理委任事務，得請求委任人預付必要費用，不必等到處理後才請求。","§167：代理權授與是另一個行為，委任契約本身不當然伴隨代理權，委任人可只委託事實行為而不授與代理權。","§549 I：當事人任何一方得隨時終止委任契約，受任人也不例外（但於不利委任人之時期終止須賠償，§549 II）。"],"tr":""},{"id":"h:106-11","p":"h","src":"106年第11題","sec":"A5","stem":"甲有 A 屋，共 95 坪，登記為 A 屋所有人。乙詢問甲 A 屋坪數，甲告知 A 屋計有 100 坪。甲與乙締結 100 坪之 A 屋買賣契約。試問，下列敘述何者錯誤？","opts":["甲侵害乙之 A 屋所有權","乙得解除契約","乙得請求減少價金","乙得以甲詐欺為由，撤銷締結該買賣契約之意思表示"],"ok":[0],"ex":["甲是A屋「所有人」，其出售行為並非侵害乙的所有權（乙尚未取得所有權），此題情境甲說謊坪數是詐欺或物之瑕疵問題，並非侵權行為，「侵害乙之A屋所有權」描述根本不成立，為錯誤選項，即應選答案。","A屋坪數短少，屬物之瑕疵，乙得解除契約（§359），正確。","乙得請求減少價金以彌補坪數短少之損失（§359），正確。","甲故意告知錯誤坪數，屬詐欺（§92），乙得撤銷其意思表示，正確。"],"tr":""},{"id":"h:106-12","p":"h","src":"106年第12題","sec":"B6","stem":"甲有 A 地，登記為 A 地所有人。甲與乙成立承攬契約，由乙承攬 A 地之整地工作。乙不僅整地有瑕疵，而且還趁整地之餘，將有毒廢棄物掩埋於 A 地之下。試問，下列敘述何者錯誤？","opts":["甲得請求乙修補瑕疵","甲依侵權行為法之規定（民法第 184 條第 1 項前半段），得請求乙回復原狀，移除掩埋在 A 地下之有毒廢棄物","甲得以掩埋有毒廢棄物乃違反保護義務為由，解除契約","甲得依民法第 495 條第 1 項規定，請求乙賠償 A 地因掩埋有毒廢棄物所減損之價額"],"ok":[3],"ex":["§493 I：承攬人完成之工作有瑕疵，定作人得定相當期限請求修補。","掩埋毒物侵害甲之 A 地所有權，成立§184 I 前段侵權行為，依§213 I 得請求回復原狀（移除廢棄物）。","乙違反保護甲財產之附隨義務，屬可歸責於債務人之不完全給付（加害給付），依§227 I 債權人得依給付遲延或給付不能之規定行使權利，進而依§254（定期催告後）或§256 解除契約；瑕疵以外之損害並得依§227 II 請求賠償。","§495 I 賠償的是「瑕疵本身」（整地瑕疵）所生損害；掩埋毒物致 A 地減損屬瑕疵以外的加害損害，應依§227 II 或侵權行為請求，非§495 I。"],"tr":""},{"id":"h:106-13","p":"h","src":"106年第13題","sec":"E4","stem":"關於遺囑，下列敘述何者正確？","opts":["遺囑乃非要式行為","無行為能力人，僅得為公證遺囑","代筆遺囑，應由遺囑人指定二人以上之見證人","繼承人及其配偶或其直系血親，不得為遺囑見證人"],"ok":[3],"ex":["遺囑為要式行為，須依法定方式（§1189）。","無行為能力人不得為遺囑（§1186I），並非得為公證遺囑。","代筆遺囑應由遺囑人指定三人以上之見證人（§1194），非二人。","繼承人及其配偶或直系血親不得為遺囑見證人（§1198），正確。"],"tr":""},{"id":"h:106-14","p":"h","src":"106年第14題","sec":"B3","stem":"甲對乙負有 1,000 萬元借款債務，丙為甲對乙所負該債務之連帶保證人。試問，下列敘述何者正確？","opts":["乙得直接請求丙履行 1,000 萬元保證債務","乙僅得同時請求甲與丙履行債務","丙連帶責任之約定無效","丙負最終責任"],"ok":[0],"ex":["連帶保證人與主債務人負連帶責任（§272、§273），且不得主張先訴抗辯（§745、§746①），債權人得直接請求丙履行全部保證債務。","§273 I：債權人得對連帶債務人之一人或數人或全體，同時或先後請求全部或一部給付，並非只能同時請求。","連帶責任可由當事人明示約定而成立（§272 I：數人負同一債務，「明示」對於債權人各負全部給付之責任者，為連帶債務），該約定有效；§272 II 是指無明示時，須法律有規定才成立連帶。","主債務人甲才是終局責任人；丙清償後依§749 取得債權人對甲之權利，可向甲求償。"],"tr":""},{"id":"h:106-15","p":"h","src":"106年第15題","sec":"C4","stem":"關於合會，下列敘述何者正確？","opts":["法人亦得為合會會員","會首得兼為同一合會之會員","限制行為能力人亦得為會員","自然人不得同時為數合會之會首"],"ok":[2],"ex":["§709-2 I：會首及會員限於自然人，法人不得為合會會員。","§709-2 II：會首不得兼為同一合會之會員。","§709-2 III：無行為能力人及限制行為能力人不得為會首，亦不得參加其法定代理人為會首之合會；條文未禁止其為一般會員，故限制行為能力人可為會員。","民法未禁止自然人同時擔任數個合會之會首，此敘述為民法所無之限制。"],"tr":""},{"id":"h:106-16","p":"h","src":"106年第16題","sec":"D2","stem":"關於物權法定主義，下列敘述何者正確？","opts":["僅得依制定法創設物權","僅得依特別法創設物權","得依習慣法創設物權","得依法理創設物權"],"ok":[2],"ex":["物權不限於依「法律」創設，習慣亦得創設（§757）。","物權之創設不限特別法，亦非僅依特別法。","物權除依法律或習慣外，不得創設（§757）；故得依習慣創設物權。","法理非§757所定物權創設之依據。"],"tr":""},{"id":"h:106-17","p":"h","src":"106年第17題","sec":"D2","stem":"關於區分所有建築物，下列敘述何者正確？","opts":["全體專有部分所有人公同共有區分所有建築物之基地","專有部分可共有或單獨所有","全體專有部分所有人公同共有區分所有建築物之公同部分","頂樓之專有部分所有人得占有區分所有建築物之屋頂，並為使用收益"],"ok":[1],"ex":["§799Ⅳ：區分所有人就共有部分及基地之「應有部分」依專有部分面積比例定之，既有應有部分比例即為「分別共有」，非公同共有（公同共有無應有部分）；§799Ⅴ另規定專有部分與其基地權利不得分離而移轉。","§799Ⅰ、Ⅱ：專有部分在構造上及使用上可獨立、且得單獨為所有權之標的，區分所有人就專有部分有單獨所有權；既為所有權之客體，可由一人單獨所有，亦可依§817由數人按應有部分共有，故敘述正確。","§799Ⅰ、Ⅱ、Ⅳ：共有部分指專有部分以外之其他部分及不屬於專有部分之附屬物，由區分所有人「共有」並依面積比例定應有部分，屬分別共有而非公同共有，選項說「公同共有」錯誤。","§799Ⅱ、Ⅲ：屋頂若非專有部分，即屬共有部分，須「經規約之約定」才得供特定所有人使用（法律另有規定者除外）；頂樓所有人不能當然占有並使用收益屋頂，選項過於絕對，錯誤。"],"tr":""},{"id":"h:106-18","p":"h","src":"106年第18題","sec":"E1","stem":"關於婚約下列敘述何者正確？","opts":["婚約，得由未成年人之法定代理人代理為之","未成年人訂定婚約，無須經法定代理人之同意","婚約，得請求強迫履行","因訂定婚約而為贈與者，婚約解除時，當事人之一方，得請求他方返還贈與物"],"ok":[3],"ex":["婚約應由男女當事人自行訂定（§972），不得代理。","未成年人訂定婚約，應得法定代理人同意（§974），非無須同意。","婚約不得請求強迫履行（§975）。","因訂定婚約而為贈與者，婚約無效、解除或撤銷時，得請求返還贈與物（§979-1），正確。"],"tr":""},{"id":"h:106-19","p":"h","src":"106年第19題","sec":"E1","stem":"關於結婚，下列敘述何者正確？","opts":["男未滿 17 歲，女未滿 15 歲者，不得結婚","結婚應以公開儀式為之","直系血親及直系姻親在 6 親等以內者，不得結婚","當事人之一方，於結婚時不能人道而不能治者，他方得向法院請求撤銷之"],"ok":[3],"ex":["17歲、15歲不符規定（現行§980為男女均須年滿18歲，舊制為男18、女16），敘述錯誤。","現行§982結婚以書面、二人以上證人簽名及登記為要件，不再以公開儀式為要件。","直系血親及直系姻親不論親等一律不得結婚（§983I①），並非限於六親等以內。","一方於結婚時不能人道而不能治者，他方得向法院請求撤銷（§995），正確。"],"tr":""},{"id":"h:106-20","p":"h","src":"106年第20題","sec":"D2","stem":"甲、乙與丙 3 人共有 A 車，應有部分各 3 分之 1，約定 A 車由丙占有、使用及收益（分管契約）。占有 A 車之丙未經甲與乙同意，出賣 A 車於丁。試問，下列敘述何者正確？","opts":["丁若不知丙非單獨所有人，且就其不知無過失，則善意取得 A 車所有權","丁若明知甲、乙與丙間之 A 車分管契約，則得占有使用收益 A 車","甲與乙若未同意，丙與丁間之 A 車的買賣，效力未定","丁對甲與乙乃有權占有"],"ok":[3],"ex":["題幹只說丙將A車「出賣」於丁，未說已交付。動產善意取得（§801、§948 I）以受讓人「受讓該動產之占有」為要件，單有買賣契約（債權行為）不生所有權移轉，故A「則善意取得A車所有權」的結論欠缺交付要件，錯誤。提醒：若題目明示已交付，丁不知丙非單獨所有人且無重大過失，依§948 I 本可善意取得；而D「有權占有」又以丁已占有A車為前提，兩選項對「是否已交付」的預設有張力，屬出題瑕疵。本題官方答案為D，不改。","§826-1 II 規範的是動產共有人間之分管約定，對「應有部分之受讓人或取得物權之人」於受讓時知悉或可得而知者「具有效力」——效果是讓受讓人「受分管約定拘束」，不是授與受讓人占有使用收益之權。丁向丙買的是整台A車，丁能否對甲、乙占有，取決於丙依分管契約對A車的占有權源（見D），與丁是否「明知」分管契約無關。B把「知悉分管契約」當成取得使用收益權的原因，錯誤。","買賣契約屬債權行為，出賣他人（或他共有人）之物，契約仍有效（§348 I，出賣人負移轉義務）；效力未定（§118）僅限處分行為。","丙依分管契約對A車有占有、使用、收益之權，對甲、乙為有權占有。實務見解認為：共有人將其依分管契約占有之共有物交由第三人占有使用（本題丙出賣並將A車交丁），第三人係本於該共有人之占有權源而占有，對他共有人非無權占有。§826-1 是規範分管約定對「應有部分受讓人」的拘束力，丁並非應有部分受讓人，不是本選項的依據。"],"tr":""},{"id":"h:106-21","p":"h","src":"106年第21題","sec":"D5","stem":"關於地上權，下列敘述何者正確？","opts":["以公共建設為目的而成立之地上權，不得定有期限","經設定地上權之土地，不得再設定抵押權","同一土地上，得設定數則內容相同之地上權","地上權亦得為時效取得之客體"],"ok":[3],"ex":["§833-1以「地上權未定有期限」為前提，可知地上權得定期、亦得不定期；本選項是扭曲§833-2：該條正是處理「以公共建設為目的而成立之地上權，『未定有期限』」時如何定其存續期限的規定，可見此類地上權可定期限、也可不定期限，並非「不得定有期限」，錯誤（§833-2 不在條文庫，字句請以法規資料庫為準）。（§841-1為區分地上權＝在他人土地上下之一定空間範圍設定之地上權，與期限無關。）","§860抵押權以不動產（土地）為標的，土地設有地上權後所有人仍可再設定抵押權；§866Ⅰ亦肯定同一不動產上抵押權與地上權得並存（先抵押後設地上權，抵押權不受影響），選項說「不得再設定抵押權」錯誤。","地上權為排他的用益物權，同一土地同一空間範圍不能同時存在內容相同、互相衝突的數個地上權；僅不同空間範圍（如區分地上權，§841-1）才可能並存，選項錯誤。","§772：取得時效之規定（§769、§770）於所有權以外財產權之取得「準用」之，於已登記之不動產亦同；故地上權得為時效取得之客體（須以行使地上權之意思占有，並請求登記），正確。"],"tr":""},{"id":"h:106-22","p":"h","src":"106年第22題","sec":"D2","stem":"關於公同共有，下列敘述何者正確？","opts":["公同關係存續中，各公同共有人，不得請求分割其公同共有物","各公同共有人，得自由處分其應有部分","公同關係，不以法律規定或習慣者為限","各公同共有人之權利，僅及於公同共有物之應有部分"],"ok":[0],"ex":["§829：公同關係存續中，各公同共有人不得請求分割公同共有物（須公同關係消滅後才可分割），正確。","§827Ⅲ：公同共有人之權利及於公同共有物之全部，並無「應有部分」可言；公同共有物之處分須經全體同意（§828Ⅲ），故不得自由處分應有部分，選項錯誤。","§827Ⅱ：依法律行為成立之公同關係，以有法律規定或習慣者為限（如合夥§668、繼承§1151）；選項稱「不以法律規定或習慣為限」與條文相反，錯誤。","§827Ⅲ：各公同共有人之權利，及於公同共有物之「全部」，而非僅及於應有部分，選項錯誤。"],"tr":""},{"id":"h:106-23","p":"h","src":"106年第23題","sec":"D6","stem":"關於最高限額抵押權，下列敘述何者正確？","opts":["當事人得約定其所擔保原債權之應確定之期日","最高限額抵押權所擔保之債權，不以由一定法律關係所生之權利為限","最高限額抵押權所擔保之債權，不得將其分離而為讓與","同一不動產上，僅得設定一項最高限額抵押權"],"ok":[0],"ex":["§881-4Ⅰ：最高限額抵押權得約定其所擔保原債權應確定之期日，並得於期日前約定變更（期日自設定時起不得逾三十年，§881-4Ⅱ），正確。","§881-1Ⅱ：最高限額抵押權所擔保之債權，以由一定法律關係所生之債權或基於票據所生之權利為限；選項說「不以…為限」與條文相反，錯誤。","§881-6Ⅰ：所擔保之債權於原債權確定前讓與他人者，最高限額抵押權不隨同移轉，可見債權可與抵押權分離而讓與（普通抵押權的§870不得分離，於最高限額抵押權不準用，§881-17），選項說「不得分離而為讓與」錯誤。","§865：同一不動產設定數抵押權，其次序依登記先後定之；最高限額抵押權依§881-17準用普通抵押權規定（§865不在排除之列），故同一不動產可設定多項，選項錯誤。"],"tr":""},{"id":"h:106-24","p":"h","src":"106年第24題","sec":"D6","stem":"關於占有之推定，下列敘述何者正確？","opts":["占有已登記之不動產而行使物權者，推定有該物權","行使所有權以外之權利者，對使其占有之人，推定有該權利","占有人推定其為他主占有","占有人推定其為無過失占有"],"ok":[3],"ex":["§943 II：占有已登記之不動產而行使物權者，不適用占有權利推定，須以登記為準。","§943 II：行使所有權以外之權利者，對使其占有之人，不適用權利推定（例如承租人對出租人不能推定有租賃權）。","§944 I：占有人推定其為以所有之意思占有，而非他主占有。","§944 I：占有人推定其為以所有之意思，善意、和平、公然及無過失占有。"],"tr":""},{"id":"h:106-25","p":"h","src":"106年第25題","sec":"A4","stem":"依民法規定，關於一定之數量有文字與號碼不符合之情形時，下列敘述何者錯誤？","opts":["若能探求出當事人原意，應以原意為準","若不能探求出當事人原意，而契約文書上對於同一數量同時以文字及號碼表示有不相符合之情形，應以文字為準","若不能探求出當事人原意，契約文書上對於同一數量同時以文字及號碼為數次表示時，應以文字最低額為準","若不能探求出當事人原意，契約文書上對於同一數量同時以文字及號碼為數次表示時，依實務見解，應以數字最低額為準"],"ok":[3],"ex":["依§98，解釋意思表示，應探求當事人真意，應以原意為準，正確。","依§4，文字與號碼不符、法院不能決定當事人原意時，應以文字為準（因文字較不易誤記），正確。","§5：以文字或號碼為數次之表示而有不符，法院不能決定何者為當事人原意時，以最低額為準（保護義務人）；再結合§4文字優先於號碼的原則，故以「文字」所表示之最低額為準，敘述正確。","§4：文字與號碼不符、不能決定原意時以文字為準；§5：數次表示不符時以最低額為準。兩者合併，應以「文字」最低額為準，而非「數字」最低額，故D錯誤，為應選答案。"],"tr":""},{"id":"h:106-26","p":"h","src":"106年第26題","sec":"A4","stem":"依民法之規定，法定要式行為有使用文字之必要時，下述情形何者錯誤？","opts":["不動產物權之移轉或設定，當事人得以蓋章代替簽名","兩願離婚之協議書，夫妻雙方得以蓋章代替簽名","在代筆遺囑之情形，遺囑人得以蓋章代替簽名","應以書面方式訂立之人事保證契約，雙方得以蓋章代替簽名"],"ok":[2],"ex":["§3Ⅱ，如有用印章代簽名者，其蓋章與簽名生同等之效力，不動產物權移轉書面亦適用此原則，正確。","離婚協議書以蓋章代替簽名，符合§3Ⅱ，正確。","§1194：代筆遺囑由見證人全體及遺囑人同行簽名，遺囑人不能簽名者「應按指印代之」，條文只允許簽名或按指印，並未規定得以蓋章代替（與§3Ⅱ一般性的蓋章代簽名不同，遺囑屬嚴格要式行為），故C錯誤，為應選答案。","人事保證契約§756-1須以書面為之，書面得以蓋章代替簽名，正確。"],"tr":""},{"id":"h:106-27","p":"h","src":"106年第27題","sec":"A4","stem":"關於撤銷權之性質，下列敘述何者錯誤？","opts":["撤銷權屬於形成權之一種，得因撤銷權人單方之意思表示到達相對人時，即生法律關係生效、變更或消滅之效力","撤銷權之行使期間，不受到消滅時效規定之限制","撤銷權行使後，其撤銷之客體視為自始無效","撤銷權須法律明文規定始得發生，當事人間不得以契約約定，由一方當事人因特定事由之發生而取得撤銷權"],"ok":[3],"ex":["形成權之行使，以意思表示到達相對人即生效力，撤銷權亦然（§116），正確。","形成權之行使期間為「除斥期間」，不適用消滅時效（除斥期間不得中斷或不完成），正確。","撤銷之效果，民法§114Ⅰ規定，法律行為被撤銷者，視為自始無效（溯及效力），正確。","撤銷權並非僅能由法律明文規定而生，當事人亦得「以契約約定」特定撤銷權（例如約定某事由發生時一方得撤銷其意思表示；注意這是「約定撤銷權」，與「約定解除權」是不同的形成權，勿混用），此為私法自治原則之體現，本選項限縮為「須法律明文」且否定契約約定，描述過於絕對，為錯誤選項，即應選答案。"],"tr":""},{"id":"h:106-28","p":"h","src":"106年第28題","sec":"D6","stem":"依民法規定，無權占有人返還占有物於回復請求人時，其得向回復請求人主張之權利及應負擔之義務，下列敘述何者正確？","opts":["善意占有人對於占有物支出之必要費用，於扣除其所收取孳息之餘額，皆得請求償還","善意占有人對於占有物因改良占有物支出之有益費用，於扣除其所收取孳息之餘額，皆得請求償還","惡意占有人對於占有物孳息之收取，推定其適法有此權利，無須返還","惡意占有人，就占有物之滅失或毀損，縱使非因可歸責於自己之事由所致者，負損害賠償之責任"],"ok":[0],"ex":["§954：善意占有人因保存占有物所支出之必要費用，得向回復請求人請求償還；已就占有物取得孳息者，僅不得請求償還「通常」必要費用。注意：A 所寫「扣除所收取孳息之餘額皆得請求」不是§954 的逐字規則——條文是取得孳息者喪失「通常必要費用」請求權，非通常（通說稱特別）必要費用仍可全額請求，並非拿孳息抵扣；本題B、C、D 均與條文明確相反，A 是唯一大方向正確的選項。","§955：善意占有人因改良占有物所支出之有益費用，僅得於占有物現存之增加價值限度內請求償還，並非「皆得」請求。","§958：惡意占有人負返還孳息之義務，其已消費者並負償還價金之義務，不得主張有收取權。","§956：惡意占有人就占有物之滅失毀損，以因可歸責於自己之事由所致者，才負損害賠償責任，非因可歸責則不負責。"],"tr":""},{"id":"h:106-29","p":"h","src":"106年第29題","sec":"D5","stem":"依民法之規定，稱典權者，謂支付典價在他人之不動產為使用、收益，於他人不回贖時，取得該不動產所有權之權。下列關於典權之敘述，何者錯誤？","opts":["典權人對於典物因轉典所受之損害，負賠償責任","典權之約定期限超過 15 年時，當事人間得附有到期不贖即作絕賣之條款","典權人為典物支出有益費用，使典物增加價值，不論該增益之價值是否仍然存在，得請求出典人償還","未定期限之典權，出典人得隨時以原典價回贖典物。但自出典後經過 30 年不回贖者，典權人即取得典物所有權"],"ok":[2],"ex":["§916：典權人對於典物因轉典或出租所受之損害，負賠償責任。","§913 I：典權約定期限不滿15年者，不得附有到期不贖即作絕賣之條款；超過15年者可以約定。","§927 I：典權人支出有益費用使典物價值增加，出典人回贖時僅以「現存之增價額」為限償還，增益價值已不存在則不得請求。","§924：未定期限之典權，出典人得隨時以原典價回贖；但出典後經過30年不回贖者，典權人取得典物所有權。"],"tr":""},{"id":"h:106-30","p":"h","src":"106年第30題","sec":"B6","stem":"19 歲之甲經父母同意受僱於乙公司。某日甲受乙公司之吩咐，將貨物送到客戶手中。途中行經十字路口，甲闖紅燈致丙在綠燈穿越時受傷，經該地區行車事故鑑定委員會認定，認定甲應負全部之肇事責任。就此情形，下列敘述何者錯誤？","opts":["甲是未成年人，對於丙之損害，無須負賠償責任","丙得主張乙與甲負連帶損害賠償責任","丙得主張甲及其父母負連帶損害賠償責任","乙賠償丙之損害後，得向甲求償"],"ok":[0],"ex":["甲雖未成年，仍須就自己的侵權行為負責，有識別能力時與法定代理人連帶負責（§184、§187 I），並非無須賠償。【新舊法】依出題年（106年）舊法19歲未成年；依現行§12甲已成年，「甲是未成年人」前提亦不成立，A在新舊法下都是錯的。","§188 I：受僱人因執行職務不法侵害他人，僱用人與行為人連帶負賠償責任。","§187 I：依出題年（106年）舊法20歲成年，19歲甲未成年、有識別能力，與法定代理人（父母）連帶負責，丙得主張，C正確。【新舊法】依現行§12甲已成年，無法定代理人，丙不得依§187向父母求償，C在現行法下變成錯誤敘述。","§188 III：僱用人賠償後，對為侵權行為之受僱人有求償權。"],"tr":""},{"id":"h:106-31","p":"h","src":"106年第31題","sec":"B2","stem":"就賣方甲與買方乙間訂立之買賣契約，下列敘述何者錯誤？","opts":["該買賣標的物因可歸責於甲之事由而滅失，致給付不能者，乙得解除契約並請求損害賠償","該買賣標的物因不可歸責甲乙之事由而滅失，致給付不能者，甲得免除該物之給付義務","該買賣標的物因不可歸責甲乙之事由而滅失，致給付不能者，乙得免除價金支付之義務","該買賣標的物因可歸責乙之事由而滅失，致給付不能者，甲不得向乙請求價金之支付"],"ok":[3],"ex":["標的物因可歸責於出賣人甲而滅失，屬§226Ⅰ可歸責於債務人之給付不能，乙得請求賠償損害；依§256，債權人於有§226 情形時並得解除契約（法條未要求先催告），此敘述正確，不是答案。","因不可歸責於雙方之事由致給付不能，依§225Ⅰ債務人（甲）免給付義務，此敘述正確，不是答案。","因不可歸責於雙方之事由致一方給付全部不能，依§266Ⅰ他方（乙）免為對待給付義務（即免付價金），此敘述正確，不是答案。","標的物因可歸責於買受人乙之事由而滅失，依§267 甲（給付不能之一方）仍得請求對待給付（價金），但應扣除其因免給付義務所得之利益；選項說「甲不得向乙請求價金」與§267 相反，敘述錯誤，故為應選答案。"],"tr":""},{"id":"h:106-32","p":"h","src":"106年第32題","sec":"E1","stem":"下列有關夫妻離婚後所生身分及財產上效力之說明，何者正確？","opts":["夫妻離婚後，其子女對未享有親權之父母一方，喪失原本享有之法定繼承權","夫妻離婚後，未享有親權之父母一方與其子女間，互相不負扶養之義務","兩願離婚之場合，關於子女之親權，由夫任之","夫妻無過失之一方，因判決離婚而限於生活困難者，他方縱無過失，亦應給予贍養費"],"ok":[3],"ex":["離婚不影響親子血親關係，子女對任何一方仍有法定繼承權。","直系血親互負扶養義務（§1114①），離婚後未親權一方仍負扶養義務。","兩願離婚者，子女權利義務依協議由一方或雙方共同任之（§1055I），非當然由夫任之。","判決離婚時，無過失之一方陷於生活困難者，他方縱無過失亦應給與相當贍養費（§1057），正確。"],"tr":""},{"id":"h:106-33","p":"h","src":"106年第33題","sec":"E4","stem":"下列有關遺產分割之敘述，何者錯誤？","opts":["繼承人請求分割遺產之不動產，性質上為處分行為，依民法第 759 條規定，於未辦妥繼承登記前，不得為之","被繼承人之遺囑，定有分割遺產之方法，或託他人代定者，從其所定","繼承人對被繼承人已屆清償期之債務，自遺產分割時起，15 年內仍負連帶責任","繼承人之一所分得之土地持分短少，得向其他繼承人請求賠償短少分配之同額價金"],"ok":[2],"ex":["遺產分割為處分行為，繼承人就不動產未辦繼承登記前不得處分（§759），敘述正確。","被繼承人遺囑定有分割方法或託他人代定者，從其所定（§1165I），正確。","繼承人之連帶責任，自遺產分割時起，如債權清償期在分割後，自清償期屆滿時起，經過5年而免除（§1171II），不是15年。","各繼承人對他繼承人因分割所得之遺產負與出賣人同一之擔保責任（§1168），短少時可請求賠償，敘述正確。"],"tr":""},{"id":"h:106-34","p":"h","src":"106年第34題","sec":"E4","stem":"下列有關繼承之敘述，何者錯誤？","opts":["奠儀於繼承發生時並不存在，非屬被繼承人所遺財產","繼承人對於被繼承人之債務，以因繼承所得遺產為限，負清償責任","債權人得單獨向法院聲請命繼承人於 3 個月內提出遺產清冊","繼承人對於遺產全部為公同共有關係，無應有部分，故若逾越應繼分比例享有（行使）權利，毋須負返還義務"],"ok":[3],"ex":["奠儀繼承開始時不存在，不屬被繼承人所遺財產，正確。","繼承人對被繼承人債務，以因繼承所得遺產為限負清償責任（§1148II），正確。","債權人得向法院聲請命繼承人於3個月內提出遺產清冊（§1156-1），正確。","遺產為公同共有（§1151），分割前不得單獨處分，逾越應繼分取得時，依不當得利仍須返還（§179），敘述「毋須負返還義務」錯誤。"],"tr":""},{"id":"h:106-35","p":"h","src":"106年第35題","sec":"A5","stem":"下列有關意思表示之敘述，何者錯誤？","opts":["因錯誤或被詐欺而締結契約者，在表意人依法撤銷其意思表示之前，契約效力未定","當事人之意思表示未合致者，其契約自始未成立","買賣為諾成契約，除當事人另有約定外，縱然未訂立書面，亦不影響契約之成立","非定期行為之契約，當事人一方遲延給付者，他方當事人得定相當期限催告其履行，如債務人仍不履行時，債權人仍須另為解約之意思表示"],"ok":[0],"ex":["因錯誤或被詐欺所訂契約，撤銷前為有效（得撤銷，§88、§92），並非效力未定。","§153Ⅰ 意思表示須一致才成立契約，不一致即不成立（§153Ⅱ則是：必要之點一致、非必要之點未表示者，推定契約成立）。","§345 買賣為諾成契約，意思表示一致即成立，無須書面。","§254、§258 非定期行為須催告後再為解除之意思表示，並非當然解除。"],"tr":""},{"id":"h:106-36","p":"h","src":"106年第36題","sec":"C2","stem":"下列有關租賃契約之敘述，何者錯誤？","opts":["租賃關係存續中，出租人未使租賃物合於約定使用收益狀態，致承租人未達租賃目的者，承租人得拒絕給付租金","出租人將已交付承租人之租賃物的所有權讓與他人，承租人與受讓人間仍須另立租賃契約始發生租賃關係","定有期限之租賃契約，當事人約定得提前終止者，於終止契約前應先期通知","租賃契約經公證並附有逕受強制執行條款者，當承租人有不付租金、租期屆滿拒不搬遷，或房東不返還押租金時，當事人可直接申請強制執行"],"ok":[1],"ex":["§423：出租人應保持租賃物合於約定使用收益之狀態；出租人未履行致承租人未達租賃目的，承租人得拒絕給付租金（同時履行抗辯，§264）。","§425 I：出租人於租賃物交付後將所有權讓與第三人者，租賃契約對受讓人仍繼續存在（買賣不破租賃），無須另訂契約。","§453：定有期限之租賃，約定得提前終止者，終止契約應依§450 III 先期通知。","公證書載明逕受強制執行者，得為執行名義（公證法§13、強制執行法§4 I④）；不付租金、拒不遷讓、不返還押租金均屬可載明事項。"],"tr":""},{"id":"h:106-37","p":"h","src":"106年第37題","sec":"D6","stem":"下列有關抵押權之敘述，何者正確？","opts":["以抵押權擔保之債權請求權，雖經時效消滅，債權人仍得於時效完成後 5 年內實行抵押權","以建築物為抵押者，其附加部分亦為抵押權效力所及，應一律併付拍賣","抵押權人聲請查封抵押物，惟該執行名義嗣後經抗告法院裁定予以廢棄確定時，抵押人可依法請求財產上及非財產上損害賠償","抵押權人於債權清償期屆滿後，為受清償，不得訂立契約取得抵押物之所有權"],"ok":[0],"ex":["§880：擔保債權之請求權雖因時效消滅，抵押權人於消滅時效完成後5年間不實行抵押權，抵押權才消滅，故5年內仍得實行。","§862 III：附加於建築物而不具獨立性之部分，為效力所及；但附加部分為獨立之物且設定後附加者，僅準用§877「得」併付拍賣，並非一律併付。","抵押權章並無「執行名義被廢棄即當然可請求財產上及非財產上損害賠償」之規定；損害賠償須另有請求權基礎，非財產上損害尤須有特別規定。","§878：抵押權人於債權清償期屆滿後，為受清償，得訂立契約取得抵押物之所有權（清償期屆至前之流抵約定依§873-1 I 須登記始得對抗第三人）。"],"tr":""},{"id":"h:106-38","p":"h","src":"106年第38題","sec":"B2","stem":"下列有關契約解除之敘述，何者錯誤？","opts":["契約解除時，當事人雙方負回復原狀之義務","解除權之行使，不妨礙損害賠償之請求","房屋買賣契約解除時，原買受人已支出之裝潢費用均得請求出賣人返還","解除權之行使，得以送達訴狀繕本予他方當事人之方法為之"],"ok":[2],"ex":["§259：契約解除時，當事人雙方負回復原狀之義務（如返還受領之給付物、金錢附加利息等），正確。","§260：解除權之行使，不妨礙損害賠償之請求，兩者可併行主張，正確。","買受人所支出之費用能否請求，依§259 ⑤：就返還之物已支出必要或有益之費用，得於他方受返還時「所得利益之限度內」請求返還；故僅限「必要或有益」費用，且以出賣人受返還所得利益為限，並非支出之裝潢費用「均得」請求返還，本選項過於絕對，錯誤，為應選答案。","解除權之行使，應向他方當事人以意思表示為之（§258 Ⅰ）；實務上認為以訴狀送達他方亦可視為已為解除之意思表示（此點為實務見解，非條文明文），正確。"],"tr":""},{"id":"h:106-39","p":"h","src":"106年第39題","sec":"D4","stem":"下列有關相鄰關係之敘述，何者錯誤？","opts":["聲響之侵入係偶發、輕微或依地方習慣認為相當者，彼此仍應於合理程度範圍內忍受，不得請求損害賠償","相鄰關係重在不動產利用人間權利義務關係之調和，不以各該不動產相互緊鄰為必要","土地所有人拆除舊建物時，致相鄰樓房發生傾斜、龜裂等，應依民法第 184 條第 2 項負損害賠償責任","土地所有人非因故意或重大過失建築房屋逾越疆界者，鄰地所有人無論何時均得提出異議，請求移去或變更其建築物"],"ok":[3],"ex":["§793：氣響、振動等侵入，若屬輕微或按地方習慣認為相當者，鄰地所有人須忍受，無從禁止。","相鄰關係重在不動產利用之調和，不以不動產直接緊鄰為必要（實務見解）。","§794：土地所有人開掘土地或為建築，不得使鄰地地基動搖或發生危險；違反屬保護他人之法律，依§184 II 負賠償責任。","§796 I：非因故意或重大過失越界建築，鄰地所有人若知其越界而不即提出異議，就不得請求移去或變更；並非「無論何時」均得提出。"],"tr":""},{"id":"h:106-40","p":"h","src":"106年第40題","sec":"A1","stem":"下列有關人格權之敘述，何者錯誤？","opts":["姓名乃用以區別人己之一種語言標誌，將人個別化，以確定其人之同一性","法人在法令限制與性質範圍內，亦享有人格權","公司名稱用以識別企業之主體性，此時姓名權等於商標權","針對無涉公益之報導，若不當揭載足資識別當事人資料，侵害其名譽權者，得依民法第 18 條請求排除侵害"],"ok":[2],"ex":["姓名為區別人己之標誌，姓名權屬人格權（§19）。","法人於法令限制及性質範圍內享有人格權（§26）。","公司名稱受公司法保護，屬營業主體識別，與商標（保護商品或服務來源識別）不同，姓名權不等於商標權。","§18Ⅰ 人格權受侵害時得請求法院除去之，有侵害之虞時得請求防止之，名譽權亦適用。"],"tr":""},{"id":"h:105-1","p":"h","src":"105年第1題","sec":"A4","stem":"有關民法的法源，民法第 1 條規定「民事，法律所未規定者，依習慣；無習慣者，依法理。」下列敘述何者正確？","opts":["民間「洗門風」的習慣，即是該條所稱之「習慣」","此之「習慣」，係專指習慣法而言","憲法關於人民之權利義務的規定，是該條所稱之法律","條約是規範國家間權利義務之協定，絕非是民法法源之一"],"ok":[1],"ex":["洗門風之習俗違反公序良俗（§72），不能作為§1之習慣。","§1 之習慣，通說指具有法的確信之習慣法，單純事實上習慣不屬之。","憲法人民權利義務規定主要規範國家與人民關係，在私法上透過概括條款間接適用，並非逕為§1 所稱法律。","經國內法程序生效之條約可具有國內法效力，絕非不得為法源之說過於絕對。"],"tr":""},{"id":"h:105-2","p":"h","src":"105年第2題","sec":"A4","stem":"依民法之規定，下列何種非屬法定要式行為？","opts":["兩願離婚","買賣契約","所有權移轉","社團章程之訂定"],"ok":[1],"ex":["兩願離婚須以書面為之，並須有二人以上之證人簽名（§1050），屬法定要式行為。","買賣契約（§345）依民法規定屬不要式契約，僅須雙方意思表示合致即可成立，不需書面或特定形式，正確（非法定要式行為）。","不動產物權之移轉或設定，應以書面為之（§758Ⅱ），屬法定要式行為。","社團設立應訂立章程（§47），章程訂定須以書面為之，屬要式行為。"],"tr":""},{"id":"h:105-3","p":"h","src":"105年第3題","sec":"B1","stem":"有關財產權之描述，下列敘述何者正確？","opts":["債權是請求權，所以只能約定由特定人請求另一特定人為一定作為，但不能約定不作為","債權具有相對性，所以當出賣人一屋先後兩賣時，前後買賣契約皆為有效","基於契約自由原則，當事人可以自由創設物權種類，不受限制","債權給付之內容，以有財產價格者為限"],"ok":[1],"ex":["債權不限於作為，不作為（如競業禁止）亦可約定（§199 III：不作為亦得為給付）。","債權具相對性，一屋二賣兩買賣契約皆有效，買受人均得向出賣人請求履行。","物權法定（§757），當事人不得任意創設物權種類。","§199 II：債之給付，不以有財產價格者為限。"],"tr":""},{"id":"h:105-4","p":"h","src":"105年第4題","sec":"A1","stem":"有關人格權之敘述，下列何者錯誤？","opts":["自由不得限制","行為能力不得拋棄","人格權具有專屬性","當人格權受侵害時，得請求法院除去其侵害"],"ok":[0],"ex":["§17Ⅰ：自由不得拋棄；§17Ⅱ：自由之限制，以不背於公共秩序或善良風俗者為限。可見自由可以被限制（只要不違背公序良俗），「自由不得限制」說得太絕對，錯誤，為應選答案。","§16：權利能力及行為能力，不得拋棄，正確。","人格權（生命、身體、健康、名譽、隱私等）與人格不可分，具一身專屬性，不得讓與或繼承，正確。","§18Ⅰ：人格權受侵害時，得請求法院除去其侵害；有受侵害之虞時，得請求防止之，正確。"],"tr":""},{"id":"h:105-5","p":"h","src":"105年第5題","sec":"A1","stem":"30 歲的甲患有精神疾病，並受監護宣告。某日，甲於精神狀況良好時，單獨到乙電信公司購買手機一支。試問甲乙間之買賣契約，其效力為何？","opts":["有效","無效","得撤銷","效力未定"],"ok":[1],"ex":["受監護宣告之人之意思表示無效（§15、§75Ⅰ），縱使精神狀況回復，在宣告被撤銷前仍屬無行為能力人，其意思表示不因精神回復而有效。","受監護宣告者在監護宣告撤銷前，其意思表示一律無效（§75Ⅰ），不論其精神狀況實際如何，此為法律上的擬制，買賣契約無效，正確。","得撤銷用於意思表示瑕疵，本題係行為能力欠缺導致無效，並非得撤銷。","效力未定用於限制行為能力人契約或無權代理，本題甲為受監護宣告之無行為能力人，效果為無效而非效力未定。"],"tr":""},{"id":"h:105-6","p":"h","src":"105年第6題","sec":"A5","stem":"甲誤認為好友所贈與之戒指，乃鍍金之假鑽戒，遂將該戒指以 5 百元之價格賣給乙，並已交付。甲事後得知此乃真金真鑽之戒指，且價值 5 萬元。有關此法律行為之敘述，下列何者正確？","opts":["甲乙間之買賣契約無效，但物權行為有效","甲乙間之買賣契約有效，但物權行為無效","甲乙間之買賣契約得撤銷，但物權行為無效","甲乙間之買賣契約得撤銷，但物權行為有效"],"ok":[3],"ex":["甲誤認戒指為假鑽，屬§88Ⅱ「物之性質」錯誤（交易上認為重要者視為意思表示內容錯誤），效果是買賣契約「得撤銷」，經撤銷才視為自始無效（§114Ⅰ），撤銷前契約並非無效；故「契約無效」的說法錯誤。","買賣契約因意思表示錯誤（§88）得撤銷，並非有效；物權行為採無因性，亦非無效。","買賣契約得撤銷（正確），但物權行為（交付）依無因性原則，不因債權行為之效力而影響，交付本身有效，並非無效。","甲誤認戒指為假鑽，對物之性質有重大錯誤，買賣契約之意思表示（§88）得撤銷；但已交付（移轉所有權之物權行為）依物權行為無因性原則，其效力獨立於債權行為之外，交付行為有效（乙已取得所有權）。若甲撤銷債權行為，乙須依不當得利返還，但此是撤銷後之效果，撤銷前物權行為有效，正確。"],"tr":""},{"id":"h:105-7","p":"h","src":"105年第7題","sec":"C1","stem":"有關法律行為之標的，下列敘述何者正確？","opts":["甲乙約定以火星上岩石為贈與標的物，該契約有效","甲乙約定故宮翠玉白菜為買賣標的物，該契約有效","甲乙約定甲需於 1 日內完成環島健走行程，該契約有效","甲乙婚前協議約定，婚後任一方若有出軌行為，必須支付對方新臺幣 100 萬元賠償費，該契約有效"],"ok":[3],"ex":["火星岩石為自始客觀不能之給付，依 §246 I 契約無效。","翠玉白菜為國有國寶級文物，其轉讓受法令禁止或限制（§71），買賣契約不能有效成立。","1日內完成環島行程為自始客觀不能，契約無效（§246 I）。","婚前協議約定違約金屬契約自由（§153），法院得依 §252 酌減，約定本身不當然違法無效。"],"tr":""},{"id":"h:105-8","p":"h","src":"105年第8題","sec":"A1","stem":"甲為限制行為能力人，當其為法律行為時，下列何種行為無效？","opts":["甲未得母之允許，於父死後 3 個月內，具狀向法院為拋棄其繼承權之意思表示","甲以詐術佯稱自己已成年，向乙購買機車一輛","甲未得父母之同意，擅自接收同學拋棄的筆電一台","甲未得父母之同意，擅自至福利社購買鉛筆"],"ok":[0],"ex":["拋棄繼承權屬「單獨行為」，依§78，限制行為能力人未得法定代理人允許之單獨行為，無效；且拋棄繼承須「一定期間內」以書面向法院聲請（§1174），屬法定要式及有期限之行為，此題測驗點：拋棄繼承為單獨行為→無效。","限制行為能力人使用詐術（佯稱成年），依§83，其法律行為為「有效」，保護善意相對人，而非無效。","接收他人拋棄之動產為無主物先占（§802），依通說屬事實行為，不以行為能力為要件，限制行為能力人亦得取得所有權，無須法定代理人允許。","日常生活所必需之行為（購買文具），依§77但書，無須法定代理人允許即有效。"],"tr":""},{"id":"h:105-9","p":"h","src":"105年第9題","sec":"C4","stem":"甲告知乙，若乙願意出國比賽，不管有無得名次，即贈與乙 200 萬元。試問甲乙間之贈與契約的附款為何？","opts":["期限","條件","負擔","約款"],"ok":[1],"ex":["期限是將來必定到來之事實，出國比賽成否不確定，不屬期限。","出國比賽為將來客觀不確定事實，贈與以之為生效前提，屬停止條件（§99 I）。","§412 之負擔是使受贈人負一定給付義務，本題出國比賽為贈與生效之前提，並非受贈人之給付義務。","『約款』並非民法所定附款類型，附款為條件、期限、負擔。"],"tr":""},{"id":"h:105-10","p":"h","src":"105年第10題","sec":"B5","stem":"甲於出國遊玩期間，適逢颱風來襲，甲家的大門因此破損，門戶洞開。鄰居乙擔心甲家遭遇盜賊，乃好心召來工匠為其修繕，支出 8 千元。試問乙得依下列何種法律關係向甲請求返還 8 千元？","opts":["無因管理","侵權行為","不當得利","債務不履行"],"ok":[0],"ex":["無因管理（§172）：未受委任、並無義務而為他人管理事務；乙為出國之甲修繕破損大門，符合本人利益，依§176 Ⅰ（管理事務利於本人且不違反本人意思者，得請求償還必要或有益費用及自支出時起之利息），乙得請求返還8千元，正確。","侵權行為（§184）是因故意或過失不法侵害他人權利而負賠償責任；乙是為甲之利益出資修繕，並未侵害甲，無從成立。","不當得利（§179）要件為「無法律上之原因」而受利益致他人受損害；甲雖因修繕受利益，但此利益有無因管理（§172、§176）作為法律上原因，欠缺「無法律上之原因」，乙應依無因管理請求償還費用，而非不當得利。","債務不履行以當事人間有債之關係（如契約）為前提；乙與甲間並無契約或約定義務，無從主張債務不履行。"],"tr":""},{"id":"h:105-11","p":"h","src":"105年第11題","sec":"B1","stem":"有關契約之敘述，下列何者正確？","opts":["契約為事實行為的一種","契約得因要約交錯之方式成立","契約皆須以書面方式為之，方得以成立","基於契約自由原則，醫生得拒絕醫治病情危急的情敵"],"ok":[1],"ex":["契約屬「法律行為」（需意思表示），非事實行為（事實行為不以意思表示為要素，如占有、無因管理）。","依§153，要約交錯：雙方各自獨立發出的要約，在不知對方要約之情況下，若內容一致，可構成契約成立，正確。","契約原則上為不要式，除法律明定書面要式者外，口頭即可成立，選項過於絕對，錯誤。","醫師有緊急醫療義務（醫師法等公法），不得以個人好惡拒絕急救，本選項以「契約自由」主張可拒絕，忽略公法義務的限制，錯誤。"],"tr":""},{"id":"h:105-12","p":"h","src":"105年第12題","sec":"C1","stem":"依現行民法規定，有關違反法定要式規定之法律行為效力，下列何者應為無效？","opts":["會員已交付首期會款，但未訂立會單","不動產買賣之債權契約，未經書面公證","不動產租賃契約期限約定 2 年，且未以書面簽訂","人事保證契約未以書面簽訂"],"ok":[3],"ex":["合會（§709-3）：合會應訂立會單，但Ⅲ規定「會員已交付首期會款者，雖未依規定訂立會單，其合會契約視為已成立」；本選項已交付首期會款，合會契約視為成立，並非無效。","不動產買賣債權契約：§166-1 雖規定以負擔不動產物權移轉義務為標的之契約應由公證人作成公證書，但該條施行日期由行政院會同司法院另定、迄未施行，現行法下不公證並不影響債權契約效力（且該條Ⅱ亦規定已合意並完成登記者仍為有效），故非無效。","不動產租賃（§422）：期限逾一年者應以字據訂立，未以字據訂立者「視為不定期限之租賃」；本選項期限2年未書面，法律效果是視為不定期限租賃，契約仍然有效，並非無效。","人事保證（§756-1 Ⅱ）：人事保證契約應以書面為之；依§73，法律行為不依法定方式者無效（但法律另有規定者除外），本條並無例外規定，故未以書面簽訂即為無效，正確。"],"tr":""},{"id":"h:105-13","p":"h","src":"105年第13題","sec":"B4","stem":"有關不當得利所應返還之客體，下列何者錯誤？","opts":["原物所生之孳息","受領之原物或原權利","原物因受領人特殊能力導致之增值","原物毀損後，受益時之價額"],"ok":[2],"ex":["§181：受領人除返還所受利益，本於該利益更有所取得者並應返還，孳息屬之。","§181：原物仍存在者，應返還原物或原權利。","§181 所指返還者為「本於該利益」所取得，受領人以特殊能力使原物增值，通說不屬應返還之客體。","§181 但書：依利益性質不能返還者，應償還其價額（價額計算時點條文未規定，依通說以受益時為準）。"],"tr":""},{"id":"h:105-14","p":"h","src":"105年第14題","sec":"C2","stem":"甲欲向乙租屋 3 年，雙方僅用通訊軟體 Line 互相協商，乙已於對話中允諾，但後來丙出更高租金，於是乙改將該屋出租給丙並交付之，後來丙得乙之同意將該屋再出租給丁，某日丁因大意未關爐火將該屋燒毀，下列敘述何者正確？","opts":["乙可以向丁主張侵權行為責任","甲可主張乙丙之租賃契約未以書面簽訂，因此無效","丙可以向丁主張侵權行為責任","甲可以向丙主張有優先締約權，因此乙丙之租賃契約對甲係屬無效"],"ok":[0],"ex":["乙為房屋所有人，丁過失失火燒毀房屋侵害所有權，乙得依§184 I 前段向丁請求侵權行為責任。","§422：未以書面訂立僅視為不定期租賃，並非無效，且甲非乙丙租約之當事人。","丙非所有人，其與丁間之損害主要屬轉租契約責任，不能逕以§184 I 前段主張。","租賃無優先締約權，甲不得主張乙丙租約無效。"],"tr":""},{"id":"h:105-15","p":"h","src":"105年第15題","sec":"B6","stem":"依侵權行為請求損害賠償之說明，下列敘述何者正確？","opts":["純粹經濟上之損失亦屬於一種損害，與權利受損一樣，得依民法第 184 條第 1 項前段主張之","債權亦屬於一種財產權，被侵害時，祗得依民法第 184 條第 1 項前段主張，而不得依同條項後段主張之","我國侵權行為之保護客體僅限於權利，未及於利益","故意以背於善良風俗之方法加損害於他人之利益，受害人亦得依侵權行為主張之"],"ok":[3],"ex":["純粹經濟上損失並非權利受損，不能直接依 §184 I 前段主張，須依後段或 §184 II。","債權是否屬§184Ⅰ前段的「權利」，學說有爭議（債權不具公示性，多數見解認為過失侵害債權原則上不賠）；但不論採哪一說，故意以背於善良風俗之方法侵害債權，都可依§184Ⅰ後段請求。選項說「祗得依前段、不得依後段」，錯在排除後段。","§184 I 後段、II 已保護利益。","§184 I 後段：故意以背於善良風俗之方法加損害於他人者，亦負賠償責任，利益亦受保護。"],"tr":""},{"id":"h:105-16","p":"h","src":"105年第16題","sec":"B2","stem":"有關民法第 250 條規定之違約金類型有「損害賠償總額預定違約金」與「懲罰性違約金」兩種，下列敘述何者正確？","opts":["「損害賠償總額預定違約金」，倘若債務人有債務不履行發生，惟債權人所受實際損害遠低於約定之額度時，債權人即不得請求此一違約金金額","「懲罰性違約金」，只要債務人有債務不履行發生時，即便債權人未因此而受損害，債權人仍得請求此一違約金金額","「損害賠償總額預定違約金」，債務人有債務不履行發生，導致債權人受損害時，債權人除此一違約金外，亦得請求其他損害賠償金額","「懲罰性違約金」，債務人有債務不履行發生，導致債權人受損害時，債權人除此一違約金外，不得請求其他損害賠償金額"],"ok":[1],"ex":["賠償總額預定性違約金，債權人不必證明實際損害即可請求，法院僅得依 §252 酌減。","懲罰性違約金（§250 II 前段：當事人另有訂定）：債務不履行即得請求違約金，不須證明損害，並得另請求損害賠償。","§250 II 前段：賠償總額預定性違約金，視為損害賠償總額，不得另請求損害賠償。","懲罰性違約金的特色就是違約金外還可請求損害賠償。"],"tr":""},{"id":"h:105-17","p":"h","src":"105年第17題","sec":"C1","stem":"若買賣標的物為特定物時，買受人不得請求下列那一種物的瑕疵擔保之法定效果？","opts":["減價","解約","損害賠償","另行交付他物"],"ok":[3],"ex":["物之瑕疵擔保，買受人得請求「減少價金」（§359），正確（可請求）。","買受人得解除契約（§359），正確（可請求）。","若出賣人故意不告知瑕疵，買受人得請求損害賠償（§360），正確（可請求）。","特定物買賣，標的是「該特定物」，買受人不得請求另行交付「他物」（他物是不同的特定物或種類物，特定物買賣本就以該特定物為標的，不能要求替換他物）；只有「種類物」買賣才有請求另行交付無瑕疵之物（§364）的選項，正確。"],"tr":""},{"id":"h:105-18","p":"h","src":"105年第18題","sec":"B2","stem":"甲將透天厝（不含基地）立約賣給乙後，尚未交付予乙前，即逢超級強烈颱風來襲，致透天厝完全倒塌。下列敘述何者正確？","opts":["乙免給付價金予甲","甲仍負有交屋之義務","甲仍得請求乙支付價金","乙得向甲主張侵權行為"],"ok":[0],"ex":["颱風為不可歸責雙方之事由（危險負擔，§266），房屋未交付前滅失，出賣人（甲）免給付義務，買受人（乙）亦免給付對待給付（價金），乙免付，正確。","特定物已滅失（颱風倒塌），甲無從再交屋，給付客觀不能，甲之交付義務消滅，並非「仍負有交屋義務」。","依§266，不可歸責雙方的危險負擔，甲乙雙方互免，甲不得再請求乙支付價金，選項錯誤。","颱風倒塌不可歸責於甲，甲並無過失或故意，乙無從主張甲的侵權行為。"],"tr":""},{"id":"h:105-19","p":"h","src":"105年第19題","sec":"C4","stem":"有關贈與契約之敘述，下列何者正確？","opts":["贈與契約一旦成立後，贈與人不得任意撤銷之","贈與契約為要式契約，因此必須作成贈與契約書","贈與屬於恩惠行為，故成立贈與契約無須受贈人之同意","因贈與契約為無償契約，故原則上贈與人不負瑕疵擔保責任"],"ok":[3],"ex":["§408 Ⅰ：贈與物之權利『未移轉前』，贈與人得撤銷其贈與；故成立後尚可任意撤銷，僅§408 Ⅱ 所列經公證之贈與、或為履行道德上義務而為之贈與例外（不是『書面』），選項說『不得任意撤銷』錯誤。","贈與為不要式契約，口頭即可成立，不必作成書面，選項錯誤。","贈與（§406）須『一方以自己財產無償給與他方，他方允受之』，需受贈人允受，雙方意思一致才成立，並非無須受贈人同意。","§411：贈與之物或權利如有瑕疵，贈與人不負擔保責任（無償，責任從輕），但故意不告知瑕疵或保證無瑕疵者，須賠償受贈人因瑕疵所生之損害，正確。"],"tr":""},{"id":"h:105-20","p":"h","src":"105年第20題","sec":"C2","stem":"依民法之規定，承租人因下列何種情形致失火而使租賃物毀損、滅失者，應對出租人負損害賠償責任？","opts":["重大過失","不可抗力","具體輕過失","抽象輕過失"],"ok":[0],"ex":["§434：承租人因重大過失致失火而使租賃物毀損滅失，應對出租人負賠償責任。","不可抗力係不可歸責，承租人不負責任。","§434 限於重大過失，具體輕過失不負責。","§434 限於重大過失，抽象輕過失不負責。"],"tr":""},{"id":"h:105-21","p":"h","src":"105年第21題","sec":"D2","stem":"有關物權之優先性，在同一標的物下，下列敘述何者正確？","opts":["當所有權與定限物權併存時，所有權之效力依舊優先於定限物權","當內容或性質相衝突之物權併存時，二者效力均等","先成立用益物權，再設定擔保物權時，該擔保物權不得對抗該已成立之用益物權","先成立擔保物權，再設定用益物權時，該擔保物權人無論如何皆可主張塗銷該用益物權"],"ok":[2],"ex":["定限物權對所有權有限制作用，所有權於定限物權存在時受其限制，效力並非優先。","內容或性質相衝突之物權併存時，先成立者優先，非效力均等。","先成立之用益物權，後設擔保物權時，擔保物權不得對抗該用益物權（實行時不得除去之）。","先成立擔保物權、再設用益物權者，須實行受影響時才得除去（§866 II），並非無論如何皆得塗銷。"],"tr":""},{"id":"h:105-22","p":"h","src":"105年第22題","sec":"D4","stem":"民法第 796 條規定，土地所有人建築房屋非因故意或重大過失逾越地界者，鄰地所有人如知其越界而不即提出異議，不得請求移去或變更其房屋。假設甲僅有抽象輕過失，且乙知其越界未即提出異議，下列敘述何者正確？","opts":["甲將自己之廚廁建於鄰地所有人乙之部分土地上，甲可以主張廚廁亦屬於該條之「建築房屋」，不得拆除","甲將房屋之全部建築在鄰地所有人乙之土地上，甲可以主張此符合「越界建築」之規定，不得拆除","甲之立體停車場越界建築在鄰地所有人乙之土地上，則鄰地所有人乙，可以主張停車場並非是該條之「建築房屋」而請求拆除","甲所建房屋整體之外，越界加建房屋，則鄰地所有人乙，可以請求拆除該加建之房屋"],"ok":[3],"ex":["§796以自己土地上建築物「逾越」地界為前提；將廚廁建在鄰地部分土地上，非自己土地上建物越界，不能援引免拆保護。","房屋全部建在乙地上，並非「越界」，不適用§796。","立體停車場若屬與房屋價值相當之其他建築物，依§796-2準用§796，乙不能以非房屋為由請求拆除。","越界加建房屋屬另一越界行為，不受§796保護，鄰地所有人得請求拆除。"],"tr":""},{"id":"h:105-23","p":"h","src":"105年第23題","sec":"D5","stem":"有關地上權之敘述，下列何者正確？","opts":["地上權乃為債權","地上權人必須支付地租","地上權之存續期間，有法定最長 20 年之限制","地上權人原則上得將其權利讓與他人或設定抵押權"],"ok":[3],"ex":["依§832，普通地上權是以在他人土地之上下有建築物或其他工作物為目的而使用其土地之權，屬物權（用益物權），不是債權，選項錯誤。","地租是否支付由當事人約定：§834 規定「無支付地租之約定」的地上權人得隨時拋棄權利，§835 則規範「有地租約定」的情形，可知地上權可為無償，並非必須支付地租，選項錯誤。","租賃契約期限不得逾20年（§449Ⅰ），且租用基地建築房屋者不適用（§449Ⅲ）；地上權並無最長20年的法定限制，選項錯誤。","依§838Ⅰ，地上權人得將其權利讓與他人或設定抵押權，但契約另有約定或另有習慣者不在此限，故原則上可讓與及抵押，正確。"],"tr":""},{"id":"h:105-24","p":"h","src":"105年第24題","sec":"D5","stem":"民法規定，區分地上權人得與其設定之土地上下有使用、收益權利之人，約定相互間使用收益之限制。其約定未經土地所有人同意者，於使用收益權消滅時，土地所有人不受該約定之拘束。此之「其設定之土地上下有使用、收益權利之人」不包含下列何種？","opts":["普通地上權人","不動產役權人","農育權人","典權人"],"ok":[3],"ex":["普通地上權人為於同一土地上下有使用收益權利之人，得與區分地上權人約定相互限制（§841-2）。","不動產役權人同為使用土地之用益物權人，屬該條範圍。","農育權人使用收益他人土地，屬該條範圍。","考選部公告答案為D。注意：§841-2 條文只寫「其設定之土地上下有使用、收益權利之人」，沒有列舉、也沒有排除典權人；典權人依§911 同樣是在他人不動產為使用、收益之人，單從條文文字導不出「不包含典權人」。官方答案的理由不在條文文字中，本題請依官方答案記住「典權人不包含」，但不要推廣成「典權人不是使用收益權人」。"],"tr":""},{"id":"h:105-25","p":"h","src":"105年第25題","sec":"D5","stem":"以他人不動產供自己不動產通行、汲水、採光、眺望、電信或以其他特定便宜之用者，稱為：","opts":["農育權","抵押權","不動產役權","土地租賃權"],"ok":[2],"ex":["農育權（§850-1）：以農作、牧畜、養殖、造林等為目的之用益物權，非本題情形。","抵押權：擔保物權，非用益物權，與本題使用他人不動產性質不同。","§851，「不動產役權」：以他人不動產（供役地）供自己不動產（需役地）通行、汲水、採光、眺望、電信等便宜之用，正確。","土地租賃權：以支付租金為對價使用土地，不具物權性質，且與本題「供他人不動產使用」之役權結構不同。"],"tr":""},{"id":"h:105-26","p":"h","src":"105年第26題","sec":"D6","stem":"有關抵押權之特性，下列敘述何者錯誤？","opts":["當不動產所有人設定抵押權後，其抵押權不因該不動產之物權讓與而受影響","抵押之不動產如經分割，其抵押權不因該不動產經分割或讓與一部而受影響","以抵押權擔保之債權，其抵押權不因該債權經分割或讓與一部而受影響","抵押權之獨立性在於其得由債權分離而為讓與，或為其他債權之擔保"],"ok":[3],"ex":["不動產所有人設定抵押權後讓與不動產，抵押權不受影響（§867）。","抵押不動產經分割或讓與一部，抵押權不受影響（§868）。","抵押債權經分割或讓與一部，抵押權不受影響（§869 I）。","抵押權不得由債權分離而為讓與，或為其他債權之擔保（§870），故不具獨立性，而具從屬性。"],"tr":""},{"id":"h:105-27","p":"h","src":"105年第27題","sec":"D6","stem":"有關抵押權之實行，下列敘述何者正確？","opts":["土地所有人於設定抵押權後，在抵押之土地上營造建築物者，抵押權人於必要時，得於強制執行程序中聲請法院將其建築物與土地併付拍賣，對於建築物之價金，無優先受清償之權","以建築物設定抵押權者，於法院拍賣抵押物時，其抵押物存在所必要之權利得讓與者，應併付拍賣。但抵押權人對於該權利賣得之價金，有優先受清償之權","設定抵押權時，土地及其土地上之建築物，同屬一人所有，而僅以土地為抵押者，於抵押物拍賣時，得聲請併付拍賣，就土地賣得之價金，有優先受清償之權","設定抵押權時，土地及其土地上之建築物，同屬一人所有，而以土地及建築物為抵押者，如經拍賣，其土地與建築物之拍定人各異時，視為已有地上權之設定，其地租法院須逕以判決定之"],"ok":[0],"ex":["設定抵押權後營造建築物者，抵押權人得聲請併付拍賣，但對建築物價金無優先受償權（§877）。","以建築物設定抵押權者，併付拍賣之權利價金，抵押權人無優先受償權（§877-1）。","設定抵押權時房屋已存在、僅以土地抵押，不屬§877「設定後營造」之情形，抵押權人不得聲請併付拍賣，更無就房屋價金優先受償可言；此時依§876 I，於抵押物（土地）拍賣時，視為房屋已有地上權之設定。","土地與建築物同屬一人而拍定人各異，視為已有地上權，地租先由當事人協議，協議不成再聲請法院以判決定之（§876 II 適用 I），非逕以判決定。"],"tr":""},{"id":"h:105-28","p":"h","src":"105年第28題","sec":"D6","stem":"乙將其所有汽車為甲設定動產質權，以為其對甲借款債務之擔保。該車並已交付甲之占有。下列那種情形，甲之動產質權並不消滅？","opts":["丙仗義相助幫乙清償該債務","甲將該車返還給乙","甲喪失對該車之占有，於第 3 年始請求返還","該車被盜後，隔年再讓與給善意第三人，甲對該第三人行使回復請求權時"],"ok":[3],"ex":["債務經第三人清償而消滅，質權因從屬性亦消滅。","質權人返還質物於出質人，動產質權消滅（§897）。","質權人喪失占有，須於二年內請求返還（§898）；第三年才請求，質權已消滅。","甲因車被盜而喪失占有，題目說「隔年」讓與善意第三人時甲即行使回復請求權，仍在喪失占有後二年內：§949 I 允許原占有人（甲）自喪失占有之時起二年以內，向善意受讓之現占有人請求回復其物；§898 則只在「二年內未請求返還」時才使質權消滅，甲已請求，質權不消滅。"],"tr":""},{"id":"h:105-29","p":"h","src":"105年第29題","sec":"D6","stem":"有關惡意占有人與善意占有人，在損害賠償請求方面，下列敘述何者正確？","opts":["善意占有人就占有物之滅失或毀損，如係不可歸責於自己之事由所致者，對於回復請求人僅以滅失或毀損所受之利益為限，負賠償之責","惡意占有人或無所有意思之占有人，就占有物之滅失或毀損，如係不可歸責於自己之事由所致者，對於回復請求人，負賠償之責","善意占有人因保存占有物所支出之必要費用，得向回復請求人請求償還。但已就占有物取得孳息者，不得請求償還通常必要費用","惡意占有人，因保存占有物所支出之必要費用，對於回復請求人，得依關於不當得利之規定，請求償還"],"ok":[2],"ex":["善意占有人就滅失毀損，僅於可歸責於己時，才以所受利益為限賠償（§953）；不可歸責時無須賠償。","惡意占有人或無所有意思占有人，須因可歸責於己才負賠償責任（§956）；不可歸責時不負責。","善意占有人因保存占有物支出之必要費用得請求償還，但已取得孳息者不得請求通常必要費用（§954）。","惡意占有人因保存占有物之必要費用，依無因管理規定請求償還（§957），非不當得利。"],"tr":""},{"id":"h:105-30","p":"h","src":"105年第30題","sec":"D6","stem":"有關動產善意受讓要件之說明，下列敘述何者正確？","opts":["讓與人與受讓人須完成讓與動產之交付行為，此之交付不包含觀念交付","受讓人出於善意且有抽象輕過失者，不受占有之保護","讓與人必須是無權代理","盜贓物為金錢時，被害人不得向善意占有人請求回復"],"ok":[3],"ex":["交付包括簡易交付、指示交付等觀念交付；以占有改定受讓者，須至受現實交付且交付時善意，始受保護（§761、§948 II）。","受讓人只有明知或因重大過失不知無權時，才不受保護（§948 I但書）；抽象輕過失仍受保護。","§948 I 保護的是受讓人對「讓與人有讓與權利」的信賴，前提是讓與人以自己名義處分他人之物（無權處分）。「無權代理」是以本人名義為法律行為，效力依§170 I 須經本人承認；第三人信賴代理權外觀者，另依表見代理（§169）處理，不適用善意受讓。故「讓與人必須是無權代理」錯誤，正確要件是「讓與人無讓與之權利」。","盜贓或遺失物如係金錢或未記載權利人之有價證券，不得向其善意受讓之現占有人請求回復（§951）。"],"tr":""},{"id":"h:105-31","p":"h","src":"105年第31題","sec":"E1","stem":"下列何者違反近親禁婚範圍之規定？","opts":["甲先收養丙男，再收養丁女，丙與丁之結婚","甲有一子乙，再收養一女丙，之後乙育有一子丁，丙育有一女戊，丁與戊之結婚","乙有一女丙，另外收養一女丁，戊有一子己，另外收養一子庚。未久，甲收養乙與戊，丙與己之結婚，丁與庚之結婚","甲與前妻育有一子乙，丙與前夫育有一女丁，甲與丙後來結婚，未久，乙與丁欲結婚"],"ok":[0],"ex":["丙、丁同被甲收養成為養兄妹，屬因收養而成立之二親等旁系血親，§983I②但書僅放寬四親等及六親等，二親等仍不得結婚，違反規定。","丁與戊為四親等旁系血親，且係因收養而成立、輩分相同，屬§983I②但書例外，得結婚。","丙與己、丁與庚均為因收養成立之四親等旁系血親，輩分相同，適用§983I②但書，得結婚。","乙與丁為繼兄妹，雙方並非血親，也非姻親（血親之配偶之血親不屬§969），不在§983禁婚範圍。"],"tr":""},{"id":"h:105-32","p":"h","src":"105年第32題","sec":"E2","stem":"下列何者非屬我國現行民法中所規定之約定財產制？","opts":["統一財產制","分別財產制","一般共同財產制","勞力所得共同財產制"],"ok":[0],"ex":["統一財產制已於修法廢止，現行約定財產制僅有共同財產制與分別財產制（§1004），故不屬現行約定財產制，符合題意。","分別財產制屬現行約定財產制（§1004、§1044），不符「非屬」題意。","一般共同財產制屬現行約定財產制（§1031），不符「非屬」題意。","勞力所得共同財產制屬現行約定財產制（§1041），不符「非屬」題意。"],"tr":""},{"id":"h:105-33","p":"h","src":"105年第33題","sec":"E2","stem":"有關夫妻財產制的規定，下列敘述何者正確？","opts":["依民法規定，夫妻除可以選擇分別財產制及共同財產制外，亦得基於契約自由原則，選擇其他分配方式","夫妻選擇分別財產制，將來離婚時仍有剩餘財產分配請求權之適用","夫妻選擇共同財產制後，可以再變更為分別財產制，互相轉換並無次數上的限制","夫妻因未約定夫妻財產制而採用法定財產制時，將來就不得任意再變更"],"ok":[2],"ex":["夫妻僅得就法定的約定財產制類型選擇其一（§1004），不能任意創設其他分配方式。","分別財產制各自保有財產，無剩餘財產差額分配（§1030-1僅於法定財產制適用）。","夫妻於婚姻關係存續中得以契約廢止財產契約或改用他種約定財產制（§1012），法律未限制次數，正確。","未約定者適用法定財產制（§1005），婚姻中亦可以契約改用約定財產制（§1012），並非不得變更。"],"tr":""},{"id":"h:105-34","p":"h","src":"105年第34題","sec":"E2","stem":"有關法定夫妻財產制之敘述，下列何者錯誤？","opts":["夫或妻各自管理、使用、收益及處分其財產","夫妻就其婚前財產及婚後財產，互負報告之義務","不論夫或妻之婚前財產或婚後財產，均屬夫或妻各自所有","夫或妻之婚前財產，於婚姻關係存續中所生之孳息，視為婚後財產"],"ok":[1],"ex":["夫或妻各自管理、使用、收益及處分其財產（§1018），敘述正確。","夫妻僅就「婚後財產」互負報告義務（§1022），不及於婚前財產，敘述錯誤。","夫或妻之財產分為婚前財產與婚後財產，由夫妻各自所有（§1017I），正確。","婚前財產於婚姻關係存續中所生孳息，視為婚後財產（§1017 II），正確。"],"tr":""},{"id":"h:105-35","p":"h","src":"105年第35題","sec":"E2","stem":"下列何者屬於剩餘財產分配請求權之標的財產？","opts":["婚前財產","婚後之薪資所得","婚後因繼承所得之財產","婚後所取得之慰撫金"],"ok":[1],"ex":["婚前財產不是婚後財產，不在剩餘財產分配範圍（§1030-1I）。","婚後薪資為婚後取得之財產，且非繼承、無償取得或慰撫金，屬剩餘財產分配標的（§1030-1I）。","因繼承或其他無償取得之財產排除分配（§1030-1I①）。","慰撫金排除分配（§1030-1I②）。"],"tr":""},{"id":"h:105-36","p":"h","src":"105年第36題","sec":"E3","stem":"隱瞞已婚之乙女與甲同居數年後，某日生下丙隨即離甲而去，甲獨力扶養丙，俟丙 19 歲生日，甲對丙告知其生母為乙，當日丙因思母心切隨即趕赴乙家要求相認，相認時刻被乙女丈夫丁撞見，一切東窗事發，乙丁大吵。過了 2 年後，上述相關人等決心為此事作一了結。試問此刻以下何人有資格提起婚生否認之訴？","opts":["甲","乙","丙","丁"],"ok":[2],"ex":["甲為生父，並非夫妻之一方或子女，不得依§1063II提起婚生否認之訴。","乙為母，為夫妻之一方，但自知悉子女非婚生起已逾2年，除斥期間經過。","依考試當時舊法（20歲成年），丙19歲知悉時尚未成年，依§1063 III但書得於成年後2年內提起，題設時仍在期間內。【現行法】112.1.1起18歲成年，丙19歲知悉時已成年，不適用但書，只能自知悉時起2年內提起（§1063 III本文）；題設「過了2年後」，丙的期間已屆滿。依現行法甲（非夫妻之一方或子女）、乙、丁、丙四人均不能再提起，本題沒有正確選項；官方答案C是依出題年舊法。","丁為夫，自知悉子女非婚生起已逾2年，除斥期間經過。"],"tr":""},{"id":"h:105-37","p":"h","src":"105年第37題","sec":"E4","stem":"依我國民法之規定，當胎兒為繼承人時，他繼承人如未保留胎兒之應繼分而分割遺產者，其分割行為之效力如何？","opts":["有效","無效","得撤銷","效力未定"],"ok":[1],"ex":["未保留胎兒應繼分而分割遺產，違反§1166 I（非保留其應繼分，他繼承人不得分割遺產）之強行規定，分割行為無效，並非有效。","分割行為無效（§1166 I、§71），正確。","並非「得撤銷」，法律效果為無效。","並非效力未定，無須經胎兒追認。"],"tr":""},{"id":"h:105-38","p":"h","src":"105年第38題","sec":"E3","stem":"甲乙為夫妻育有二女丙與丁，甲為傳香火認識已婚之戊女，同居一年後生下己男，甲把己接回家中同住將其養育成人，但丙與己相處極為不睦，丙亦曾對己口出穢言且被判刑確定，某日丙與己再起爭執，己一時失手將丙刺成重傷，丁見狀，起身亦把己刺成重傷，丁與己嗣後雙雙被判重刑確定，乙為此人倫悲劇在眾人前以不堪字眼侮辱甲，甲亦默默承受，但隔日即因傷心過度辭世。試問本案中，何人對甲無繼承權？","opts":["乙","丙","丁","己"],"ok":[3],"ex":["乙雖公開侮辱甲，但甲默默承受而未表示其不得繼承，不符§1145I⑤，乙不喪失繼承權（且乙為配偶）。","丙僅辱罵己，對象不是被繼承人甲，亦未致人於死，不符§1145I①，有繼承權。","丁刺傷己，己非甲之應繼承人，不符§1145I①「對於被繼承人或應繼承人」之要件，有繼承權（§1145I①含「雖未致死因而受刑之宣告」，未致死本身不是不喪失之理由）。","己為已婚之戊所生，推定為戊之夫之婚生子女（§1063I），在未經否認前與甲無法律上父子關係，視為認領（§1065I）僅適用於非婚生子女，故己對甲無繼承權。"],"tr":""},{"id":"h:105-39","p":"h","src":"105年第39題","sec":"E4","stem":"有關拋棄繼承之敘述，下列何者正確？","opts":["向戶政機關為之","得以言詞或書面為之","於被繼承人死亡之時起 3 個月內為之","繼承之拋棄，溯及於繼承開始時發生效力"],"ok":[3],"ex":["拋棄繼承應以書面向法院為之，非向戶政機關（§1174II）。","拋棄繼承須以書面向法院為之，不得以言詞（§1174II）。","期間為知悉其得繼承之時起3個月內（§1174II），不是自死亡時起。","繼承之拋棄溯及於繼承開始時發生效力（§1175），正確。"],"tr":""},{"id":"h:105-40","p":"h","src":"105年第40題","sec":"E4","stem":"下列那種情形，甲所立的遺囑為有效？","opts":["甲 6 歲，經由其父母之代理而立之遺囑","甲 15 歲，預立遺囑後，得其父母之追認","甲 10 歲，但已得其父母之同意而立之遺囑","甲 17 歲，未得其父母之允許或承認而立之遺囑"],"ok":[3],"ex":["6歲為無行為能力人，不得為遺囑（§1186I）；遺囑為須本人親自為之的身分行為，亦不得由父母代理，代理所立之遺囑無效。","未滿16歲不得為遺囑（§1186II），事後追認亦無用。","10歲依§13為限制行為能力人，但§1186II但書規定未滿16歲者不得為遺囑；此為年齡門檻，不是「欠缺同意」的問題，故即使父母事前同意亦無效。","17歲為限制行為能力人，無須法定代理人允許即可為遺囑（§1186II），為有效。"],"tr":""},{"id":"h:104-1","p":"h","src":"104年第1題","sec":"A5","stem":"甲與乙通謀虛偽意思表示，將甲所有之 A 地賣予乙並移轉登記為乙所有。嗣後乙擅自將 A 地出賣丙，並完成移轉登記，惟丙不知甲、乙通謀虛偽意思表示之事。下列敘述，何者正確？","opts":["甲與乙間關於 A 地之買賣契約效力未定","甲與乙間關於 A 地之買賣契約無效","甲與乙間關於 A 地之買賣契約有效","乙與丙間關於 A 地之買賣契約無效"],"ok":[1],"ex":["通謀虛偽意思表示依§87Ⅰ為「無效」，並非效力未定。","甲乙通謀虛偽，依§87Ⅰ，其意思表示無效，買賣契約無效；但依但書，不得以此無效對抗善意第三人丙，丙仍得取得A地所有權，正確。","通謀虛偽之意思表示，甲乙間契約無效，並非有效。","乙與丙間之買賣契約（債權行為）本身成立並有效（兩造意思表示合致），且丙為善意，依§87Ⅰ但書受到保護，物權移轉亦對丙有效，故乙丙間買賣契約並非無效。"],"tr":""},{"id":"h:104-2","p":"h","src":"104年第2題","sec":"D2","stem":"承上題，嗣後丙將 A 地又賣給丁，並完成移轉登記。A 地之所有權應屬何人？","opts":["甲","乙","丙","丁"],"ok":[3],"ex":["甲已將A地以登記為生效要件之方式處分，物權變動依§758 I以登記為準，登記後甲不再是所有人。","乙若僅取得買賣之債權，未經登記不生物權變動（§758 I），不能取得所有權。","丙已將A地移轉登記予丁，丙因登記移轉而喪失所有權。","不動產物權依法律行為變動須經登記始生效力（§758 I）；丁已完成移轉登記，取得A地所有權。"],"tr":""},{"id":"h:104-3","p":"h","src":"104年第3題","sec":"A5","stem":"甲對乙表示，如不贈與家傳骨董，即告發其走私之事，乙被迫贈與之。該贈與契約之效力為：","opts":["有效","無效","得撤銷","效力未定"],"ok":[0,2],"ex":["受脅迫所為之意思表示於撤銷前仍屬有效，撤銷後始視為自始無效（§92、§114Ⅰ），故答「有效」亦有依據。","受脅迫之贈與並非當然無效，須經撤銷才失效。","被脅迫而為意思表示者，表意人得撤銷之（§92Ⅰ）。","效力未定適用於限制行為能力人、無權代理等情形，不適用於脅迫。"],"tr":""},{"id":"h:104-4","p":"h","src":"104年第4題","sec":"A4","stem":"下列契約，何者不得聲請法院撤銷？","opts":["因急迫輕率無經驗而訂立週年利率高達 60%之高利貸契約","乘他人急迫輕率無經驗而訂立之婚約","債務人所訂立有害及債權之贈與契約","因被詐欺或被脅迫而訂立之離婚協議"],"ok":[1],"ex":["§74 乘他人急迫、輕率、無經驗而為顯失公平之財產給付約定，法院得撤銷或減輕；年利率60%之高利貸屬之。","§74 僅適用於財產上給付之法律行為，婚約為身分行為，不適用，不得依§74 撤銷。","§244Ⅰ 債務人所為無償行為有害及債權者，債權人得聲請法院撤銷。","因被詐欺或被脅迫而為離婚協議，得依§92 撤銷其意思表示。"],"tr":""},{"id":"h:104-5","p":"h","src":"104年第5題","sec":"A6","stem":"甲授權乙為代理人，由乙代為與丙協議及締結房屋買賣事宜。下列敘述，何者正確？","opts":["乙明知該房屋有瑕疵仍與丙締約時，甲得對丙主張瑕疵擔保責任","乙受甲之授權後，得再另受丙之授權，同時代理甲、丙締結買賣契約","乙死亡時，代理權消滅，不能為繼承之標的","乙不得為限制行為能力人"],"ok":[2],"ex":["本題以甲為買受人。依§105，代理人之意思表示因明知或可得而知其事情致效力受影響時，其事實之有無就代理人（乙）決之（白話：知不知情看代理人）；乙締約時明知房屋有瑕疵，等同買受人知情，依§355Ⅰ（買受人於契約成立時知其物有瑕疵者，出賣人不負擔保之責），甲不得對丙主張瑕疵擔保。","§106：代理人非經本人許諾，不得既為第三人之代理人而為本人與第三人之法律行為（雙方代理禁止；但專履行債務者例外）。乙受甲授權後，若要再受丙授權同時代理雙方，須經本人（甲、丙）許諾，並非當然可為。","§108Ⅰ：代理權之消滅，依其所由授與之法律關係定之；授權通常基於委任，依§550委任關係因當事人一方死亡而消滅（契約另有訂定或性質不能消滅者除外），故乙死亡時代理權消滅。代理權專屬於代理人本人，不能成為繼承標的，正確。","§104：代理人所為或所受意思表示之效力，不因其為限制行為能力人而受影響，代理人不以有完全行為能力為必要，故乙得為限制行為能力人，本選項錯誤。"],"tr":""},{"id":"h:104-6","p":"h","src":"104年第6題","sec":"C4","stem":"乙與甲約定，於甲大學畢業時，乙將贈與甲汽車一輛。此項贈與契約所附約款之性質如何？","opts":["終期","始期","停止條件","解除條件"],"ok":[2],"ex":["終期是指到某一確定期日後法律行為「失效」，本題是到畢業時開始生效，非失效，並非終期。","始期是指到確定期日後法律行為開始生效；「大學畢業」是否發生並不確定（可能退學、休學、未能畢業），故非「確定」到來的期日，非始期。","「大學畢業」為「不確定是否會發生」之事實，符合條件之定義；其成就時使贈與「開始生效」，故為停止條件（§99Ⅰ），正確。","解除條件是條件成就時使「已生效之法律行為失效」；本題是條件成就才生效，非失效，非解除條件。"],"tr":""},{"id":"h:104-7","p":"h","src":"104年第7題","sec":"B2","stem":"債權人甲不得代位其債務人乙，行使乙對第三人丙之何項權利？","opts":["不動產登記請求權","扶養請求權","實行抵押權","提起訴訟之權利"],"ok":[1],"ex":["不動產登記請求權具有財產性，可代位行使，A可代位。","扶養請求權屬「一身專屬權」（§242但書），甲不得代位乙行使對丙之扶養請求，正確，為應選答案。","抵押權之實行係財產性權利，可代位行使，C可代位。","訴訟行為（如起訴請求）係保全財產之行為，原則上可代位行使，D可代位。★一身專屬權不得代位（§242但書）：扶養請求、離婚請求、撤銷婚姻等身分權。"],"tr":""},{"id":"h:104-8","p":"h","src":"104年第8題","sec":"B2","stem":"下列關於因債務不履行而解除契約之敘述，何者正確？","opts":["債權人解除契約者，即不得再向債務人請求損害賠償","因債務人給付不能而為解除時，債權人仍須對債務人為履行之催告始得解除","如債權人為履行之催告時未定期間，催告後經相當期間，仍得逕為解除","因解除而互負回復原狀義務時，債務人不得主張同時履行抗辯權"],"ok":[2],"ex":["§260：解除權之行使，不妨礙損害賠償之請求。","§256：給付不能時，債權人得逕行解除，無須催告。","§254 催告未定期限者，催告後經相當期間仍不履行，債權人得解除契約（實務見解）。","§261：解除後回復原狀準用同時履行規定（§264），債務人得主張同時履行抗辯。"],"tr":""},{"id":"h:104-9","p":"h","src":"104年第9題","sec":"A4","stem":"甲、乙締結由甲出售其所有之建物予乙之買賣契約，但該建物實際上已於甲、乙締約前一日因火災而全部燒毀。該買賣契約效力如何？","opts":["效力未定","乙得解除契約","乙得撤銷契約","無效"],"ok":[3],"ex":["效力未定用於限制行為能力或無權代理情形，與本題標的不能問題無關。","契約因自始客觀不能而無效，已無法律效力，無須再以「解除」方式終止（解除是對有效契約之終止手段）。","撤銷用於意思表示瑕疵（如詐欺、脅迫、錯誤），本題並無意思表示瑕疵。","建物於締約前已全部燒毀，給付標的自始即客觀不能（任何人皆無法給付），依§246Ⅰ，以不能之給付為契約標的者，其契約無效，正確。"],"tr":""},{"id":"h:104-10","p":"h","src":"104年第10題","sec":"B2","stem":"甲、乙締結由甲出售 10 打市面上普遍流通之紅酒予乙之買賣契約，甲依約於約定期日將標的物運送至乙之住所地時，乙以自己尚未備妥儲藏場所為由拒絕受領。甲不得已乃將物品運回繼續保管，卻於保管期間中該等紅酒全數破裂。下列敘述，何者正確？","opts":["即使紅酒之破裂係因甲之重大過失所致，乙亦不得向甲主張損害賠償","如紅酒之破裂係因不可抗力所致，乙之價金債務消滅","甲之種類債務尚未特定","甲之債務成為給付不能"],"ok":[3],"ex":["§237：債權人受領遲延中，債務人僅就故意或重大過失負責；破裂若因甲重大過失，乙仍得請求賠償。","受領遲延中危險已移轉債權人負擔，不可抗力致標的物滅失，乙之價金債務並不消滅。","甲已將紅酒運至乙住所為現實提出（§235），必要行為完成，依 §200 II 種類之債已特定。","種類之債已特定為該10打紅酒，全數破裂致標的物滅失，甲之債務成為給付不能。"],"tr":""},{"id":"h:104-11","p":"h","src":"104年第11題","sec":"A1","stem":"甲為成年人，因精神障礙而受監護之宣告，某日甲精神回復而有識別能力，向乙購買手機一只，惟因過失打破櫃台玻璃。下列敘述，何者正確？","opts":["甲與乙之手機買賣契約無效，關於打破櫃台玻璃不成立侵權行為","甲與乙之手機買賣契約有效，關於打破櫃台玻璃成立侵權行為","甲與乙之手機買賣契約無效，關於打破櫃台玻璃成立侵權行為","甲與乙之手機買賣契約效力未定，關於打破櫃台玻璃不成立侵權行為"],"ok":[2],"ex":["侵權行為以「識別能力」（有識別其行為之責任能力）而非「行為能力」為判斷基礎，甲精神回復時雖有識別能力，仍可成立侵權行為責任，前半段買賣契約無效正確，但後半段否定侵權行為成立錯誤。","受監護宣告之人為無行為能力人（§15），其意思表示無效（§75），買賣契約無效，前半段錯誤。","受監護宣告之人為無行為能力人，意思表示無效，買賣契約無效；但侵權行為以識別能力為要件（§187），甲精神回復有識別能力時，打破玻璃之行為仍可成立侵權行為（§184），正確答案。","買賣契約無效（非效力未定），且侵權行為可成立，兩者均描述錯誤。"],"tr":""},{"id":"h:104-12","p":"h","src":"104年第12題","sec":"C5","stem":"甲將其對乙之債權讓與予丙。下列何者會使此債權讓與無效？","opts":["甲乙間有不得讓與之特約，但丙為善意之情形","甲未將證明債權之文件交付予丙","乙不同意甲丙間之債權移轉行為","該債權係甲為維持生活所必須之債權"],"ok":[3],"ex":["§294 II：不得讓與之特約不得對抗善意第三人，丙善意，讓與有效。","§296 交付證明文件為讓與人義務，未交付不影響讓與效力。","§297：債權讓與無須債務人同意，只需通知，乙不同意不影響效力。","§294 I(3)：禁止扣押之債權不得讓與，維持生活所必須之債權屬之，讓與無效。"],"tr":""},{"id":"h:104-13","p":"h","src":"104年第13題","sec":"B3","stem":"甲、乙、丙三人對丁負有各自分擔比例為三分之一之 300 萬元連帶債務。下列敘述，何者正確？","opts":["連帶債務罹於消滅時效後，甲對丁為債務之承認時，該中斷時效之效力及於乙、丙","甲以時價 300 萬元之珠寶對丁為代物清償時，如事前未得乙、丙同意，甲不得向乙、丙求償","甲對丁清償 300 萬元時，如乙無資力，則甲得對丙求償 200 萬元","甲對丁先清償 90 萬元時，甲得對乙、丙分別求償 30 萬元"],"ok":[3],"ex":["§279：承認非絕對效力事項，連帶債務人之一承認僅對該人生效，不及於乙、丙。","代物清償為 §274 絕對效力事由，甲清償後依 §281 I 即得向乙、丙求償，無須事前同意。","§282 I：乙無資力之100萬由甲、丙平均分擔，甲得向丙求償100萬加50萬＝150萬，非200萬。","§280、§281 I：甲清償之90萬依平均分擔比例（各1/3），得向乙、丙各求償30萬。"],"tr":""},{"id":"h:104-14","p":"h","src":"104年第14題","sec":"B2","stem":"甲賣 A 屋給乙，尚未移轉交付，嗣後 A 屋因可歸責於丙之事由失火滅失，然甲對 A 屋投有火災保險。下列敘述，何者錯誤？","opts":["甲得主張免給付義務，乙亦得主張免對待給付","此為給付不能，甲、乙間之買賣契約無效","乙得履行對待給付後，請求甲讓與對失火肇事者丙之損害賠償請求權","乙得依民法第 225 條第 2 項請求甲交付保險金"],"ok":[1],"ex":["§225 I：因不可歸責於債務人之事由致給付不能，債務人免給付義務；乙依 §266 I 亦免對待給付。","給付不能為嗣後不能，契約原本有效，僅債務人免給付義務；§246 契約無效指訂約時即不能。","§225 II：債務人對第三人有損害賠償請求權者，債權人得請求讓與，乙須履行對待給付。","§225 II：債權人得請求交付債務人所受領之賠償物，本題以保險金屬代償利益作答（學說對保險金是否屬之有爭議）。"],"tr":""},{"id":"h:104-15","p":"h","src":"104年第15題","sec":"B6","stem":"甲有 A 車一輛借乙使用，乙因滑手機未注意車前狀況，而與丙酒駕闖紅燈之 B 車相撞，乙重傷，A 車全毀。下列敘述，何者正確？","opts":["甲若向丙請求 A 車之損害賠償，丙不得主張甲就 A 車投有保險，應扣除保險金","乙及丙對 A 車之損害，應負連帶賠償責任","乙母可向丙請求精神慰藉金","乙向丙請求賠償時，丙不得主張因乙與有過失，應減輕賠償金額"],"ok":[0,1],"ex":["保險金為保險契約對價所得，不屬損益相抵之利益，加害人丙不得以甲投保為由扣除。","乙之過失與丙之過失均為A車全毀之原因，構成共同加害（§185 I），應連帶賠償。","乙母非被害人，僅於身分法益被侵害且情節重大時方得依 §195 III 請求；乙僅重傷，並非當然得請求。","§217 I：被害人與有過失，法院得減輕賠償金額或免除，丙得主張乙與有過失（乙滑手機未注意）。"],"tr":""},{"id":"h:104-16","p":"h","src":"104年第16題","sec":"C4","stem":"甲因長期出國，將其所有名貴青花瓷一只交由乙代為保管。乙向丙偽稱該瓷為己有，欲以該瓷與丙所有之名車互易，雙方達成讓與合意並互相交付完畢。下列敘述，何者錯誤？","opts":["該互易契約有效","丙得主張因善意受讓而取得該只青花瓷之所有權","丙移轉名車所有權之行為於甲承認之前為效力未定","甲得向乙請求損害賠償"],"ok":[2],"ex":["互易準用買賣（§398），負擔行為不以處分權限為要件，契約有效。","乙無處分權，丙善意受讓，並受交付，依 §948 善意取得所有權（甲係自願交付，無 §949 例外）。","丙處分的是自己所有之名車，為有權處分，生效不須他人承認；效力未定者是無權處分（乙之處分）。","乙無權處分致甲喪失所有權，甲得依 §184 I 前段或 §179 向乙請求損害賠償或返還利益。"],"tr":""},{"id":"h:104-17","p":"h","src":"104年第17題","sec":"B1","stem":"下列關於抵銷之敘述，何者正確？","opts":["甲對乙有金錢債權、乙對甲有因侵權行為而生之損害賠償請求權時，乙不得對甲主張抵銷","甲對乙有金錢債權、乙對甲有禁止扣押之金錢債權時，甲不得對乙主張抵銷","甲對乙之金錢債權及乙對甲之金錢債權的履行地不同時，乙不得對甲主張抵銷","甲對乙之金錢債權及乙對甲之金錢債權的履行地不同時，甲不得對乙主張抵銷"],"ok":[1],"ex":["§339 禁止抵銷的是「故意侵權行為之債務人」，本題乙為債權人，乙得主張抵銷。","§338：禁止扣押之債，其債務人不得主張抵銷；甲為禁止扣押債權之債務人，不得抵銷。","§336：清償地不同亦得抵銷，僅主張人應賠償他方因此所生之損害。","§336：清償地不同亦得抵銷，甲可主張抵銷但應賠償損害。"],"tr":""},{"id":"h:104-18","p":"h","src":"104年第18題","sec":"C4","stem":"下列關於民法規定之贈與契約的敘述，何者正確？","opts":["為履行道德上之義務的贈與契約，不得撤銷","為確認贈與意思，贈與契約須以書面定之","贈與契約為無償契約，贈與人不負瑕疵擔保責任","贈與人就其重大過失，對於受贈人不負給付不能之責任"],"ok":[0],"ex":["§408 II：為履行道德上義務之贈與，不得撤銷。","贈與為不要式契約，口頭即可成立（§406）；書面亦不影響撤銷權（§408 II 例外僅限經公證或為履行道德上義務之贈與）。","§411：贈與人原則上不負瑕疵擔保責任，但故意不告知或保證無瑕疵者例外，選項說法絕對化。","§410：贈與人就故意或重大過失仍須負給付不能責任。"],"tr":""},{"id":"h:104-19","p":"h","src":"104年第19題","sec":"C2","stem":"下列關於租賃之敘述，何者錯誤？","opts":["租金，得以金錢或租賃物之孳息充之","不動產之租賃契約，其期限逾一年者，應以字據訂立之","未以字據訂立之不動產之租賃契約，無效","租用基地建築房屋者，承租人於契約成立後，得請求出租人為地上權之登記"],"ok":[2],"ex":["§421 Ⅱ：租金得以金錢或租賃物之孳息充之，正確。","§422：不動產之租賃契約，其期限逾一年者，應以字據訂立之，正確。","§422：未以字據訂立者，『視為不定期限之租賃』，契約仍有效而非無效；本選項說『無效』與條文不符，錯誤，為應選答案。","§422-1：租用基地建築房屋者，承租人於契約成立後，得請求出租人為地上權之登記，正確。"],"tr":""},{"id":"h:104-20","p":"h","src":"104年第20題","sec":"C2","stem":"甲出租 A 屋給乙。下列敘述，何者正確？","opts":["租賃期間內，甲不願修繕 A 屋漏水之水管，乙得不經催告，逕行終止契約","A 屋因乙未盡善良管理人之注意致失火燒毀，乙應負損害賠償責任","若 A 屋是輻射屋，乙雖明知仍承租之，其後乙仍得以其危及健康而終止契約","依民法第 347 條，租賃契約準用買賣契約「物之瑕疵擔保」規定，故甲依法僅擔保 A 屋於交付時無瑕疵即可"],"ok":[2],"ex":["§430：出租人未修繕，承租人須定相當期限催告，逾期仍不修繕才得終止契約，不得逕行終止。","§434：承租人失火僅就重大過失負責，未盡善良管理人注意尚不足以負責。","§424：租賃物有危及承租人健康之瑕疵者，承租人雖於訂約時已知，仍得終止契約。","§423：出租人須於租賃關係存續中保持租賃物合於約定使用收益之狀態，並非僅擔保交付時無瑕疵。"],"tr":""},{"id":"h:104-21","p":"h","src":"104年第21題","sec":"B3","stem":"關於民法規定之保證契約。下列敘述，何者正確？","opts":["債權人第一次請求清償時，僅得向主債務人請求","保證人不得僅保證主債務人之債務的一部分","保證契約由債權人及保證人口頭約定即可成立","主債務人所有之抗辯，非經其同意，保證人不得主張"],"ok":[2],"ex":["債權人可依§745 直接向保證人請求，僅保證人得主張先訴抗辯，非僅得向主債務人請求。","保證人可僅就主債務一部分為保證，保證債務不得重於主債務（§741）。","保證契約為不要式契約，口頭即可成立（§756-1 II 之書面要件係規範人事保證，與一般保證無關）。","§742 I：主債務人所有之抗辯，保證人得主張之，無須主債務人同意。"],"tr":""},{"id":"h:104-22","p":"h","src":"104年第22題","sec":"D6","stem":"甲有名筆一枝，其子乙將甲之筆賣給知情之丙，乙、丙於民國 104 年 9 月 28 日簽訂買賣契約，惟尚未交付。嗣後，乙又於 104 年 10 月 10 日將甲之筆賣給不知情之丁並交付之。甲於 104 年 11 月 1 日死亡，乙是甲之唯一繼承人。試問何人取得該筆之所有權？","opts":["甲","乙","丙","丁"],"ok":[3],"ex":["乙無處分權出賣，丁善意受讓並受交付，依§948取得所有權，甲因而喪失所有權。","丁於10月10日受交付時，依§801、§948 善意取得所有權，甲同時喪失所有權；11月1日甲死亡時，該筆已不屬於遺產，乙無從繼承取得。","丙僅與乙訂有買賣之債權契約，筆尚未交付，不取得所有權（§761）。","丁不知情且受現實交付，依善意受讓規定（§801、§948）取得該筆所有權。"],"tr":""},{"id":"h:104-23","p":"h","src":"104年第23題","sec":"D3","stem":"甲遺失價值拾萬元之金戒指一只，被大學生乙拾得並依法招領。下列敘述，何者錯誤？","opts":["自通知或最後招領之日起逾六個月，若甲未認領者，由乙取得該戒指所有權","乙於受領取通知或公告後六個月內未領取者，該戒指歸屬於保管地之地方自治團體","甲認領該戒指時，乙可向甲請求壹萬元報酬","乙對甲之報酬請求權，因六個月間不行使而消滅"],"ok":[1],"ex":["自通知或最後招領之日起逾六個月，遺失人未認領者，拾得人取得所有權（§807 I）。","歸屬保管地地方自治團體者，是拾得人於受通知或公告後三個月內未領取之情形，並非六個月（§807 II）。","遺失人認領時，拾得人得請求報酬，但不得超過拾得物價值十分之一（§805 II），價值十萬元則上限為一萬元。","拾得人之報酬請求權，因六個月間不行使而消滅（§805 IV）。"],"tr":""},{"id":"h:104-24","p":"h","src":"104年第24題","sec":"D3","stem":"承上題，下列何種情形，乙不得向甲請求報酬？","opts":["甲為退休教師，依法請領退休金度日","乙在捷運車廂內座椅上撿到甲的戒指","乙在公園座椅上撿到甲的戒指","乙未於七日內通知、報告或交存拾得物"],"ok":[3],"ex":["領取退休金不屬§805-1所列不得請求報酬之情形，乙仍得請求。","乙為一般人，非場所管理人或受僱人，在捷運車廂拾得仍得請求報酬（§805-1 第1款僅限管理人或受僱人）。","乙在公園拾得，亦非管理人或受僱人，並非不得請求報酬之人。","拾得人未於七日內通知、報告或交存拾得物者，不得請求報酬（§805-1 第2款）。"],"tr":""},{"id":"h:104-25","p":"h","src":"104年第25題","sec":"D3","stem":"關於添附，下列敘述，何者正確？","opts":["動產因附合而為不動產之重要成分者，動產及不動產所有人，共有該動產所有權","動產與他人之動產附合，非毀損不能分離，或分離需費過鉅者，各動產所有人，按其動產附合時之比例，比例高者取得合成物之所有權","動產與他人之動產混合，不能識別，或識別需費過鉅者，拍賣之","附合之動產，有可視為主物者，該主物所有人，取得合成物之所有權"],"ok":[3],"ex":["動產因附合成為不動產重要成分者，不動產所有人取得動產所有權（§811），非共有。","動產附合不能分離者，各所有人按附合時之價值共有合成物（§812 I），不是比例高者取得。","動產混合不能識別者，準用附合規定，由各所有人按價值共有（§813、§812 I），並非拍賣。","附合之動產有可視為主物者，主物所有人取得合成物之所有權（§812 II）。"],"tr":""},{"id":"h:104-26","p":"h","src":"104年第26題","sec":"D2","stem":"甲將其單獨所有之土地的特定部分出售予乙後，如該土地無不可分割之限制時，乙得如何請求甲履行其移轉所有權之義務？","opts":["請求甲移轉登記按該特定部分計算之土地應有部分，與甲共有該土地","請求甲將該特定部分分割後移轉登記與乙","乙得選擇請求甲為上述(A)或(B)之任一種移轉登記方式","本買賣契約欠缺確定性與可能性而無效，乙不得請求甲為移轉登記"],"ok":[1],"ex":["買賣標的為特定部分，並非移轉應有部分；單獨所有人不能以應有部分移轉代替履行。","買賣標的特定部分之土地，契約有效；甲須先辦理分割，再將該特定部分移轉登記予乙（§348 I、§758）。","甲不須讓乙選擇履行方式，應依標的特定部分之買賣履行，須先分割。","特定部分之範圍可得確定，契約並非不確定而無效。"],"tr":""},{"id":"h:104-27","p":"h","src":"104年第27題","sec":"D2","stem":"甲、乙、丙三人各有應有部分三分之一分別共有 A 地。下列敘述，何者正確？","opts":["甲得以其應有部分供第三人丁設定不動產役權","三人協議分割達成合意之履行請求權，有消滅時效之適用","甲須以共有人過半數及應有部分合計過半數之同意，始得請求分割","甲得以共有人過半數及應有部分合計過半數之同意，以 A 地供丁設定抵押權"],"ok":[1],"ex":["設定不動產役權屬處分共有物負擔，須全體共有人同意（§819 II），甲不得單以應有部分設定。","協議分割所生之履行請求權屬請求權，適用十五年消滅時效（§125）；§824 II 也明文規定分割方法「於協議決定後因消滅時效完成經共有人拒絕履行者」，法院得因任何共有人之請求裁判分割。","各共有人得隨時請求分割（§823 I），無須共有人過半數同意。","以共有物設定抵押權屬設定負擔，須得全體共有人同意（§819 II），非多數決事項。"],"tr":""},{"id":"h:104-28","p":"h","src":"104年第28題","sec":"D2","stem":"關於區分所有建築物，下列敘述，何者錯誤？","opts":["稱區分所有建築物者，謂數人區分一建築物而各專有其一部，就專有部分有單獨所有權，並就該建築物及其附屬物之共同部分共有之建築物","區分所有建築物共有部分，指區分所有建築物專有部分以外之其他部分及不屬於專有部分之附屬物","區分所有建築物共有部分除法律另有規定外，不得經規約之約定，供區分所有建築物之特定所有人使用","區分所有建築物專有部分得經其所有人之同意，依規約之約定，供區分所有建築物之所有人共同使用"],"ok":[2],"ex":["區分所有建築物之定義如此規定（§799 I）。","共有部分指專有部分以外之其他部分及不屬於專有部分之附屬物（§799 II）。","共有部分除法律另有規定外，得經規約約定供特定所有人使用（§799 III），並非不得。","專有部分得經所有人同意，依規約之約定供共同使用（§799 III）。"],"tr":""},{"id":"h:104-29","p":"h","src":"104年第29題","sec":"D5","stem":"甲以其土地設定不動產役權於乙後，復以同一土地之一部分設定普通地上權於丙。丙之普通地上權的效力如何？","opts":["當然無效","當然有效、且其效力優先於乙之不動產役權","無妨害乙之不動產役權時，當然有效","乙、丙各自之用益物權的優先效力，由所有權人甲決定之"],"ok":[2],"ex":["後設定地上權並非無效（物權不衝突即並存），選項過於絕對，錯誤。","依物權「先設定者優先」原則，不動產役權（先設定）優先於地上權（後設定），並非地上權效力優先，選項錯誤。","後設定之地上權，「無妨害已設定不動產役權時」，地上權有效；若行使地上權會妨礙不動產役權，則地上權之行使受限，正確。","物權效力依法律規定（先設定優先），並非由所有人甲決定，選項錯誤。"],"tr":""},{"id":"h:104-30","p":"h","src":"104年第30題","sec":"D6","stem":"甲以 A 地設定抵押權於乙，擔保其對乙所負債務後，復將 A 地設定地上權於丙，由丙於 A 地上建築房屋。甲屆期無力清償債務，乙實行對 A 地之抵押權時，抵押權人實行抵押權受有影響者。下列敘述，何者正確？","opts":["法院得除去丙之地上權，乙於必要時並得聲請法院將建築物與土地併付拍賣","法院得除去丙之地上權，但乙僅得聲請法院拍賣土地","法院不得除去丙之地上權，但乙於必要時，得聲請法院將地上權及建築物與土地併付拍賣","法院不得除去丙之地上權，乙僅得聲請法院拍賣土地"],"ok":[0],"ex":["抵押權設定後才成立之地上權，抵押權人實行受影響者，法院得除去之（§866 II），並得於必要時聲請將丙所建建築物與土地併付拍賣（§877 II 準用 I；但對建築物價金無優先受償權）。","乙於必要時亦得聲請將建築物與土地併付拍賣（§877 II），不限於拍賣土地。","設定在後之地上權，法院得除去（§866 II）。","法院得除去丙之地上權，且乙得聲請併付拍賣建築物。"],"tr":""},{"id":"h:104-31","p":"h","src":"104年第31題","sec":"C2","stem":"乙所有 A 地及建造於 A 地上之 B 屋。甲因其對乙之債權屆期未獲清償，乃向法院聲請拍賣 A 地，並由丙拍定。乙之 B 屋與丙取得之 A 地間的法律關係如何？","opts":["視為已有地上權之設定","視為在 B 屋得使用期限內，有租賃關係","推定在 B 屋得使用期限內，有租賃關係","丙得請求乙拆除 B 屋"],"ok":[0],"ex":["§838-1：土地與建物同屬一人，因強制執行拍賣使土地、建物拍定人各異時，視為已有地上權之設定。","拍賣情形依 §838-1 為地上權而非租賃；§425-1 租賃推定適用於讓與情形。","拍賣時為「視為」地上權，並非「推定」租賃。","因已視為有地上權，丙不得請求拆屋。"],"tr":""},{"id":"h:104-32","p":"h","src":"104年第32題","sec":"D6","stem":"下列關於最高限額抵押權之敘述，何者正確？","opts":["為避免法律關係複雜，最高限額抵押權不得共有","原債權確定前，抵押權人與抵押人得約定變更其債務人","最高限額抵押權人得讓與其抵押權次序與後次序抵押權人","原債權確定前，抵押權人得任意分割最高限額抵押權之一部與他人"],"ok":[1],"ex":["依§881-9Ⅰ，最高限額抵押權得為數人共有（各共有人按債權額比例分配其得優先受償之價金），選項說「不得共有」錯誤。","依§881-3Ⅰ，原債權確定前，抵押權人與抵押人得約定變更§881-1Ⅱ 所定債權之範圍或其債務人，正確。","抵押權次序之讓與規定在§870-1（普通抵押權）；但§881-17 準用普通抵押權規定時，明文排除§870-1，所以最高限額抵押權人不得依該條讓與次序給後次序抵押權人，選項錯誤。","依§881-8Ⅰ，原債權確定前，抵押權人須「經抵押人之同意」，才能將最高限額抵押權之全部或分割其一部讓與他人，並非可任意為之，選項錯誤。"],"tr":""},{"id":"h:104-33","p":"h","src":"104年第33題","sec":"E1","stem":"甲之兄長乙與丙結婚，丙有兄長丁。關於四人之親系及親等關係，下列敘述，何者錯誤？","opts":["甲與乙為旁系血親二親等","乙與丁為旁系姻親二親等","甲與丙為旁系姻親二親等","甲與丁為旁系姻親二親等"],"ok":[3],"ex":["甲、乙為兄弟，同源於父母，為旁系血親二親等，敘述正確。","乙之配偶丙之兄長丁為配偶之血親，從配偶之親等（§970②），丙與丁二親等，故乙與丁為旁系姻親二親等，正確。","丙為甲之血親（兄）乙之配偶，屬血親之配偶（§969），依§970①從其配偶（乙）之親系及親等，為旁系姻親二親等，正確。","甲與丁之關係為「血親之配偶之血親」，不屬§969所列姻親三類（血親之配偶、配偶之血親、配偶之血親之配偶），兩人不是姻親，敘述錯誤。"],"tr":""},{"id":"h:104-34","p":"h","src":"104年第34題","sec":"E1","stem":"甲男婚外情，甲妻丁得知忿而與甲離婚，並完成登記。甲旋即與乙女於教堂牧師見證下，宣布結為夫妻，並請鄰近攤販丙、戊於結婚證書上簽名。下列敘述，何者正確？","opts":["甲、乙婚姻有效成立，因甲、乙有公開之儀式及二人以上之證人","甲、乙婚姻有效成立，因甲、丁已離婚，且甲、乙有結婚證書","甲、乙婚姻不成立，因甲不得同時與二人結婚","甲、乙婚姻不成立，因甲、乙未辦理結婚登記"],"ok":[3],"ex":["現行§982結婚要件為書面、二人以上證人簽名及戶政登記，不再以公開儀式為要件，故婚姻非因儀式而成立。","甲乙雖有結婚證書，但結婚仍須登記（§982），離婚登記完成也不能取代結婚登記。","甲與丁已離婚登記，並無重婚問題（§985），不是因此不成立。","結婚須有書面、二人以上證人簽名，並應由雙方向戶政機關為結婚登記（§982），本題未登記，不具備§982之方式，依§988①結婚無效（選項所稱「不成立」即指婚姻不生效力）。"],"tr":""},{"id":"h:104-35","p":"h","src":"104年第35題","sec":"E1","stem":"關於子女之監護，下列敘述，何者錯誤？","opts":["夫妻離婚者，對於未成年子女權利義務之行使或負擔，原則上由夫任之","夫妻未為協議或協議不成者，法院得依夫妻之一方、主管機關、社會福利機構或其他利害關係人之請求或依職權酌定之","協議不利於子女者，法院得依主管機關、社會福利機構或其他利害關係人之請求或依職權為子女之利益改定之","行使、負擔權利義務之一方未盡保護教養之義務或對未成年子女有不利之情事者，他方、未成年子女、主管機關、社會福利機構或其他利害關係人得為子女之利益，請求法院改定之"],"ok":[0],"ex":["離婚後未成年子女權利義務之行使或負擔，依協議由一方或雙方共同任之（§1055I），現行法已無「原則由夫任之」，敘述錯誤。","未為協議或協議不成者，法院得依夫妻之一方、主管機關、社會福利機構或其他利害關係人請求或依職權酌定（§1055I），正確。","協議不利於子女者，法院得依主管機關等請求或依職權為子女利益改定（§1055II），正確。","一方未盡保護教養義務或有不利情事，他方、子女、主管機關等得請求法院改定（§1055III），正確。"],"tr":""},{"id":"h:104-36","p":"h","src":"104年第36題","sec":"E3","stem":"年甫 16 歲之乙受第三人甲贈與房屋一間，乙之父母丙、丁均健在。下列敘述，何者正確？","opts":["丙、丁各得單獨管理該房屋","非得乙之同意，丙、丁不得使用該房屋","丙、丁得共同將該房屋出租收取租金","丙為清償自身之債務，得將該房屋出售並移轉所有權"],"ok":[2],"ex":["未成年子女之特有財產，由父母『共同』管理（§1088 Ⅰ），並非各得單獨管理。","父母對未成年子女之特有財產有使用、收益之權（§1088 Ⅱ 本文），無須子女同意；選項說『非得乙之同意不得使用』錯誤。","父母共同管理子女財產（§1088 Ⅰ），將房屋出租收取租金屬管理、收益行為，由丙、丁共同為之，正確。","§1088 Ⅱ 但書：非為子女之利益，不得處分其特有財產；丙為清償自己債務出售乙之房屋，並非為子女利益，不得為之。"],"tr":""},{"id":"h:104-37","p":"h","src":"104年第37題","sec":"E4","stem":"某富婆在其遺囑中載明將遺產全部留給自己之愛狗繼承。依我國法律規定，狗可否取得該遺產？","opts":["可以","不可以","由繼承人決定","由法院決定"],"ok":[1],"ex":["狗為物而非權利主體，無權利能力（§6），不能成為繼承人或受遺贈人。","§6：人之權利能力始於出生、終於死亡；狗是「物」不是人，也不是法人（§26），沒有權利能力，不能成為繼承人或受遺贈人，故不能取得遺產。","是否取得與繼承人意願無關，狗根本無權利能力。","亦非法院決定，法律已明定權利能力限於自然人與法人。"],"tr":""},{"id":"h:104-38","p":"h","src":"104年第38題","sec":"E4","stem":"甲、乙夫婦因重大車禍入院，夫甲於入院當日死亡、妻乙於次日死亡。甲有弟一人丙、乙有母丁及妹一人戊。甲之遺產總額為 720 萬元時，丙、丁、戊三人如何分配？","opts":["丙 240 萬元、丁 240 萬元、戊 240 萬元","丙 240 萬元、丁 300 萬元、戊 180 萬元","丙 360 萬元、丁 360 萬元、戊 0 元","丙 360 萬元、丁 180 萬元、戊 180 萬元"],"ok":[2],"ex":["甲死後乙繼承1/2（配偶與兄弟姊妹同繼承，§1144②），丙1/2；乙次日才死，乙所繼承部分成為乙之遺產，不是三等分。","丁不可得300萬元，乙之遺產由第二順位母丁單獨繼承，戊被排除。","甲遺產配偶乙1/2＝360萬、弟丙1/2＝360萬（§1144②）；乙死後所得360萬為其遺產，乙無子女，由第二順位母丁繼承（§1138②），第三順位妹戊不得繼承，故丙360、丁360、戊0。","戊為第三順位兄弟姊妹，因第二順位母丁存在不得繼承（§1138），不是180萬元。"],"tr":""},{"id":"h:104-39","p":"h","src":"104年第39題","sec":"E4","stem":"甲為 18 歲之人，未得法定代理人之允許，自書遺囑一份，寫明將所有財產全部捐給某公益團體。該遺囑之效力如何？","opts":["效力未定，因為未得法定代理人之允許","無效，因為未得法定代理人之允許","有效，因為無須法定代理人之允許","無效，因為內容違反特留分之規定"],"ok":[2],"ex":["18歲遺囑不是效力未定；遺囑為單獨行為，限制行為能力人無須法定代理人允許（§1186II），只須年滿16歲。","遺囑有效，不須允許，非無效。","依出題年舊法（20歲成年），18歲之甲為限制行為能力人，滿16歲即可自行立遺囑，不須法定代理人允許（§1186II）；現行法18歲已成年，有完全行為能力，當然更不須允許。自書遺囑只要符合§1190方式，即為有效。","侵害特留分只是繼承人得行使扣減權（§1225），遺囑並非無效。"],"tr":""},{"id":"h:104-40","p":"h","src":"104年第40題","sec":"E4","stem":"甲死亡後，其法定繼承人為其妻乙及兄丙、妹丁，計算法定繼承人特留分之基礎財產額為 480 萬元。丁之特留分金額為何？","opts":["60 萬元","40 萬元","30 萬元","20 萬元"],"ok":[1],"ex":["60萬元為應繼分1/4之1/2（120萬之一半）所得，誤用特留分比例（兄弟姊妹之特留分為應繼分1/3，§1223④）。","配偶乙1/2、兄丙1/4、妹丁1/4（§1144②）；丁應繼分120萬，兄弟姊妹特留分為應繼分三分之一（§1223④），120×1/3＝40萬元。","丁應繼分為480萬×1/4＝120萬（§1144②），兄弟姊妹特留分為應繼分1/3（§1223④），正確是40萬；30萬是把比例錯用成1/4（120萬×1/4）。","正確是丁應繼分120萬×1/3＝40萬（§1144②、§1223④），20萬不符此計算。"],"tr":""},{"id":"h:103-1","p":"h","src":"103年第1題","sec":"A4","stem":"依法律之規定，有使用文字之必要者，下列敘述何者正確？","opts":["須本人自寫，並親自簽名或蓋章","得不由本人自寫，但必須親自簽名或蓋章","如以指印、十字或其他符號代簽名者，在文件上，經一人簽名證明，亦與簽名生同等之效力","如以指印、十字或其他符號代簽名者，在文件上，經一人以指印、十字或其他符號代簽名者證明，亦與簽名生同等之效力"],"ok":[1],"ex":["§3Ⅰ 使用文字之必要者，得不由本人自寫，並非必須自寫。","§3Ⅰ 得不由本人自寫，但必須親自簽名（§3Ⅱ 以蓋章代簽名亦同效力）。","§3Ⅲ 以指印、十字或其他符號代簽名者，須經二人簽名證明，非一人。","§3Ⅲ 證明者須「簽名」證明，不是以指印、十字等符號代簽。"],"tr":""},{"id":"h:103-2","p":"h","src":"103年第2題","sec":"A4","stem":"關於形成權，下列敘述何者正確？","opts":["所謂形成權係指當事人得依據雙方自由意志，形成法律關係之權利","形成權的行使，原則上不得附條件或期限","形成權的行使期間，法律多設有消滅時效","同意權、抗辯權與解除權均屬形成權"],"ok":[1],"ex":["形成權是「單方」以意思表示使法律關係發生、變更或消滅的權利，並非雙方合意，如撤銷權、解除權皆為一方行使即生效力。","形成權行使如附停止條件，則不確定何時生效，影響相對人之法律地位，故原則上不得附條件或期限，正確。","形成權之行使期間通常設有「除斥期間」，而非消滅時效；兩者重要區別：消滅時效完成後，義務人得拒絕給付但債權不消滅；除斥期間經過，形成權本身即消滅，不得再行使。","同意權（如法定代理人承認契約）屬形成權；抗辯權（如同時履行抗辯）不屬形成權，而是拒絕相對人請求之防禦性權利；故並非三者皆屬形成權，敘述錯誤。"],"tr":""},{"id":"h:103-3","p":"h","src":"103年第3題","sec":"D1","stem":"下列何種權利屬於準物權？","opts":["農育權","商標權","漁業權","典權"],"ok":[2],"ex":["農育權屬於民法物權編明文之「用益物權」，並非準物權。","商標權屬「智慧財產權」（無形財產權），性質上非物權亦非準物權。","漁業權依漁業法規定設立，性質上準用物權規定（具有排他性、可讓與等物權特性），屬「準物權」，正確。★準物權：礦業權、漁業權、水權等，依特別法準用物權規定。","典權為民法物權編明文規定之物權（§911以下），屬真正物權，而非準物權。"],"tr":""},{"id":"h:103-4","p":"h","src":"103年第4題","sec":"A2","stem":"關於社團法人解散時，清算人的職務內容，下列何者正確？1了結現務 2收取債權 3清償債務 4變更章程","opts":["123","124","134","234"],"ok":[0],"ex":["§40Ⅰ 清算人職務為了結現務、收取債權、清償債務、移交賸餘財產；123皆屬之。","4變更章程非清算人職務，清算人不得變更章程。","4變更章程不屬清算職務，且此選項漏列2收取債權。","此選項漏列1了結現務，且包含非職務之4變更章程。"],"tr":""},{"id":"h:103-5","p":"h","src":"103年第5題","sec":"A1","stem":"下列何者不具有民法上之權利能力？","opts":["植物人","受破產宣告之法人","合夥","受監護宣告之自然人"],"ok":[2],"ex":["植物人仍屬自然人，權利能力始於出生終於死亡（§6），仍具權利能力。","受破產宣告之法人仍具有法人資格與權利能力，僅其財產之管理、處分權轉由破產管理人行使，法人本身並未消滅。","合夥（民法第667條以下）非法人，不具有獨立之民事主體資格，亦無民法上之「權利能力」，其以「合夥人全體」名義為法律行為，並非合夥本身為主體。這是常考的陷阱：合夥≠法人，無權利能力。","受監護宣告之自然人仍具有完全之權利能力，僅行為能力受到限制（被擬制為無行為能力人），兩者務必分清。"],"tr":""},{"id":"h:103-6","p":"h","src":"103年第6題","sec":"A1","stem":"關於住所，下列敘述何者正確？","opts":["限制行為能力人，因特定行為選定居所者，關於其行為，視為住所","法人，以其主事務所之所在地為住所","妻，以夫之住所為住所","一人同時僅得有兩住所"],"ok":[1],"ex":["官方答案為B，本選項依官方視為錯誤。但須知：§23「因特定行為選定居所者，關於其行為，視為住所」條文並未限定主體，A字面與§23相符。官方的理由應是：限制行為能力人依§21「以其法定代理人之住所為住所」，選定居所屬意思表示性質的行為，須得法定代理人允許（§77），不能單憑自己選定即「視為住所」。考場遇到不加主體的§23原文，仍判為正確。","依§29，法人以其主事務所之所在地為住所，正確。","此為民法舊制。現行§1002：夫妻之住所由雙方共同協議之，未協議或協議不成時得聲請法院定之，並非妻當然以夫之住所為住所。","§20Ⅱ明定「一人同時不得有兩住所」，故不是「僅得有兩住所」，更不是可有數個住所。"],"tr":""},{"id":"h:103-7","p":"h","src":"103年第7題","sec":"A3","stem":"關於天然孳息，下列敘述何者正確？","opts":["稱天然孳息者，謂利息、租金及其他因法律關係所得之收益","有收取天然孳息權利之人，按其權利存續期間內之日數，取得其孳息","物之成分及其天然孳息，於分離後，除法律另有規定外，仍屬於其物之所有人","抵押權之效力，及於抵押物扣押後抵押人就抵押物得收取之天然孳息。但抵押權人，非以扣押抵押物之事情，通知應清償天然孳息之義務人，不得與之對抗"],"ok":[2],"ex":["此為「法定孳息」（§69Ⅱ：利息、租金及其他因法律關係所得之收益）；「天然孳息」是果實、動物之產物及其他依物之用法所收穫之出產物（§69Ⅰ）。","按日數取得孳息是「法定孳息」的規則（§70Ⅱ）；天然孳息是有收取權利之人，在其權利存續期間內，取得與原物分離之孳息（§70Ⅰ），並非按日數。","依§766，物之成分及其天然孳息，於分離後，除法律另有規定外，仍屬於其物之所有人，正確。","選項混用規定。現行§863：抵押權效力及於抵押物扣押後自抵押物分離而得由抵押人收取之天然孳息；「得與義務人對抗須通知」的但書屬§864對「法定孳息」的規定。選項把法定孳息的規則與天然孳息的措辭拼在一起，不正確。"],"tr":""},{"id":"h:103-8","p":"h","src":"103年第8題","sec":"A4","stem":"18 歲之甲所為下列何種行為屬於無效？","opts":["買賣他人之物","買賣違章建築","被脅迫所締結之買賣契約","撤銷有關買賣之錯誤意思表示"],"ok":[3],"ex":["買賣他人之物，買賣契約（負擔行為）本身有效，出賣人負有取得並移轉標的物所有權之義務（§348）；處分行為才有效力未定問題（§118），故不是無效。","違章建築的買賣本身仍可成立有效的債權契約，並不屬於「無效」；且本題重點在18歲者的行為能力，而非標的物合法性。","被脅迫所為之意思表示，依§92表意人得撤銷，在撤銷前仍有效，不是當然無效。","撤銷錯誤的意思表示（§88）是形成權之行使，屬單獨行為；依出題年（103年）舊法成年為20歲，18歲之甲為限制行為能力人，未得法定代理人允許所為單獨行為，依§78無效（契約才是效力未定，§79）。現行法：§12「滿十八歲為成年」，18歲之甲已成年，其撤銷行為有效，D在現行法下不再是無效，本題在現行法下無正解。"],"tr":""},{"id":"h:103-9","p":"h","src":"103年第9題","sec":"B2","stem":"甲與乙於民國（下同）103 年 10 月 1 日簽訂買賣契約將自有古董錶以新臺幣（下同）20 萬元出售予乙，約定同年 11 月 1 日交付該錶予乙。但同年 10 月 5 日不知情的丙向甲表示願以 25 萬元之價格購買該古董錶，甲同意出售，並當場銀貨兩訖。關於乙如何主張其權利，下列敘述何者正確？","opts":["乙基於買賣契約所生之債權得向甲請求交付該錶，並移轉該錶所有權。甲對乙須負可歸責給付不能之損害賠償責任","乙基於買賣契約所生之債權得向丙請求交付該錶，並移轉該錶所有權。甲對丙須負可歸責給付不能之損害賠償責任","乙基於所有權得向甲請求交付該錶。甲對乙須負侵權行為之損害賠償責任","乙基於所有權得向丙請求交付該錶。甲對丙須負侵權行為之損害賠償責任"],"ok":[0],"ex":["乙對甲有債權（§348），甲將標的物另賣並交付丙致不能履行，為可歸責之給付不能，甲對乙負損害賠償（§226 I）。","債權具相對性，乙不得向第三人丙請求交付；丙取得所有權並無違法。","乙未受交付，尚未取得所有權（§761），不能主張所有權；甲之責任為債務不履行，非當然構成侵權行為。","乙非所有人，不得對丙主張所有物返還；且丙是從所有人甲受讓並受交付（§761Ⅰ），屬有權處分，不論丙善意或惡意都已取得所有權（不是善意取得）。"],"tr":""},{"id":"h:103-10","p":"h","src":"103年第10題","sec":"A4","stem":"關於附條件的法律行為，下列敘述何者正確？","opts":["附停止條件之法律行為，於條件成就時，失其效力","附條件的法律行為，其條件成就之效果於條件成就之時發生，不得依當事人之特約變更","因條件成就而受不利益之當事人，如以不正當行為促其條件之成就者，視為條件已成就","附條件之法律行為當事人，於條件成否未定前，若有損害相對人因條件成就所應得利益之行為者，負賠償損害之責任"],"ok":[3],"ex":["附停止條件之法律行為，於條件成就時「開始」發生效力，而非失其效力（失其效力是解除條件成就時的效果）。","依§99Ⅲ，條件成就之效果，當事人得依特約使其溯及效力發生，故非「不得」依特約變更，本選項錯誤。","選項把兩種情形混在一起：§101Ⅰ是「因條件成就而『受不利益』之當事人，以不正當行為『阻』其成就→視為條件已成就」；而「受利益之當事人以不正當行為『促』其成就」依§101Ⅱ是「視為條件不成就」。選項說「受不利益者促其成就→視為已成就」，與兩項規定皆不符，錯誤。","依§100，附條件法律行為之當事人，於條件成否未定前，若有損害相對人因條件成就所應得利益之行為，負損害賠償責任，此為條件成否未定期間當事人的保護規定，正確。"],"tr":""},{"id":"h:103-11","p":"h","src":"103年第11題","sec":"B6","stem":"甲糕餅業者向乙原料供應商購買食用油，用以添加於糕餅之製造，但該油之品質發生問題，經查該油係製油業者丙所生產，丙就其產品應對甲負何種責任？","opts":["無過失責任","故意責任","中間責任","不須負責"],"ok":[2],"ex":["無過失責任是消保法§7 的規定，但消保法以有「消費關係」為前提：消費者＝以消費為目的而為交易、使用商品者（消保法§2 第1款）。甲買油是當作糕餅原料、為營業而使用，不是以消費為目的，甲丙之間沒有消費關係，不適用消保法§7。（消保法§7Ⅲ 雖然也保護「第三人」，但那是指消費關係中受波及的人，不是買商品來加工生產的業者——題解見解。）回到民法 §191-1：丙能舉證商品無欠缺或已盡相當注意就免責，所以不是無過失責任。","§191-1 並非以故意為要件。","丙為商品製造人，依 §191-1 就其商品之通常使用所致損害負責，但能證明生產無欠缺或已盡相當注意者免責，即舉證責任倒置之中間責任。","丙為商品製造人，依 §191-1 仍須負責，非不須負責。"],"tr":""},{"id":"h:103-12","p":"h","src":"103年第12題","sec":"A4","stem":"下列關於暴利行為之敘述，何者錯誤？","opts":["雖違反公序良俗，但有效","利害關係人得行使撤銷權","並非詐害債權行為","應於法律行為後一年內提起救濟"],"ok":[0,1],"ex":["暴利行為依§74 為得撤銷或減輕給付，而非因違反§72 而無效；暴利行為在法院撤銷前「有效」，但它是否屬「違反公序良俗」學說有爭議（一說§74為§72之特別規定），因此A的定性有爭議，考選部更正為A、B均給分。考場要記的是：暴利行為＝法院撤銷或減輕給付（§74Ⅰ），1年內聲請（§74Ⅱ），不是當然無效。","§74Ⅰ 係「法院因利害關係人聲請撤銷或減輕給付」，須循法院，並非以意思表示逕行撤銷權；本題考選部認定有爭議。","暴利行為與§244 詐害債權行為要件不同，前者為顯失公平，後者為害及債權，故非詐害債權行為。","§74Ⅱ 聲請應於法律行為後1年內為之。"],"tr":""},{"id":"h:103-13","p":"h","src":"103年第13題","sec":"C1","stem":"甲將房屋出賣於乙並交付之，但尚未完成移轉登記，乙已支付一半價金，其後該屋因地震而全毀。下列敘述，何者正確？","opts":["乙仍應支付全部買賣價金","甲應承擔一半損失","乙得解除買賣契約","甲得主張重建後再交屋"],"ok":[0],"ex":["本題關鍵：房屋已「交付」乙（§373，危險自交付時移轉買受人），地震為不可抗力，危險由乙承擔，乙仍須支付全部價金（§373，物之危險自交付時起由買受人負擔），正確。","危險已於交付時移轉乙，甲不須分擔損失。","危險由乙負擔，乙無從解除（危險負擔原則下，乙仍負對待給付義務）。","特定物（房屋）滅失後已無從重建返還相同之物，且危險已移轉乙，甲無義務重建。"],"tr":""},{"id":"h:103-14","p":"h","src":"103年第14題","sec":"A6","stem":"關於代理，下列敘述何者正確？","opts":["代理人非經本人之許諾，不得既為第三人之代理人，而為本人與第三人之法律行為。但其法律行為，係專履行債務者，不在此限","代理權之限制及撤回，不得以之對抗善意第三人。至於該第三人有無過失而不知其事實者，則非所問","代理人於代理權限內，以代理人名義所為之意思表示，直接對本人發生效力","代理人所為或所受意思表示之效力，不因其為無行為能力人而受影響"],"ok":[0],"ex":["依§106，代理人未經本人許諾，不得同時擔任雙方當事人之代理人（雙方代理禁止），但「專履行債務之行為」例外，因此類行為對本人無害，正確。","依§107，代理權之限制及撤回，雖不得以之對抗善意第三人，但若第三人知道或「應知道」（有過失而不知）者，仍得對抗，故「有無過失非所問」之描述錯誤。","代理效力的關鍵是以「本人名義」而非「代理人名義」；以代理人自己名義（即使在授權範圍內）不能對本人發生代理效力，此選項描述錯誤。","依§104，代理人所為或所受意思表示之效力「不因其為限制行為能力人而受影響」；若為「無行為能力人」則不得為有效之意思表示，無行為能力人所為之意思表示無效，故§104保護的是「限制行為能力人」代理人，非無行為能力人，本選項以「無行為能力人」替換，屬錯誤敘述。"],"tr":""},{"id":"h:103-15","p":"h","src":"103年第15題","sec":"B6","stem":"甲駕駛機車載乙，與丙發生車禍，致乙跌落機車，身體多處受傷，經查甲、丙均有過失。下列敘述，何者錯誤？","opts":["乙得向丙請求損害賠償","丙不得主張乙應承擔甲之過失","乙得向甲請求損害賠償","甲丙為共同侵權行為人"],"ok":[1],"ex":["丙有過失致乙受傷，乙得依§184 Ⅰ（因故意或過失不法侵害他人權利者，負損害賠償責任）向丙請求賠償，敘述正確。","依實務見解（最高法院判例），機車駕駛人甲載送乙時，為後座乘客乙之使用人，丙得依§217Ⅲ（準用於被害人之使用人）主張乙應承擔甲之過失、減輕賠償；選項說「丙不得主張」，故為錯誤敘述。","甲有過失致乙受傷，乙亦得依§184 Ⅰ向甲請求損害賠償，敘述正確。","甲、丙之過失共同造成乙之傷害，數人共同不法侵害他人權利者，連帶負損害賠償責任（§185 Ⅰ），可認為共同侵權行為人，敘述正確。"],"tr":""},{"id":"h:103-16","p":"h","src":"103年第16題","sec":"D2","stem":"關於共有物分割，下列敘述何者正確？","opts":["共有物依共有人協議分割時，並不適用多數決原則","共有人以契約訂有不分割之期限者不得逾十年；逾十年者，縮短為十年","共有之不動產，其契約訂有管理之約定時，約定不分割之期限，不得逾五十年；逾五十年者，縮短為五十年","不動產共有人間關於共有物分割或禁止分割之約定，對於應有部分之受讓人或取得物權之人，以受讓或取得時知悉其情事或可得而知者為限，亦具有效力"],"ok":[0],"ex":["協議分割須全體共有人同意，不適用多數決，多數決僅用於管理（§820 I）。","不分割期限一般不得逾五年，逾五年者縮短為五年（§823 II）。","共有不動產訂有管理約定者，不分割期限上限為三十年，逾三十年縮短為三十年，非五十年（§823 II但書）。","不動產共有人間之約定須經登記後才對受讓人具有效力（§826-1 I）；「知悉或可得而知」之規定適用於動產（§826-1 II）。"],"tr":""},{"id":"h:103-17","p":"h","src":"103年第17題","sec":"C3","stem":"關於居間人之報酬及支出費用，下列敘述何者正確？","opts":["契約附有解除條件者，於該條件成就前，居間人不得請求報酬","居間人因媒介應得之報酬，除契約另有訂定或另有習慣外，應由契約當事人雙方平均負擔","約定之報酬，較居間人所任勞務之價值，為數過鉅失其公平者，報酬給付義務人得以意思表示請求酌減之","居間人違反其對於委託人之義務，而為利於委託人之相對人之行為，或違反誠實及信用方法，由相對人收受利益者，不得向委託人請求報酬，僅得請求償還其支出之必要費用"],"ok":[1],"ex":["§568 II：契約附停止條件者，條件成就前居間人不得請求報酬；解除條件則契約已生效，居間人得請求報酬。","§570：居間人因媒介應得之報酬，除契約另有訂定或另有習慣外，由契約當事人雙方平均負擔。","§572：報酬過鉅失公平者，須由法院因給付義務人請求酌減，並非自行以意思表示酌減。","§571：居間人違反義務而收受相對人利益者，不得向委託人請求報酬及償還費用，並非僅能請求費用。"],"tr":""},{"id":"h:103-18","p":"h","src":"103年第18題","sec":"C2","stem":"甲乙係多年好友，甲長年於國外經商，遂概括委任乙代為管理 A 屋，約定乙就 A 屋得為甲為一切行為。但民法規定，不動產之租賃其期限逾多久者，乙仍須有特別授權？","opts":["二年","一年半","一年","半年"],"ok":[0],"ex":["§534 但書第2款：受概括委任者，不動產之租賃其期限逾『二年』者，須有特別授權；其他須特別授權者尚有不動產出賣或設定負擔（第1款）、贈與（第3款）、和解、起訴、提付仲裁，正確。","一年半於§534 並無規定，期限門檻是二年。","『一年』是§422 的門檻：不動產租賃期限逾一年者應以字據訂立，與委任特別授權的二年門檻不同，勿混淆。","半年於§534 並無規定，期限門檻是二年。"],"tr":""},{"id":"h:103-19","p":"h","src":"103年第19題","sec":"C4","stem":"關於合夥人出資及合夥財產，下列敘述何者正確？","opts":["合夥人之出資，得為金錢，其他財產權或勞務，但不得以信用代之","合夥財產不足清償合夥之債務時，各合夥人對於不足之額，連帶負其責任","合夥人之出資及其他合夥財產，為合夥人全體分別共有之集合財產","合夥因損失而至資本減少時，除合夥契約有特別訂定外，合夥人有補充之義務"],"ok":[1],"ex":["§667 II：合夥出資得為金錢、其他財產權，或以勞務、信用或其他利益代之，信用亦可出資。","§681：合夥財產不足清償合夥債務時，各合夥人對不足額連帶負責。","§668：合夥人出資及其他合夥財產為合夥人全體之公同共有，並非分別共有。","§669：合夥因損失致資本減少，除契約特別訂定外，合夥人無補充義務。"],"tr":""},{"id":"h:103-20","p":"h","src":"103年第20題","sec":"D2","stem":"甲自行出資建造違章建築房屋一幢，將之出售予乙，並已交付乙占有。但事後甲對乙主張其為所有權人，請求乙返還房屋。下列敘述何者正確？","opts":["甲之請求為無理由。因為違章建築是違法行為，甲無法取得該屋所有權","甲之請求為有理由。因為違章建築買賣是違法行為，買賣契約無效，甲得請求回復原狀","甲之請求為有理由。甲可根據民法第 767 條第 1 項前段，所有人對於無權占有或侵奪其所有物者，得請求返還之","甲之請求為無理由。縱甲根據民法第 767 條第 1 項前段，所有人對於無權占有或侵奪其所有物者，得請求返還之。乙基於買賣契約非無權占有該屋，故無須返還"],"ok":[3],"ex":["違章建築雖違反建築法規，出資建造的甲仍原始取得該屋所有權（非因法律行為取得，不以登記為要件）；只是違建無法登記，甲出賣後不能依§758 I 移轉所有權，買受人乙依實務見解取得的是「事實上處分權」。所以「甲無法取得所有權」錯誤。","違章建築之買賣契約仍有效，並不因建物違章而無效，甲不得請求回復原狀。","乙持有買賣契約占有，並非無權占有，甲不能依§767 I前段請求返還。","乙基於有效買賣契約占有，有占有本權，甲縱主張§767 I前段，乙亦得以買賣契約抗辯而無須返還。"],"tr":""},{"id":"h:103-21","p":"h","src":"103年第21題","sec":"B3","stem":"甲、乙、丙共同竊取丁之財物，丁損失共計新臺幣 30 萬元，丁僅原諒其子甲之行為，而免除其債務。下列敘述，何者正確？","opts":["乙若全額清償後，得向甲、丙各求償新臺幣 10 萬元","乙若全額清償後，僅得向丙求償新臺幣 10 萬元","乙若全額清償後，僅得向丙求償新臺幣 15 萬元","丁免除甲之債務，乙、丙之債務亦應同生免除效力"],"ok":[1],"ex":["§276 I：免除甲之債務，只免甲應分擔部分，甲應分擔之部分由債權人丁自負，乙不得向甲求償。","乙、丙各分擔10萬；丁免除甲之債務後，乙、丙共欠20萬，乙清償後依 §281 I 僅得向丙求償其分擔額10萬。","丙之分擔額為10萬（§280 平均分擔），甲之分擔部分不轉由乙、丙承擔，故非15萬。","§276 I：免除僅就該債務人應分擔之部分，他債務人同免責任，其餘部分仍須負責，並非全部免除。"],"tr":""},{"id":"h:103-22","p":"h","src":"103年第22題","sec":"D4","stem":"關於越界建築之處理，下列敘述何者正確？","opts":["土地所有人建築圍牆時因重大過失逾越地界者，鄰地所有人如知其越界而不即提出異議，不得請求移去或變更其圍牆","土地所有人建築圍牆時非因重大過失逾越地界者，鄰地所有人如知其越界而不即提出異議，不得請求移去或變更其圍牆","土地所有人建築房屋時因重大過失逾越地界者，鄰地所有人如知其越界而不即提出異議，不得請求移去或變更其房屋","土地所有人建築房屋時非因重大過失逾越地界者，鄰地所有人如知其越界而不即提出異議，不得請求移去或變更其房屋"],"ok":[3],"ex":["因重大過失越界者，不得適用§796的免拆保護；且§796要件為非因故意或重大過失，題述與要件相反。","§796保護的是「建築房屋」越界；圍牆一般不具有與房屋相當之價值，不在§796-2準用範圍，所以圍牆越界時，鄰地所有人縱知情未即異議，仍得請求移去。B與D的差別就在「圍牆」與「房屋」。","因重大過失越界建築房屋，不符§796「非因故意或重大過失」之要件，鄰地所有人仍得請求移去。","土地所有人建築房屋非因（故意或）重大過失越界，鄰地所有人知其越界而不即提出異議者，不得請求移去或變更其房屋（§796 I）。"],"tr":""},{"id":"h:103-23","p":"h","src":"103年第23題","sec":"D5","stem":"甲在其土地上為乙設定眺望不動產役權，其後甲未獲得乙之同意又為丙設定地上權，丙預備在該地上建築房屋，若該房屋建成，乙之眺望權將因而受到影響，下列敘述，何者正確？","opts":["應不許丙設定地上權","縱然設定地上權，亦屬無效","地上權人不許在該地上建築房屋","設定地上權後，不動產役權消滅"],"ok":[2],"ex":["已設定不動產役權，並不禁止所有人再設定地上權，地上權仍得設定。","地上權有效成立，但其行使受先成立之不動產役權限制，並非無效。","先成立之眺望不動產役權有優先效力，地上權人不得為妨害眺望之行為，故不許在該地上建築妨礙眺望之房屋。","後設定地上權不會使先成立之不動產役權消滅。"],"tr":""},{"id":"h:103-24","p":"h","src":"103年第24題","sec":"D5","stem":"關於地上權，下列敘述何者正確？","opts":["普通地上權乃以在他人土地上下之一定空間範圍內有建築物或其他工作物為目的而使用其土地之權","地上權定有期限，而有支付地租之約定者，地上權人得支付未到期之三年分地租後，拋棄其權利","地上權人得將其權利設定權利質權。但契約另有約定或另有習慣者，不在此限","地上權人，因不可抗力，妨礙其土地之使用，得請求免除或減少租金"],"ok":[1],"ex":["普通地上權是在他人土地上下有建築物或其他工作物為目的而使用其土地之權（§832，竹木已改屬農育權）；限定上下一定空間範圍者為區分地上權（§841-1）。","定有期限而有地租者，地上權人得支付未到期之三年分地租後拋棄其權利（§835 I）。","地上權為不動產物權，得設定抵押權（§882、§838 I），非權利質權之標的。","地上權人不得因不可抗力妨礙土地使用而請求免除或減少地租（§837）。"],"tr":""},{"id":"h:103-25","p":"h","src":"103年第25題","sec":"D5","stem":"甲將土地為乙設定典權並交付之，其後甲將該地出賣與丙，乙主張有權以相同條件購買，此權利稱為：","opts":["找貼權","留買權","回贖權","絕賣權"],"ok":[1],"ex":["找貼權（§926）：出典人於典權存續中表示讓與典物所有權予典權人時，典權人得按時價找貼，取得典物所有權（以一次為限）；與本題「出典人賣給第三人丙，典權人以相同條件購買」不同。","依§919Ⅰ，出典人將典物出賣於他人時，典權人有以相同條件留買之權，此即留買權；本題甲將土地出賣給丙，乙主張以相同條件購買，正確。","回贖權（§923Ⅰ）：典權定有期限者，期限屆滿後出典人得以原典價贖回典物，是出典人的權利，與本題不同。","絕賣：典權附有絕賣條款（§913），或典期屆滿後經過二年出典人不以原典價回贖（§923Ⅱ），典權人即取得典物所有權；與本題情形不同。"],"tr":""},{"id":"h:103-26","p":"h","src":"103年第26題","sec":"A5","stem":"甲忘記乙已清償債務，遂誤將對乙之新臺幣 20 萬元之債權，以新臺幣 15 萬元出賣與丙。下列敘述，何者正確？","opts":["甲、丙間之買賣契約無效","甲須負權利瑕疵擔保責任","丙得主張善意取得該債權","丙得主張甲應負無權代理人責任"],"ok":[1],"ex":["甲丙間之買賣係以「對乙之債權」為標的，甲誤認債權存在，但買賣契約本身在成立上無問題（甲有出售意思、丙有購買意思、合意買賣債權），並非無效。惟甲所出賣之債權實際上不存在（乙已清償），此時涉及權利瑕疵擔保。","甲出賣之債權實際上因乙清償而消滅，即甲出賣的是「不存在的權利」，依§350「債權或其他權利之出賣人，應擔保其權利確係存在」（權利瑕疵擔保；§349是擔保第三人不得主張權利，與本題不同），甲須對丙負權利瑕疵擔保責任，正確。","善意取得（§801、§948）適用於動產物權，「債權」之讓與不適用善意取得原則（債權非動產），丙無法主張善意取得不存在之債權。","無權代理人責任（§110）發生於「無代理權而以代理人名義」為法律行為之情形，本題甲係以自己名義出賣自己（誤以為存在的）債權，並非代理人問題，此主張無所依據。"],"tr":""},{"id":"h:103-27","p":"h","src":"103年第27題","sec":"D6","stem":"下列何者不屬於直接占有人？","opts":["房屋承租人","土地之典權人","汽車之受委託保管人","為雇主駕駛汽車之司機"],"ok":[3],"ex":["承租人直接使用、占有租賃物，為直接占有人，正確（屬直接占有）。","典權人支付典價取得不動產使用收益，為直接占有人（對典物有直接管領力），正確（屬直接占有）。","受委託保管汽車者對汽車有直接管領，為直接占有人，正確（屬直接占有）。","司機為雇主駕駛汽車，係「輔助占有人」（§942，占有輔助人），司機僅依雇主指示駕駛，無獨立占有意思，其管領的利益歸屬於雇主（雇主為直接占有人），司機本身「不屬於」直接占有人，正確為應選答案。★輔助占有（§942）：在從屬關係下為他人管領者，不具有獨立占有地位。"],"tr":""},{"id":"h:103-28","p":"h","src":"103年第28題","sec":"D6","stem":"下列何種權利，不得單獨成為抵押權之標的物？","opts":["地上權","不動產役權","農育權","典權"],"ok":[1],"ex":["§882，地上權「得為」抵押權之標的（得以地上權設定抵押），A可以，選項排除。","不動產役權（§851以下）係附隨於需役地而存在，不得與需役地分離（§853），故「不得單獨」成為抵押權標的物，正確，為應選答案。","§882，農育權「得為」抵押權標的，C可以，選項排除。","§882，典權「得為」抵押權標的，D可以，選項排除。★記法：地上權、農育權、典權均可單獨抵押（§882）；不動產役權因附隨性不得單獨抵押。"],"tr":""},{"id":"h:103-29","p":"h","src":"103年第29題","sec":"E2","stem":"法定財產制關係消滅時，夫或妻現存之婚後財產，扣除婚姻關係存續所負債務後，如有剩餘，其雙方剩餘財產之差額，應平均分配。稱為：","opts":["剩餘財產分配請求權","財產酌給請求權","扶養費請求權","贍養費請求權"],"ok":[0],"ex":["§1030-1：法定財產制關係消滅時，雙方剩餘財產之差額平均分配，稱剩餘財產分配請求權。","財產酌給請求權為§1149，指被繼承人生前繼續扶養之人得請求酌給遺產。","扶養費請求權為扶養義務之給付請求，與本題無關。","贍養費請求權為§1057，指判決離婚時無過失之一方生活陷困得請求給與。"],"tr":""},{"id":"h:103-30","p":"h","src":"103年第30題","sec":"D6","stem":"下列關於最高限額抵押權之敘述，何者正確？","opts":["得有效約定最高限額係指本金最高限額","得約定凡是書面契約所生之債權，均屬擔保範圍","得約定凡是新臺幣 100 萬元以下之債權，均屬擔保範圍","得經抵押人之同意，將最高限額抵押權讓與他人"],"ok":[3],"ex":["依§881-1Ⅰ，最高限額抵押權係就債權人對債務人一定範圍內之不特定債權，「在最高限額內」設定；且§881-2Ⅱ 規定利息、遲延利息、違約金與原債權合計不逾最高限額範圍者，亦得行使，可知是「債權最高限額」，並非僅限本金，選項錯誤。","依§881-1Ⅱ，最高限額抵押權所擔保之債權，以由「一定法律關係」所生之債權或基於票據所生之權利為限；「凡書面契約所生之債權」範圍過於不特定，不符，選項錯誤。","同§881-1Ⅱ，擔保範圍須限於一定法律關係或票據所生之債權，僅以金額「100萬元以下」劃定範圍，缺乏法律關係的限定，選項錯誤。","依§881-8Ⅰ，原債權確定前，抵押權人經抵押人之同意，得將最高限額抵押權之全部或分割其一部讓與他人，正確。"],"tr":""},{"id":"h:103-31","p":"h","src":"103年第31題","sec":"E2","stem":"下列何者不屬於夫妻之特有財產？","opts":["妻之化妝品","夫之行醫工具","夫上班代步所駕駛之自用汽車","妻之首飾"],"ok":[2],"ex":["§1031-1 I：專供夫或妻個人使用之物屬特有財產，化妝品屬之。","§1031-1 I：專供夫或妻職業上必需之物屬特有財產，行醫工具屬之。","自用代步汽車並非專供個人使用或職業上必需之物，不屬特有財產。","§1031-1 I：專供個人使用之物屬特有財產，首飾屬之。"],"tr":""},{"id":"h:103-32","p":"h","src":"103年第32題","sec":"D5","stem":"設定抵押權時，土地及其土地上之建築物，同屬於一人所有，而以土地及建築物為抵押者，如經拍賣，其土地與建築物之拍定人各異時，關於拍定人間之關係，下列敘述何者正確：","opts":["視為已有不動產役權之設定","視為已有地上權之設定","視為取得使用借貸權","視為取得租賃權"],"ok":[1],"ex":["不動產役權是需役地與供役地之間的關係，本題為土地與建物拍賣後之關係，性質不同。","§876 II（適用 I），土地及其上建物同屬一人，以土地及建物為抵押，拍賣後由不同人拍得，「視為」已設定地上權（保護建物所有人使用土地之權益），正確。★§876「視為已有地上權之設定」。","使用借貸為債之關係，而§876明定「視為已有地上權之設定」（物權），選項錯誤。","租賃關係適用於§425-1（買賣分離情形，且為「推定」），本題為抵押拍賣，適用§876（「視為」地上權），選項法律關係錯誤。"],"tr":""},{"id":"h:103-33","p":"h","src":"103年第33題","sec":"E2","stem":"夫妻之財產及所得，除特有財產外，合併為共同財產者，屬於下述何種所有型態？","opts":["夫妻公同共有","夫妻分別共有","夫妻區分所有","夫妻總體共有"],"ok":[0],"ex":["§1031，夫妻共同財產制下，除特有財產外，夫妻之財產「合併為共同財產，屬夫妻公同共有」，正確。","分別共有是各人有確定應有部分比例的共有，夫妻共同財產無此結構，選項錯誤。","區分所有指各自就建物特定部分有所有權（如公寓），與夫妻財產制無關，選項錯誤。","「總體共有」並非民法用語，選項錯誤。"],"tr":""},{"id":"h:103-34","p":"h","src":"103年第34題","sec":"E4","stem":"甲死亡，由配偶乙繼承其遺產，乙對於甲所積欠丙之債務，應負何種責任？","opts":["負無限清償責任","負部分清償責任","不負責任","以因繼承所得遺產為限負清償責任"],"ok":[3],"ex":["繼承人負限定責任而非無限責任（§1148 II）。","並無「部分清償責任」之法律類型，繼承人以遺產為限負責。","繼承人並非不負責任，仍須以所得遺產清償。","§1148 II：繼承人對於被繼承人之債務，以因繼承所得遺產為限，負清償責任。"],"tr":""},{"id":"h:103-35","p":"h","src":"103年第35題","sec":"E4","stem":"因他人拋棄繼承而應為繼承之人，為拋棄繼承時，應於知悉其得繼承之日起多久為之？","opts":["一個月","二個月","三個月","六個月"],"ok":[2],"ex":["§1176 VII：因他人拋棄繼承而應為繼承之人，應於知悉其得繼承之日起「三個月」內為拋棄，不是一個月。","期間為三個月，非二個月（§1176 VII）。","§1176 VII：「因他人拋棄繼承而應為繼承之人，為拋棄繼承時，應於知悉其得繼承之日起三個月內為之」（題幹即此項原文）；方式仍依§1174 II以書面向法院為之。","§1176 VII所定期間為知悉其得繼承之日起「三個月」，不是六個月。"],"tr":""},{"id":"h:103-36","p":"h","src":"103年第36題","sec":"E2","stem":"甲、乙約定為共同財產制為其夫妻財產制，其後甲死亡，繼承人為乙及生女丙，經查甲、乙之共同財產共價值新臺幣 100 萬元，乙得分得金額為：","opts":["新臺幣 75 萬元","新臺幣 50 萬元","新臺幣 100 萬元","新臺幣 25 萬元"],"ok":[0],"ex":["甲死亡使共同財產制消滅，夫妻各取得共同財產之半數（§1039）：乙先取得50萬元；甲之50萬元為遺產，乙與丙（配偶與第一順位平均，§1144①）各得25萬元，乙合計75萬元。","50萬元僅是乙依§1039取得之共同財產一半，漏算乙另可繼承甲遺產25萬元。","共同財產不會全歸生存配偶；§1039原則上各取半數，甲之一半才是遺產。","25萬元只是乙繼承所得，漏算乙原本即取得的共同財產一半。"],"tr":""},{"id":"h:103-37","p":"h","src":"103年第37題","sec":"E4","stem":"甲男乙女婚姻關係存續中生女丙。嗣後甲乙離婚，甲男另與戊結婚，並由戊收養未成年之丙。丙成年後與丁男結婚但尚無子女，某日丙女因故死亡。問丙之遺產應如何繼承？","opts":["由甲、乙、丁共同繼承，每人之應繼分為三分之一","由甲、乙、丁共同繼承，惟丁之應繼分為二分之一","由甲、戊、丁共同繼承，每人之應繼分為三分之一","由甲、戊、丁共同繼承，惟丁之應繼分為二分之一"],"ok":[3],"ex":["甲為丙之生父，乙因丙被繼親收養而與丙之權利義務停止（§1077II），且乙非繼承人，不能與丁共同繼承。","同A，乙不是繼承人；丁之應繼分二分之一雖與B相符，但B列乙為繼承人即屬錯誤。","丁為配偶，與第二順位父母同時繼承，應繼分為二分之一而非三分之一（§1144②）。","丙被戊收養，但戊為甲之配偶，夫妻一方收養他方子女者，丙與生父甲之權利義務不受影響（§1077II但書），故父母為甲、戊；丙無子女，由第二順位父母與配偶丁共同繼承（§1138、§1144②），丁1/2，甲、戊各1/4。"],"tr":""},{"id":"h:103-38","p":"h","src":"103年第38題","sec":"E4","stem":"繼承人在繼承開始前幾年內，從被繼承人受有財產之贈與者，該財產視為其所得遺產？","opts":["半年內","1 年內","2 年內","3 年內"],"ok":[2],"ex":["§1148-1 I所定期間是繼承開始前「二年內」，半年不是法定期間。","§1148-1 I所定期間是繼承開始前「二年內」，不是1年。","依民法§1148-1 I，繼承人在繼承開始前二年內，從被繼承人受有財產之贈與者，該財產視為其所得遺產，期間為2年（遺產及贈與稅法§15 亦有死亡前2年內贈與併入遺產課稅之類似規定）。","§1148-1 I所定期間是繼承開始前「二年內」，不是3年。"],"tr":""},{"id":"h:103-39","p":"h","src":"103年第39題","sec":"E4","stem":"繼承開始時，繼承人之有無不明者，由親屬會議於一個月內選定遺產管理人，並將繼承開始及選定遺產管理人之事由，向法院報明。關於遺產管理人之職務，以下敘述何者正確？","opts":["編製遺產清冊，並為保存遺產必要之處置。遺產清冊，管理人應於就職後六個月內編製之","聲請法院依公示催告程序，限定六個月以上之期間，公告被繼承人之債權人及受遺贈人，命其於該期間內報明債權及為願受遺贈與否之聲明，被繼承人之債權人及受遺贈人為管理人所已知者，應分別通知之","清償債權或交付遺贈物。惟遺贈物之交付，應先於債權之清償","有繼承人承認繼承或遺產歸屬國庫時，為遺產之移交"],"ok":[3],"ex":["遺產清冊應於管理人就職後三個月內編製（§1179II），非六個月。","§1179I③公示催告所定期間為一年以上，而非六個月以上。","§1179I④遺贈物之交付應在清償債權之後，非先於債權清償。","§1179I⑤有繼承人承認繼承或遺產歸屬國庫時，管理人應為遺產之移交，敘述正確。"],"tr":""},{"id":"h:103-40","p":"h","src":"103年第40題","sec":"E4","stem":"甲有配偶乙及子丙，甲生前預立遺囑，內容表示死後要將全部財產遺贈給好友丁，嗣甲死亡時，全部遺產為新臺幣（下同）100 萬元，試問受遺贈人丁可得多少？","opts":["100 萬元","75 萬元","50 萬元","20 萬元"],"ok":[2],"ex":["遺囑侵害特留分，受遺贈人不可能取得全部，特留分人得行使扣減權（§1225）。","75萬元超過可處分額，仍侵害特留分。","配偶乙、子丙應繼分各1/2（§1144①），特留分各為應繼分1/2（§1223①③），共計1/2＝50萬元，可自由處分之遺產即為50萬元，丁得50萬元。","乙、丙特留分合計為遺產1/2（50萬元），其餘50萬元是甲可自由處分的部分（§1187），遺贈在此範圍內有效，丁得50萬元；20萬元低於可處分額，沒有任何依據。"],"tr":""},{"id":"h:102-1","p":"h","src":"102年第1題","sec":"B2","stem":"甲向乙建設公司購買預售屋一戶，約定甲應依已完成之工程進度所定付款明細表之規定於工程完工後繳款，半年後乙建設公司資金週轉不靈，財產遭法院查封，甲是否應繼續繳納約定的工程款？","opts":["資金週轉不靈，屬可歸責於乙建設公司之事由，甲可拒絕繳納已完工的工程款","因甲無過失，可免給付之義務，甲可拒絕繳納已完工的工程款","基於買賣契約，甲得向乙建設公司主張同時履行抗辯，拒絕繳納已完工的工程款","甲可主張在乙建設公司未繼續進行工程或提出擔保前，得拒絕繳納已完工的工程款"],"ok":[3],"ex":["乙週轉不靈並非給付不能，乙之債務尚在；甲不得僅因此拒絕繳款，而須依 §265 主張不安抗辯。","§225 免給付義務須因給付不能且不可歸責；甲之給付（付款）並未不能，不能以無過失免除。","§264 I 但書：甲依約有先為給付之義務，不得主張同時履行抗辯。","§265：應先為給付者，若他方財產於訂約後顯形減少而有難為對待給付之虞，他方未為對待給付或提出擔保前，得拒絕自己之給付。"],"tr":""},{"id":"h:102-2","p":"h","src":"102年第2題","sec":"C1","stem":"甲將其所有 A 屋委託乙仲介公司銷售，定價新臺幣 980 萬元，丙經乙仲介公司銷售人員帶看之後，對 A 屋甚是滿意，但是希望價格能降為新臺幣 950 萬元，乃給付新臺幣 20 萬元斡旋金予乙仲介公司作為與屋主斡旋差價之用。下列敘述何者正確？","opts":["丙交付新臺幣 20 萬元斡旋金，為定金之給付，推定該買賣契約成立","丙交付新臺幣 20 萬元斡旋金，為要約之引誘，買賣契約尚未成立","丙交付新臺幣 20 萬元斡旋金，為新要約，買賣契約尚未成立","丙交付新臺幣 20 萬元斡旋金，為要約之承諾，買賣契約成立"],"ok":[2],"ex":["斡旋金並非§248 定金，賣方尚未同意，不能推定契約成立。","屋主定價是要約之引誘，丙以較低價格並交付斡旋金，已表示購買意思，屬要約而非要約之引誘。","不論把屋主定價看成要約之引誘（丙出價即為要約），或看成要約（丙減價依§160 II 視為拒絕原要約而為新要約），丙以950萬元出價都是一個尚待屋主承諾的新要約；斡旋金只是表示購買誠意，屋主尚未承諾，買賣契約未成立。","屋主定價本屬要約之引誘，丙無承諾可言，且變更價格依§160 II 亦非承諾。"],"tr":""},{"id":"h:102-4","p":"h","src":"102年第4題","sec":"C1","stem":"甲以新臺幣 1000 萬元向乙購買某特定房屋，買賣契約何時成立？","opts":["甲交付新臺幣 1000 萬元於乙時","乙將該特定房屋交付於甲時","甲、乙完成交屋及付清價金時","甲、乙就房屋及價金互相同意時"],"ok":[3],"ex":["交付價金是「履行」契約的行為，並非契約「成立」時點，成立不需先交付。","交付房屋同樣是履行行為，非契約成立要件。","買賣契約不以「完成交屋及付清價金」為成立要件，成立遠早於此。","依§345Ⅱ，當事人就「標的物」及「價金」互相同意時，買賣契約即為成立（諾成契約），正確。買賣是最典型的諾成契約：意思合致→成立→各負交付義務。"],"tr":""},{"id":"h:102-5","p":"h","src":"102年第5題","sec":"C2","stem":"甲與乙訂立租賃契約，向乙承租房屋，雙方約定租賃期限為二年，未以書面為之，且甲亦未交付押金。下列敘述何者正確？","opts":["租賃契約於甲交付押金後始成立","租賃契約於甲交付押金後始生效","租賃契約未以書面為之，視為不定期限之租賃","租賃契約未以書面為之，出租人得撤銷租賃契約"],"ok":[2],"ex":["租賃為諾成契約（§421 I），當事人意思一致即成立，押金交付非成立要件。","押金不影響租賃契約之生效。","§422：不動產租賃期限逾1年而未以字據訂立者，視為不定期租賃。","未以書面訂立並無撤銷權規定，只是視為不定期。"],"tr":""},{"id":"h:102-6","p":"h","src":"102年第6題","sec":"E1","stem":"甲男乙女結婚時約定，雙方婚後若有婚外情之情事發生，雙方無條件離婚，並賠償對方新臺幣 1000 萬元。此約定的法律效力為何？","opts":["此約定為停止條件，條件成就時，離婚發生效力","此約定為解除條件，條件成就時，婚姻失其效力","此約定為不法條件，約定條件無效","此約定為不許附條件之法律行為，約定條件無效"],"ok":[3],"ex":["結婚、離婚為身分行為，不許附條件，並非停止條件。","離婚為身分行為，不許附解除條件，條件成就不使婚姻失效。","約定不屬於不法條件問題，而是身分行為不得附條件；兩願離婚須依§1050書面、證人並登記。","身分行為（結婚、離婚）要求明確、安定，不許附條件，附條件之約定無效；離婚應依§1050辦理。"],"tr":""},{"id":"h:102-7","p":"h","src":"102年第7題","sec":"D6","stem":"甲為 A 地的所有權人，乙為 A 地的抵押權人，丙為 A 地的地上權人。關於當事人間的權利義務，下列敘述何者錯誤？","opts":["乙的抵押權設定後，甲仍得將 A 地設定地上權給丙","若乙的抵押權設定在地上權之後，日後乙實行抵押權受有影響時，法院得除去丙的地上權後拍賣 A 地","若乙的抵押權設定後，甲在 A 地上蓋造 B 屋，日後乙實行抵押權受有影響時，得聲請法院將 B 屋與 A 地併付拍賣","乙的抵押權設定後，擔保債權未受清償前，甲得將 A 地售予丁"],"ok":[1],"ex":["抵押權設定後，所有人仍得於同一不動產設定地上權（§866 I），抵押權不受影響。","法院得除去者限於抵押權「設定後」才成立之用益物權（§866 II）；地上權在先者，抵押權人不得請求除去。","抵押權設定後於抵押地上營造建築物者，抵押權人得聲請併付拍賣，但對建築物價金無優先受償權（§877）。","抵押權設定後，所有人仍得將不動產讓與他人，抵押權不因此受影響（§867）。"],"tr":""},{"id":"h:102-8","p":"h","src":"102年第8題","sec":"D4","stem":"甲所有的 A 地與乙所有的 B 地相鄰，甲在 A 地上建築房屋及圍牆，其中圍牆有一部分越界建築在 B 地上。下列敘述何者正確？","opts":["乙如果知道甲有越界建築之情事而不即提出異議者，不得請求甲拆除越界的圍牆","甲對於乙所受之損害，應支付償金，但得不拆除越界的圍牆","乙得請求甲以相當之價額購買越界部分的土地，不得請求甲拆除越界的圍牆","乙得請求甲拆除越界的圍牆，返還被占用的土地"],"ok":[3],"ex":["免除拆除須土地所有人「非因故意或重大過失」越界（§796 I，圍牆若屬§796-2之建築物而準用），題目並未交代無故意重過失，不能一概不得拆除。","償金係於鄰地所有人不得請求拆除之情形，鄰地所有人得請求之補償（§796 I但書），非無條件得不拆除。","不得請求拆除時，鄰地所有人是「得」請求以相當價額購買越界土地，而非不得請求拆除；本題前提亦不成立。","未具備§796免拆要件時，鄰地所有人為所有人，得依§767 I請求拆除越界部分並返還土地。"],"tr":""},{"id":"h:102-9","p":"h","src":"102年第9題","sec":"A5","stem":"甲因負債，為避免債權人強制執行，故與乙訂立虛偽買賣契約，將甲僅有之一棟房屋賣給乙，並將房屋所有權移轉登記於乙（均為通謀虛偽意思表示）。乙將該屋賣給善意之丙，並將房屋所有權移轉登記於善意之丙。下列敘述何者正確？","opts":["乙祇是登記名義人，並非真正所有權人，故丙無法取得房屋之所有權","乙不祇是登記名義人，亦是真正所有權人，故丙可取得房屋之所有權","丙因信賴不動產之登記，並已依法辦理所有權移轉登記，故取得房屋之所有權","丙雖信賴不動產之登記，並已依法辦理所有權移轉登記，但仍然無法取得房屋之所有權"],"ok":[2],"ex":["甲乙間通謀虛偽意思表示雖無效（乙非真正所有權人），但§87Ⅰ但書明文：不得以其無效對抗善意第三人，故不影響善意丙取得所有權的結果，本選項後段結論錯誤。","選項說乙「不只是登記名義人，亦是真正所有權人」——前半段就錯：甲乙間買賣與移轉都是通謀虛偽意思表示，依§87Ⅰ無效，乙只是登記名義人，並非真正所有權人。丙之所以取得所有權，是因為善意第三人受保護（§87Ⅰ但書、§759-1Ⅱ），不是因為乙是所有人，故理由錯誤。","甲乙間買賣及移轉雖無效，但依§87Ⅰ但書，不得以其無效對抗善意第三人丙；丙信賴登記外觀並完成移轉登記，另依§759-1Ⅱ「因信賴不動產登記之善意第三人，已依法律行為為物權變動之登記者，其變動之效力，不因原登記物權之不實而受影響」，應受保護而取得房屋所有權，此為通謀虛偽意思表示「善意第三人保護」的核心考點。","結論相反：善意丙信賴登記並已完成移轉登記，依§87Ⅰ但書（不得以無效對抗善意第三人）及§759-1Ⅱ（物權變動效力不因原登記不實而受影響），丙取得房屋所有權。"],"tr":""},{"id":"h:102-10","p":"h","src":"102年第10題","sec":"D2","stem":"甲有一宗土地，與乙訂立買賣契約，將該宗土地賣給乙。雙方訂立買賣契約後，因土地飆漲，甲藉故不願履行契約上之義務。乙起訴請求甲移轉買賣標的物之所有權，法院判決乙勝訴確定。下列敘述何者正確？","opts":["乙因法院之判決，取得不動產物權，故於判決確定時，即已取得該土地之所有權","乙必須根據確定判決，辦畢所有權移轉登記後，始能取得該土地之所有權","甲依法院之確定判決，將土地交付於乙時，乙即取得該土地之所有權","甲依法院之確定判決，將土地之所有權狀交付於乙時，乙即取得該土地之所有權"],"ok":[1],"ex":["判決確定即取得物權者限於形成判決（§759），本題請求移轉所有權屬給付判決，須辦理登記。","給付判決僅使乙取得請求移轉登記之執行名義，須辦畢所有權移轉登記才取得所有權（§758）。","不動產物權變動以登記為生效要件（§758），交付不生所有權移轉效力。","交付所有權狀不生物權變動效力，仍須登記（§758）。"],"tr":""},{"id":"h:102-11","p":"h","src":"102年第11題","sec":"D2","stem":"甲有一棟房屋，與乙訂立買賣契約，將該房屋賣給乙。下列敘述何者正確？","opts":["買賣契約有效成立時，立刻使乙取得房屋之所有權","甲將房屋交付給乙時，立刻使乙取得房屋之所有權","甲將房屋所有權狀交付給乙前，乙無法取得房屋之所有權","甲將房屋所有權移轉登記給乙前，乙無法取得房屋之所有權"],"ok":[3],"ex":["買賣契約（債權行為）依§345Ⅱ 於標的物及價金互相同意時成立，但僅生債之關係，並不使乙立即取得所有權，選項錯誤。","不動產（房屋）所有權依法律行為取得，依§758Ⅰ 非經登記不生效力，僅交付占有並不移轉所有權（交付才生效力的是動產，§761Ⅰ），選項錯誤。","所有權狀只是行政上的證明文件，交付所有權狀不等於辦理登記，不是取得不動產所有權的要件，選項錯誤。","依§758Ⅰ，不動產物權依法律行為而取得，非經登記不生效力；甲將房屋移轉登記給乙之前，乙無法取得所有權，正確。"],"tr":""},{"id":"h:102-12","p":"h","src":"102年第12題","sec":"D2","stem":"甲死亡時，遺有子女乙、丙二人為繼承人，及房屋一棟。下列敘述何者正確？","opts":["甲對房屋之所有權，並不因甲死亡，而發生所有權之移轉","房屋為不動產，乙丙二人非經登記，無法取得房屋所有權","乙丙二人縱使未辦理登記，仍然因繼承而取得房屋所有權","乙丙二人縱使未辦理登記，仍因繼承而得處分房屋所有權"],"ok":[2],"ex":["依§1147、§1148Ⅰ，繼承因被繼承人死亡而開始，繼承人自繼承開始時承受被繼承人財產上之一切權利義務，房屋所有權因繼承而移轉，選項說「不發生移轉」錯誤。","依§759，因繼承、強制執行、徵收、法院判決等非因法律行為而取得不動產物權者，於登記前即已取得（§758 的登記生效要件只適用於法律行為），選項說「非經登記無法取得」錯誤。","繼承是非因法律行為而取得不動產物權（§759），乙丙縱未辦理登記，仍因繼承而取得房屋所有權，正確。","依§759，繼承人於登記前雖已取得不動產物權，但「應經登記，始得處分其物權」，未登記前不得處分，選項錯誤。"],"tr":""},{"id":"h:102-13","p":"h","src":"102年第13題","sec":"B3","stem":"甲於民國 102 年 1 月 1 日向乙借新臺幣 10 萬元，約定同年 6 月 30 日清償，並由丙於其期限內擔任保證人。下列敘述何者正確？","opts":["清償期屆滿，乙允許甲延期清償時，應得丙之同意，否則丙不負保證責任","丙得隨時通知乙終止保證契約，並於通知到達乙後，不負保證責任","清償期屆滿後，丙應定一個月以上之期限催告乙向甲請求，丙始能免責","丙得隨時通知甲終止保證契約，並於通知到達甲後，不負保證責任"],"ok":[0],"ex":["§755 I：定有期限之債務，債權人允許主債務人延期，除保證人已同意外，保證人不負保證責任。","§754 I 隨時終止僅適用連續發生之債務且未定期間者，單一借款且定有期限不適用。","催告免責（§753）限於「未定期間」之保證，且係催告債權人向主債務人為審判上之請求；本題保證定有期間（適用§752），不適用；保證人免責事由另如§755 延期未經同意。","終止保證之通知對象為債權人而非主債務人，且本題非連續債務，不適用§754。"],"tr":""},{"id":"h:102-14","p":"h","src":"102年第14題","sec":"D2","stem":"甲、乙、丙三人共有一筆 A 地，應有部分各三分之一。下列敘述何者錯誤？","opts":["甲、乙二人得在未經丙同意的情況下，將 A 地出售與丁建設公司","甲、乙二人得在未經丙同意的情況下，將 A 地出租與戊使用","甲得在未經乙、丙同意的情況下，將其 A 地的應有部分設定抵押權與庚銀行","甲、乙、丙三人經裁判分割 A 地時，須待分割登記完成時，才各自取得單獨所有權"],"ok":[3],"ex":["僅就買賣之債權契約而言，出賣人不以有處分權為必要即可訂立；而 A 是土地，處分共有土地可依土地法§34-1Ⅰ 多數決（共有人過半數及應有部分合計過半數），甲乙二人、應有部分合計三分之二已達門檻（應事先書面通知丙，丙有優先承購權），不必依§819 II 全體同意，故本選項正確。","出租屬管理行為，得依§820 I以共有人過半數及應有部分合計過半數決定，甲乙合計三分之二已足。","共有人得自由處分其應有部分，包括設定抵押權（§819 I）。","裁判分割為形成判決，分割判決確定時即生物權變動效力，不待登記（§759）。"],"tr":""},{"id":"h:102-15","p":"h","src":"102年第15題","sec":"B6","stem":"甲承攬乙建設公司之營造工程，在執行承攬事項時，因過失致路人丙受到傷害。下列敘述何者正確？","opts":["乙建設公司如非於定作或指示有過失，即不負損害賠償責任","乙建設公司雖非於定作或指示有過失，但應與甲連帶負損害賠償責任","乙建設公司賠償丙之損害後，對甲有內部求償權","乙建設公司應單獨對丙負損害賠償責任，對甲無內部求償權"],"ok":[0],"ex":["§189：承攬人執行承攬事項不法侵害他人，定作人原則上不負賠償責任，除非定作或指示有過失。","定作人無過失時不與承攬人連帶，只有定作或指示有過失才可能共同負責。","乙原則上無須賠償，亦無代甲負責之內部求償問題；§188 III 求償規定適用於僱傭而非承攬。","乙非單獨負責；無過失時不負責任，有過失時也是與承攬人共同負責。"],"tr":""},{"id":"h:102-16","p":"h","src":"102年第16題","sec":"B6","stem":"甲男與乙女已經訂婚，而且同居，雖尚未結婚，但感情非常好。甲男某日外出工作，遭無照駕駛之丙喝酒闖紅燈撞擊，當場死亡。下列敘述何者正確？","opts":["因乙女與甲男有訂婚之關係，故乙女得請求丙賠償慰撫金","因乙女與甲男已經同居，故乙女得請求丙賠償慰撫金","因乙女與甲男感情非常好，故乙女得請求丙賠償慰撫金","因乙女與甲男尚未結婚，故乙女不得請求丙賠償慰撫金"],"ok":[3],"ex":["§194僅規定被害人之父母、子女及配偶得請求非財產上損害賠償；訂婚者非配偶。","同居不改變身分，非§194所列之人。","感情深厚不是§194所列身分。","乙與甲尚未結婚，非配偶，依§194不得請求慰撫金。"],"tr":""},{"id":"h:102-17","p":"h","src":"102年第17題","sec":"C2","stem":"甲房東將其所有 A 屋出租給乙房客，嗣後甲因財務問題將 A 屋出售與丙。下列敘述何者正確？","opts":["丙擁有 A 屋的所有權，所以丙可以要求乙房客搬遷","若甲、乙之間的房屋租賃契約未經公證且超過 5 年者，丙可以要求乙房客搬遷","若甲、乙之間的房屋租賃契約未定期限者，丙可主張隨時終止租賃契約，要求乙房客搬遷","租期屆滿後，乙得向丙主張返還二個月的押租金"],"ok":[1],"ex":["§425 I：租賃物所有權讓與時租約對受讓人繼續存在，丙不得逕要求乙搬遷。","§425 II：未經公證之不動產租賃，期限逾5年者不適用買賣不破租賃，故丙可要求乙搬遷。","依§425 II，未經公證且未定期限之不動產租賃，不適用買賣不破租賃，租約對受讓人丙根本不繼續存在；丙不是出租人，談不上「終止租約」，而是直接以所有人身分請求乙返還房屋（§767 I）。至於§450 II 雖規定未定期限者「各當事人得隨時終止契約」，那是租約當事人之間的規定，且依§450 III 仍須先期通知；選項把「受讓人」當成可終止租約的出租人，故不正確。","押租金是否返還、由誰返還，取決於押租金的約定與交付：實務見解認為受讓人僅在其自出租人受交付押租金之範圍內，對承租人負返還義務；題幹既未交代押租金之約定、數額，也未交代甲是否已將押租金移交丙，民法更無「返還二個月押租金」的規定（「二個月」是土地法§99 對押租金所設上限，不是返還數額），故選項不能成立。"],"tr":""},{"id":"h:102-18","p":"h","src":"102年第18題","sec":"D6","stem":"甲有一幅臺灣著名畫家之名畫，市值新臺幣 500 萬元，借給乙在畫展中展覽，並未委託乙出售。丙觀賞該名畫，愛不釋手，不知該畫是乙向甲借的，於是向乙表示願出新臺幣 700 萬元請乙割愛，乙就以新臺幣 700 萬元將該畫賣給丙，並以移轉所有權之意思交付給丙。下列敘述何者正確？","opts":["甲得請求丙返還該畫","甲得請求乙新臺幣 700 萬元","甲最多只能請求乙新臺幣 500 萬元","甲最多只能請求乙新臺幣 600 萬元"],"ok":[1],"ex":["丙善意且受現實交付，依§801、§948取得該畫所有權，甲不得向丙請求返還。","乙明知非己有而出售，屬不法管理，本人甲得主張享有管理所得利益（§177 II），可請求乙交出所得價金700萬元。","甲所得請求者不以畫之市值為限，得及於乙所得全部價金利益。","600萬元沒有任何請求權基礎對應：依侵權行為或不當得利，是以畫的市值500萬元計算；依不法管理（§177 II 準用 I），可請求乙處分所得的全部700萬元。兩種算法都不會得出600萬元。"],"tr":""},{"id":"h:102-19","p":"h","src":"102年第19題","sec":"A4","stem":"甲與女秘書乙發生婚外情，甲與乙約定以繼續維繫婚外情為前提，贈與乙 A 屋一棟，一年後乙不欲繼續維持不倫關係，A 屋該如何處理？","opts":["A 屋係以解除條件為前提的贈與契約，條件成就，贈與契約解除，A 屋須返還給甲","甲與乙之間的贈與契約係以維繫婚外情為前提，贈與契約內容違反公序良俗無效，A 屋須返還給甲","乙受贈 A 屋係屬不法原因而為給付者，甲事後不能請求返還 A 屋","甲贈與乙 A 屋為無償行為，故贈與人甲可隨時撤銷該贈與契約，請求返還 A 屋"],"ok":[2],"ex":["本題核心並非條件成就與否，而是贈與原因（維繫婚外情）本身違反公序良俗，一開始即無效（§72），不待條件成就使其「解除」。","前半段「違反公序良俗無效」正確（§72：法律行為背於公共秩序或善良風俗者無效）；但後半段「A屋須返還給甲」有誤：甲交付房屋係基於不法原因所為之給付，依§180第4款不得請求返還（但不法原因僅於受領人一方存在者除外），故結論錯誤。","契約因違反公序良俗而無效（§72），甲交付A屋係基於「維繫婚外情」此不法原因所為之給付，依§180第4款不法原因之給付不得請求返還，故甲事後不能請求返還A屋。這是本題最重要的陷阱：無效≠當然可以要回。","贈與為無償行為不代表可隨時撤銷：§408Ⅰ只在「贈與物之權利未移轉前」才得撤銷，本題討論返還A屋，即甲已給付，不得再依§408撤銷；且契約本身已因§72無效，返還與否應依§180第4款處理（不得請求返還）。"],"tr":""},{"id":"h:102-20","p":"h","src":"102年第20題","sec":"B6","stem":"18 歲的甲騎機車上學途中撞傷騎腳踏車的乙。下列敘述何者正確？","opts":["甲未成年，所以不須負損害賠償之責","由甲的法定代理人負損害賠償之責","以甲行為時有意思能力為限，與其法定代理人連帶負損害賠償責任","法定代理人如其監督並未疏懈，或縱加以相當之監督，而仍不免發生損害者，得主張免責"],"ok":[3],"ex":["§187 I：未成年人有識別能力時須負責，並與法定代理人連帶，未成年不當然免責。【新舊法】依出題年（102年）舊法20歲成年，18歲之甲未成年；依現行§12（滿十八歲為成年），甲已成年，「甲未成年」前提即不成立，A在新舊法下都是錯的。","有識別能力時由行為人與法定代理人連帶負責；僅無識別能力才由法定代理人單獨負責（§187 I）。","§187 I 之要件為行為時「識別能力」，並非意思能力。","§187 II：法定代理人監督並未疏懈，或縱加相當監督仍不免發生損害者，不負賠償責任。【新舊法】依出題年（102年）舊法，18歲甲為限制行為能力人，有法定代理人，D正確，官方答案D；依現行§12甲已成年、沒有法定代理人，§187整條（含Ⅱ免責）都不適用，甲依§184Ⅰ自負責任，D所述情形不存在，本題在現行法下無正確選項。"],"tr":""},{"id":"h:102-21","p":"h","src":"102年第21題","sec":"D2","stem":"甲所有的 A 屋蓋在乙已登記的 B 地上 18 年。下列敘述何者正確？","opts":["乙可向甲主張 B 地的所有物返還請求權，請求甲拆屋還地","已經超過 15 年，乙不可向甲主張 B 地的所有物返還請求權，請求甲拆屋還地","甲可主張時效取得 B 地的所有權","甲如為善意占有人，始得主張時效取得 B 地的所有權"],"ok":[0],"ex":["乙是B地已登記所有人，依§767Ⅰ 對無權占有其土地者得請求返還並除去妨害（拆屋還地）；已登記不動產所有人的物上請求權不適用消滅時效，故乙隨時得請求，正確。","一般請求權消滅時效為15年（§125），但已登記不動產所有人的回復請求權、除去妨害請求權依大法官解釋（釋字第107號、第164號）不罹於消滅時效，所以超過15年乙仍可請求，選項錯誤。","依§769、§770，時效取得不動產所有權限於占有「他人未登記之不動產」；B地已登記，甲無法時效取得，選項錯誤。","同C，B地已登記，不論甲是否善意（§770 的善意無過失10年）或§769 的20年占有，均不能時效取得已登記不動產。★重點：已登記不動產→物上請求權不罹消滅時效，也不能被時效取得。"],"tr":""},{"id":"h:102-22","p":"h","src":"102年第22題","sec":"A6","stem":"甲未將代理權授與給乙，乙卻以甲之代理人名義與善意之丙訂立買賣契約，甲不承認乙之無權代理行為。下列敘述何者正確？","opts":["乙與丙簽訂之買賣契約，效力雖不及於甲，但在乙丙之間有效","乙與丙簽訂之買賣契約，對甲丙、乙丙均無效，丙得請求乙損害賠償","乙與丙簽訂之買賣契約，對甲丙、乙丙均無效，丙得請求甲損害賠償","乙與丙簽訂之買賣契約，對甲丙、乙丙均有效，但丙得撤銷買賣契約"],"ok":[1],"ex":["甲拒絕承認後，無權代理行為對甲確定不生效力，且對「乙丙間」也不生效力（因契約是乙以甲之代理人名義訂立，並非乙以自己名義訂約，乙丙間不成立另一個有效契約）。","甲拒絕承認，契約對甲丙、乙丙均確定不生效力（無效）；依§110，無代理權人以他人之代理人名義所為之法律行為，對於善意之相對人（丙），須負損害賠償之責，故丙得向乙（無權代理人）請求損害賠償，正確。","丙得請求損害賠償的對象是無權代理人「乙」，而非本人「甲」，因為甲從未授權，不須負責。","甲既已拒絕承認，契約對甲不生效力，並非有效，選項前提錯誤。"],"tr":""},{"id":"h:102-23","p":"h","src":"102年第23題","sec":"C2","stem":"甲向乙承租 A 地種植柚子樹，後來政府公告將徵收 A 地。下列敘述何者錯誤？","opts":["柚子樹為不動產之出產物，屬於乙所有","柚子為天然孳息，天然孳息的收取權為土地所有權人乙","政府徵收乙所有的 A 地，範圍包括甲在 A 地上種植的柚子樹","政府徵收 A 地之補償金歸屬於乙"],"ok":[1],"ex":["§66 II：不動產出產物尚未分離者為該不動產之部分，柚子樹屬土地之構成部分，歸土地所有人乙。","§70 I：有收取天然孳息權利之人於權利存續期間內取得孳息，承租人甲於租期內有使用收益權（§421 I），收取權人是甲而非乙。","徵收標的為土地及其定著物，土地上之樹木屬土地部分，包括在徵收範圍內。","土地徵收補償金歸土地所有權人乙。"],"tr":""},{"id":"h:102-24","p":"h","src":"102年第24題","sec":"A2","stem":"A 公司的董事甲前往與客戶簽約時，不慎撞傷路人乙。下列敘述何者正確？","opts":["屬車禍事故，由董事甲自行負損害賠償責任","由 A 公司負損害賠償責任，但是 A 公司對董事甲有求償權","由 A 公司與董事甲連帶負損害賠償責任","A 公司若已盡監督職務執行之責，可舉證免責"],"ok":[2],"ex":["董事執行職務（前往簽約）所致損害，屬法人侵權，不得僅由董事個人負責。","§28 規定法人與行為人連帶負責，並非單由公司負責；§28 未排除對董事之求償，但選項說法未呈現連帶。","§28 法人對董事因執行職務加於他人之損害，與該行為人連帶負賠償責任。","§188 的選任監督免責屬僱用人責任；§28 無舉證免責規定，公司不得以盡監督責任免責。"],"tr":""},{"id":"h:102-25","p":"h","src":"102年第25題","sec":"A1","stem":"某甲 25 歲，為受輔助宣告之人。下列敘述何者正確？","opts":["甲之輔助宣告可由其表哥向社會福利機構提出聲請","甲受輔助宣告後，自行購買不動產的行為，無效","甲之輔助人乙，不得受讓甲所有的 A 屋","甲受輔助宣告後，自行將其所有的智慧型手機贈與好友丙的行為，有效"],"ok":[2],"ex":["輔助宣告應向「法院」聲請（§15-1Ⅰ：法院得因本人、配偶、四親等內親屬、檢察官、主管機關或社會福利機構之聲請為輔助宣告）；社會福利機構是有權聲請之人，並非受理聲請的機關，向社會福利機構提出聲請不生聲請之效力。","§15-2Ⅰ第5款：受輔助宣告之人處分不動產等重要財產應經輔助人同意；未經同意，依§15-2Ⅱ準用§78～§83，契約效力未定（§79）、單獨行為無效（§78），並非一律無效。","§1113-1Ⅱ規定輔助人及有關輔助之職務準用§1102，§1102：監護人不得受讓受監護人之財產。故輔助人乙不得受讓甲所有的A屋，以避免利益衝突。","§15-2Ⅰ第2款：受輔助宣告之人為贈與，應經輔助人同意（純獲法律上利益或依年齡身分、日常生活所必需者除外）；贈與手機予友人並非純獲利益，未經同意依§15-2Ⅱ準用§79，效力未定，不是當然有效。"],"tr":""},{"id":"h:102-26","p":"h","src":"102年第26題","sec":"D6","stem":"甲所有的古董花瓶為乙所盜並寄放在丙的古董店裡展售，嗣後為顧客丁所買。關於當事人之間的權利義務，下列敘述何者錯誤？","opts":["丙出售古董花瓶的行為，須經甲的承認始生效力","不知情的顧客丁因丙的受讓移轉，取得古董花瓶的所有權","該古董花瓶係盜贓物，甲得於古董花瓶喪失占有之時起一年內向丁請求回復其物","甲須償還丁購買古董花瓶之價金，始得請求回復其物"],"ok":[2],"ex":["這裡的「出售行為」指丙把花瓶所有權移轉給丁的處分行為：丙無處分權，屬無權處分，依§118 I 須經權利人甲承認始生效力。（買賣契約本身是債權行為，不以有處分權為必要，仍有效；與99-20同一規則。）","丁善意受讓動產占有，受法律保護而取得所有權（§801、§948），盜贓物亦同，但甲有回復請求權。","盜贓物之回復請求期間為自喪失占有時起二年內（§949 I），非一年。","丁自販賣同種物品之商人善意買得，原占有人須償還其支出之價金才得回復其物（§950）。"],"tr":""},{"id":"h:102-27","p":"h","src":"102年第27題","sec":"C1","stem":"甲向乙購買房屋，雙方簽訂買賣契約後，乙將房屋交付於甲，但尚未辦理所有權移轉登記，突然發生地震致使房屋全毀。下列敘述何者正確？","opts":["甲雖未取得房屋所有權，但仍需交付約定之房屋價金","甲因未取得房屋所有權，故毋需交付約定之房屋價金","甲已受領房屋之交付，故需交付約定之房屋價金之一半","甲已受領房屋之交付，僅需給付相當於使用房屋之租金"],"ok":[0],"ex":["買賣標的物之利益及危險，自交付時起由買受人承擔（§373）；房屋已交付，毀損滅失之危險由甲負擔，仍須付價金。","危險已隨交付移轉，甲不因未登記而免付價金（§373）。","法律未規定價金減半，危險負擔依§373全部移轉。","危險移轉後買受人仍負擔全部價金，非僅付使用租金。"],"tr":""},{"id":"h:102-28","p":"h","src":"102年第28題","sec":"D5","stem":"甲所有的 A 地因通行之需在乙的 B 地上設定不動產役權。下列敘述何者錯誤？","opts":["甲得將 A 地設定抵押權與丙銀行","甲得將 B 地上的不動產役權單獨讓與給丁","嗣後 A 地分割並讓與，為戊、己所有，戊、己皆享有 B 地上的不動產役權","嗣後 B 地分割並讓與，為庚、辛所有，甲的不動產役權仍存在庚、辛受讓的 B 地上"],"ok":[1],"ex":["需役不動產之所有人仍得就需役地設定抵押權，不受不動產役權之限制。","不動產役權不得由需役不動產分離而為讓與，或為其他權利之標的物（§853）。","需役不動產經分割者，不動產役權為各部分之利益仍存續（§856）。","供役不動產經分割者，不動產役權就其各部分仍存續（§857）。"],"tr":""},{"id":"h:102-29","p":"h","src":"102年第29題","sec":"C2","stem":"甲向乙承租房屋居住，因火災致房屋毀損滅失，乙請求甲損害賠償。下列敘述何者正確？","opts":["甲因火災致乙之房屋毀損滅失，構成侵權行為，應負抽象輕過失責任","甲因火災致乙之房屋毀損滅失，構成侵權行為，應負具體輕過失責任","甲因火災致乙之房屋毀損滅失，承租人甲僅負重大過失責任","甲因火災致乙之房屋毀損滅失，承租人甲僅負故意責任"],"ok":[2],"ex":["§434：承租人失火責任限於重大過失，並非抽象輕過失。","承租人失火不負具體輕過失責任。","§434：租賃物因承租人失火而毀損滅失，承租人僅就重大過失負賠償責任。","承租人重大過失即須負責，並非僅限故意。"],"tr":""},{"id":"h:102-30","p":"h","src":"102年第30題","sec":"E4","stem":"甲早年喪偶，育有子女三人乙、丙、丁，嗣後與戊女結婚，並生有二子女 A、B，戊女與前夫育有二女C、D。關於這家人將來的繼承關係，下列敘述何者正確？","opts":["若甲死亡，甲的遺產由乙、丙、丁、戊及 A、B、C、D 共同繼承","若戊死亡，戊的遺產由甲和 A、B、C、D 共同繼承","若乙未婚，因意外事故死亡，乙的遺產由甲、戊共同繼承","若戊與 C 出遊，二人因意外事故死亡，C 未婚，C 的遺產由甲與 D 共同繼承"],"ok":[1],"ex":["C、D為戊與前夫所生，與甲僅為繼子女（姻親），非甲之繼承人（§1138）。","戊之配偶甲及戊之直系血親卑親屬A、B、C、D同為繼承（§1138、§1144(1)）。","乙未婚無子女，第二順序為父母；乙之母已歿，由甲繼承，戊為繼母非繼承人。","戊、C同時遇難者推定同時死亡，互不繼承（§11）；C之遺產由其生父（若生存）繼承，甲為繼父非繼承人。"],"tr":""},{"id":"h:102-31","p":"h","src":"102年第31題","sec":"E3","stem":"甲男乙女為夫妻，乙生下孩子丙。下列關於受胎期間之推定何者錯誤？","opts":["甲乙於民國 100 年 2 月 1 日結婚，丙於同年 7 月 1 日出生，丙為甲乙在婚姻關係存續中所生的孩子，丙推定為甲乙的婚生子女","甲乙於民國 100 年 2 月 1 日結婚，丙於同年 12 月 1 日出生，丙為甲乙在婚姻關係存續中所生的孩子，丙推定為甲乙的婚生子女","甲乙於民國 100 年 3 月 1 日離婚，丙於同年 7 月 1 日出生，丙雖非甲乙在婚姻關係存續中所生的孩子，但丙推定為甲乙的婚生子女","甲乙於民國 100 年 3 月 1 日離婚，丙於同年 11 月 1 日出生，丙雖非甲乙在婚姻關係存續中所生的孩子，但丙推定為甲乙的婚生子女"],"ok":[0],"ex":["結婚至丙出生僅約150日，不足181日，受胎期間（出生前第181日至第302日，§1062）全在婚前，不能依§1063推定為婚姻中受胎之婚生子女。","結婚至丙出生逾302日，受胎期間全在婚姻中，推定婚生（§1062、§1063 I）。","離婚至丙出生約122日，受胎期間全在離婚前，推定婚生（§1062、§1063 I）。","離婚至丙出生約245日，受胎期間跨越離婚日，其中有在婚姻關係存續中之部分，推定為婚生（§1062、§1063 I）。"],"tr":""},{"id":"h:102-32","p":"h","src":"102年第32題","sec":"E3","stem":"趙男與錢女結婚，婚後產下一子登記姓名為趙大富。下列敘述何者錯誤？","opts":["趙大富未成年前，得由父母以書面約定變更為錢大富","嗣後趙男與錢女離婚，法院得依錢女之請求，為子女之利益，宣告變更趙大富為錢大富","趙大富 20 歲後，經父母同意得申請變更姓氏為錢大富","已成年子女姓氏的變更其次數以一次為限"],"ok":[2],"ex":["§1059：子女出生登記後未成年前，父母得以書面約定變更為父姓或母姓（以一次為限）。","§1059：父母離婚等情形，法院得依請求為子女利益宣告變更姓氏。","§1059：已成年子女得自行決定變更為父姓或母姓，毋須父母同意。","§1059：成年子女之姓氏變更以一次為限。"],"tr":""},{"id":"h:102-33","p":"h","src":"102年第33題","sec":"E1","stem":"甲男 20 歲，乙女 15 歲，二人一見鍾情，決定廝守終身，於是結婚。乙女尚未滿適婚年齡，亦尚未懷孕。下列敘述何者正確？","opts":["乙女未滿適婚年齡，其結婚無效","乙女未滿適婚年齡，乙女得不經法院逕行撤銷結婚","乙女未滿適婚年齡，乙女得向法院請求撤銷結婚","乙女未滿適婚年齡，需經法定代理人同意始得撤銷"],"ok":[2],"ex":["未達結婚年齡之婚姻是得撤銷，並非無效（§988無效事由不含婚齡）。","撤銷結婚須向法院請求，不得逕行撤銷（§989）。","§989：結婚違反婚齡規定者，當事人或其法定代理人得向法院請求撤銷。","當事人本人亦得請求撤銷，無須法定代理人同意。"],"tr":""},{"id":"h:102-34","p":"h","src":"102年第34題","sec":"E1","stem":"關於姻親關係，下列敘述何者正確？","opts":["甲之兒子乙與丙女結婚，甲與丙無姻親關係","甲之配偶乙，乙有一個哥哥丙，甲與丙無姻親關係","甲之配偶乙，乙有一個哥哥丙，丙有配偶丁，甲與丁無姻親關係","甲之兒子乙與丙女結婚，丙女之父親為丁，甲與丁無姻親關係"],"ok":[3],"ex":["§969：血親之配偶為姻親，丙為甲之兒媳，與甲有姻親關係。","§969：配偶之血親為姻親，丙為乙（甲之配偶）之哥哥，與甲為姻親。","§969：配偶之血親之配偶為姻親，丁為丙之配偶，與甲為姻親。","甲與丁（親家）之間不屬於§969所稱血親之配偶、配偶之血親或配偶之血親之配偶，無姻親關係。"],"tr":""},{"id":"h:102-35","p":"h","src":"102年第35題","sec":"E3","stem":"甲男與乙女未結婚，但生下丙。下列敘述何者正確？","opts":["乙女必須認領丙，丙才視為乙之婚生子女","縱使甲與乙嗣後結婚，丙仍是非婚生子女","甲死後，丙得向甲之繼承人提起認領之訴","甲認領丙後，無論如何絕對不得撤銷認領"],"ok":[2],"ex":["§1065 II：非婚生子女與生母之關係，視為婚生子女，無須認領。","§1064：非婚生子女，其生父與生母結婚者，視為婚生子女（準正）。","§1067：認領之訴，於生父死亡後得向生父之繼承人為之。","§1070：認領後不得撤銷，但有事實足認其非生父者不在此限，並非絕對不得撤銷。"],"tr":""},{"id":"h:102-36","p":"h","src":"102年第36題","sec":"D2","stem":"關於不動產所有權取得時效，下列敘述何者錯誤？","opts":["應以所有之意思","應和平公然繼續占有","應占有他人未登記之不動產","時效完成即取得不動產所有權"],"ok":[3],"ex":["§769，以「所有之意思」和平公然繼續占有，為時效取得不動產要件，正確。","和平（無暴力）、公然（公開）、繼續占有，均為必要條件，正確。","時效取得不動產，限於「他人未登記之不動產」，已登記不動產不能時效取得（§770），正確。","時效取得不動產，時效完成後，僅取得「請求登記為所有人」之權利，須「向地政機關聲請登記」後才取得所有權（§769），並非「時效完成即取得」，選項錯誤，為應選答案。"],"tr":""},{"id":"h:102-37","p":"h","src":"102年第37題","sec":"E4","stem":"甲死亡時，遺有財產新臺幣 500 萬元。甲有子女乙、丙二人為其法定繼承人，甲生前立有遺囑，載明若乙之兒子丁考上不動產經紀人，無償給與丁新臺幣 100 萬元。甲死亡時，丁尚未考上不動產經紀人。下列敘述何者正確？","opts":["遺囑於甲死亡時發生效力，丁取得新臺幣 100 萬元之所有權","遺囑於丁考上不動產經紀人時發生效力，丁取得新臺幣 100 萬元之所有權","遺囑於甲死亡時發生效力，丁取得請求給付新臺幣 100 萬元之債權","遺囑於丁考上不動產經紀人時發生效力，丁取得請求給付新臺幣 100 萬元之債權"],"ok":[3],"ex":["遺贈為債權效力，且附停止條件之遺贈，條件成就才發生效力（§1200），甲死亡時丁尚未取得所有權。","遺贈僅發生債權請求權，並非直接取得所有權。","遺贈附停止條件，於甲死亡時丁尚未取得債權，要待條件成就（§1200）。","§1200：遺贈附停止條件者，自條件成就時發生效力；丁考上時取得請求給付100萬之債權。"],"tr":""},{"id":"h:102-38","p":"h","src":"102年第38題","sec":"A1","stem":"19 歲之甲與 20 歲之乙訂立買賣契約，將一宗土地賣給乙，並將土地所有權移轉登記給乙。下列敘述何者正確？","opts":["買賣契約及所有權移轉契約，均需得甲之法定代理人書面或非書面之允許，始生效力","買賣契約及所有權移轉契約，均需得甲之法定代理人書面允許，一定要書面允許始生效","買賣契約需得甲之法定代理人書面允許，始生效力；所有權移轉契約則無須書面允許，亦生效力","所有權移轉契約需得甲之法定代理人書面允許，始生效力；買賣契約則無須書面允許，亦生效力"],"ok":[0],"ex":["§77限制行為能力人為意思表示應得法定代理人之允許，法條並未要求允許必須以「書面」為之，口頭允許亦可，買賣契約（債權行為）與所有權移轉（物權行為）兩者均須得法定代理人允許（不限書面），始生效力，依出題年舊法正確。（以上為出題年102年舊法：成年20歲，19歲之甲為限制行為能力人。現行法§12「滿十八歲為成年」，19歲之甲已成年，買賣與移轉均無須任何人允許，A的前提在現行法下不成立。）","法定代理人之允許不以書面為限，本選項限定「一定要書面」錯誤。","選項說買賣契約「需得書面允許」始生效力——錯在這裡：§77只要求「允許」，未要求書面，口頭允許亦可。後半段「所有權移轉無須書面允許」本身並沒錯（允許本來就不限書面；但移轉仍須得允許）。原解析把選項讀成「所有權移轉無須允許」，與選項文字不符。","選項說所有權移轉「需得書面允許」始生效力——錯在這裡：§77之允許不限書面。注意：不動產物權移轉行為本身依§758Ⅱ「應以書面為之」，但這是物權行為的方式，不是法定代理人「允許」的方式，不要混為一談。後半段「買賣無須書面允許」本身沒錯（仍須得允許，只是不限書面）。"],"tr":""},{"id":"h:102-39","p":"h","src":"102年第39題","sec":"E4","stem":"甲死亡後，其子女乙、丙二人為繼承人。甲留有房屋一棟市值新臺幣 500 萬元，且甲對丁有新臺幣500 萬元債權，已屆清償期。遺產分割時，乙分得房屋，丙分得債權。乙對丁何時之支付能力應負擔保責任？","opts":["乙就遺產分割時丁之支付能力負擔保之責","乙就債務實際清償時丁之支付能力負擔保之責","乙就清償期屆滿時丁之支付能力負擔保之責","乙就甲死亡時丁之支付能力負擔保之責"],"ok":[0],"ex":["§1169 I：遺產之債權，債務人於分割時已屆清償期者，分割時之支付能力負擔保責任。","擔保時點非債務實際清償時。","以清償期屆至時為準者，僅限分割時尚未屆清償期之債權（§1169 II），本題債權已屆期。","擔保時點非被繼承人死亡時。"],"tr":""},{"id":"h:102-40","p":"h","src":"102年第40題","sec":"E4","stem":"甲與乙結婚，並無子女，甲死亡時，甲之父母丙、丁尚健在；設甲遺有財產新臺幣 1200 萬元，並無任何債務。請問如何繼承？","opts":["乙得新臺幣 600 萬元，丙、丁各得新臺幣 300 萬元","乙得新臺幣 800 萬元，丙、丁各得新臺幣 200 萬元","乙得新臺幣 1200 萬元，丙、丁各得新臺幣 0 元","乙、丙、丁各得新臺幣 400 萬元"],"ok":[0],"ex":["§1144(2)：配偶與第二順序（父母）同為繼承時，配偶應繼分為遺產1/2，其餘1/2由父母均分（§1141），即乙600萬、丙丁各300萬。","此為配偶應繼分2/3之情形，與§1144(2)不符。","配偶與父母同為繼承，父母並非不得繼承。","配偶與父母非均分，配偶為1/2（§1144(2)）。"],"tr":""},{"id":"h:101-1","p":"h","src":"101年第1題","sec":"A2","stem":"下列有關法人之敘述，何者錯誤？","opts":["社團法人應設章程","以遺囑捐助設立財團法人者，不以訂立捐助章程為必要","應設董事","應設監察人"],"ok":[3],"ex":["此敘述正確，故非答案。§47：設立社團者，應訂定章程並記載目的、名稱、董事、總會等事項。","此敘述正確，故非答案。§60Ⅰ：設立財團應訂立捐助章程，但以遺囑捐助者不在此限；§60Ⅲ：以遺囑捐助而無遺囑執行人時，法院得依主管機關、檢察官或利害關係人之聲請指定遺囑執行人。","此敘述正確，故非答案。§27Ⅰ：法人應設董事，董事對外代表法人並執行事務。","本題問「錯誤」者。§27Ⅳ：法人「得」設監察人，監察法人事務之執行，為任意機關而非必設機關，「應設監察人」錯誤，為本題答案。"],"tr":""},{"id":"h:101-2","p":"h","src":"101年第2題","sec":"A5","stem":"甲於 98 年 6 月 1 日受乙脅迫，約定將甲所有之動產以遠低於市價之價格出售予乙。事經 2 年餘後，乙請求甲依約交付該動產。下列敘述何者正確？","opts":["甲得於撤銷原先受脅迫所為之意思表示後，拒絕給付","甲得撤銷受脅迫意思表示之權利行使期間已過，應為給付","即使甲未撤銷受脅迫所為之意思表示，仍得拒絕給付","甲得主張與乙所締結之契約自始無效，拒絕給付"],"ok":[2],"ex":["§93 撤銷權須自脅迫終止後1年內行使，2年餘後撤銷權已消滅，無法再撤銷。","雖撤銷權期間已過，但被害人仍可依§198 拒絕履行，非「應為給付」。","乙之脅迫構成侵權行為，因侵權行為取得之債權，被害人之廢止請求權縱因時效消滅，仍得拒絕履行（§198）。","§92 受脅迫所為意思表示為「得撤銷」，並非自始無效。"],"tr":""},{"id":"h:101-3","p":"h","src":"101年第3題","sec":"C1","stem":"甲當面向乙表示願以一千萬元出售甲所有之 A 房屋予乙，乙當場未置可否，經三日後乙回覆甲願以一千萬元購買 A 屋。就甲、乙各自之意思表示，下列敘述何者最正確？","opts":["甲之意思表示為要約，乙之意思表示為承諾","甲之意思表示為要約引誘，乙之意思表示為要約","甲之意思表示為要約，乙之意思表示為要約引誘","甲之意思表示為要約，乙之意思表示為新要約"],"ok":[3],"ex":["乙三日後才回覆，已逾對話要約應即時承諾之期間（§156），不是有效承諾。","甲所為特定價格與標的之表示是要約，並非要約引誘。","乙之回覆不是要約引誘，而是遲到之承諾，視為新要約。","§156 對話要約須立時承諾，否則失效；§160Ⅰ 遲到之承諾視為新要約。"],"tr":""},{"id":"h:101-4","p":"h","src":"101年第4題","sec":"B6","stem":"下列有關加害人應負損害賠償責任之敘述，何者最正確？","opts":["受僱人甲因執行職務不法侵害第三人乙之權利時，原則上僅由甲對乙負損害賠償責任","限制行為能力人甲不法侵害第三人乙之權利時，即使甲於行為時有識別能力，原則上由甲及其法定代理人對乙連帶負損害賠償責任","法人甲之董事丙因執行職務對第三人乙造成損害時，因甲無實體存在，故僅由丙單獨對乙負損害賠償責任","甲、丙、丁三人共謀聯手圍毆乙，實際下手時，如丁僅在一旁叫囂助陣，則丁不須對乙因被毆所生損害負賠償責任"],"ok":[1],"ex":["§188Ⅰ 僱用人與受僱人連帶負責，並非原則上僅受僱人負責。","§187Ⅰ 限制行為能力人行為時有識別能力者，與其法定代理人連帶負損害賠償責任。","§28 法人與董事連帶負責，並非僅董事單獨負責。","§185Ⅱ 幫助人視為共同行為人，丁叫囂助陣屬幫助，仍須連帶負責。"],"tr":""},{"id":"h:101-5","p":"h","src":"101年第5題","sec":"C4","stem":"甲、乙、丙三人締結合夥契約，並以每月三萬元租金租用甲所有之房屋為共同經營事業之場所。惟因合夥事業經營不順致合夥解散，解散後已無合夥財產清償累計三個月未支付之租金。就積欠之九萬元租金，出租人甲得向乙、丙為如何之主張？","opts":["甲僅得分別向乙、丙請求各應支付三萬元","甲僅得分別向乙、丙請求各應支付四萬五千元","甲僅得向乙或丙請求應支付六萬元","甲僅得向乙或丙請求應支付九萬元"],"ok":[0],"ex":["甲本身也是合夥人，須自負應分擔之一份；損失分擔比例依§677 I，未約定者按出資額比例；本題未載約定與出資額，以三人均等計算，九萬元每人分擔三萬元。甲對外雖可依§681 主張合夥人連帶責任，但甲自己就是應分擔的合夥人之一，自己那三萬元不能再向別人要，故甲僅得分別向乙、丙請求其各自分擔額三萬元。","若乙、丙各負四萬五千元，等於甲不分擔，與合夥人亦應分擔損失之內部關係不符。","甲不得向乙或丙就六萬元全額請求，因甲自己亦為債務人之一，請求範圍限於他人應分擔額。","§681 之連帶責任是對外保護第三債權人；甲兼為合夥人，不能請求九萬全額。"],"tr":""},{"id":"h:101-6","p":"h","src":"101年第6題","sec":"C1","stem":"甲與乙締結將甲所有 A 屋出售予乙之買賣契約後，A 屋於甲依約交付予乙前因火災燒毀致不能給付。下列敘述何者最正確？","opts":["如 A 屋之燒毀係可歸責於甲之事由所致，乙僅須支付二分之一之價金","如 A 屋之燒毀係可歸責於乙之事由所致，甲僅得請求支付二分之一之價金","如 A 屋之燒毀係可歸責於甲之事由所致，乙得解除契約","如 A 屋之燒毀係可歸責於第三人丙之事由所致，乙仍須支付二分之一之價金"],"ok":[2],"ex":["可歸責甲致給付不能，乙得依§226 I 請求損害賠償或§256 解除契約，法律無『價金減半』之規定。","§267：因可歸責債權人之事由致給付不能，債務人得請求全部對待給付（扣除所免費用與取得利益），並非二分之一。","§226 I、§256：可歸責債務人之事由致給付不能，債權人得解除契約並請求損害賠償。","可歸責於第三人而不可歸責雙方者，§225 I 免給付義務、§266 I 乙免為對待給付，並非支付一半。"],"tr":""},{"id":"h:101-7","p":"h","src":"101年第7題","sec":"C5","stem":"甲與乙約定，甲不得將其對乙之非不得讓與的 A 金錢債權讓與予第三人。事後，甲卻違反與乙之約定，將 A 債權讓與予丙。就此情形，下列敘述何者最正確？","opts":["甲、乙之約定違反誠信原則，無效。甲、丙間之讓與契約有效","甲、乙之約定有效。但如丙為善意第三人，甲、乙之約定不得對抗丙","無論債權人如何變動，債務人乙皆須清償，故甲、乙間之約定無效","甲、乙之約定效力未定。甲、丙之讓與契約無效"],"ok":[1],"ex":["債權禁止讓與之特約依契約自由有效，不因違反誠信原則而無效。","§294Ⅰ②、Ⅱ 禁止讓與特約有效，但不得對抗善意第三人，丙善意則讓與有效。","債權之讓與禁止約定有效，不可因債務人最終都要清償就否定其效力。","約定並非效力未定，且丙善意時讓與契約有效。"],"tr":""},{"id":"h:101-8","p":"h","src":"101年第8題","sec":"E4","stem":"被繼承人甲於生前立下遺囑。下列敘述何者最正確？","opts":["甲遺囑中之受遺贈人於遺囑生效前死亡者，其遺贈無效","甲得以遺囑禁止遺產之分割，但其禁止之效力以五年為限","未滿十六歲之甲於經其法定代理人允許時，得立遺囑","甲遺囑中之受遺贈人拋棄遺贈者，自為拋棄之意思表示時發生效力"],"ok":[0],"ex":["§1201：受遺贈人於遺囑發生效力前死亡者，其遺贈不生效力。","§1165 II：遺囑禁止遺產分割者，其禁止效力以十年為限，不是五年。","§1186：未滿16歲者不得為遺囑，且限制行為能力人立遺囑無須法定代理人允許，故不因法定代理人允許而得立。","§1206 II：遺贈之拋棄，溯及遺囑人死亡時發生效力，不是自表示時。"],"tr":""},{"id":"h:101-9","p":"h","src":"101年第9題","sec":"B1","stem":"甲借款十萬元予乙，約定於半年後清償。下列敘述何者最正確？","opts":["對於乙之期前清償，甲不得為反對之意思表示","甲請求乙為期前清償時，乙不得拒絕","乙之期前清償縱經甲受領，乙仍得以其期限利益受損，向甲主張不當得利返還請求權","乙之期前清償如經甲受領，則乙不得再向甲主張不當得利返還請求權"],"ok":[3],"ex":["§316：期前清償須「無反對之意思表示」，甲可有反對（如約定不得期前清償），並非不得為反對表示。","§316：定有清償期者，債權人不得於期前請求清償，乙得拒絕。","§180(2)：債務人於未到期之債務因清償而為給付者，不得請求返還；期限利益屬債務人，提前清償即視為拋棄，不能主張利益受損而請求不當得利。","§180(2)：未到期債務因清償而為給付，債權人受領後，債務人不得再依不當得利請求返還。"],"tr":""},{"id":"h:101-10","p":"h","src":"101年第10題","sec":"B1","stem":"甲對乙有於今年（下同）5 月 31 日到期之買賣價金金錢債權，乙對甲有於 6 月 30 日到期之消費借貸金錢債權。甲於 7 月 1 日主張抵銷，乙於 7 月 5 日回覆同意甲之抵銷的主張。試問：因甲主張抵銷而消滅之債之關係，於何時發生效力？","opts":["5 月 31 日","6 月 30 日","7 月 1 日","7 月 5 日"],"ok":[1],"ex":["5/31 只是甲之債權屆期，但乙之債權（甲之債務）至6/30始屆期，尚未達雙方均可抵銷。","§335 I 後段：抵銷溯及最初得為抵銷時；依§334 I 須兩債務均屆清償期，即6/30，甲7/1單方意思表示（§335 I）即生抵銷。","7/1 為甲為意思表示之日，但抵銷效力依§335 I 後段溯及最初得為抵銷時。","抵銷為單方行為，不需乙同意（§335 I），乙7/5之回覆不影響效力時點。"],"tr":""},{"id":"h:101-11","p":"h","src":"101年第11題","sec":"C3","stem":"甲、乙間約定由甲幫乙為訂約之媒介，並由乙給付報酬予甲。甲、乙所定契約之名稱為下列何者？","opts":["承攬契約","代辦契約","僱傭契約","居間契約"],"ok":[3],"ex":["承攬（§490）：一方為他方完成一定之工作，他方俟工作完成給付報酬；重在完成「工作結果」，而非替人報告訂約機會或媒介訂約，故非本題契約。","「代辦」指代辦商（§558，本條文庫未收，不逐字引用）：代辦商的重點是受商號委託、以該商號名義辦理商號事務，並不是為他人報告訂約機會或媒介訂約；本題甲是「媒介訂約、收報酬」，符合§565居間，不是代辦。","僱傭（§482）：一方於一定或不定期限內為他方服勞務，他方給付報酬；重在提供勞務本身，與居間「促成他人訂約」不同。","居間（§565）：一方為他方報告訂約之機會或為訂約之媒介，他方給付報酬之契約；本題甲為乙媒介訂約、乙給付報酬，正是居間契約，正確。"],"tr":""},{"id":"h:101-12","p":"h","src":"101年第12題","sec":"B2","stem":"出賣人甲依其與買受人乙間之動產買賣契約，於約定之日合法提出給付，卻遭乙拒絕受領。依實務見解，就乙拒絕受領之法律效果，下列敘述何者最正確？","opts":["甲得解除契約","甲不得向乙請求繼續保管給付物之必要費用","甲得拋棄對該動產之占有","甲對標的物之保管，僅就故意負其責任"],"ok":[0],"ex":["買受人有受領標的物義務（§367），實務肯認其受領義務屬債務，經催告仍拒絕受領者，出賣人得依§254解除契約。","債權人遲延時，債務人得請求賠償提出及保管給付物之必要費用（§240），故甲得請求。","得拋棄占有者限於有交付不動產義務之債務人（§241 I）；本題為動產，不適用。","債權人受領遲延期間，債務人僅就故意或重大過失負責（§237），非僅故意。"],"tr":""},{"id":"h:101-13","p":"h","src":"101年第13題","sec":"C2","stem":"甲將其所有土地出租予乙建築房屋。下列敘述何者錯誤？","opts":["契約成立後，乙得請求甲為地上權之登記","乙將房屋所有權移轉予丙時，原基地租賃契約對於丙仍繼續存在","乙出賣房屋時，甲無依同樣條件優先承買之權利","甲、乙得約定由乙負擔就土地應納之一切稅捐"],"ok":[2],"ex":["§422-1：租用基地建築房屋者，承租人於契約成立後，得請求出租人為地上權之登記，正確。","§426-1：租用基地建築房屋，承租人房屋所有權移轉時，其基地租賃契約對於房屋受讓人仍繼續存在，正確。","§426-2 Ⅰ：承租人出賣房屋時，基地所有人有依同樣條件優先承買之權；甲（基地所有人）有優先承買權，選項說『無』，與條文相反，錯誤，為應選答案。","§427 規定租賃物應納之一切稅捐由出租人負擔，但該條並無禁止另約之規定，當事人得依契約自由約定由承租人負擔，正確。"],"tr":""},{"id":"h:101-14","p":"h","src":"101年第14題","sec":"D2","stem":"甲、乙、丙三人分別共有一筆 A 土地。三人就 A 地約定各自得使用之特定部分，且於二十年內不得請求分割。下列敘述何者最正確？","opts":["如甲使用部分在約定不得請求分割期間內被徵收，甲仍得隨時請求分割","不得分割之約定逾五年，無效。三人應重新約定","不得分割之約定逾五年，應縮短為五年","於約定不得請求分割期間內，任一共有人皆不得處分其應有部分"],"ok":[0],"ex":["約定不分割期間內若有重大事由，共有人仍得隨時請求分割（§823 III）；使用部分被徵收使約定管理基礎喪失，屬重大事由。","不分割約定逾五年並非無效，而是縮短（§823 II）；且不動產訂有管理約定者上限為三十年。","共有不動產訂有管理之約定時，不分割期限上限為三十年（§823 II但書），二十年未逾限，不須縮短。","各共有人得自由處分其應有部分（§819 I），不分割約定不限制應有部分之處分。"],"tr":""},{"id":"h:101-15","p":"h","src":"101年第15題","sec":"D5","stem":"甲以其土地設定地上權於乙後，乙以該地上權設定抵押權於丙。下列敘述何者最正確？","opts":["原則上如乙未得甲之同意，丙所設定之抵押權無效","如乙繼承甲之土地，地上權因混同而消滅","非得丙之同意，乙不得拋棄其地上權","甲不須乙、丙同意，得自由拋棄其土地所有權"],"ok":[2],"ex":["依§882，地上權得為抵押權之標的；且§838Ⅰ 規定地上權人得將其權利讓與他人或設定抵押權（除非契約另有約定或習慣），不須土地所有人甲同意，丙之抵押權有效，選項錯誤。","乙繼承甲之土地，地上權與土地所有權同歸一人，依§762 本文其他物權因混同而消滅；但書規定其他物權之存續於所有人或第三人有法律上利益者不消滅，本題丙對地上權有抵押權，地上權存續於丙有法律上利益，故不因混同而消滅，選項錯誤。","依§764Ⅱ，物權之拋棄，如第三人有以該物權為標的物之其他物權者，非經該第三人同意，不得為之；丙以乙的地上權為標的設有抵押權，乙非得丙同意不得拋棄地上權，正確。","甲拋棄土地所有權，同樣受§764Ⅱ 限制：乙就該土地有地上權（以土地所有權為基礎的其他物權），非經第三人同意不得拋棄，所以甲並非「不須同意得自由拋棄」，選項錯誤。"],"tr":""},{"id":"h:101-16","p":"h","src":"101年第16題","sec":"D5","stem":"甲以其土地設定地上權於乙。下列敘述何者最正確？","opts":["定有期限之地上權原則上不因建築物於所定期限內滅失而消滅","甲、乙間不得設定未定有期限之地上權","甲、乙間不得設定未定有地租之地上權","因不可抗力致妨礙土地之使用時，乙得請求減免租金"],"ok":[0],"ex":["地上權不因建築物或其他工作物之滅失而消滅（§841）。","地上權得不定期限（§833-1、§834、§835），當事人可約定未定期限。","地上權得為無償，不以有地租為必要（§835-1 II規範無償地上權之酌定地租），故可設定無地租之地上權。","地上權人不得因不可抗力妨礙土地使用而請求免除或減少地租（§837）。"],"tr":""},{"id":"h:101-17","p":"h","src":"101年第17題","sec":"E4","stem":"甲懷胎乙五個月時，其丈夫丙因病過世，留下一棟房屋與現金 200 萬元之遺產，下列敘述何者最正確？","opts":["乙尚未出生，不具有權利能力，不得繼承丙之遺產","乙雖尚未出生，但關於利益之享有具有部分行為能力，得繼承丙之遺產","乙以將來非死產者為限，關於個人利益之保護享有行為能力，在出生後得溯及繼承開始時繼承丙之遺產","乙以將來非死產者為限，關於個人利益之保護享有權利能力，得繼承丙之遺產"],"ok":[3],"ex":["§7：胎兒以將來非死產者為限，關於個人利益之保護，視為既已出生，故得繼承。","§7係視為既已出生而有權利能力，並非「部分行為能力」；胎兒無行為能力。","胎兒享有的是權利能力而非行為能力，選項概念錯誤（§7）。","§7：以將來非死產為限，關於個人利益之保護享有權利能力，可繼承丙之遺產（§1166亦規定保留胎兒應繼分）。"],"tr":""},{"id":"h:101-18","p":"h","src":"101年第18題","sec":"D6","stem":"甲分別於乙、丙所有之不動產設定普通抵押權，以擔保甲對乙之債權。下列敘述何者最正確？","opts":["甲向丙請求清償債務時，丙得主張先訴抗辯權","即使甲對乙之債權已因時效而消滅，甲仍得於消滅時效完成後五年內實行對丙之抵押權","甲僅得先對乙之不動產實行抵押權","甲實行對丙之抵押權後，丙不得向乙求償"],"ok":[1],"ex":["物上保證人丙不享有先訴抗辯權，抵押權人得就其抵押物直接實行（先訴抗辯屬保證§745）。","債權時效完成後，抵押權人於五年內未實行抵押權者，抵押權始消滅（§880）；五年內仍得實行，物上保證人之抵押物亦同（§145 I）。","抵押權人對債務人與物上保證人之不動產，原則得任擇其一實行（§875）；同時拍賣時，依§875-1 應先就債務人所有之抵押物賣得價金受償，選項「僅得先對乙」之說法不正確。","物上保證人因抵押權實行失去抵押物所有權時，於其清償之限度內承受債權人對債務人之債權（§879 I，法定代位），丙得向乙求償。"],"tr":""},{"id":"h:101-19","p":"h","src":"101年第19題","sec":"C5","stem":"甲以其對乙尚未屆清償期之金錢債權設定權利質權於丙，以擔保丙對甲之金錢債權，並於設定時即通知乙。下列敘述何者最正確？","opts":["該權利質權之設定，未得乙之同意，無效","乙得以於受通知後始對甲取得之金錢債權，對丙主張抵銷","乙得以於受通知時對甲之已屆清償期之金錢債權，對丙主張抵銷","該權利質權之設定，須由甲、丙共同通知乙，始對乙生效力"],"ok":[2],"ex":["權利質權設定準用債權讓與規定（§902），讓與債權無須債務人同意，只需通知（§297），故設定並非無效。","§299 II：只有債務人「受通知時」已對讓與人取得之債權才可抵銷，受通知後才取得者不得主張。","權利質權依§902「依關於其權利讓與之規定」設定，所以質權人丙的地位就像債權讓與的受讓人；乙能不能對丙抵銷，看§299Ⅱ兩個要件：①乙「受通知時」對甲已有債權；②該債權的清償期「先於或同時」於被質押的債權屆至。涵攝：甲對乙的債權設質時「尚未屆清償期」，乙對甲的債權在受通知時「已屆清償期」，乙的債權先到期，兩個要件都符合，乙得對丙主張抵銷。被質押的債權還沒到期也不妨礙：那是乙自己的債務，§316 債務人得於期前清償，乙可以放棄期限利益拿來抵銷。用意：乙本來就能等自己的債權到期後，拿來抵銷甲的債權；不能因為甲把債權拿去設質，乙就失去這個期待。對照 B：受通知後才取得的債權，要件①不符，不能抵銷。","§297 I：通知由讓與人或受讓人任一方為之即可（§902 準用），不必甲、丙共同通知。"],"tr":""},{"id":"h:101-20","p":"h","src":"101年第20題","sec":"E2","stem":"關於法定夫妻財產制，下列敘述何者錯誤？","opts":["無論是婚前財產或婚後財產，由夫妻各自所有","夫或妻婚前財產，於婚姻關係存續中所生之孳息，推定為婚後財產","夫或妻各自管理、使用、收益及處分其財產","夫妻因判決而離婚者，其現存婚後財產之價值的計算，以起訴時為準"],"ok":[1],"ex":["§1017 I：夫或妻之財產分為婚前財產與婚後財產，由夫妻各自所有。","§1017 II：婚前財產於婚姻關係存續中所生之孳息，是「視為」婚後財產，而非推定，不得以反證推翻。","§1018：夫妻各自管理、使用、收益及處分其財產。","§1030-4 I但書：因判決離婚者，現存婚後財產價值以起訴時為準。"],"tr":""},{"id":"h:101-21","p":"h","src":"101年第21題","sec":"E4","stem":"甲死亡時有遺族配偶乙，子女丙及丁，丙之子女戊。下列敘述何者最正確？","opts":["如繼承財產不足清償繼承債務，乙以其固有財產清償繼承債務後，不得向債權人主張不當得利返還請求權","丙未表示是否繼承前即死亡，戊得於甲死亡後一年內，拋棄對甲之繼承","即使丁於拋棄繼承時尚未成年，亦不得於事後撤銷拋棄之意思表示","如丙已先於甲死亡，且丙於生前即表示拋棄繼承，則戊不得繼承甲之財產"],"ok":[0],"ex":["繼承人負限定責任（§1148 II）：限制的是「責任範圍」，被繼承人的債務本身並未消滅（通說稱超出遺產部分為自然債務，債權人不能強制執行繼承人的固有財產）。乙自願以固有財產清償，債權人受領仍有法律上原因，不成立不當得利，乙不得請求返還。","拋棄期間為知悉其得繼承時起三個月（§1174 II），不是一年；戊之主張期間亦不因此延長。","限制行為能力人未得法定代理人允許所為單獨行為無效（§78），拋棄繼承為單獨行為，並非「不得撤銷」之問題。","丙於甲死亡前不可能有效拋棄繼承（拋棄須於繼承開始後，§1174），丙先於甲死亡時，戊得代位繼承（§1140）。"],"tr":""},{"id":"h:101-22","p":"h","src":"101年第22題","sec":"A1","stem":"甲發生車禍傷及腦部，成為植物人，下列敘述何者最正確？","opts":["甲成為植物人喪失權利能力","甲雖成為植物人，但關於個人利益之享受仍具有部分權利能力","植物人為無行為能力人，並且不具有權利能力","甲雖成為植物人，仍具有權利能力"],"ok":[3],"ex":["權利能力始於出生、終於死亡（§6）；植物人仍生存，權利能力不因此喪失。","植物人仍生存，依§6享有完整權利能力，並非僅就「個人利益之享受」有部分權利能力。「關於個人利益之保護視為既已出生」是§7對「胎兒」的特別規定，不能套用於植物人。","權利能力與行為能力是不同概念：植物人縱受監護宣告而無行為能力（§15），其權利能力仍然存在，不可混淆。","權利能力始於出生終於死亡（§6），植物人生命現象仍存在，具有完整權利能力；其意思能力欠缺，可能影響的是行為能力（得經法院為監護宣告），而非權利能力。"],"tr":""},{"id":"h:101-23","p":"h","src":"101年第23題","sec":"B6","stem":"甲被酒醉駕車之乙撞傷住院，甲所駕駛之汽車亦因此受損，下列敘述何者最正確？","opts":["甲對於汽車所受之損害，僅得請求乙將汽車修復原狀，不得主張修復原狀所必要之費用以代替回復原狀","甲受傷住院，得因人格權受侵害對乙請求非財產上之損害賠償，其請求之數額限於甲實際所受之損害","甲對於汽車所受之損害，得對加害人乙請求汽車因毀損所減少之數額","被害人甲若對第三人負有法定扶養義務者，加害人乙對該第三人亦應負損害賠償責任"],"ok":[2],"ex":["§213 III：負損害賠償責任者，債權人得請求支付回復原狀所必要之費用以代回復原狀，不限於請求修復原狀。","§195 I：非財產上損害（慰撫金）依被害人身分地位、痛苦程度等酌定相當金額，並非限於實際所受損害數額。","§196：不法毀損他人之物者，被害人得請求賠償其物因毀損所減少之價額。","§192 II：對第三人負法定扶養義務者，加害人對該第三人負賠償責任，限於被害人「致死」之情形；本題甲僅受傷。"],"tr":""},{"id":"h:101-24","p":"h","src":"101年第24題","sec":"A2","stem":"甲為幫助清寒家庭學生求學，捐助三千萬元成立 A 教育基金會，經主管機關許可後，登記為法人，下列敘述何者最正確？","opts":["甲之捐助行為為事實行為","A 教育基金會應設董事","A 教育基金會為公益社團法人","A 教育基金會應設總會，作為基金會之最高意思機關"],"ok":[1],"ex":["捐助行為係以財產捐贈成立法人之意思表示，屬法律行為（單獨行為），並非事實行為。","財團法人應設董事，執行財團事務並代表法人對外行使職權（§27，法人通則規定，財團直接適用），正確。","以捐助財產設立、無社員組織者為「財團法人」，非社團法人，本題捐助3000萬元設立基金會，屬財團法人。","財團法人無社員組織，故無「總會」，總會是社團法人特有的最高意思機關，財團法人無此機關設計。"],"tr":""},{"id":"h:101-25","p":"h","src":"101年第25題","sec":"C2","stem":"甲出租房屋給乙，三天後乙搬入居住，並依約繳交房租，下列敘述何者最正確？","opts":["關於房屋租金之請求權，其消滅時效期間為兩年","租賃期間若甲將房屋出賣給丙，甲與乙之租賃關係即消滅","甲若將房屋贈與丁，並移轉房屋所有權給丁，則乙之租賃契約對丁繼續存在","甲若先後將房屋出賣給戊與辛，則基於優先性之考量，僅甲與戊之買賣契約生效"],"ok":[2],"ex":["§126：租金請求權之消滅時效為5年，非2年。","買賣不破租賃（§425 I），出賣後租賃關係不因此消滅。","§425 I：租賃物交付後，承租人占有中，所有權因贈與讓與第三人，租賃契約對受讓人仍繼續存在。","一物二賣兩買賣契約均有效，並非僅先訂之契約生效。"],"tr":""},{"id":"h:101-26","p":"h","src":"101年第26題","sec":"A1","stem":"甲十八歲，已婚，下列敘述何者最正確？","opts":["甲已成年","甲得獨立為有效之單獨行為","甲授與代理權給乙，其授權行為效力未定","甲如欲與其配偶兩願離婚，得自行為之，無須得法定代理人之同意"],"ok":[1],"ex":["依出題年（101年）舊法，成年為20歲，18歲仍屬未成年；已婚只是使其有行為能力（舊§13Ⅲ），並未成年，故A錯誤。現行法：§12「滿十八歲為成年」，18歲之甲已成年，A敘述在現行法下為真。","未成年人已結婚者有行為能力（舊§13Ⅲ），故得獨立為有效之單獨行為。","已婚未成年人既有行為能力，授權行為無須法定代理人承認，不屬效力未定。","依出題年舊法，§1049但書規定未成年人兩願離婚應得法定代理人同意，故「無須同意」錯誤。現行§1049：「夫妻兩願離婚者，得自行離婚。」但書已刪，且18歲之甲已成年，現行法下D敘述為真。"],"tr":""},{"id":"h:101-27","p":"h","src":"101年第27題","sec":"C3","stem":"甲委任乙處理 A 土地買賣相關事宜，下列敘述何者最正確？","opts":["委任人甲得將對乙之處理委任事務請求權讓與第三人","受任人乙若受有報酬，委任人甲無須因受任人之請求，預付處理委任事務之必要費用","受任人乙因不可歸責於自己之事由，不得已須在不利於委任人之時期終止契約者，對於委任人甲因此所受之損害無須付賠償責任","以上皆為正確"],"ok":[2],"ex":["委任以信任為基礎，委任事務請求權依債之性質不得讓與（§294 I①），不得任意讓與第三人。","§545：受任人得請求委任人預付處理委任事務之必要費用，與有無報酬無關。","§549 II 但書：因非可歸責於該當事人之事由致不得不終止契約者，不負損害賠償責任。","A、B 選項不正確，故『以上皆正確』不成立。"],"tr":""},{"id":"h:101-28","p":"h","src":"101年第28題","sec":"C5","stem":"甲將其對乙之債權讓與給丙，下列敘述何者最正確？","opts":["甲若未將債權讓與之事由通知乙，則甲與丙間之債權讓與無效","甲應將證明債權之文件，交付受讓人丙","債權讓與為負擔行為","債權讓與時，該債權擔保之最高限額抵押權亦隨同移轉"],"ok":[1],"ex":["§297 通知僅為對債務人生效之要件，讓與人與受讓人間讓與合意即生效力，未通知並非無效。","§296：讓與人應將證明債權之文件交付受讓人，並應告以主張該債權所必要之一切情形。","債權讓與使債權移轉，直接變動權利，為處分行為（準物權行為），並非負擔行為。","§295 雖規定從屬權利隨同移轉，但最高限額抵押權於原債權確定前，擔保債權之讓與不隨同移轉（§881-6）。"],"tr":""},{"id":"h:101-29","p":"h","src":"101年第29題","sec":"C2","stem":"甲將位於忠孝路的一間公寓出租給乙，租期三年，下列敘述何者最正確？","opts":["乙若遲繳租金，甲應在兩年內請求乙繳納，否則租金請求權將罹於消滅時效","甲與乙之租賃契約若未經公證，在乙搬入租賃房屋後，縱使甲將租賃物所有權讓與第三人，甲與乙之租賃契約對於第三人不生效力","乙搬入租賃房屋居住後，縱使甲將租賃物所有權基於贈與之原因讓與第三人丙，租賃契約對於丙不生效力，丙得請求乙搬離租屋處並返還房屋","租賃物之修繕，得因雙方當事人之約定，由承租人負責"],"ok":[3],"ex":["§126：租金請求權時效為5年，不是2年。","§425 I：租期3年，雖未公證，因交付且占有中，所有權移轉後租約仍對受讓人繼續存在。","贈與讓與所有權亦適用§425 I，租賃契約對丙繼續存在，丙不得請求乙搬離。","§429 I：租賃物修繕除契約另有訂定外由出租人負擔，故當事人得約定由承租人修繕。"],"tr":""},{"id":"h:101-30","p":"h","src":"101年第30題","sec":"C4","stem":"乙家中的寵物飼料已吃完，向鄰居甲借用一包飼料供家中寵物食用，並約定隔日還給甲一包相同的新飼料，下列敘述何者最正確？","opts":["甲與乙之間成立使用借貸","甲與乙之借貸契約於雙方意思合致時即為成立","甲與乙之契約如未約定報償，貸與人甲對於借用物之瑕疵，非因故意而未告知時，對於借用人乙因此所受之損害無須負損害賠償責任","借用人不能以種類、品質、數量相同之物返還時，應以借用時，借用地之價值償還"],"ok":[2],"ex":["約定返還「相同種類、品質、數量之物」，是消費借貸（§474），非使用借貸（返還原物）。","消費借貸為要物契約，依§474Ⅰ須移轉金錢或其他代替物之所有權於他方，始生效力（舊§475 已於88年刪除），非意思合致即成立。","§476 II、III：無報償之消費借貸，借用物有瑕疵時，借用人得照有瑕疵原物之價值返還（II）；貸與人故意不告知其瑕疵者，借用人始得請求損害賠償（III）。","§479：借用人不能以種類、品質、數量相同之物返還時，原則以返還時、返還地之價值償還，非借用時、借用地。"],"tr":""},{"id":"h:101-31","p":"h","src":"101年第31題","sec":"A6","stem":"甲為乙之代理人，下列敘述何者最正確？","opts":["若甲為意定代理人，其被相對人丙詐欺所為之代理行為，應由甲自行撤銷","甲逾越代理權限所為之代理行為，得因乙之承認而確定生效","若甲僅十六歲，甲所為之代理行為無效","若甲為乙之法定代理人，得因乙之同意，為雙方代理行為"],"ok":[1],"ex":["代理人意思表示有無瑕疵（意思欠缺、被詐欺、被脅迫），依§105原則就代理人決定；但法律效果歸屬本人，撤銷權原則上歸屬於本人乙，而非由代理人甲自行撤銷。","代理人逾越代理權限所為之行為屬無權代理，依§170非經本人承認，對本人不生效力（效力未定）；經本人乙承認，即確定生效。","代理人不以有行為能力為必要，§104：代理人所為意思表示之效力不因其為限制行為能力人而受影響，故16歲之甲所為代理行為並非無效。","§106：雙方代理（既為本人又為第三人之代理人而為法律行為）須「經本人許諾」才可。甲若為乙之「法定代理人」，表示乙為無行為能力人或限制行為能力人（§76、§77），其許諾本身須由法定代理人（即甲）代為或同意，等於甲自己許諾自己，無從達到由本人判斷利益的目的，故不能認為因乙之同意即可為雙方代理。"],"tr":""},{"id":"h:101-32","p":"h","src":"101年第32題","sec":"B2","stem":"甲向乙提出給付，但給付遲延，下列敘述何者最正確？","opts":["乙得向甲主張遲延之損害賠償以代替原定給付","甲在遲延中，對於因不可抗力而生之損害，原則上毋須負責","遲延之債務，以支付金錢為標的者，債權人乙得向債務人甲請求以法定利率計算之遲延利息","對於甲之遲延給付，不論是否可歸責於甲，甲皆應負遲延之賠償責任"],"ok":[2],"ex":["§232：遲延後債權人得請求賠償不履行損害以代原給付，須以遲延後之給付對債權人無利益並拒絕給付為前提，非當然得請求。","§231 II：債務人在遲延中，對於不可抗力所生之損害亦應負責，除非證明縱不遲延仍不免發生損害。","§233 I：金錢債務遲延，債權人得請求依法定利率（§203 週年5%）計算之遲延利息。","§230：因不可歸責於債務人之事由致未為給付者，債務人不負遲延責任。"],"tr":""},{"id":"h:101-33","p":"h","src":"101年第33題","sec":"C4","stem":"甲向乙訂購珍珠項鍊一條，甲與乙並約定由乙直接向第三人丙提出給付，丙對乙有直接請求權，下列敘述何者最正確？","opts":["在丙表示享受其利益之意思後，甲與乙仍得隨時撤銷丙所取得之利益","在丙表示享受其利益之意思後，丙得請求乙向自己提出給付，但乙得以由契約所生之一切抗辯對抗丙","在丙表示享受其利益之意思後，乙得向丙請求給付項鍊之價金","甲與乙所締結之買賣契約為負擔契約，對第三人丙不生效力，丙不得對乙直接請求給付"],"ok":[1],"ex":["§269 II：第三人未表示享受利益意思前，當事人得變更或撤銷；表示後即不得再撤銷。","§269 I、§270：第三人有直接請求給付權，債務人得以由契約所生之一切抗辯對抗受益之第三人。","價金係要約人甲依買賣契約應給付予乙，乙不得向第三人丙請求價金；丙僅享受受領項鍊之利益。","§269 I：利益第三人契約有效，第三人丙對債務人乙有直接請求給付之權。"],"tr":""},{"id":"h:101-34","p":"h","src":"101年第34題","sec":"A5","stem":"甲與乙通謀虛偽買賣甲所有之 A 土地一筆，並將 A 地所有權移轉給乙，下列敘述何者最正確？","opts":["甲與乙所為之通謀虛偽意思表示效力未定","甲與乙所為之通謀虛偽買賣有效，但所有權之移轉無效","乙將 A 地出賣給丙，締結買賣契約，乙與丙之買賣構成無權處分","乙將 A 地出賣給丙，締結買賣契約，乙與丙之買賣契約有效"],"ok":[3],"ex":["通謀虛偽意思表示依§87Ⅰ本文為「無效」，不是效力未定。","甲乙間買賣（債權行為）與所有權移轉（物權行為）皆為通謀虛偽之意思表示，依§87Ⅰ本文均無效，並非買賣有效而僅移轉無效。","無權處分（§118Ⅰ：無權利人就權利標的物所為之處分，經有權利人承認始生效力）針對的是「處分行為」（移轉所有權）。乙丙簽訂的買賣契約是負擔行為（債權契約），不是處分，故不構成無權處分；乙事後移轉登記給丙才可能涉及無權處分問題。","乙丙間買賣是負擔行為，出賣人乙負有§348的移轉所有權義務，債權契約不以出賣人有處分權為成立有效要件，故買賣契約有效；至於所有權能否移轉予丙，另涉及§87Ⅰ但書（不得以通謀虛偽之無效對抗善意第三人）的保護。"],"tr":""},{"id":"h:101-35","p":"h","src":"101年第35題","sec":"D6","stem":"甲向乙借款 500 萬元，並將所有之 A 地設定普通抵押權給乙，下列敘述何者最正確？","opts":["乙就 A 地賣得之價金有優先受償之權","乙得僅將抵押權讓與給第三人丙，而保留對甲之借款返還債權","抵押權不因登記之先後定其次序，具有平等性","甲若將 A 地讓與給丁，則乙之抵押權消滅"],"ok":[0],"ex":["§860，抵押權人就抵押物賣得之價金，有優先於其他債權人受清償之權，正確。","§870，抵押權隨同債權移轉，不得與債權分離而單獨讓與（從屬性），乙不得僅讓與抵押權而保留債權，選項錯誤。","§865，同一不動產上有數個抵押權時，依其登記先後定其次序（先登記者次序在先），並非「平等」，選項錯誤。","§867，抵押人（甲）得讓與不動產（A地）所有權（讓與所有權不消滅抵押權），抵押權隨物存在（對物之權，而非對人之權），讓與後抵押權仍存在，選項說「抵押權隨即消滅」錯誤。"],"tr":""},{"id":"h:101-36","p":"h","src":"101年第36題","sec":"B4","stem":"甲將自己之汽車停在乙的停車格內多日，乙自己沒有汽車，停車格也未出租給他人使用，甲在乙的要求下將汽車開走，下列敘述何者最正確？","opts":["乙仍得對甲主張無因管理，請求必要費用之返還","乙仍得對甲主張債務不履行之損害賠償責任","乙仍得對甲主張不當得利，請求甲返還利益","乙仍得對甲主張無權代理之損害賠償責任"],"ok":[2],"ex":["無因管理須有為他人管理之意思（§172），乙並未管理甲之事務，反而是甲占用乙之停車格。","甲乙之間並無契約關係，不生債務不履行責任。","§179：無法律上原因而受利益致他人受損害者，應返還。甲無權占用停車格取得使用利益，乙即使未使用，仍得依不當得利請求返還使用利益。","甲未以乙名義為法律行為，與無權代理無關。"],"tr":""},{"id":"h:101-37","p":"h","src":"101年第37題","sec":"C4","stem":"甲向乙借一套百科全書，下列敘述何者最正確？","opts":["在乙承諾將百科全書借給甲後，甲與乙之借貸契約即成立","甲與乙之借貸契約為諾成契約","甲與乙之借貸契約為消費借貸契約","甲與乙之借貸契約為要物契約，以物之交付作為契約之成立要件"],"ok":[3],"ex":["使用借貸（§464）為「以物交付他方」而約定無償使用後返還之契約，屬要物契約，須物已交付才成立；乙僅承諾借出、尚未交付，契約尚未成立。","使用借貸不是合意即成立的諾成契約：§464 以「以物交付他方」為契約要素，未交付百科全書前，雙方縱有合意，借貸契約仍未成立，故「諾成契約」之說錯誤。","消費借貸（§474）是移轉金錢或其他代替物「所有權」，約定以種類、品質、數量相同之物返還；本題借的是特定一套百科全書，使用後須返還原物，屬使用借貸（§464），不是消費借貸。","使用借貸（§464）為要物契約，須以「物之交付」作為成立要件，正確。（消費借貸§474 亦為要物契約，但本題標的是返還原物，屬使用借貸。）"],"tr":""},{"id":"h:101-38","p":"h","src":"101年第38題","sec":"C1","stem":"甲與乙締結 A 畫的買賣契約，約定由出賣人甲在兩天內將 A 畫送至乙處；甲將 A 畫交由店員丙送至乙處，因丙之過失，A 畫滅失。下列敘述何者最正確？","opts":["甲免給付義務","乙得向丙主張侵害所有權之損害賠償責任","甲應對乙負擔給付不能之損害賠償責任","丙應對乙負擔給付不能之損害賠償責任"],"ok":[2],"ex":["§224：債務人之履行輔助人之故意過失，債務人與自己之故意過失負同一責任，甲不得免責。","A 畫尚未交付，所有權仍屬甲（§761 I），乙非所有權人，無所有權受侵害可言。","丙為甲之履行輔助人，依§224 甲須負責，甲因可歸責事由致給付不能，依§226 I 對乙負損害賠償責任。","丙與乙無債之關係，給付不能責任由甲負擔，丙不對乙負給付不能損害賠償責任。"],"tr":""},{"id":"h:101-39","p":"h","src":"101年第39題","sec":"D1","stem":"甲在自己之院子栽種梨樹一棵，結滿果實，一陣大風吹過，將部分果實吹落到鄰居之 A 庭院中；乙為 A庭院之承租人，丙為 A 庭院之所有權人。問：誰取得吹落到 A 庭院果實之所有權？","opts":["甲","乙","丙","乙與丙共同取得"],"ok":[1],"ex":["果實自落於鄰地者，視為屬於鄰地所有人（§798），甲非所有人。","考選部公告本題答案為B。§798文義是落果「視為屬於鄰地所有人」；官方答案採擴張解釋：本條在避免果樹所有人進入鄰地撿拾而生糾紛，鄰地由承租人乙占有、使用收益時，落果歸實際使用鄰地的乙。","依§798文義，落果視為屬於鄰地「所有人」，即丙；但本題官方答案採擴張解釋，歸承租人乙，所以C不是本題答案。考場判斷：題目沒有承租人等使用人時選鄰地所有人；像本題特別點出承租人時，依官方立場選承租人。（另：鄰地為公用地者不適用§798。）","法律僅規定歸鄰地所有人，並未規定由承租人與所有人共同取得。"],"tr":""},{"id":"h:101-40","p":"h","src":"101年第40題","sec":"D5","stem":"甲有 A 地一筆，設定地上權於乙，下列敘述何者最正確？","opts":["若乙積欠地租達一年之總額時，甲得不經催告終止地上權","乙原則上不得將地上權讓與第三人丙，但地上權之期限逾二十年者，不在此限","因不可抗力而妨礙 A 地之使用時，乙不得請求甲減少地租","地上權因建築物或其他工作物之滅失而消滅"],"ok":[2],"ex":["地租積欠達二年總額，須定相當期限催告，逾期未付才得終止（§836 I），非一年且須催告。","地上權人原則上得讓與其權利（§838 I），契約另有約定或習慣者除外，與期限是否逾二十年無關。","地上權人不得因不可抗力妨礙土地使用，而請求減免地租（§837）。","地上權不因建築物或其他工作物滅失而消滅（§841）。"],"tr":""},{"id":"h:100-1","p":"h","src":"100年第1題","sec":"C4","stem":"下列關於贈與契約之敘述何者正確？","opts":["贈與契約之贈與人對其贈與之物，有瑕疵時，原則上贈與人應負物之瑕疵擔保責任","贈與契約為無償契約，所以贈與人均可撤銷其贈與","定期給付之贈與，不因贈與人死亡而失其效力","贈與人僅就其故意或重大過失，對於受贈人負給付不能之責任"],"ok":[3],"ex":["贈與人原則上不負物之瑕疵擔保責任（§411 本文）；僅贈與人故意不告知瑕疵或保證無瑕疵時，才對受贈人因瑕疵所生損害負賠償義務（§411 但書）。","贈與人並非『均可』撤銷：§408 Ⅰ 僅限於贈與物之權利『未移轉前』得撤銷，已移轉者不得任意撤銷；Ⅱ 經公證之贈與或為履行道德上義務而為贈與者，亦不得任意撤銷。（§416 是受贈人忘恩時贈與人的法定撤銷權，另為一事。）","定期給付之贈與，依§415，因贈與人或受贈人之死亡而失其效力（但贈與人有反對意思表示者除外）；本選項說『不因贈與人死亡而失效』與條文相反。","依§410，贈與人僅就其故意或重大過失，對於受贈人負給付不能之責任（無償契約，責任從輕），正確。"],"tr":""},{"id":"h:100-2","p":"h","src":"100年第2題","sec":"C2","stem":"關於租賃契約，下列何者錯誤？","opts":["出租人不以所有權人為限","未立字據之租約無效","租賃契約之承租人為租賃物之直接占有人，出租人為間接占有人","租賃契約為有償契約"],"ok":[1],"ex":["出租人不以所有人為限，有占有使用權即可出租（如二房東），正確。","租賃契約為「不要式契約」，不以書面為成立要件；口頭租約有效，只是不動產租賃逾一年者應以書面訂立，未以書面者「視為不定期限」（§422），並非無效，「未立字據→無效」之描述錯誤。","承租人直接使用租賃物，為直接占有人；出租人透過承租人間接占有，為間接占有人，正確。","租賃為有償雙務契約（租金對待給付），正確。"],"tr":""},{"id":"h:100-3","p":"h","src":"100年第3題","sec":"C3","stem":"下列何種契約之屬性為無償契約？","opts":["使用借貸","僱傭契約","承攬契約","居間契約"],"ok":[0],"ex":["使用借貸（§464）：借用人「無償」使用後返還，為無償契約，正確。","僱傭契約以給付報酬為要件（§482），為有償雙務契約。","承攬契約定作人須給付報酬（§490），為有償契約。","居間人促成契約後得請求報酬（§565），為有償契約。"],"tr":""},{"id":"h:100-4","p":"h","src":"100年第4題","sec":"C2","stem":"下列何者，非民法所規定關於出租人之義務？","opts":["租賃物之交付義務","對租賃物之修繕義務","租賃物為動物時，其飼料費之支出","租賃物為房屋時，該房屋所應繳納之稅金"],"ok":[2],"ex":["出租人應以合於約定使用收益之租賃物交付承租人，並於租賃關係存續中保持其合於約定使用、收益之狀態（§423），屬出租人義務。","租賃物之修繕，除契約另有訂定或習慣外，由出租人負擔（§429 Ⅰ），屬出租人義務。","§428：租賃物為動物者，其飼養費由『承租人』負擔，不是出租人義務，故『飼料費由出租人支出』不屬民法所規定之出租人義務，為應選答案。","§427：就租賃物應納之一切稅捐（如房屋稅），由出租人負擔，屬民法所規定之出租人義務。"],"tr":""},{"id":"h:100-5","p":"h","src":"100年第5題","sec":"C4","stem":"甲向乙借了 50 萬，約定利息為週年利率百分之 30 計算，下列敘述何者正確？","opts":["約定之利率過高，該消費借貸無效","約定之利率過高，超過法定週年利率 20%部分之利息無效","約定之利率過高，超過法定週年利率 20%部分之利息，乙無請求權","依契約自由原則，該利率之約定有效，乙得向甲請求利息之支付"],"ok":[2],"ex":["利率過高不影響消費借貸（§474）效力，不會導致借貸無效。","考試當年§205 效果為「債權人對超過部分無請求權」，非「利息無效」。","考試當年§205 約定利率超過週年20%者，債權人對超過部分之利息無請求權。","契約自由受§205 限制，超過上限部分無請求權，並非全部有效。"],"tr":""},{"id":"h:100-6","p":"h","src":"100年第6題","sec":"C1","stem":"甲向乙買一台液晶電視，約定一手交錢一手交貨，於乙未交付液晶電視前，當乙向甲請求價金之支付時，甲得主張：","opts":["撤銷權","解除權","不安抗辯權","同時履行抗辯權"],"ok":[3],"ex":["撤銷權須有意思表示瑕疵等事由，本題無。","解除權須有法定或約定解除事由，本題無。","不安抗辯權（§265）適用於有先為給付義務者，本題為同時交換。","§264Ⅰ 因契約互負債務者，於他方未為對待給付前得拒絕自己之給付。"],"tr":""},{"id":"h:100-7","p":"h","src":"100年第7題","sec":"B1","stem":"甲向大大車行買一台中古 A 車給其子乙，並約定其子乙得直接向該車行請求交付 A 車，則甲與大大車行間之契約屬於：","opts":["附負擔之法律行為","第三人利益契約","債權讓與行為","第三人保證契約"],"ok":[1],"ex":["附負擔是在法律行為（如贈與）中附加受益人須履行某義務，本題並無對乙的附加義務要求。","第三人利益契約（§269）：契約約定向第三人（乙）為給付者，第三人得直接請求債務人履行，本題完全符合，甲（要約人）、車行（承諾人/債務人）、乙（受益第三人），正確。","債權讓與是甲將既有債權移轉給乙，本題甲是新設第三人受益條款，並非讓與既有債權。","保證是保證人擔保他人債務，此處乙並非在保證甲的債務，選項性質不符。"],"tr":""},{"id":"h:100-8","p":"h","src":"100年第8題","sec":"A4","stem":"甲向乙承諾當民國 100 年 12 月 31 日那天，要將天上的某一顆星星送給乙，乙並允諾之。則甲乙間之約定效力如何？","opts":["因自始客觀不能，故約定無效","因雙方意思表示合致，故約定有效","因嗣後客觀不能，故約定有效","因嗣後主觀不能，故約定有效"],"ok":[0],"ex":["星星無法交付，屬契約成立時「自始」即客觀不能（任何人皆不能實現）。依§246，以不能之給付為契約標的者，契約無效（例外：不能情形可除去且當事人預期除去後給付者仍有效）；知情一方並須依§247對善意信賴契約有效之他方負賠償責任。","意思表示合致只是契約成立要件之一；標的自始客觀不能，仍依§246使契約無效，不因合意而有效。","「嗣後不能」是契約成立後才發生的給付不能，契約本身有效，僅依§225（不可歸責於債務人，免給付義務）或§226（可歸責，負賠償責任）處理；本題自始即不能，非嗣後不能。","「主觀不能」是債務人個人不能給付而他人可以給付；星星任何人都無法給付，屬客觀不能。主觀不能不適用§246使契約無效，債務人不履行時另依§226等債務不履行規定處理。"],"tr":""},{"id":"h:100-9","p":"h","src":"100年第9題","sec":"C1","stem":"甲出售土地給乙，交付土地後乙發現實際坪數比契約書所載坪數少 5%。下列敘述，何者錯誤？","opts":["若無顯失公平之情形，乙可以請求減少價金或解除契約","瑕疵擔保責任自土地交付時起經過三年而消滅","此瑕疵若乙於契約成立時知悉而甲不知，甲不負擔保之責","乙若不通知甲坪數短少，視為承認其所受領之物"],"ok":[1],"ex":["§359：物有瑕疵得解除或減少價金，但解除顯失公平者僅得請求減少價金。","§365 I：買受人之解除權或減價請求權，於依§356 通知後六個月間不行使，或自物之交付時起經過五年而消滅（不分動產、不動產），並非三年。","§355 I：買受人於契約成立時知其物有瑕疵者，出賣人不負擔保責任。","§356：買受人應從速檢查並通知出賣人，怠於通知者視為承認所受領之物。"],"tr":""},{"id":"h:100-10","p":"h","src":"100年第10題","sec":"C3","stem":"甲為定作人，與乙訂立承攬契約，由乙為甲建一房屋。關於此案例，下列敘述何者正確？","opts":["乙得就承攬之報酬額，對於將來完成之甲之房屋，請求預為抵押權之登記","工作未完成前，定作人甲不得隨時終止契約","定作人甲所供給之材料，因不可抗力而毀損者，承攬人須負其責","如乙所蓋房屋有瑕疵，甲於房屋交付後二年始發見者，不得請求乙修補"],"ok":[0],"ex":["§513：承攬之工作為建築物等，承攬人得就報酬額，對於將來完成之定作人不動產，請求預為抵押權之登記（開始工作前亦得為之）。","§511：工作未完成前，定作人得隨時終止契約，但應賠償承攬人因契約終止而生之損害。","§508 II：定作人所供給之材料，因不可抗力而毀損滅失者，承攬人不負其責。","建築物瑕疵發見期間延長為五年（§499），交付後二年發見仍得依§493 請求修補。"],"tr":""},{"id":"h:100-11","p":"h","src":"100年第11題","sec":"B1","stem":"下列敘述，何者正確？","opts":["契約之要約人，因要約而受拘束，不可預先聲明不受拘束","貨物標定賣價陳列者，視為要約之引誘","對話為要約者，非立時承諾，即失其拘束力，因此不得定承諾期限","將要約變更而承諾者，視為拒絕原要約而為新要約"],"ok":[3],"ex":["§154Ⅰ但書：要約當時預先聲明不受拘束者，不受要約拘束，故要約人「可以」預先聲明不受拘束；選項說「不可」，錯誤。","依§154Ⅱ，貨物標定賣價陳列者「視為要約」（非要約引誘），此為考試常見混淆點。","§156：對話為要約者，非立時承諾，即失其拘束力；這是未另定承諾期限時的規則，並未禁止當事人另定承諾期限，選項說「不得定承諾期限」，錯誤。","§160Ⅱ：將要約擴張、限制或為其他變更而承諾者，視為拒絕原要約而為新要約，正確，此為「非正式承諾→反要約」之考點。"],"tr":""},{"id":"h:100-12","p":"h","src":"100年第12題","sec":"C2","stem":"乙承租甲所有之土地種植果樹，約定租期二年，未訂立字據。關於此案例，下列敘述何者正確？","opts":["此為定期租賃契約","乙於契約成立後，得請求甲為地上權之登記","若甲於土地交給乙占有後，將土地所有權移轉給丙，乙仍可主張租賃契約對丙成立","就租賃物應納之一切稅捐，由出租人甲負擔"],"ok":[3],"ex":["§422：不動產租賃期限逾1年而未以字據訂立者視為不定期租賃，本題兩年未立字據，並非定期租賃。","§422-1 地上權登記請求限於租用基地建築房屋，本題為種植果樹，不適用。","本題視為不定期租賃，依§425 II 未公證之不定期租賃不適用買賣不破租賃，乙不得向受讓人丙主張。","§427：就租賃物應納之一切稅捐，由出租人負擔。"],"tr":""},{"id":"h:100-13","p":"h","src":"100年第13題","sec":"B4","stem":"下列關於不當得利之敘述，何者正確？","opts":["無法律上之原因而受利益，致他人受損害者，應返還其利益","因清償債務而為給付，於給付時明知無給付之義務者，得請求返還","不當得利之受領人，只須返還其所受之利益，如本於該利益更有所取得者，無須返還","不當得利之受領人，不知無法律上之原因，縱其所受之利益已不存在者，仍應負返還之責任"],"ok":[0],"ex":["§179 無法律上之原因而受利益致他人受損害者，應返還其利益。","§180③ 因清償債務而為給付，於給付時明知無給付之義務者，不得請求返還。","§181 受領人除返還所受利益外，本於該利益更有所取得者並應返還。","§182Ⅰ 受領人不知無法律上原因，所受利益已不存在者，免負返還責任。"],"tr":""},{"id":"h:100-14","p":"h","src":"100年第14題","sec":"A4","stem":"下列何者為附解除條件之法律行為？","opts":["甲如能考 100 分，乙就給甲 100 元","甲向乙借 1 萬元，約定乙每月支付利息 100 元","當甲大學畢業時，乙的房屋就不再出租給甲","甲乙間約定於民國 105 年時，二人即結婚"],"ok":[2],"ex":["「考100分」是使法律行為「開始生效」的條件，屬停止條件（§99Ⅰ）。","此為單純的借貸利息約定，並非附條件行為，屬確定期限或無條件之給付約定。","「大學畢業」這個不確定事實發生時，使已生效的租賃契約「失其效力」，屬解除條件（§99Ⅱ）。","「民國105年」是確定會到來的期日，屬「期限」（始期）而非「條件」（條件是不確定是否發生之事實），此為期限與條件的重要區辨。"],"tr":""},{"id":"h:100-15","p":"h","src":"100年第15題","sec":"A1","stem":"關於死亡宣告，下列敘述何者錯誤？","opts":["得聲請死亡宣告者，僅限於失蹤人之利害關係人","死亡宣告係私法上的制度，不生公法上的效果","死亡宣告在於結束失蹤人原住居所為中心之法律關係，而不在剝奪失蹤人之權利能力","死亡宣告為推定死亡，故允許提出反證而撤銷死亡宣告"],"ok":[0],"ex":["本題問「錯誤」者。§8：失蹤滿七年後，法院得因「利害關係人或檢察官」聲請為死亡宣告，並非僅限利害關係人，故本選項錯誤，為本題答案（常考陷阱：檢察官亦得聲請）。","此敘述正確，故非答案。死亡宣告僅發生私法上（如繼承開始、婚姻關係消滅）之效果，不影響公法上權利義務。","此敘述正確，故非答案。死亡宣告制度目的在了結以失蹤人住居所為中心之法律關係，並非使其喪失權利能力。","此敘述正確，故非答案。死亡宣告採「推定」死亡（§9：以判決內確定死亡之時推定其死亡，但有反證者不在此限），得提出反證，經法院撤銷死亡宣告。"],"tr":""},{"id":"h:100-16","p":"h","src":"100年第16題","sec":"A2","stem":"關於財團法人之敘述，下列何者正確？","opts":["其權利能力始於訂立捐助章程，終於清算解散","財團為公益法人，其設立須經地方法院許可","董事有數人者，除章程另有規定外，各董事均得代表法人","財團法人並非自然人，無侵權行為能力"],"ok":[2],"ex":["法人權利能力始於「登記完成」（成立），而非訂立捐助章程；清算完結才終止，並非清算「解散」時。","財團法人之設立許可，應向「目的事業主管機關」申請，並非地方法院；地方法院僅辦理「登記」。","依§27Ⅱ，董事就法人一切事務對外代表法人，董事有數人者，除章程另有規定外，各董事均得單獨代表法人，正確。","法人對於董事等有代表權人因執行職務所加於他人之損害，與行為人連帶負賠償責任（§28），法人具有侵權行為能力（法人實在說）。"],"tr":""},{"id":"h:100-17","p":"h","src":"100年第17題","sec":"A2","stem":"關於法人依其性質，不得享有下列何種權利？","opts":["姓名權","自由權","專利權","名譽權"],"ok":[1],"ex":["姓名權（法人為名稱權）性質上法人得享有。","自由權（如人身自由）以自然人之肉體存在為前提，性質上專屬自然人，法人不得享有，此即§26但書「專屬於自然人之權利義務」之典型例。","專利權為財產權之一種，法人得為專利權人。","名譽權法人得享有（例如公司商譽受侵害得請求救濟）。"],"tr":""},{"id":"h:100-18","p":"h","src":"100年第18題","sec":"B4","stem":"甲到乙所開設之賭場賭博，賭輸了 10 萬元，下列敘述何者正確？","opts":["賭博為甲乙間債務發生之原因關係，所以甲應支付乙 10 萬","如甲已經付款給乙，則甲得主張賭博行為違反公序良俗無效，依不當得利向乙請求返還","如甲已經付款給乙，雖甲得主張賭博行為違反公序良俗無效，但甲之給付為出於不法原因之給付，所以不得向乙請求返還","如甲已經付款給乙，甲得主張侵權行為，向乙請求損害賠償"],"ok":[2],"ex":["賭博行為違反公序良俗而無效（§72），賭債無請求權。","雖賭博無效，給付人若為不法原因給付，不得依不當得利請求返還（§180④）。","§180④ 因不法原因而為給付者不得請求返還，賭債已付不能請求返還。","甲自願賭博並給付，不構成乙之侵權行為；亦不應迂迴規避§180④。"],"tr":""},{"id":"h:100-19","p":"h","src":"100年第19題","sec":"A1","stem":"甲僱傭 17 歲未婚之乙為店員，並授與代理權以甲之名義販售物品，若甲之法定代理人均不同意。則：","opts":["僱傭契約無效，代理權授與有效","僱傭契約無效，代理權授與亦無效","僱傭契約有效，代理權授與無效","僱傭契約有效，代理權授與亦有效"],"ok":[1],"ex":["依題幹字面，表示不同意的是「甲」之法定代理人，即甲亦為限制行為能力人：甲所訂僱傭契約未得允許，經拒絕承認確定無效（§79）；甲之授權行為屬有相對人之單獨行為，未得允許依§78 無效，故「代理權授與有效」不成立。","考選部更正公告本題答B給分：依題幹字面，甲之法定代理人均不同意，僱傭契約確定無效（§79），甲之授權行為依§78 亦無效。（若題意實指乙之法定代理人不同意，則僱傭無效、授權有效（§104 代理人不須有行為能力），即A之說法，本題因此有爭議。）","僱傭契約因法定代理人拒絕承認而確定無效，並非有效。","僱傭契約欠缺法定代理人允許，不能有效（§77、§79），故「契約有效」不成立。"],"tr":""},{"id":"h:100-20","p":"h","src":"100年第20題","sec":"A1","stem":"甲男於民國 90 年 3 月 1 日離開住所，從此失蹤，其妻乙依法聲請死亡宣告，經法院判決宣告死亡。若甲實際上並未死亡，請問下列敘述，何者正確？","opts":["推定甲於民國 90 年 3 月 1 日死亡","受死亡宣告後，甲所為之法律行為均無效","若甲安然生還，該死亡宣告即自動失去效力","乙繼承甲之財產，善意處分之部分不受甲生還影響"],"ok":[3],"ex":["§9Ⅱ：死亡之時「應為前條各項所定期間最後日終止之時」。甲90年3月1日失蹤，一般失蹤須滿7年（§8Ⅰ），推定死亡時點是失蹤滿7年之期間最後日終止時，不是離家當日。","死亡宣告僅發生私法上推定死亡之效果（§9Ⅰ，得以反證推翻），甲本人如仍生存，其在外地所為之法律行為仍屬有效，並非當然無效。","死亡宣告須經法院「撤銷」死亡宣告之判決，並非甲生還即自動失效，仍須踐行法定程序。","為保護交易安全，繼承人（乙）於死亡宣告經撤銷前，善意信賴宣告而處分遺產之行為，不因甲事後生還而受影響（家事事件法§163：撤銷死亡宣告之裁定確定前之善意行為不受影響；此條不在條文庫，無法逐字核對），正確。"],"tr":""},{"id":"h:100-21","p":"h","src":"100年第21題","sec":"A3","stem":"下列何者，屬於民法上之物？","opts":["活人胸腔中跳動之心臟","博物館中展示之木乃伊","天上飄浮的雲層","植入身體的人造關節"],"ok":[1],"ex":["活人身體之一部分為人格之一部，與身體不可分離時不是民法上的物（人格權客體）。","已死亡之人體（木乃伊）已非人格主體，通說認為屬物，得為所有權客體。","雲層不能為人所支配、無法特定與獨立，不具物之性質。","人造關節植入體內即與身體結合成為身體之一部，通說不再視為獨立之物。"],"tr":""},{"id":"h:100-22","p":"h","src":"100年第22題","sec":"D2","stem":"下列何者，非基於所有權而發生之請求權？","opts":["所有物返還請求權","所有權之妨害除去請求權","所有權之妨害預防請求權","占有物之返還請求權"],"ok":[3],"ex":["所有物返還請求權（§767Ⅰ 前段：所有人對無權占有或侵奪其所有物者，得請求返還），基於所有權而發生，屬物上請求權。","妨害除去請求權（§767Ⅰ 中段：對妨害其所有權者，得請求除去），基於所有權而發生。","妨害預防請求權（§767Ⅰ 後段：有妨害其所有權之虞者，得請求防止），基於所有權而發生。","占有物返還請求權（§962：占有人占有被侵奪者，得請求返還其占有物）是基於「占有」而生，不是基於所有權；占有人不必是所有人也能行使，故為應選答案。★物上請求權（§767）基於所有權；占有保護請求權（§962）基於占有，兩者分清。（§960 則是占有人的自力救濟。）"],"tr":""},{"id":"h:100-23","p":"h","src":"100年第23題","sec":"D6","stem":"關於普通抵押權之敘述，下列何者錯誤？","opts":["抵押權之設定須以書面為之，並辦理登記","抵押人設定抵押權時，對於抵押物須有所有權及處分權","以抵押權所擔保之債權，經讓與其一部者，抵押權仍不受影響","於抵押權所擔保之債權全部被清償時，抵押權仍不消滅"],"ok":[3],"ex":["依§758Ⅰ，不動產物權依法律行為設定，非經登記不生效力；依§758Ⅱ 並應以書面為之，抵押權設定亦同，敘述正確。","設定抵押權是處分行為，抵押人須對抵押物有所有權及處分權，敘述正確。","依§869Ⅰ，以抵押權擔保之債權如經分割或讓與其一部者，其抵押權不因此而受影響，敘述正確。","抵押權從屬於所擔保的債權；債之關係消滅時，擔保及其他從屬權利隨同消滅（§307；本庫未收錄該條，只列條號；抵押權從屬性亦見§870），所以擔保債權全部清償後抵押權即消滅；選項說「仍不消滅」錯誤，故為應選答案。"],"tr":""},{"id":"h:100-24","p":"h","src":"100年第24題","sec":"D5","stem":"下列關於地上權之敘述，何者正確？","opts":["稱普通地上權者，謂以在他人土地之上下有建築物或種植竹木為目的而使用其土地之權","地上權不因建築物或其他工作物之滅失而消滅","地上權人均得隨時拋棄其權利","土地所有權讓與時，已預付之地租，均不得對抗第三人"],"ok":[1],"ex":["§832：普通地上權為在他人土地上下有建築物或其他工作物為目的而使用其土地之權；種植竹木屬農育權（§850-1）。","§841：地上權不因建築物或其他工作物之滅失而消滅。","只有無地租約定者才得隨時拋棄（§834）；有地租約定者，定有期限須支付未到期之三年分地租（§835 I），未定期限須一年前通知或支付未到期之一年分地租（§835 II），所以並非「均」得隨時拋棄。","§836-1：土地所有權讓與時，已預付之地租，經登記者可對抗受讓人；並非均不得對抗。"],"tr":""},{"id":"h:100-25","p":"h","src":"100年第25題","sec":"D4","stem":"甲有 A、B 二地，因出賣 A 地給乙，致 B 地與公路無適宜之連絡，不能為通常之使用。下列敘述何者正確？","opts":["甲可以任擇 A 地或其他相鄰之地而通行之","甲通行鄰地已造成鄰地負擔，不得再主張開設道路","甲通行鄰地時，為求便利，可任意選擇通行之處所","若甲不主張開設道路而通行 A 地，無須支付乙償金"],"ok":[3],"ex":["§789 I：因土地讓與形成袋地者，僅得通行受讓人之土地，不得任選他人土地。","§788 I：有通行權人於必要時得開設道路，但應對鄰地所受損害支付償金；並非不得主張開設道路。","§787 II：通行處所及方法應擇對鄰地損害最少者，不得任意選擇。","§789 II：因土地讓與而通行者，無須支付償金。"],"tr":""},{"id":"h:100-26","p":"h","src":"100年第26題","sec":"D2","stem":"甲死亡，遺留房屋一棟，有乙、丙二位繼承人。下列敘述何者正確？","opts":["未分割前，該屋為乙、丙分別共有","移轉登記前，乙、丙即取得該屋所有權，然而應經登記，始得處分之","若該屋被無權占有，乙、丙須共同向無權占有人起訴請求返還","若乙、丙於繼承前於該屋上有抵押權，該抵押權不因繼承而受影響"],"ok":[1],"ex":["依§1151，繼承人有數人時，在分割遺產前各繼承人對遺產全部為公同共有，不是分別共有，選項錯誤。","依§1148Ⅰ，繼承人自繼承開始時承受被繼承人財產上之權利，且依§759，因繼承於登記前已取得不動產物權者，應經登記始得處分其物權；故乙丙在登記前已取得所有權，但須登記後才能處分，正確。","遺產為公同共有（§1151），依§828Ⅱ 準用§821，各共有人對第三人得就共有物之全部為本於所有權之請求（但回復共有物之請求，僅得為共有人全體之利益為之）；因此乙或丙可單獨起訴請求返還，不須共同起訴，選項錯誤。","若乙丙原為該屋之抵押權人，繼承後該屋所有權歸乙丙，抵押權與所有權同歸一人，依§762 其他物權因混同而消滅（除非其存續於所有人或第三人有法律上利益）；所以不能一概說抵押權「不因繼承而受影響」，選項錯誤。"],"tr":""},{"id":"h:100-27","p":"h","src":"100年第27題","sec":"D3","stem":"下列關於動產之敘述，何者錯誤？","opts":["甲以占有之意思，占有被遺棄之流浪狗，甲取得該狗之所有權","公園管理員在所管理之公園內拾得遺失物者，對遺失人不得請求報酬","甲乙各有一桶白油漆，不慎混合在一起，二人應按其混合時之價值，共有混合後之油漆","加工於他人之動產者，其加工物之所有權，原則上屬於加工人"],"ok":[0,3],"ex":["先占須「以所有之意思」占有無主動產（§802）；題述僅「占有之意思」，要件不符，且是否取得所有權不能僅憑占有意思認定。","拾得人在公眾得出入之場所，若為該場所之管理人或受僱人，依§805-1不得請求報酬；公園管理員屬之。","動產混合不能識別或識別需費過鉅者，準用附合規定（§813、§812 I），各所有人按混合時價值共有合成物。","加工於他人動產，加工物原則上屬材料所有人，僅加工增價顯逾材料價值時才屬加工人（§814）。"],"tr":""},{"id":"h:100-28","p":"h","src":"100年第28題","sec":"D2","stem":"甲將其所有之 A 車借給乙，不久卻將 A 車贈與給乙，則甲對乙得以何種方式交付 A 車？","opts":["現實交付","簡易交付","占有改定","指示交付"],"ok":[1],"ex":["現實交付（§761Ⅰ 前段：動產物權之讓與，非將動產交付不生效力）：須將動產實際移轉占有給受讓人；本題乙已在占有A車，不需再現實交付。","簡易交付（§761Ⅰ 但書）：受讓人已占有動產者，於讓與合意時即生效力；乙原已借用占有A車，甲、乙只要就贈與（讓與）達成合意即完成交付，正確。","占有改定（§761Ⅱ）：讓與人讓與後仍繼續占有動產，雙方訂立契約使受讓人取得間接占有以代交付；本題甲讓與後不再占有，並非此情形。","指示交付（§761Ⅲ）：動產由第三人占有時，讓與人以對第三人的返還請求權讓與受讓人以代交付；本題車在乙手上，無第三人，並非此情形。★交付四種：現實（§761Ⅰ前）、簡易（§761Ⅰ但書，受讓人已占有）、占有改定（§761Ⅱ，讓與人繼續占有）、指示（§761Ⅲ，讓與對第三人之返還請求權）。"],"tr":""},{"id":"h:100-29","p":"h","src":"100年第29題","sec":"D6","stem":"甲將 A 屋設定普通抵押權給乙銀行後，甲又將該 A 屋出租給丙，下列敘述何者為正確？","opts":["甲乙間之抵押權無效","甲丙間之租約無效","甲乙間之抵押權不因此而受影響，但 A 屋之租金由乙收取之","甲乙間之抵押權不因此而受影響，A 屋之租金仍由甲收取之"],"ok":[3],"ex":["抵押權不移轉占有（§860），設定後抵押人仍可使用，抵押權有效。","抵押權設定後，所有人仍得成立租賃關係（§866 I），租約有效。","抵押權效力及於法定孳息（租金）須經扣押，且抵押權人須通知義務人（§864），未扣押前租金歸抵押人收取。","設定抵押後出租，抵押權不受影響（§866 I）；抵押物未經扣押前，租金仍由出租人甲收取（§864反面）。"],"tr":""},{"id":"h:100-30","p":"h","src":"100年第30題","sec":"E3","stem":"關於收養之敘述，下列何者錯誤？","opts":["限於未成年人，方得被收養","養父母死亡後，養子女得聲請法院許可終止收養","夫妻應共同收養子女","養子女從收養者之姓或維持原來之姓"],"ok":[0],"ex":["成年人亦得被收養，民法另設成年收養的特別規定（§1079-2，被收養者為成年人時法院不予認可的事由）；收養並不限於未成年人。","§1080-1：養父母死亡後，養子女得聲請法院許可終止收養；選項敘述與該條相符。","§1074：夫妻收養子女時應共同為之，但夫妻一方收養他方之子女者不在此限。","§1078：養子女從收養者之姓或維持原來之姓。"],"tr":""},{"id":"h:100-31","p":"h","src":"100年第31題","sec":"E1","stem":"關於離婚之敘述，下列何者錯誤？","opts":["兩願離婚，雙方當事人須以書面為之","兩願離婚時，不得請求贍養費及損害賠償","判決離婚時，因判決離婚而受有損害者，得向有過失之他方請求損害賠償","離婚時，採分別財產制者，各自取回其結婚時之財產"],"ok":[3],"ex":["§1050：兩願離婚應以書面為之，有二人以上證人簽名並向戶政機關登記。","法定的損害賠償（§1056）與贍養費（§1057）請求權僅規定於判決離婚，兩願離婚無此法定請求權。","§1056 I：因判決離婚而受有損害者，得向有過失之他方請求賠償。","§1058：夫妻離婚時，除採用分別財產制者外，各自取回其結婚或變更夫妻財產制時之財產（現行條文，已非舊法「固有財產」）；分別財產制本來即各保有其財產，無「取回」問題。"],"tr":""},{"id":"h:100-32","p":"h","src":"100年第32題","sec":"E1","stem":"依民法關於結婚之規定，下列敘述何者錯誤？","opts":["未成年人結婚，應由法定代理人代為意思表示","表兄妹結婚者，無效","有配偶者再與他人結婚時，後婚無效","原則上結婚後夫妻各保其本姓"],"ok":[0],"ex":["結婚須當事人自行為意思表示，不得由法定代理人代為；依出題年舊法，舊§981僅規定未成年人結婚須得法定代理人「同意」，仍由本人表示結婚意思；現行法（112.1.1起）成年與結婚年齡均為18歲、§981已刪除，未成年人根本不能結婚，A敘述依新舊法都錯。","§983：旁系血親六親等內不得結婚（因收養而成立之四親等、六親等旁系血親輩分相同者除外），表兄妹為非收養之四親等旁系血親，其結婚依§988無效。","§988(3)：違反§985重婚禁止者，後婚無效。","§1000：夫妻各保有其本姓，但得書面約定冠姓並登記。"],"tr":""},{"id":"h:100-33","p":"h","src":"100年第33題","sec":"E4","stem":"關於拋棄繼承之敘述，下列何者正確？","opts":["應於繼承開始之日起 2 個月內為之","繼承之拋棄，溯及於繼承開始時發生效力","拋棄繼承者，就其所管理之遺產，於拋棄當時不負任何責任","配偶拋棄繼承權者，其應繼分應歸後順序之繼承人"],"ok":[1],"ex":["拋棄繼承期間為知悉其得繼承時起三個月內，非繼承開始日起2個月（§1174 II）。","§1175：繼承之拋棄，溯及於繼承開始時發生效力。","§1176-1：拋棄繼承者，就其管理之遺產，於其他繼承人或遺產管理人開始管理前，應與處理自己事務為同一注意，繼續管理，並非不負責任。","§1176：配偶拋棄繼承權者，其應繼分歸屬於與其同為繼承之人，不是後順序繼承人。"],"tr":""},{"id":"h:100-34","p":"h","src":"100年第34題","sec":"E1","stem":"甲男乙女欲結婚，請問下列何種情形，甲乙不得結婚？","opts":["甲男曾與乙女之母親結婚，後因不孕而離婚","甲 18 歲，乙 17 歲","甲之祖母與乙之祖母為二親等之親姊妹","甲之父母為丙、丁，乙之父母為戊、己，丙、己各自與前配偶離婚後，丙、己結婚"],"ok":[0,2],"ex":["§983 II：直系姻親結婚之限制，於姻親關係消滅後亦適用；甲曾為乙之母的配偶（乙之繼父），離婚後仍不得結婚。","100年當時男滿18歲、女滿16歲即達結婚年齡（須法定代理人同意），故依出題年舊法可結婚；現行法（112.1.1起）§980男女未滿18歲不得結婚，乙17歲依現行法即不得結婚（違反者依§989得撤銷）。","甲祖母與乙祖母為親姊妹，甲、乙為六親等旁系血親，非因收養，依§983不得結婚。","丙、己再婚後，甲乙為無血緣之繼兄妹，彼此非§969所稱血親或姻親，無§983之結婚限制。"],"tr":""},{"id":"h:100-35","p":"h","src":"100年第35題","sec":"E2","stem":"關於法定夫妻財產制，下列敘述，何者正確？","opts":["夫妻之一方以自己財產清償他方之債務時，於婚姻關係存續中，不得請求償還","因繼承而得之財產，不計入夫或妻現存之婚後財產","夫或妻於婚姻關係存續中，就其婚後財產所為履行道德上義務之贈與，他方得聲請法院撤銷之","剩餘財產分配請求權專屬夫或妻享有，不得由繼承人主張之"],"ok":[1],"ex":["§1023 II：夫妻之一方以自己財產清償他方之債務時，雖於婚姻關係存續中，亦得請求償還。","§1030-1 I但書：因繼承或其他無償取得之財產，不列入剩餘財產差額計算。","§1020-1：夫妻無償行為有害剩餘財產分配請求權者他方得聲請撤銷，但為履行道德上義務所為之相當贈與不在此限，故不得撤銷。","§1030-1：請求權原則上不得讓與或繼承，但已依契約承諾或已起訴者除外，繼承人於此情形可主張。"],"tr":""},{"id":"h:100-36","p":"h","src":"100年第36題","sec":"E3","stem":"下列親屬若未同居一處，何者不互負扶養義務？","opts":["父母子女間","夫妻之間","兄弟姊妹相互間","直系姻親相互間"],"ok":[3],"ex":["§1114(1)：直系血親相互間互負扶養義務，不以同居為要件。","§1116-1：夫妻互負扶養義務，不以同居為要件。","§1114(3)：兄弟姊妹相互間互負扶養義務，不以同居為要件。","直系姻親僅「夫妻一方與他方之父母同居」時才互負扶養義務（§1114(2)）；未同居者互不負扶養義務。"],"tr":""},{"id":"h:100-37","p":"h","src":"100年第37題","sec":"E4","stem":"下列之人：1直系血親卑親屬 2祖父母 3兄弟姊妹 4父母；其正確之法定遺產繼承順序為何？","opts":["1432","1423","4123","4312"],"ok":[0],"ex":["§1138：第一順序直系血親卑親屬，第二順序父母，第三順序兄弟姊妹，第四順序祖父母，即1→4→3→2。","此排列把祖父母排在兄弟姊妹之前，不符§1138。","此排列把父母排第一，直系血親卑親屬排第二，不符§1138。","此排列完全顛倒，不符§1138。"],"tr":""},{"id":"h:100-38","p":"h","src":"100年第38題","sec":"E4","stem":"甲死亡時遺留存款三百萬元以及債務五百萬元，無配偶，有子乙與孫丙各一人。下列敘述何者正確？","opts":["若乙未依法辦理拋棄繼承，乙必須全部清償所繼承之五百萬元債務","若乙拋棄繼承，丙亦同受拋棄效力所及，無須繼承","乙所繼承之債務，以因繼承所得遺產為限，負連帶責任","乙欲拋棄繼承，應於知悉其得繼承之時起三個月內，以書面向甲之債權人與債務人為之"],"ok":[2],"ex":["繼承人僅以所得遺產為限清償（§1148 II），無須全部清償500萬。","拋棄繼承僅及於拋棄者本人，乙之子丙為第一順序繼承人，因乙拋棄而得繼承，並非當然同受拋棄效力；依§1176 V「第一順序之繼承人，其親等近者均拋棄繼承權時，由次親等之直系血親卑親屬繼承」，乙拋棄後由孫丙遞補成為繼承人；丙須自行於知悉得繼承之日起三個月內決定是否拋棄（§1176 VII）。","§1148 II限定責任；§1153 I繼承人對被繼承人之債務負連帶責任，故乙以所得遺產為限負連帶責任。","拋棄應於知悉其得繼承之時起三個月內以書面向法院為之，並通知因其拋棄而應為繼承之人（§1174 III），並非向債權人與債務人為之（§1174 II）。"],"tr":""},{"id":"h:100-39","p":"h","src":"100年第39題","sec":"E4","stem":"下列關於遺囑之敘述何者正確？","opts":["未滿 18 歲者不得為遺囑","自書遺囑必須親筆自書，不得自行電腦打字列印後，親自簽名為之","18 歲以上之人得為遺囑見證人","口授遺囑，自遺囑人能依其他方式為遺囑之時起，經過二個月而失其效力"],"ok":[1],"ex":["§1186：限制行為能力人無須法定代理人允許即得為遺囑，但未滿16歲者不得為遺囑，門檻是16歲而非18歲。","§1190：自書遺囑應自書遺囑全文、記明年月日並親自簽名；電腦打字列印不符「自書全文」要件。","依出題年舊法：成年為20歲，18歲者為未成年人，依§1198①不得為遺囑見證人，故C錯。【現行法】112.1.1起成年為18歲，18歲者已非未成年人，不再受§1198①限制；只要沒有§1198②～⑤事由（受監護或輔助宣告、繼承人或受遺贈人及其配偶或直系血親、公證人之同居人助理人或受僱人），即得為見證人，故依現行法C原則上變成正確敘述。本題官方答案B依出題年舊法。","§1196：口授遺囑自遺囑人能依其他方式為遺囑時起，經過三個月失其效力，非二個月。"],"tr":""},{"id":"h:100-40","p":"h","src":"100年第40題","sec":"E4","stem":"下列何種繼承人之繼承特留分，為其應繼分三分之一？","opts":["直系血親卑親屬","父母","配偶","祖父母"],"ok":[3],"ex":["§1223(1)：直系血親卑親屬之特留分為其應繼分二分之一。","§1223(2)：父母之特留分為其應繼分二分之一。","§1223(3)：配偶之特留分為其應繼分二分之一。","§1223(5)：祖父母之特留分為其應繼分三分之一（兄弟姊妹亦同）。"],"tr":""},{"id":"h:99-1","p":"h","src":"99年第1題","sec":"A2","stem":"法人社員總會決議之內容違反法令或章程者，其決議之效力：","opts":["有效","得撤銷","無效","效力未定"],"ok":[2],"ex":["依§56Ⅱ，總會決議之「內容」違反法令或章程者，無效，不是有效；內容違法不會因為多數社員通過就變成有效。","「得撤銷」是§56Ⅰ的效果：總會「召集程序」或「決議方法」違反法令章程時，社員得於決議後三個月內請求法院撤銷（出席社員當場未異議者除外）。本題問「決議內容」違法，性質不同。","依民法§56Ⅱ，總會決議之「內容」違反法令或章程者，無效。這是考試最愛混淆的地方：程序違法→得撤銷；內容違法→無效。","效力未定是指須待第三人承認才確定的狀態（如§79限制行為能力人未得允許所訂契約須經法定代理人承認、§170無權代理須經本人承認）；總會決議內容違法，法條直接規定為無效（§56Ⅱ），沒有待承認的問題。"],"tr":""},{"id":"h:99-2","p":"h","src":"99年第2題","sec":"A4","stem":"現年十七歲的高中生甲，假造其父母的同意函，以 3 萬元向乙機車行購買中古機車一部，由於沒有駕照無法辦理過戶。試問：甲與乙間之機車買賣契約之效力如何？","opts":["效力未定","有效","無效","得撤銷"],"ok":[1],"ex":["限制行為能力人未得法定代理人允許所訂契約，一般是效力未定（§79：須經法定代理人承認始生效力）；但甲用詐術使人信其已得允許，適用§83特別規定，契約直接有效，不再是效力未定。","依民法§83，限制行為能力人「用詐術」使人信其為有行為能力人或已得法定代理人之允許者，其法律行為為有效。甲假造同意函屬使用詐術，故買賣契約有效，法律不再保護利用詐術的限制行為能力人。","無效是§78（限制行為能力人未得允許所為「單獨行為」）、§75（無行為能力人意思表示）的效果；本題是契約，且適用§83，不是無效。","§83已明文規定該法律行為「為有效」，是針對詐術的特別規定，直接排除效力未定；得撤銷（§92）是被詐欺、被脅迫之表意人的權利，並非本題§83所設的效果，故不選。"],"tr":""},{"id":"h:99-3","p":"h","src":"99年第3題","sec":"A7","stem":"甲向乙影視事業公司租借 10 片電影 DVD 片，10 天共計租金為 1000 元，則乙對甲之請求權消滅時效期間為何？","opts":["15 年","10 年","5 年","2 年"],"ok":[3],"ex":["§125 一般請求權15年，但租賃動產為營業者之租價有特別短期時效，不適用15年。","民法無10年之一般請求權時效，§125為15年、§126為5年、§127為2年。","§126 之5年適用於租金等定期給付，但以租賃動產為營業者之租價已列入§127，不適用5年。","§127③ 以租賃動產為營業者之租價，請求權2年間不行使而消滅；乙影視公司出租DVD即屬之。"],"tr":""},{"id":"h:99-4","p":"h","src":"99年第4題","sec":"A6","stem":"以下關於代理制度之敘述，何者正確？","opts":["無權代理人所為之法律行為屬無效之法律行為","甲為乙之代理人，乙在學校被其他同學霸凌，甲憤而到學校為乙出氣毆打霸凌之同學，則應由乙負賠償責任","代理人於代理權限內以本人名義所為之法律行為對本人有效","代理人在代理期間，因為無從辨識之故，只能為本人服務，禁止從事自己的法律行為"],"ok":[2],"ex":["無權代理原則上是「效力未定」（§170），須經本人承認才生效，並非當然無效。","甲毆打他人是甲個人的侵權行為（事實行為），與「代理」（法律行為）無關，代理不及於事實行為，應由甲自己負責。","代理制度的核心：代理人於代理權限內，以本人名義所為之意思表示，直接對本人發生效力（§103Ⅰ）。","代理人並非「只能」為本人服務，代理人仍可從事自己的法律行為，僅雙方代理/自己代理受到限制（§106）。"],"tr":""},{"id":"h:99-5","p":"h","src":"99年第5題","sec":"A1","stem":"有一年約 70 歲之老翁甲，因已有初期失智之現象，其子乙乃向法院聲請對其為輔助宣告，並以乙為其輔助人。則下列敘述何者錯誤？","opts":["甲在路上行走時，被超速行駛的機車駕駛丙撞傷，甲如欲與丙和解，應得乙之同意","甲擅自移轉其所有房屋一棟之所有權給女兒丁，其法律效果為效力未定","甲平常喜歡與老友上餐館小酌一番，受輔助宣告之後仍然可以自由為之","甲為無行為能力人"],"ok":[3],"ex":["此敘述正確，故非答案。§15-2Ⅰ第4款：受輔助宣告之人為和解，應經輔助人同意（甲與丙和解屬之）。","此敘述正確，故非答案。§15-2Ⅰ第5款：不動產之處分須經輔助人同意；未經同意，依§15-2Ⅱ準用§78～§83，契約效力未定（§79：須經承認始生效力）。","此敘述正確，故非答案。§15-2Ⅰ但書：「依其年齡及身分、日常生活所必需者」不在須經輔助人同意之列，餐館小酌屬日常生活行為，可自行為之。","本題問「錯誤」者。受輔助宣告之人仍有行為能力，只是就§15-2Ⅰ列舉的重要行為須經輔助人同意；無行為能力人是未滿7歲之未成年人（§13Ⅰ）或受監護宣告之人（§15）。「甲為無行為能力人」錯誤，故為本題答案。"],"tr":""},{"id":"h:99-6","p":"h","src":"99年第6題","sec":"B2","stem":"甲醫師對於急症患者拒絕醫療，違反契約法上的何種義務？","opts":["次給付義務","強制締約義務","附隨義務","從給付義務"],"ok":[1],"ex":["次給付義務是原給付不能、遲延等時之替代或補充義務。","醫師不得無故拒絕急救，醫師法§21 課以救治義務，屬法定強制締約義務，違反即違反強制締約義務。","附隨義務（§148Ⅱ 誠信）是契約成立後之保護、通知等義務。","從給付義務是為使主給付完全實現所附之輔助義務。"],"tr":""},{"id":"h:99-7","p":"h","src":"99年第7題","sec":"A6","stem":"意定代理權之授與，其法律性質為何？","opts":["雙方行為","共同行為","無相對人之單獨行為","有相對人之單獨行為"],"ok":[3],"ex":["代理權授與是本人單方的行為，無須代理人承諾即生效，非雙方行為（契約）。","共同行為指多數當事人朝同一目的所為之意思表示（如社團設立行為），與代理權授與不同。","代理權授與須向代理人或向代理行為之相對人為之，屬「有相對人」之單獨行為，並非無相對人。","通說認為代理權授與係本人單方之意思表示，向代理人或相對人為之即生效力，屬有相對人之單獨行為（§167）。"],"tr":""},{"id":"h:99-8","p":"h","src":"99年第8題","sec":"A3","stem":"下列何者，非屬事實行為？","opts":["無主物的先占","對要約的拒絕","無因管理","埋藏物的發現"],"ok":[1],"ex":["先占（§802：以所有之意思占有無主動產者，取得所有權）重在「占有」此一事實，效果由法律直接賦予，不須表達法律效果的意思表示，屬事實行為。","本題問「非」事實行為者。拒絕要約是向要約人表示不願訂約之意思，其效果（§155：要約經拒絕者，失其拘束力）係依表意人所表示之意思而生，屬以「表示」為核心的行為，不是單憑事實發生而依法生效的事實行為，故為答案。","無因管理（§172：未受委任並無義務而為他人管理事務）是管理事務的事實行為，不以意思表示為要件，效果依法律規定發生，屬事實行為。","埋藏物之發見（§808：發見埋藏物而占有者取得所有權；在他人物中發見者，與該物所有人各取一半）重在發見並占有的事實，屬事實行為。"],"tr":""},{"id":"h:99-9","p":"h","src":"99年第9題","sec":"B1","stem":"下列何種情形，係行使形成權之行為？","opts":["贈與人交付贈與物","共有人出賣應有部分","受僱人依法提出辭呈","買賣雙方合意解除契約"],"ok":[2],"ex":["交付贈與物係履行契約的「事實行為」，不是形成權行使（形成權是單方意思表示使法律關係產生/變更/消滅）。","共有人「出賣」應有部分是與買受人訂立買賣契約，屬雙方的負擔行為（債權行為），不是處分行為；之後移轉應有部分才是處分行為（§819Ⅰ 各共有人得自由處分其應有部分）。無論負擔或處分，都須雙方意思合致，並非單方意思表示即生效果的形成權行使。","受僱人提出辭呈是「單方意思表示使勞動契約消滅」，典型形成權行使，正確。形成權例：撤銷、解除、辭職、終止、抵銷。","合意解除需雙方同意，屬雙方行為（合意契約），非單方形成權。"],"tr":""},{"id":"h:99-10","p":"h","src":"99年第10題","sec":"A1","stem":"14 歲之甲未得父母之允許，對同學為債務免除之意思表示，其效力如何？","opts":["有效","無效","得撤銷","效力未定"],"ok":[1],"ex":["免除債務屬單獨行為，並非純獲法律上利益，未得允許不能當然有效。","依§78，限制行為能力人未得法定代理人之允許，所為之「單獨行為」無效（相對於契約行為是效力未定，單獨行為則直接無效，兩者是常考的對比考點）。","得撤銷用於意思表示瑕疵情形，與本題行為能力欠缺無關。","效力未定是「契約」未得允許時的效果（§79），本題是單獨行為（債務免除），法條明文規定為無效而非效力未定。"],"tr":""},{"id":"h:99-11","p":"h","src":"99年第11題","sec":"C1","stem":"甲欲購買乙所有房屋 1 棟，經數次與乙磋商之後，雙方同意該屋以 500 萬元成交，並詳細約定付款及交屋、移轉所有權方式，為求慎重並由丙丁 2 人擔任見證人，且言明為免日後爭議，應將約定內容寫成契約書。嗣後因乙反悔，結果連契約書都無法完成。則下列敘述何者正確？","opts":["因為無法完成契約書，因此甲乙之契約不成立","甲如果已經給付部分價金，應以不當得利請求返還","甲如能證明與乙已有訂立契約之合意，仍得請求乙履行","甲為了使乙履行契約，應先請求乙完成契約書"],"ok":[2],"ex":["§166 約定須用書面者，未完成前僅推定契約不成立，並非當然不成立。","甲能證明契約已成立，則價金給付有債之原因，不是不當得利。","§166 推定可被推翻，甲如證明雙方已達成合意，仍得請求履行。","買賣為諾成契約（§345），無須先完成契約書才可請求履行。"],"tr":""},{"id":"h:99-12","p":"h","src":"99年第12題","sec":"A6","stem":"甲為房屋仲介公司之員工，經甲之斡旋乙同意將其所有房屋出售於丙，乙丙雙方皆委任甲處理登記及付款事宜並授與代理權，事成之後乙丙應支付甲相當之報酬。以下敘述何者錯誤？","opts":["此時雖屬所謂雙方代理，但因已經本人許諾，故可有效","甲有要事需出國，乃將辦理登記事宜委託同事丁代為處理，因丁之疏失致丙受損害，由於甲並無過失可以無庸負責","由於委任之事項中包含不動產登記事宜，就此部分包含代理權之授與應做成書面契約","甲處理相關事務時，應以善良管理人之注意程度，謹慎為之"],"ok":[1],"ex":["此敘述正確，故非答案。雙方代理原則禁止，但經本人許諾者不在此限（§106：代理人非經本人許諾，不得既為本人又為第三人之代理人而為本人與第三人之法律行為）；乙丙皆授與代理權並許諾，可有效。","本題問「錯誤」者。甲將事務轉託丁，屬複委任：§537規定受任人應自己處理委任事務，須經委任人同意、有習慣或不得已事由才可使第三人代為處理；違反者，依§538Ⅰ就丁之行為與就自己之行為負同一責任；縱依規定轉託，依§538Ⅱ仍須就丁之選任及指示負責。甲不能以「自己無過失」當然免責，故本選項錯誤。","此敘述正確，故非答案。§531：委任處理之法律行為依法應以文字為之者，其處理權及代理權之授與亦應以文字為之；不動產物權變動之行為依§758Ⅱ應以書面為之，故登記事宜之委任及代理權授與須書面。","此敘述正確，故非答案。§535：受任人處理委任事務，原則上與處理自己事務為同一注意，但「受有報酬者」應以善良管理人之注意為之；本題乙丙事成後支付報酬，甲須盡善良管理人之注意。"],"tr":""},{"id":"h:99-13","p":"h","src":"99年第13題","sec":"C4","stem":"甲男與乙女為男女朋友關係，甲同意將其名下之豪宅贈與乙，以下之敘述何者錯誤？","opts":["甲在未移轉該屋之所有權給乙之前，隨時可以向乙表示反悔，撤銷贈與","贈與為單獨行為","甲在未移轉房屋所有權給乙之前，因為電線走火將該屋燒毀時，除非甲有故意重大過失，否則無庸負給付不能之責任","甲移轉該屋之所有權給乙，乙搬入該屋之後，即使發現該屋漏水嚴重，原則上亦無法請求甲修繕"],"ok":[1],"ex":["§408 I：贈與物之權利未移轉前，贈與人得撤銷其贈與；§408 II 例外為經公證之贈與或為履行道德上義務而為贈與，本題未見公證，情境成立。","贈與須一方無償給與、他方允受（§406），為契約（雙方行為），不是單獨行為。","§410：贈與人僅就故意或重大過失對受贈人負給付不能責任，電線走火非故意重大過失者無須負責。","§411：贈與物有瑕疵贈與人原則上不負擔保責任（故意不告知或保證無瑕疵例外），故乙原則上無法請求修繕。"],"tr":""},{"id":"h:99-14","p":"h","src":"99年第14題","sec":"B6","stem":"甲受僱於乙客運公司擔任公車司機，某日在依照路線載客途中，因過失撞傷路人丙。下列敘述何者錯誤？","opts":["丙可以只向甲請求賠償","丙可以只向乙請求賠償","乙賠償之後，原則上可以向甲主張求償","甲乙對丙負不真正連帶債務之關係"],"ok":[3],"ex":["受害人丙得依§184Ⅰ 單獨請求甲賠償。","§188Ⅰ 僱用人乙與受僱人甲連帶負責，丙得單向乙請求（§273）。","§188Ⅲ 僱用人賠償後對受僱人有求償權。","§188Ⅰ 明文規定僱用人與行為人「連帶」負賠償責任，為連帶債務，非不真正連帶。"],"tr":""},{"id":"h:99-15","p":"h","src":"99年第15題","sec":"B2","stem":"甲至乙家具行購買 1 組展示中之沙發，約定於隔日由乙送貨至甲指定之處所。乙之員工丙送貨途中，因精神不濟發生翻車事故，沙發全毀，以下敘述何者錯誤？","opts":["雖然沙發係因丙之過失而毀損，乙仍須負債務不履行之責任","因為尚有另外 1 組圖案類似之沙發，甲可請求乙交付該組沙發替代","乙可以向丙主張沙發毀損之損害賠償","甲必須解除契約之後，才能免除給付價金之債務"],"ok":[1],"ex":["§224 債務人之使用人（丙）之過失視為債務人之過失，乙須負債務不履行責任。","展示中的特定沙發為特定物買賣，標的毀損則給付不能，不得請求交付另一組類似沙發替代。","沙發尚未交付，所有權屬乙，乙得對丙依侵權或僱傭契約請求賠償。","給付不能可歸責於債務人，甲之價金債務不當然消滅，須依§256 解除契約後才免付價金（§259 回復原狀）。"],"tr":""},{"id":"h:99-16","p":"h","src":"99年第16題","sec":"C5","stem":"甲使用乙銀行發行之信用卡消費後，共計有 15 萬元卡債無法返還，乙銀行在未知會甲之情形下，將該筆債權出售給丙。下列敘述何者錯誤？","opts":["因為甲未受到任何通知，故乙丙之讓與行為無效","甲乙之間如果有設定擔保，該擔保亦隨同由丙取得","甲乙之間如果有特約約定該筆債權不得讓與，丙公司如屬善意時，其讓與仍然有效","甲欲清償債務時，經第 3 人告知，才知乙已將債權讓與丙，乃主動向丙清償債務，此屬有效之行為"],"ok":[0],"ex":["債權讓與契約不須債務人同意或通知（§294Ⅰ）；通知只影響對債務人之效力（§297）。","§295Ⅰ 債權讓與時其擔保及其他從屬權利隨同移轉。","§294Ⅱ 不得讓與之特約不得對抗善意第三人，丙善意，讓與有效。","債務人知悉讓與後自行向受讓人清償，是承認讓與，有效。"],"tr":""},{"id":"h:99-17","p":"h","src":"99年第17題","sec":"C2","stem":"以下有關租賃關係之敘述何者正確？","opts":["租賃物如有修繕之必要，基於使用者付費之原則，應由承租人負擔修繕之費用","承租人有使用收益租賃物之權利，所以可以自行將房間分租，當二房東","甲將其房屋出租與乙，言明租期 3 年，有訂立契約書但未公證。至第 2 年時甲將房屋所有權讓與丙，乙得向丙主張該租賃契約仍存在","租賃之房屋因電線走火發生火災，房屋因而受損時，因承租人未盡善良管理人之責，應負損害賠償責任"],"ok":[2],"ex":["§429 I：租賃物修繕除契約另有訂定或習慣外，由出租人負擔。","§443 I：承租人非經出租人承諾，不得將租賃物轉租於他人；但書僅限「房屋」之「一部分」且「無反對之約定」時才可轉租。選項把轉租的依據說成「承租人有使用收益權，所以可以」，並以「當二房東」概括表示可自行轉租，忽略原則須經承諾及但書的兩個條件，故不成立（對照 109-8：附上「除有反對之約定外、一部分」條件的敘述才正確）。","§425 I：租賃物交付後所有權讓與第三人，租賃契約對受讓人繼續存在；本題期限3年，未逾§425 II 之5年限制，雖未公證仍適用。","§434：承租人失火僅就重大過失負賠償責任，單純未盡善良管理人注意不足以負責。"],"tr":""},{"id":"h:99-18","p":"h","src":"99年第18題","sec":"B2","stem":"銀行對於肉眼顯能辨識之票據印文真偽，而未為辨識，其責任係屬何種性質之責任？","opts":["屬重大過失之責任","屬抽象輕過失之責任","屬具體輕過失之責任","無過失責任"],"ok":[0],"ex":["肉眼顯能辨識而未辨識，顯然欠缺普通人之注意，屬重大過失。","抽象輕過失指欠缺「善良管理人之注意」（通說之過失分級；§220 只規定債務人就故意或過失負責、過失輕重依事件特性酌定，並未定義善良管理人注意）。肉眼即可辨識卻未辨識，連普通人的注意都欠缺，程度更重，屬重大過失，不是抽象輕過失。","具體輕過失指欠缺與處理自己事務同一之注意，本題非此類。","無過失責任須法律明文規定，本題為過失責任。"],"tr":""},{"id":"h:99-19","p":"h","src":"99年第19題","sec":"B4","stem":"基於下列何種原因而取得利益，應依關於不當得利之規定，返還其所受利益？","opts":["因確定判決取得利益","因添附取得利益","因消滅時效取得利益","因取得時效取得利益"],"ok":[1],"ex":["確定判決具既判力，取得利益有法律上原因，不成立不當得利。","§816 因添附（§811至§815）喪失權利而受損害者，得依不當得利規定請求償金。","§144Ⅰ 時效完成僅生拒絕給付抗辯權，債務人所受利益有法律上原因。","取得時效完成取得權利，屬原始取得（§768），有法律上原因，非不當得利。"],"tr":""},{"id":"h:99-20","p":"h","src":"99年第20題","sec":"D2","stem":"甲將其所有機車 1 部，寄託於乙處，乙擅自將之以價金新臺幣 3 萬元讓售給知情的丙，並將該車交付給丙。下列有關乙丙間法律關係之敘述，何者正確？","opts":["債權行為有效，物權行為無效","債權行為無效，物權行為有效","債權行為效力未定，物權行為無效","債權行為有效，物權行為效力未定"],"ok":[3],"ex":["前半正確：買賣（債權行為）不以出賣人有處分權為必要，仍有效；後半錯誤：乙無處分權而移轉機車所有權，依§118 I 屬效力未定（經甲承認始生效力），不是「無效」。","債權行為有效；物權行為依§118 I 效力未定，並非有效。","債權行為不因欠缺處分權而效力未定。","債權行為有效；乙為無權處分，物權行為依§118 I 效力未定，經甲承認始生效力，且丙知情不得善意取得（§948）。"],"tr":""},{"id":"h:99-21","p":"h","src":"99年第21題","sec":"D2","stem":"下列有關公同共有之情形，何者不能準用分別共有之規定？","opts":["公同共有物之分割","公同共有人應有部分之自由處分","公同共有物之管理","公同共有物分割後之權利義務關係"],"ok":[1],"ex":["依§830Ⅱ，公同共有物之分割，除法律另有規定外，準用關於共有物分割之規定，可準用，不是答案。","分別共有人各有應有部分，依§819Ⅰ 得自由處分；公同共有人則無各自獨立的應有部分，依§828Ⅲ，公同共有物之處分及其他權利行使，除法律另有規定外，須得公同共有人全體同意。因此「應有部分之自由處分」不能準用，為應選答案。","依§828Ⅱ，§820（共有物之管理）、§821 等規定於公同共有準用，可準用，不是答案。","公同共有物分割後，依§830Ⅱ 準用共有物分割之規定（包括§825：各共有人對他共有人因分割所得之物，按其應有部分負與出賣人同一之擔保責任），可準用，不是答案。"],"tr":""},{"id":"h:99-22","p":"h","src":"99年第22題","sec":"D2","stem":"甲乙丙 3 人因繼承而共有祖傳土地 1 筆，應有部分各為三分之一，以下關於共有之敘述何者正確？","opts":["3 人為維持祖傳土地之完整性，乃訂立禁止永世不得分割之契約，該契約如經登記，即可有效","甲如欲以該筆土地設定抵押權，只要再得到乙丙其中 1 人同意即可","乙欲出賣其應有部分時，應得甲及丙之同意","即使甲反對，只要乙丙同意時，即可針對該筆共有土地訂立分管契約"],"ok":[3],"ex":["§823 II：約定不分割之期限不得逾五年，逾五年者縮短為五年；但共有之不動產訂有管理之約定時，上限為三十年（§823 II 但書）。無論哪一種，「永世不得分割」都會被縮短，不可能永久有效；登記（§826-1 I）只使約定對應有部分受讓人生效，不能讓超過上限的部分有效。","§819 II：共有物之處分、變更及設定負擔，應得共有人全體同意，不是只要再取得一人同意。","§819 I：各共有人得自由讓與其應有部分，不需其他共有人同意。","§820 I：共有物管理（含分管）得由共有人過半數且應有部分合計過半數同意（乙丙合計 2/3），甲反對不影響。"],"tr":""},{"id":"h:99-23","p":"h","src":"99年第23題","sec":"D2","stem":"甲乙丙丁共有土地 1 筆，應有部分各為四分之一，以下關於分管契約之敘述何者錯誤？","opts":["分管契約乃約定特定部分之共有物專歸特定共有人使用之契約，故其成立須得全體共有人同意始可","不動產之分管契約如經登記，可以對抗應有部分之受讓人","分管契約為債權契約","分管契約成立後，因情勢變更難以繼續時，任何共有人均得聲請法院以裁定變更之"],"ok":[0],"ex":["共有物之管理（含使用分管）依§820 I 得以多數決行之，分管契約不以全體共有人同意為必要。","§826-1 I：不動產共有人間關於共有物使用、管理等約定，經登記後，對應有部分受讓人或取得物權之人有效力。","分管契約僅有債權效力，登記後才對特定繼受人生效。","§820 III：管理因情事變更難以繼續時，法院得因任何共有人聲請，以裁定變更之。"],"tr":""},{"id":"h:99-24","p":"h","src":"99年第24題","sec":"D2","stem":"XYZ 3 人共有土地 1 筆，各有應有部分三分之一，三人協議分割該筆土地，於 6 月 2 日達成協議，8 月20 日完成登記。以下敘述何者錯誤？","opts":["在無法令或約定禁止分割之情形下，任何共有人均得隨時請求分割共有物","當事人間於 6 月 2 日即取得各該分得部分之單獨所有權","分割共有物之協議屬債權契約","由於該筆土地面積遼闊，XYZ 3 人得約定僅分割其中一半，其餘一半仍繼續共有"],"ok":[1],"ex":["§823 I：無法令或約定禁止分割時，各共有人得隨時請求分割共有物。","協議分割為債權契約，不動產須依§758 I 登記才生物權變動，故 6 月 2 日尚未取得單獨所有權，8 月 20 日登記後才取得。","分割協議為債權契約。","分割方法由共有人協議決定，得僅就部分土地分割，其餘部分仍維持共有。"],"tr":""},{"id":"h:99-25","p":"h","src":"99年第25題","sec":"D5","stem":"以下關於地上權之敘述何者錯誤？","opts":["地上權可以訂有期限，或為未定期限之地上權","地上權可以為有償，亦可為無償","以在他人土地上下之一定空間範圍內設定之地上權稱為區分地上權","地上權如有支付地租之約定時，地上權人仍可以隨時拋棄其權利"],"ok":[3],"ex":["地上權得定期限或不定期限，兩者皆可（未定期限見§833-1、§835 II；定有期限見§835 I）。","地上權得有償或無償，是否支付地租依約定（§834、§835）。","§841-1：區分地上權為在他人土地上下一定空間範圍內設定之地上權。","§835 II：未定有期限而有支付地租約定者，地上權人拋棄權利時，應於一年前通知土地所有人，或支付未到期之一年分地租（定有期限者依§835 I 須付三年分地租），不得隨時拋棄；無地租者才可隨時拋棄（§834）。"],"tr":""},{"id":"h:99-26","p":"h","src":"99年第26題","sec":"D6","stem":"以下關於占有之敘述何者錯誤？","opts":["寵物店之店員甲照顧顧客乙寄放之寵物狗，帶該隻寵物狗出外散步時，咬傷在公園遊玩之幼童，此時甲應負損害賠償責任","動產善意受讓人必須善意且無重大過失始可","占有人由拍賣或公共市場以善意買得盜贓遺失物時，真正權利人得於 2 年內，償還支出之價金後，請求回復其物","占有人之占有被侵奪者，占有人之返還請求權自侵奪時起，1 年間不行使而消滅"],"ok":[0],"ex":["依§190 I 動物致人損害，由占有人負責；店員受僱於店並受其指示管領寵物，屬占有輔助人（§942），占有人為寵物店，甲不依§190 負責。","§948：善意受讓動產占有者受保護，但受讓人明知或因重大過失不知讓與人無權處分者，不在此限。","選項「拍賣或公共市場」是修正前§950的用語，現行§950改為「公開交易場所」，規則相同。§949、§950：現占有人由公開交易場所或販賣與其物同種之物之商人，以善意買得盜贓遺失物者，原占有人須於二年內償還其支出之價金才得回復其物。","§963：占有被侵奪者，其返還請求權自侵奪時起一年間不行使而消滅。"],"tr":""},{"id":"h:99-27","p":"h","src":"99年第27題","sec":"D2","stem":"以下關於不動產所有權之敘述何者正確？","opts":["甲於 6 月 15 日因其父過世而繼承土地 1 筆，至 10 月 5 日始辦畢繼承登記，則甲於 10 月 5 日取得該筆土地之所有權","甲於自己所有土地上興建房屋，因與鄰地之境界不明，以致圍牆部分逾越疆界坐落於乙所有鄰地上，乙雖於興建中即已查知該事，卻待 2 年後整棟房屋完工後，始請求甲返還土地。此時甲可以拒絕，並請求以相當價額購買越界部分土地","區分所有建築物專有部分之所有權人出賣其所有權時，可以保留基地之權利，另為適當之處置","因土地之讓與或一部分割，而形成袋地時，袋地所有權人僅得通行讓與人或他分割人之所有地，且無須支付償金"],"ok":[3],"ex":["§759、§1147：因繼承於繼承開始時即取得，登記只是處分前提；甲在 6 月 15 日已取得所有權，並非 10 月 5 日。","§796 II：鄰地所有人知越界而未異議，得請求購買越界土地者是鄰地所有人，不是越界建築人甲；甲不得主張。","區分所有建築物專有部分與所屬共有部分及其基地權利不得分離而為移轉或設定負擔（§799 V），不得保留基地權利。","§789：因土地讓與或分割形成袋地時，僅得通行受讓人、讓與人或他分割人土地，且無須支付償金。"],"tr":""},{"id":"h:99-28","p":"h","src":"99年第28題","sec":"D6","stem":"約定於債權已屆清償期而未為清償時，抵押物之所有權移屬於抵押權人者，此一約定之效力為何？","opts":["非經登記，不得對抗第三人","非經登記，不生效力","效力未定","得撤銷"],"ok":[0],"ex":["§873-1 I：流抵約定，非經登記，不得對抗第三人。","流抵約定未登記，在當事人間仍有效，只是不得對抗第三人，並非不生效力。","§873-1 I 已明定流抵約定「非經登記，不得對抗第三人」：在當事人間有效，登記只決定能否對抗第三人。效力未定是像§118 I 無權處分那樣「經有權利人之承認始生效力」的情形，流抵約定不屬之。","§873-1 對流抵約定只規定「非經登記，不得對抗第三人」，沒有賦予任何人撤銷權；要撤銷須另有意思表示瑕疵等撤銷事由，本題沒有。"],"tr":""},{"id":"h:99-29","p":"h","src":"99年第29題","sec":"D6","stem":"債務人甲在其 3000 萬元之抵押土地上，有乙、丙、丁第一、第二及第三順位依次序為 1000 萬元、2000萬元及 800 萬元之普通抵押權，乙為丁抵押權人之利益，而將其第一順位讓與丁。此稱之為：","opts":["次序之絕對拋棄","次序之相對拋棄","次序之讓與","次序之互易"],"ok":[2],"ex":["絕對拋棄無須指定特定人，後次序依序遞升，與「為丁之利益」不同。","相對拋棄是乙與丁同順位，按債權額比例分配，非丁取得第一順位。","次序之讓與（§870-1Ⅰ①「為特定抵押權人之利益，讓與其抵押權之次序」）：先次序抵押權人（乙）為後次序（丁）之利益，讓與優先受償之地位，丁在乙債權額範圍內優先受償。","互易是兩個抵押權人相互對調次序，本題為單向讓與。"],"tr":""},{"id":"h:99-30","p":"h","src":"99年第30題","sec":"D6","stem":"以下關於最高限額抵押權之敘述何者正確？","opts":["最高限額抵押權所擔保之債權，包含因一定關係所生之不特定債權或基於票據所生之權利","我國最高限額抵押權係採本金最高限額","基於抵押權之從屬性，最高限額抵押權所擔保之任何 1 筆債權一旦讓與他人，最高限額抵押權亦隨之移轉","最高限額抵押權僅對原債權有擔保之效力"],"ok":[0],"ex":["§881-1 II：最高限額抵押權所擔保之債權，包含基於一定法律關係所生之不特定債權及基於票據所生之權利。","§881-2：最高限額抵押權人就原債權、利息、遲延利息及違約金等，於最高限額範圍內行使權利，採債權（全部）最高限額，非本金最高限額。","§881-6：原債權確定前，債權讓與他人者，最高限額抵押權不隨同移轉。","§881-2 範圍不限於原債權，尚包括利息、遲延利息、違約金。"],"tr":""},{"id":"h:99-31","p":"h","src":"99年第31題","sec":"E4","stem":"甲之配偶早亡，有乙丙丁 3 名子女，其中乙與 A 結婚，有兩子 X 及 Y，丙丁則尚未結婚，甲有財產 3000萬元。以下敘述何者錯誤？","opts":["甲死亡時，其子丙已先死亡時，則甲之遺產由乙丁繼承","甲死亡後，其子乙因悲傷過度亦於 1 個月後死亡，則甲之 3000 萬元遺產，由丙、丁各繼承 1000 萬元，剩餘 1000 萬元由 A 及 X、Y 共同繼承","甲死亡前，其子乙已先死亡時，則甲之 3000 萬元遺產，由丙、丁各繼承 1000 萬元，剩餘 1000 萬元由A 及 X、Y 共同繼承","甲得以遺囑自由處分其財產，但不得侵害繼承人之特留分"],"ok":[2],"ex":["丙先死亡且未婚無直系卑親屬可代位，第一順序繼承人僅乙、丁（§1138(1)、§1141均分）。","甲死亡時乙尚生存，已繼承1000萬；乙嗣後死亡，該1000萬成為乙之遺產，由乙之繼承人A（配偶）、X、Y繼承（§1138、§1144）。","乙先於甲死亡，其直系卑親屬X、Y代位繼承乙之應繼分1000萬（§1140）；乙之配偶A非甲之繼承人，不得共同繼承。","§1187：遺囑人於不違反關於特留分規定之範圍內，得以遺囑自由處分遺產。"],"tr":""},{"id":"h:99-32","p":"h","src":"99年第32題","sec":"E4","stem":"繼承人於下列何者情形，並不喪失繼承權？","opts":["乙酒駕騎乘機車，不小心於家門口將其父甲撞死因而受刑之宣告","乙為獨占全部遺產，欺騙其父甲其他兄弟丙丁與外人勾結圖謀財產，其父甲因此作成遺囑，將財產全部遺留給乙","乙為獨占全部遺產，私下塗改父甲之遺囑","乙與其父甲素來相處不洽，屢次於大庭廣眾之下辱罵父甲豬狗不如，令父甲心灰意冷，向其友人 A 表示遺產絕不留給乙"],"ok":[0],"ex":["§1145 I(1)限於「故意」致被繼承人於死而受刑之宣告才喪失；酒駕撞死屬過失，不喪失繼承權。","§1145 I(2)：以詐欺或脅迫使被繼承人為關於繼承之遺囑，喪失繼承權。","§1145 I(4)：偽造、變造、隱匿或湮滅被繼承人關於繼承之遺囑，塗改遺囑屬變造，喪失繼承權。","§1145 I(5)：對被繼承人有重大虐待或侮辱情事，經被繼承人表示其不得繼承者，喪失繼承權；本題公然辱罵且甲表示不留遺產，符合。"],"tr":""},{"id":"h:99-33","p":"h","src":"99年第33題","sec":"E2","stem":"甲（男）乙（女）於民國 94 年 3 月結婚，甲乙依法約定分別財產制為其夫妻財產制。下列敘述，何者正確？","opts":["甲乙就其婚後財產，互負報告之義務","甲乙各自保有其財產之所有權","甲乙之債務，應由甲乙共同清償","家庭生活費用由甲負擔，甲得請求乙為相當之負擔"],"ok":[1],"ex":["報告財產狀況之義務是法定財產制的規定（§1022）；分別財產制各自管理，無此義務。","§1044：分別財產制，夫妻各保有其財產之所有權，各自管理、使用、收益及處分。","§1046、§1023 I：分別財產制下，夫妻各自對其債務負清償之責，並非共同清償。","§1003-1：家庭生活費用，除法律或契約另有約定外，由夫妻各依其經濟能力、家事勞動或其他情事分擔，並非當然由甲負擔。"],"tr":""},{"id":"h:99-34","p":"h","src":"99年第34題","sec":"E4","stem":"因他人拋棄繼承而為繼承人者，其主張拋棄繼承之法定期間為何？","opts":["於知悉其得繼承之日起 2 個月內","自繼承開始時起 3 個月內，必要時得向法院聲請延展","於知悉其得繼承之日起 3 個月內","自繼承開始時起 2 個月內，必要時得向法院聲請延展"],"ok":[2],"ex":["拋棄繼承期間為三個月，不是二個月（§1174 II）。","期間自「知悉其得繼承時」起算而非繼承開始時，且拋棄繼承無延展規定；可延展的是限定繼承陳報遺產清冊期間（§1156）。","§1176 VII：「因他人拋棄繼承而應為繼承之人，為拋棄繼承時，應於知悉其得繼承之日起三個月內為之」，題目問的正是這一項；方式仍依§1174 II以書面向法院為之。","起算點與延展均不符，同選項B之理由（§1174 II）。"],"tr":""},{"id":"h:99-35","p":"h","src":"99年第35題","sec":"E4","stem":"甲（被繼承人）生前對乙（繼承人）所為之何種贈與，於計算甲之應繼遺產時，係屬應歸扣之生前特種贈與？","opts":["乙結婚時，甲贈與乙 100 萬元","乙生日時，甲贈與乙 100 萬元","乙生子時，甲贈與乙 100 萬元","乙參加競賽奪冠，甲贈與乙 100 萬元"],"ok":[0],"ex":["§1173：繼承人在繼承開始前因結婚、分居或營業已從被繼承人受贈者，應將贈與價額加入應繼遺產（歸扣），結婚贈與屬之。","生日贈與非§1173列舉之結婚、分居、營業，不歸扣。","生子贈與非§1173列舉事由，不歸扣。","競賽奪冠獎勵性贈與非§1173列舉事由，不歸扣。"],"tr":""},{"id":"h:99-36","p":"h","src":"99年第36題","sec":"A4","stem":"下列何種行為，為違反公序良俗？","opts":["繼承人拋棄繼承","夫妻約定家庭生活費用由妻負擔","父親死亡前，兄弟姊妹預先訂約剝奪母親之應繼分","出租人與承租人約定，承租人應負責修繕租賃標的物"],"ok":[2],"ex":["§1174 繼承人得拋棄繼承權，是法律明定之權利，不違反公序良俗。","§1003-1 家庭生活費用除法律或契約另有約定外由夫妻分擔，約定由妻負擔屬契約自由範圍。","兄弟姊妹預訂契約剝奪母親應繼分，是對尚未發生之他人繼承權預先處分，有違§72及§1138以下之法定繼承秩序，無效。","§429 租賃物修繕除契約另有訂定外由出租人負擔，故可約定由承租人負責修繕，屬有效特約。"],"tr":""},{"id":"h:99-37","p":"h","src":"99年第37題","sec":"E3","stem":"關於收養子女，下列敘述，何者錯誤？","opts":["收養子女應輩分相當","被收養人已結婚者，其出養之意思，自己決定，不必得配偶之同意","除夫妻共同收養外，1 人不能同時為 2 人之養子女","收養子女，除訂立收養契約外，應經法院之認可"],"ok":[1],"ex":["§1073-1：旁系血親六親等內、旁系姻親五親等內輩分不相當者不得收養，故收養須輩分相當。","被收養人已結婚者，其配偶為當事人家庭成員，被收養須得配偶同意（§1076），不能自行決定。","§1075：除夫妻共同收養外，一人不得同時為二人之養子女。","§1079：收養應以書面為之並向法院聲請認可。"],"tr":""},{"id":"h:99-38","p":"h","src":"99年第38題","sec":"E2","stem":"關於夫妻財產制之敘述何者錯誤？","opts":["除法定財產制外，夫妻可以約定為共同財產制或分別財產制","夫妻約定財產制時，應以書面為之","夫妻約定財產制不須登記可以對抗第三人","共同財產制之下，除夫妻特有財產以外之財產合併為共同財產，屬夫妻公同共有"],"ok":[2],"ex":["§1004：夫妻得以契約就本法所定約定財產制（共同財產制、分別財產制）中選擇其一；未約定者以法定財產制為其財產制（§1005），此敘述正確，故非本題應選。","§1007：夫妻財產制契約之訂立、變更或廢止，應以書面為之，此敘述正確，故非本題應選。","§1008Ⅰ：夫妻財產制契約之訂立、變更或廢止，非經登記，不得以之對抗第三人；選項說「不須登記可以對抗」與條文相反，錯誤，為應選答案。","§1031：共同財產制下夫妻之財產及所得，除特有財產外合併為共同財產，屬夫妻公同共有，此敘述正確，故非本題應選。"],"tr":""},{"id":"h:99-39","p":"h","src":"99年第39題","sec":"E4","stem":"甲死亡留有總計 5000 萬元之現金存款，但同時積欠銀行 7000 萬元債務未清償，其妻早已死亡，子女有乙丙丁戊 4 人。以下敘述何者正確？","opts":["在一般情形，因為遺產不足清償債務，不足之 2000 萬元應由乙丙丁戊 4 人平均分攤","乙如欲拋棄繼承，應於知悉繼承之時起 2 個月內，以書面向法院為之","乙拋棄繼承時，其應繼承之遺產歸國家所有","分割遺產之前，各繼承人對遺產全部為公同共有"],"ok":[3],"ex":["繼承人僅以所得遺產為限負清償責任（§1148 II），不足部分繼承人不須以固有財產平均分擔。","拋棄繼承須於知悉其得繼承之時起三個月內以書面向法院為之（§1174 II），不是二個月。","拋棄者之應繼分歸屬於其他同為繼承之人（§1176），無人繼承時才歸屬國庫（§1185），並非因拋棄即歸國家。","§1151：繼承人有數人時，在分割遺產前，各繼承人對於遺產全部為公同共有。"],"tr":""},{"id":"h:99-40","p":"h","src":"99年第40題","sec":"E2","stem":"關於剩餘財產分配請求權之敘述何者正確？","opts":["夫妻約定為分別財產制者，夫妻離婚時亦可主張剩餘財產分配請求權","計算剩餘財產之夫妻財產包括婚前財產及婚後財產","配偶婚後無償取得之財產，不屬計算剩餘財產之標的","剩餘財產分配請求權，應自請求人知有剩餘財產之差額時起，2 年間不行使而消滅，自法定財產制關係消滅時起，逾十年者，亦同"],"ok":[2],"ex":["剩餘財產分配請求權僅於法定財產制關係消滅時產生（§1030-1）；分別財產制為約定財產制，無此請求權。","計算對象僅限婚後財產，婚前財產不列入（§1030-1）。","§1030-1 I但書：因繼承或其他無償取得之財產及慰撫金，不列入剩餘財產差額計算。","§1030-1 V：請求權自知有差額時起2年、自法定財產制關係消滅時起逾5年不行使而消滅，不是10年。"],"tr":""}]};
